class ArdaccountsController extends AdminAppController
{
    public $helpers = array('Html', 'Form', 'Session', 'Paginator', 'Tinymce', 'Js' => array('Jquery'));
    public $components = array('Session', 'Paginator', 'search-master.Prg');
    protected static $_ardSchemaCacheRefreshed = false;

    public function beforeFilter()
    {
        parent::beforeFilter();
        if($this->_shouldRunControllerBootstrap('ardaccounts.schema', '2026-07-16.expenseapprovals.2') || !$this->_expenseApprovalSchemaReady())
        {
            $this->_ensureArdTables();
            $this->_ensureBusinessAccountingSchema();
            $this->_ensureExpenseApprovalSchema();
        }
        $this->_ensureExpenseApprovalNotificationTemplates();
    }

    protected function _expenseApprovalSchemaReady()
    {
        try
        {
            $this->loadModel('Admin.Ardledger');
            $requestTable = $this->Ardledger->query("SHOW TABLES LIKE 'ardaccounts_expense_approval_requests'");
            $historyTable = $this->Ardledger->query("SHOW TABLES LIKE 'ardaccounts_expense_approval_history'");
            $settingColumn = $this->Ardledger->query("SHOW COLUMNS FROM `ardaccounts_settings` LIKE 'expense_approval_enabled'");
            return !empty($requestTable) && !empty($historyTable) && !empty($settingColumn);
        }
        catch(Exception $e)
        {
            return false;
        }
    }

    protected function _ensureExpenseApprovalSchema()
    {
        $this->loadModel('Admin.Ardledger');
        $sql = array(
            "CREATE TABLE IF NOT EXISTS `ardaccounts_expense_approval_requests` (
                `id` bigint(20) NOT NULL AUTO_INCREMENT,
                `project_id` int(11) NOT NULL DEFAULT 0,
                `ref_no` varchar(80) NOT NULL DEFAULT '',
                `entry_date` date NOT NULL,
                `ledger_id` bigint(20) NOT NULL DEFAULT 0,
                `expense_ledger_id` bigint(20) NOT NULL DEFAULT 0,
                `amount` decimal(15,2) NOT NULL DEFAULT 0.00,
                `description` text,
                `construction_site_id` bigint(20) NOT NULL DEFAULT 0,
                `source_type` varchar(60) NOT NULL DEFAULT 'manual_expense',
                `source_id` bigint(20) NOT NULL DEFAULT 0,
                `status` varchar(30) NOT NULL DEFAULT 'Pending Manager',
                `created_by` int(11) NOT NULL DEFAULT 0,
                `submitted_at` datetime DEFAULT NULL,
                `manager_verified_by` int(11) NOT NULL DEFAULT 0,
                `manager_verified_at` datetime DEFAULT NULL,
                `ceo_approved_by` int(11) NOT NULL DEFAULT 0,
                `ceo_approved_at` datetime DEFAULT NULL,
                `rejected_by` int(11) NOT NULL DEFAULT 0,
                `rejected_at` datetime DEFAULT NULL,
                `rejection_reason` text,
                `transaction_id` bigint(20) NOT NULL DEFAULT 0,
                `created` datetime DEFAULT NULL,
                `modified` datetime DEFAULT NULL,
                PRIMARY KEY (`id`),
                KEY `project_status` (`project_id`,`status`),
                KEY `created_by` (`created_by`),
                KEY `transaction_id` (`transaction_id`),
                KEY `submitted_at` (`submitted_at`)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3",
            "CREATE TABLE IF NOT EXISTS `ardaccounts_expense_approval_history` (
                `id` bigint(20) NOT NULL AUTO_INCREMENT,
                `project_id` int(11) NOT NULL DEFAULT 0,
                `request_id` bigint(20) NOT NULL,
                `actor_user_id` int(11) NOT NULL DEFAULT 0,
                `action` varchar(40) NOT NULL DEFAULT '',
                `from_status` varchar(30) NOT NULL DEFAULT '',
                `to_status` varchar(30) NOT NULL DEFAULT '',
                `comment` text,
                `created` datetime DEFAULT NULL,
                PRIMARY KEY (`id`),
                KEY `request_id` (`request_id`),
                KEY `project_id` (`project_id`),
                KEY `actor_user_id` (`actor_user_id`),
                KEY `created` (`created`)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3"
        );
        foreach($sql as $statement)
        {
            $this->Ardledger->query($statement);
        }
        foreach(array(
            "ALTER TABLE `ardaccounts_settings` ADD COLUMN `expense_approval_enabled` tinyint(1) NOT NULL DEFAULT 0",
            "ALTER TABLE `ardaccounts_settings` ADD COLUMN `expense_approval_ceo_user_id` int(11) NOT NULL DEFAULT 0"
        ) as $statement)
        {
            try { $this->Ardledger->query($statement); } catch(Exception $e) {}
        }
        try
        {
            $this->Ardledger->getDataSource()->flushMethodCache();
            Cache::clear(false, '_cake_model_');
        }
        catch(Exception $e) {}
    }

    protected function _expenseApprovalConfig($projectId)
    {
        $projectId = (int)$projectId;
        $config = array('enabled' => 0, 'ceo_user_id' => 0);
        if($projectId <= 0)
        {
            return $config;
        }
        try
        {
            $this->loadModel('Admin.Ardsetting');
            $rows = $this->Ardsetting->query("SELECT `expense_approval_enabled`,`expense_approval_ceo_user_id` FROM `ardaccounts_settings` WHERE `project_id`=".$projectId." ORDER BY `id` DESC LIMIT 1");
            $row = !empty($rows[0]['ardaccounts_settings']) ? $rows[0]['ardaccounts_settings'] : (!empty($rows[0][0]) ? $rows[0][0] : array());
            if(empty($row) && !empty($rows[0]['Ardsetting']))
            {
                $row = $rows[0]['Ardsetting'];
            }
            $config['enabled'] = !empty($row['expense_approval_enabled']) ? 1 : 0;
            $config['ceo_user_id'] = !empty($row['expense_approval_ceo_user_id']) ? (int)$row['expense_approval_ceo_user_id'] : 0;
        }
        catch(Exception $e) {}
        return $config;
    }

    protected function _expenseApprovalNotificationTemplateDefaults()
    {
        $managerSms = 'Expense approval required. Ref: $referenceNo, Agency: $agencyName, Date: $voucherDate, Amount: $amountWithCurrency, From: $sourceAccount, Expense: $expenseAccount, Requested by: $requesterName. Review: $approvalUrl';
        $ceoSms = 'Final expense approval required. Ref: $referenceNo, Agency: $agencyName, Date: $voucherDate, Amount: $amountWithCurrency, From: $sourceAccount, Expense: $expenseAccount, Requested by: $requesterName, Verified by: $managerName. Review: $approvalUrl';
        $managerWhatsapp = '*Expense Approval Required*'."\n\n".'Dear $recipientName,'."\n".'An expense request is waiting for Manager verification.'."\n\n".'*Reference:* $referenceNo'."\n".'*Agency:* $agencyName'."\n".'*Voucher Date:* $voucherDate'."\n".'*Amount:* $amountWithCurrency'."\n".'*Payment From:* $sourceAccount'."\n".'*Expense Account:* $expenseAccount'."\n".'*Requested By:* $requesterName'."\n".'*Description:* $description'."\n\n".'Review now: $approvalUrl'."\n".'Print voucher: $voucherUrl';
        $ceoWhatsapp = '*Final Expense Approval Required*'."\n\n".'Dear $recipientName,'."\n".'A Manager-verified expense request is waiting for your final approval.'."\n\n".'*Reference:* $referenceNo'."\n".'*Agency:* $agencyName'."\n".'*Voucher Date:* $voucherDate'."\n".'*Amount:* $amountWithCurrency'."\n".'*Payment From:* $sourceAccount'."\n".'*Expense Account:* $expenseAccount'."\n".'*Requested By:* $requesterName'."\n".'*Verified By:* $managerName'."\n".'*Description:* $description'."\n\n".'Approve or reject: $approvalUrl'."\n".'Print voucher: $voucherUrl';
        $emailShell = '<div style="font-family:Arial,sans-serif;color:#172033;max-width:820px;margin:0 auto"><div style="background:#0b2344;color:#fff;padding:18px 22px"><h2 style="margin:0;font-size:20px">$emailHeading</h2><p style="margin:5px 0 0;color:#dbeafe">$emailIntro</p></div><div style="padding:20px 22px;border:1px solid #dbe3ee;border-top:0"><p>Dear <strong>$recipientName</strong>,</p><p>$emailMessage</p><p style="margin:18px 0"><a href="$approvalUrl" style="background:#2563eb;color:#fff;padding:11px 18px;text-decoration:none;font-weight:bold">Open Approval Queue</a> <a href="$voucherUrl" style="color:#2563eb;margin-left:12px">Print Voucher</a></p>$voucherHtml<p style="color:#64748b;font-size:12px;margin-top:18px">This is an automated approval notification from $siteName.</p></div></div>';
        return array(
            'EAM' => array('sms_name' => 'Expense Approval - Manager SMS', 'sms_body' => $managerSms, 'email_name' => 'Expense Approval Required - $referenceNo', 'email_body' => $emailShell),
            'EAC' => array('sms_name' => 'Expense Approval - CEO SMS', 'sms_body' => $ceoSms, 'email_name' => 'Final Expense Approval Required - $referenceNo', 'email_body' => $emailShell),
            'WAM' => array('sms_name' => 'Expense Approval - Manager WhatsApp', 'sms_body' => $managerWhatsapp),
            'WAC' => array('sms_name' => 'Expense Approval - CEO WhatsApp', 'sms_body' => $ceoWhatsapp)
        );
    }

    protected function _ensureExpenseApprovalNotificationTemplates()
    {
        static $ensured = false;
        if($ensured)
        {
            return;
        }
        $ensured = true;
        try
        {
            $this->loadModel('Admin.Smstemplate');
            $this->loadModel('Admin.Emailtemplate');
            if(is_object($this->Smstemplate) && method_exists($this->Smstemplate, 'ensureOwnershipSchema'))
            {
                $this->Smstemplate->ensureOwnershipSchema();
            }
            if(is_object($this->Emailtemplate) && method_exists($this->Emailtemplate, 'ensureOwnershipSchema'))
            {
                $this->Emailtemplate->ensureOwnershipSchema();
            }
            foreach($this->_expenseApprovalNotificationTemplateDefaults() as $type => $template)
            {
                $smsExists = $this->Smstemplate->find('first', array('fields' => array('Smstemplate.id'), 'conditions' => array('Smstemplate.type' => $type), 'recursive' => -1));
                if(empty($smsExists['Smstemplate']['id']) && !empty($template['sms_body']))
                {
                    $this->Smstemplate->create();
                    $this->Smstemplate->save(array('Smstemplate' => array(
                        'name' => $template['sms_name'],
                        'description' => $template['sms_body'],
                        'status' => 'Published',
                        'type' => $type,
                        'user_id' => null,
                        'project_id' => null
                    )), array('validate' => false, 'callbacks' => false));
                }
                if(isset($template['email_body']))
                {
                    $emailExists = $this->Emailtemplate->find('first', array('fields' => array('Emailtemplate.id'), 'conditions' => array('Emailtemplate.type' => $type), 'recursive' => -1));
                    if(empty($emailExists['Emailtemplate']['id']))
                    {
                        $this->Emailtemplate->create();
                        $this->Emailtemplate->save(array('Emailtemplate' => array(
                            'name' => $template['email_name'],
                            'description' => $template['email_body'],
                            'status' => 'Published',
                            'type' => $type,
                            'user_id' => null,
                            'project_id' => null
                        )), array('validate' => false, 'callbacks' => false));
                    }
                }
            }
        }
        catch(Exception $e)
        {
            CakeLog::write('error', 'Expense approval template bootstrap failed: '.$e->getMessage());
        }
    }

    protected function _expenseApprovalActor()
    {
        $user = !empty($this->adminValue['User']) ? (array)$this->adminValue['User'] : (array)$this->Session->read('User.User');
        $group = !empty($this->adminValue['Ugroup']) ? (array)$this->adminValue['Ugroup'] : array();
        $groupId = !empty($user['ugroup_id']) ? (int)$user['ugroup_id'] : 0;
        if((empty($group['name']) || empty($group['type'])) && $groupId > 0)
        {
            try
            {
                $Ugroup = ClassRegistry::init('Ugroup');
                $row = $Ugroup->find('first', array('conditions' => array('Ugroup.id' => $groupId), 'recursive' => -1));
                if(!empty($row['Ugroup'])) { $group = $row['Ugroup']; }
            }
            catch(Exception $e) {}
        }
        return array(
            'user_id' => !empty($user['id']) ? (int)$user['id'] : (int)$this->luserId,
            'group_id' => $groupId,
            'group_name' => strtolower(trim((string)(isset($group['name']) ? $group['name'] : ''))),
            'group_type' => strtoupper(trim((string)(isset($group['type']) ? $group['type'] : ''))),
            'is_super' => $this->_isGlobalAdmin()
        );
    }

    protected function _isExpenseApprovalAccountant($actor = array())
    {
        $actor = empty($actor) ? $this->_expenseApprovalActor() : $actor;
        return !empty($actor['is_super']) || (int)$actor['group_id'] === 6 || strpos($actor['group_name'], 'account') !== false;
    }

    protected function _isExpenseApprovalManager($actor = array())
    {
        $actor = empty($actor) ? $this->_expenseApprovalActor() : $actor;
        return !empty($actor['is_super']) || (int)$actor['group_id'] === 3 || strpos($actor['group_name'], 'manager') !== false;
    }

    protected function _isExpenseApprovalCeo($projectId, $actor = array())
    {
        $actor = empty($actor) ? $this->_expenseApprovalActor() : $actor;
        if(!empty($actor['is_super']))
        {
            return true;
        }
        $config = $this->_expenseApprovalConfig((int)$projectId);
        if((int)$config['ceo_user_id'] > 0)
        {
            return (int)$config['ceo_user_id'] === (int)$actor['user_id'];
        }
        return (int)$actor['group_id'] === 4 || $actor['group_name'] === 'ceo' || $actor['group_name'] === 'agency';
    }

