    protected function _extractEditIdFromRequest()
    {
        $editId = isset($this->request->query['edit']) ? (int)$this->request->query['edit'] : 0;
        if($editId > 0)
        {
            return $editId;
        }
        if(!empty($_GET['edit']) && (int)$_GET['edit'] > 0)
        {
            return (int)$_GET['edit'];
        }
        $editId = isset($this->request->params['named']['edit']) ? (int)$this->request->params['named']['edit'] : 0;
        if($editId > 0)
        {
            return $editId;
        }
        $passParams = isset($this->request->params['pass']) && is_array($this->request->params['pass']) ? $this->request->params['pass'] : array();
        foreach($passParams as $passParam)
        {
            $token = urldecode((string)$passParam);
            if(stripos($token, 'edit:') === 0)
            {
                $candidateId = (int)substr($token, 5);
                if($candidateId > 0)
                {
                    return $candidateId;
                }
            }
        }
        return 0;
    }

    protected function _normalizeYmdDate($value, $fallback = '')
    {
        $value = trim((string)$value);
        if($value === '' || $value === '0000-00-00')
        {
            return $fallback;
        }
        $formats = array('Y-m-d', 'd-m-Y', 'd/m/Y', 'Y/m/d', 'm/d/Y');
        foreach($formats as $fmt)
        {
            $dt = DateTime::createFromFormat($fmt, $value);
            if($dt && $dt->format($fmt) === $value)
            {
                return $dt->format('Y-m-d');
            }
        }
        $ts = strtotime(str_replace('/', '-', $value));
        if($ts !== false)
        {
            return date('Y-m-d', $ts);
        }
        return $fallback;
    }

    protected function _normalizePayrollMonthValue($value, $fallback = '')
    {
        $value = trim((string)$value);
        if($value === '')
        {
            return $fallback;
        }
        if(preg_match('/^(\d{4})-(\d{2})$/', $value, $m))
        {
            $year = (int)$m[1];
            $month = (int)$m[2];
            if($year > 0 && $month >= 1 && $month <= 12)
            {
                return sprintf('%04d-%02d', $year, $month);
            }
            return $fallback;
        }
        if(preg_match('/^(\d{2})[\/\-](\d{4})$/', $value, $m))
        {
            $month = (int)$m[1];
            $year = (int)$m[2];
            if($year > 0 && $month >= 1 && $month <= 12)
            {
                return sprintf('%04d-%02d', $year, $month);
            }
        }
        $monthDateFormats = array('d-M-Y','j-M-Y','d-M-y','j-M-y','d F Y','j F Y','d/m/Y','d-m-Y');
        foreach($monthDateFormats as $monthDateFormat)
        {
            $dt = DateTime::createFromFormat($monthDateFormat, $value);
            if($dt && $dt->format($monthDateFormat) === $value)
            {
                return $dt->format('Y-m');
            }
        }
        $ts = strtotime($value . '-01');
        if($ts === false)
        {
            $ts = strtotime($value);
        }
        if($ts !== false)
        {
            return date('Y-m', $ts);
        }
        return $fallback;
    }

    protected function _normalizeHrEmployeeScope($scope = '')
    {
        $scope = strtolower(trim((string)$scope));
        if(!in_array($scope, array('all', 'labour', 'staff'), true))
        {
            return 'all';
        }
        return $scope;
    }

    protected function _hrEmployeeScopeFromRequest($defaultScope = 'all')
    {
        $scope = '';
        if(isset($this->request->query['employee_scope']))
        {
            $scope = (string)$this->request->query['employee_scope'];
        }
        if($scope === '' && isset($this->request->data['employee_scope']))
        {
            $scope = (string)$this->request->data['employee_scope'];
        }
        if($scope === '' && isset($this->request->data['Ardhremployee']['employee_scope']))
        {
            $scope = (string)$this->request->data['Ardhremployee']['employee_scope'];
        }
        if($scope === '' && isset($this->request->data['Ardhpayroll']['employee_scope']))
        {
            $scope = (string)$this->request->data['Ardhpayroll']['employee_scope'];
        }
        if($scope === '' && isset($this->request->data['Ardhpayment']['employee_scope']))
        {
            $scope = (string)$this->request->data['Ardhpayment']['employee_scope'];
        }
        if($scope === '')
        {
            $scope = (string)$defaultScope;
        }
        return $this->_normalizeHrEmployeeScope($scope);
    }

    protected function _hrEmployeeScopeLabel($scope = 'all')
    {
        $scope = $this->_normalizeHrEmployeeScope($scope);
        if($scope === 'labour')
        {
            return __('Labour');
        }
        if($scope === 'staff')
        {
            return __('Staff');
        }
        return __('All Employees');
    }

    protected function _hrEmployeeScopeConditions($alias = 'Ardhremployee', $scope = 'all')
    {
        $scope = $this->_normalizeHrEmployeeScope($scope);
        if($scope === 'labour')
        {
            return array($alias . '.salary_type' => 'daily');
        }
        if($scope === 'staff')
        {
            return array($alias . '.salary_type !=' => 'daily');
        }
        return array();
    }

    protected function _hrEmployeeScopeSql($field = 'salary_type', $scope = 'all')
    {
        $scope = $this->_normalizeHrEmployeeScope($scope);
        if($scope === 'labour')
        {
            return "{$field}='daily'";
        }
        if($scope === 'staff')
        {
            return "{$field}<>'daily'";
        }
        return '1=1';
    }

    protected function _hrEmployeeMatchesScope($employeeRow, $scope = 'all')
    {
        $scope = $this->_normalizeHrEmployeeScope($scope);
        if($scope === 'all')
        {
            return true;
        }
        $employeeData = isset($employeeRow['Ardhremployee']) ? (array)$employeeRow['Ardhremployee'] : array();
        $salaryType = strtolower(trim((string)(isset($employeeData['salary_type']) ? $employeeData['salary_type'] : 'monthly')));
        if($scope === 'labour')
        {
            return ($salaryType === 'daily');
        }
        return ($salaryType !== 'daily');
    }

    protected function _hrEmployeeScopeQuery($scope = 'all')
    {
        $scope = $this->_normalizeHrEmployeeScope($scope);
        if($scope === 'all')
        {
            return array();
        }
        return array('employee_scope' => $scope);
    }

    protected function _normalizeHrEmployeeLedger($projectId, $ledgerId)
    {
        $this->loadModel('Admin.Ardledger');
        $projectId = (int)$projectId;
        $ledgerId = (int)$ledgerId;
        if($projectId <= 0 || $ledgerId <= 0)
        {
            return 0;
        }

        $ledgerRow = (array)$this->Ardledger->find('first', array(
            'fields' => array('Ardledger.id', 'Ardledger.type', 'Ardledger.category'),
            'conditions' => array(
                'Ardledger.id' => $ledgerId,
                'Ardledger.project_id' => $projectId,
                'Ardledger.is_trashed' => 0
            ),
            'recursive' => -1
        ));
        if(empty($ledgerRow['Ardledger']['id']))
        {
            return 0;
        }

        $ledgerType = strtolower(trim((string)(isset($ledgerRow['Ardledger']['type']) ? $ledgerRow['Ardledger']['type'] : 'bank')));
        $ledgerCategory = trim((string)(isset($ledgerRow['Ardledger']['category']) ? $ledgerRow['Ardledger']['category'] : ''));
        $mustUpdate = false;
        $saveData = array('id' => (int)$ledgerRow['Ardledger']['id']);
        if($ledgerType !== 'bank')
        {
            $saveData['type'] = 'bank';
            $mustUpdate = true;
        }
        if($ledgerCategory === '' || strcasecmp($ledgerCategory, 'labour') === 0)
        {
            $saveData['category'] = 'HR Employee';
            $mustUpdate = true;
        }
        if($mustUpdate)
        {
            $this->Ardledger->id = (int)$ledgerRow['Ardledger']['id'];
            $this->Ardledger->save(array('Ardledger' => $saveData), array('validate' => false, 'callbacks' => false));
        }

        return (int)$ledgerRow['Ardledger']['id'];
    }

    protected function _ensureHrLabourLedger($projectId, $employeeCode, $employeeName, $preferredLedgerId = 0)
    {
        $this->loadModel('Admin.Ardledger');
        $projectId = (int)$projectId;
        $preferredLedgerId = (int)$preferredLedgerId;
        $employeeCode = trim((string)$employeeCode);
        $employeeName = trim((string)$employeeName);
        if($projectId <= 0)
        {
            return 0;
        }

        if($preferredLedgerId > 0)
        {
            $normalizedPreferred = $this->_normalizeHrEmployeeLedger($projectId, $preferredLedgerId);
            if($normalizedPreferred > 0)
            {
                return $normalizedPreferred;
            }
        }

        $nameCandidates = array();
        if($employeeCode !== '')
        {
            $nameCandidates[] = 'HR - ' . $employeeCode;
            $nameCandidates[] = 'Labour - ' . $employeeCode;
        }
        if($employeeName !== '')
        {
            $nameCandidates[] = 'HR - ' . $employeeName;
            $nameCandidates[] = 'Labour - ' . $employeeName;
        }
        $nameCandidates[] = 'HR Employee';
        $nameCandidates = array_values(array_unique(array_filter(array_map('trim', $nameCandidates))));

        foreach($nameCandidates as $ledgerName)
        {
            $existingLedger = (array)$this->Ardledger->find('first', array(
                'fields' => array('Ardledger.id'),
                'conditions' => array(
                    'Ardledger.project_id' => $projectId,
                    'Ardledger.name' => $ledgerName,
                    'Ardledger.is_trashed' => 0
                ),
                'order' => array('Ardledger.id' => 'asc'),
                'recursive' => -1
            ));
            if(!empty($existingLedger['Ardledger']['id']))
            {
                return $this->_normalizeHrEmployeeLedger($projectId, (int)$existingLedger['Ardledger']['id']);
            }
        }

        $ledgerName = !empty($nameCandidates[0]) ? (string)$nameCandidates[0] : 'HR Employee';
        $this->Ardledger->create();
        $saveOk = $this->Ardledger->save(array('Ardledger' => array(
            'project_id' => $projectId,
            'name' => $ledgerName,
            'type' => 'bank',
            'category' => 'HR Employee',
            'account_no' => '',
            'mobile_no' => '',
            'address' => '',
            'balance' => 0,
            'is_trashed' => 0
        )));
        if($saveOk)
        {
            return $this->_normalizeHrEmployeeLedger($projectId, (int)$this->Ardledger->id);
        }
        return 0;
    }

    protected function _hrAttendancePayrollSummary($projectId, $employeeRow, $payrollMonth)
    {
        $this->loadModel('Admin.Ardhattendance');
        $projectId = (int)$projectId;
        $employeeData = isset($employeeRow['Ardhremployee']) ? (array)$employeeRow['Ardhremployee'] : array();
        $employeeId = isset($employeeData['id']) ? (int)$employeeData['id'] : 0;
        $payrollMonth = $this->_normalizePayrollMonthValue($payrollMonth, date('Y-m'));
        $startDate = $payrollMonth . '-01';
        $endDate = date('Y-m-t', strtotime($startDate));
        $daysInMonth = (int)date('t', strtotime($startDate));

        $presentDaysRaw = 0.0;
        $absentCount = 0;
        $leaveCount = 0;
        $halfDayCount = 0;
        $attendanceRowsCount = 0;
        $overtimeHours = 0.0;

        $attendanceRows = (array)$this->Ardhattendance->find('all', array(
            'fields' => array('Ardhattendance.attendance_status', 'Ardhattendance.overtime_hours'),
            'conditions' => array(
                'Ardhattendance.project_id' => $projectId,
                'Ardhattendance.employee_id' => $employeeId,
                'Ardhattendance.attendance_date >=' => $startDate,
                'Ardhattendance.attendance_date <=' => $endDate
            ),
            'recursive' => -1
        ));
        foreach($attendanceRows as $attendanceRow)
        {
            $attendanceData = isset($attendanceRow['Ardhattendance']) ? (array)$attendanceRow['Ardhattendance'] : array();
            $status = strtolower(trim((string)(isset($attendanceData['attendance_status']) ? $attendanceData['attendance_status'] : 'present')));
            $hours = round((float)(isset($attendanceData['overtime_hours']) ? $attendanceData['overtime_hours'] : 0), 2);
            if($hours > 0)
            {
                $overtimeHours += $hours;
            }
            $attendanceRowsCount++;
            if($status === 'absent')
            {
                $absentCount++;
            }
            elseif($status === 'leave')
            {
                $leaveCount++;
                $presentDaysRaw += 1.0;
            }
            elseif($status === 'half_day')
            {
                $halfDayCount++;
                $presentDaysRaw += 0.5;
            }
            else
            {
                $presentDaysRaw += 1.0;
            }
        }

        $workingDays = ($attendanceRowsCount > 0) ? (float)$attendanceRowsCount : (float)$daysInMonth;
        if($workingDays <= 0)
        {
            $workingDays = (float)$daysInMonth;
        }
        $presentDays = round($presentDaysRaw, 2);
        if($presentDays > $workingDays)
        {
            $presentDays = $workingDays;
        }
        $absentDays = round(max(0, $workingDays - $presentDays), 2);
        $overtimeHours = round($overtimeHours, 2);

        $salaryType = strtolower(trim((string)(isset($employeeData['salary_type']) ? $employeeData['salary_type'] : 'monthly')));
        if($salaryType !== 'daily')
        {
            $salaryType = 'monthly';
        }
        $baseSalary = round((float)(isset($employeeData['base_salary']) ? $employeeData['base_salary'] : 0), 2);
        $overtimeRate = round((float)(isset($employeeData['overtime_rate']) ? $employeeData['overtime_rate'] : 0), 2);

        $baseCalculated = 0.0;
        if($salaryType === 'daily')
        {
            $baseCalculated = round($baseSalary * $presentDays, 2);
        }
        else
        {
            $dayFactor = ($workingDays > 0 ? $workingDays : (float)$daysInMonth);
            if($dayFactor <= 0)
            {
                $dayFactor = 1.0;
            }
            $baseCalculated = round(($baseSalary / $dayFactor) * $presentDays, 2);
        }
        $overtimeAmount = round($overtimeHours * $overtimeRate, 2);

        $linkedUserId = isset($employeeData['linked_user_id']) ? (int)$employeeData['linked_user_id'] : 0;
        $commissionEarned = 0.0;
        $commissionPaid = 0.0;
        if($linkedUserId > 0 && $projectId > 0)
        {
            $walletRows = (array)$this->Ardhattendance->query(
                "SELECT
                    SUM(CASE
                        WHEN UPPER(TRIM(COALESCE(type,'')))='CR'
                             AND (LOWER(COALESCE(remarks,'')) LIKE '%commission%' OR COALESCE(deals_payment_id,0) > 0)
                        THEN amount ELSE 0 END) AS commission_earned,
                    SUM(CASE
                        WHEN UPPER(TRIM(COALESCE(type,'')))='DR'
                             AND LOWER(COALESCE(remarks,'')) LIKE 'paid commission to %'
                        THEN amount ELSE 0 END) AS commission_paid
                 FROM awallet_histories
                 WHERE project_id=".(int)$projectId."
                   AND user_id=".(int)$linkedUserId."
                   AND date >= '".$startDate." 00:00:00'
                   AND date <= '".$endDate." 23:59:59'"
            );
            if(!empty($walletRows[0][0]))
            {
                $walletAgg = (array)$walletRows[0][0];
                $commissionEarned = round((float)(isset($walletAgg['commission_earned']) ? $walletAgg['commission_earned'] : 0), 2);
                $commissionPaid = round((float)(isset($walletAgg['commission_paid']) ? $walletAgg['commission_paid'] : 0), 2);
            }
        }
        $commissionBalance = round(max(0, $commissionEarned - $commissionPaid), 2);
        $grossPay = round($baseCalculated + $overtimeAmount, 2);
        if($grossPay < 0)
        {
            $grossPay = 0;
        }
        $netEstimated = round($grossPay + $commissionBalance, 2);
        if($netEstimated < 0)
        {
            $netEstimated = 0;
        }

        return array(
            'project_id' => $projectId,
            'employee_id' => $employeeId,
            'employee_name' => trim((string)(isset($employeeData['full_name']) ? $employeeData['full_name'] : '')),
            'employee_code' => trim((string)(isset($employeeData['employee_code']) ? $employeeData['employee_code'] : '')),
            'linked_user_id' => $linkedUserId,
            'salary_type' => $salaryType,
            'base_salary' => $baseSalary,
            'working_days' => round($workingDays, 2),
            'present_days' => round($presentDays, 2),
            'absent_days' => $absentDays,
            'leave_days' => (float)$leaveCount,
            'half_days' => (float)$halfDayCount,
            'overtime_hours' => $overtimeHours,
            'overtime_rate' => $overtimeRate,
            'overtime_amount' => $overtimeAmount,
            'gross_pay' => $grossPay,
            'commission_earned' => $commissionEarned,
            'commission_paid' => $commissionPaid,
            'commission_balance' => $commissionBalance,
            'commission_amount' => $commissionBalance,
            'net_pay_estimated' => $netEstimated,
            'payroll_month' => $payrollMonth,
            'month_start' => $startDate,
            'month_end' => $endDate
        );
    }

    protected function _recordConstructionConsumptionFromStockOut($stockRow, $stockEntryId = 0)
    {
        $projectRefId = isset($stockRow['construction_project_id']) ? (int)$stockRow['construction_project_id'] : 0;
        if($projectRefId <= 0)
        {
            return true;
        }
        $this->loadModel('Admin.Ardconstructionproject');
        $this->loadModel('Admin.Ardconstructionconsumption');
        $projectRow = $this->Ardconstructionproject->find('first', array(
            'conditions' => array(
                'Ardconstructionproject.id' => $projectRefId,
                'Ardconstructionproject.project_id' => (int)$stockRow['project_id']
            ),
            'recursive' => -1
        ));
        if(empty($projectRow['Ardconstructionproject']))
        {
            return false;
        }
        $entry = array(
            'project_id' => (int)$stockRow['project_id'],
            'construction_project_id' => $projectRefId,
            'milestone_id' => isset($stockRow['milestone_id']) ? (int)$stockRow['milestone_id'] : 0,
            'stock_entry_id' => (int)$stockEntryId,
            'site_id' => isset($stockRow['site_id']) ? (int)$stockRow['site_id'] : 0,
            'consumption_type' => 'material',
            'material_type' => isset($stockRow['material_type']) ? (string)$stockRow['material_type'] : '',
            'unit_type' => isset($stockRow['unit_type']) ? (string)$stockRow['unit_type'] : '',
            'quantity' => isset($stockRow['quantity']) ? (float)$stockRow['quantity'] : 0,
            'unit_cost' => isset($stockRow['unit_cost']) ? (float)$stockRow['unit_cost'] : 0,
            'total_cost' => isset($stockRow['total_cost']) ? (float)$stockRow['total_cost'] : 0,
            'entry_date' => isset($stockRow['movement_date']) ? (string)$stockRow['movement_date'] : date('Y-m-d'),
            'notes' => isset($stockRow['notes']) ? (string)$stockRow['notes'] : ''
        );
        $this->Ardconstructionconsumption->create();
        return (bool)$this->Ardconstructionconsumption->save(array('Ardconstructionconsumption' => $entry), false);
    }

    protected function _isCashReceiptPaymentType($paymentTypeName)
    {
        $name = strtolower(trim((string)$paymentTypeName));
        return ($name !== '' && strpos($name, 'cash') !== false);
    }

    protected function _isOnlineReceiptPaymentType($paymentTypeName)
    {
        $name = strtolower(trim((string)$paymentTypeName));
        if($name === '')
        {
            return false;
        }
        if(strpos($name, 'cash') !== false)
        {
            return false;
        }
        return (strpos($name, 'online') !== false ||
            strpos($name, 'bank transfer') !== false ||
            strpos($name, 'transfer') !== false ||
            strpos($name, 'ubl') !== false);
    }

    protected function _receiptLedgerNameKey($name)
    {
        return strtolower(preg_replace('/[^a-z0-9]/', '', (string)$name));
    }

    protected function _getOrCreateDefaultExpenseLedger($projectId)
    {
        $this->loadModel('Admin.Ardledger');
        $projectId = (int)$projectId;
        if($projectId <= 0)
        {
            return 0;
        }

        $existing = $this->Ardledger->find('first', array(
            'fields' => array('Ardledger.id'),
            'conditions' => array(
                'Ardledger.project_id' => $projectId,
                'Ardledger.type' => 'expense',
                'Ardledger.is_trashed' => 0,
                'OR' => array(
                    array('Ardledger.name' => 'General Expense Account'),
                    array('Ardledger.category' => 'Auto Expense Account')
                )
            ),
            'order' => array('Ardledger.id' => 'asc'),
            'recursive' => -1
        ));
        if(!empty($existing['Ardledger']['id']))
        {
            return (int)$existing['Ardledger']['id'];
        }

        $trashed = $this->Ardledger->find('first', array(
            'fields' => array('Ardledger.id'),
            'conditions' => array(
                'Ardledger.project_id' => $projectId,
                'Ardledger.type' => 'expense',
                'Ardledger.is_trashed' => 1,
                'OR' => array(
                    array('Ardledger.name' => 'General Expense Account'),
                    array('Ardledger.category' => 'Auto Expense Account')
                )
            ),
            'order' => array('Ardledger.id' => 'asc'),
            'recursive' => -1
        ));
        if(!empty($trashed['Ardledger']['id']))
        {
            $restoreId = (int)$trashed['Ardledger']['id'];
            $this->Ardledger->id = $restoreId;
            $this->Ardledger->save(array('Ardledger' => array(
                'id' => $restoreId,
                'is_trashed' => 0
            )), false);
            return $restoreId;
        }

        $row = array(
            'project_id' => $projectId,
            'name' => 'General Expense Account',
            'type' => 'expense',
            'category' => 'Auto Expense Account',
            'account_no' => '',
            'mobile_no' => '',
            'address' => '',
            'balance' => 0,
            'is_trashed' => 0
        );
        $this->Ardledger->create();
        if($this->Ardledger->save(array('Ardledger' => $row), false))
        {
            return (int)$this->Ardledger->id;
        }
        return 0;
    }

    protected function _defaultExpenseLedgerForAutoVoucher($projectId, $settingsField)
    {
        $this->loadModel('Admin.Ardsetting');
        $this->loadModel('Admin.Ardledger');
        $projectId = (int)$projectId;
        if($projectId <= 0)
        {
            return 0;
        }

        $settingsField = preg_replace('/[^a-z0-9_]/i', '', (string)$settingsField);
        $allowedFields = array(
            'purchase_payment_expense_ledger_id',
            'payroll_payment_expense_ledger_id'
        );
        if(!in_array($settingsField, $allowedFields, true))
        {
            return $this->_getOrCreateDefaultExpenseLedger($projectId);
        }

        $ledgerId = 0;
        try
        {
            $row = $this->_fetchArdSettingsRowRaw($projectId);
            if(!empty($row[$settingsField]))
            {
                $ledgerId = (int)$row[$settingsField];
            }
        }
        catch(Exception $e)
        {
            $ledgerId = 0;
        }

        if($ledgerId > 0)
        {
            $valid = $this->Ardledger->find('first', array(
                'fields' => array('Ardledger.id'),
                'conditions' => array(
                    'Ardledger.id' => $ledgerId,
                    'Ardledger.project_id' => $projectId,
                    'Ardledger.is_trashed' => 0,
                    'Ardledger.type' => 'expense'
                ),
                'recursive' => -1
            ));
            if(!empty($valid['Ardledger']['id']))
            {
                return $ledgerId;
            }
        }

        return $this->_getOrCreateDefaultExpenseLedger($projectId);
    }

    protected function _getDefaultExpenseSourceLedger($projectId, $excludeLedgerId = 0)
    {
        $this->loadModel('Admin.Ardledger');
        $projectId = (int)$projectId;
        $excludeLedgerId = (int)$excludeLedgerId;
        if($projectId <= 0)
        {
            return 0;
        }

        // Prefer canonical cash/bank ledgers for expense source side.
        $canonical = $this->_getOrCreateCanonicalReceiptLedgers($projectId);
        if(!empty($canonical['cash']) && (int)$canonical['cash'] > 0 && (int)$canonical['cash'] !== $excludeLedgerId)
        {
            return (int)$canonical['cash'];
        }
        if(!empty($canonical['ubl']) && (int)$canonical['ubl'] > 0 && (int)$canonical['ubl'] !== $excludeLedgerId)
        {
            return (int)$canonical['ubl'];
        }

        $fallback = $this->Ardledger->find('first', array(
            'fields' => array('Ardledger.id'),
            'conditions' => array(
                'Ardledger.project_id' => $projectId,
                'Ardledger.is_trashed' => 0,
                'Ardledger.type !=' => 'expense',
                'Ardledger.id !=' => $excludeLedgerId
            ),
            'order' => array('Ardledger.id' => 'asc'),
            'recursive' => -1
        ));
        if(!empty($fallback['Ardledger']['id']))
        {
            return (int)$fallback['Ardledger']['id'];
        }

        return 0;
    }

    protected function _getOrCreateCanonicalReceiptLedgers($projectId)
    {
        $this->loadModel('Admin.Ardledger');
        $projectId = (int)$projectId;
        $result = array('ubl' => 0, 'cash' => 0, 'map' => array());
        if($projectId <= 0)
        {
            return $result;
        }

        $rows = $this->Ardledger->find('all', array(
            'fields' => array('Ardledger.id', 'Ardledger.name'),
            'conditions' => array(
                'Ardledger.project_id' => $projectId,
                'Ardledger.is_trashed' => 0,
                'Ardledger.type !=' => 'expense'
            ),
            'order' => array('Ardledger.id' => 'asc'),
            'recursive' => -1
        ));

        $ublCandidates = array();
        $cashCandidates = array();
        foreach((array)$rows as $row)
        {
            if(empty($row['Ardledger']['id']))
            {
                continue;
            }
            $lid = (int)$row['Ardledger']['id'];
            $name = trim((string)$row['Ardledger']['name']);
            $key = $this->_receiptLedgerNameKey($name);
            $result['map'][$lid] = $name;
            if($key === 'ubl' || strpos($key, 'ubl') !== false)
            {
                $ublCandidates[] = $lid;
            }
            if($key === 'cashinhand' || $key === 'cash' || strpos($key, 'cashinhand') !== false || strpos($key, 'cash') !== false)
            {
                $cashCandidates[] = $lid;
            }
        }

        if(!empty($ublCandidates))
        {
            $result['ubl'] = (int)$ublCandidates[0];
        }
        if(!empty($cashCandidates))
        {
            $result['cash'] = (int)$cashCandidates[0];
        }

        if($result['ubl'] <= 0)
        {
            $this->Ardledger->create();
            if($this->Ardledger->save(array('Ardledger' => array(
                'project_id' => $projectId,
                'name' => 'UBL',
                'type' => 'bank',
                'category' => 'Auto Receipt Account',
                'balance' => 0,
                'is_trashed' => 0
            )), false))
            {
                $result['ubl'] = (int)$this->Ardledger->id;
                $result['map'][$result['ubl']] = 'UBL';
            }
        }

        if($result['cash'] <= 0)
        {
            $this->Ardledger->create();
            if($this->Ardledger->save(array('Ardledger' => array(
                'project_id' => $projectId,
                'name' => 'Cash-inhand',
                'type' => 'bank',
                'category' => 'Auto Receipt Account',
                'balance' => 0,
                'is_trashed' => 0
            )), false))
            {
                $result['cash'] = (int)$this->Ardledger->id;
                $result['map'][$result['cash']] = 'Cash-inhand';
            }
        }

        // Normalize canonical names for clean UI.
        if($result['ubl'] > 0)
        {
            $this->Ardledger->id = (int)$result['ubl'];
            $this->Ardledger->save(array('Ardledger' => array('id' => (int)$result['ubl'], 'name' => 'UBL')), false, array('name'));
            $result['map'][(int)$result['ubl']] = 'UBL';
        }
        if($result['cash'] > 0)
        {
            $this->Ardledger->id = (int)$result['cash'];
            $this->Ardledger->save(array('Ardledger' => array('id' => (int)$result['cash'], 'name' => 'Cash-inhand')), false, array('name'));
            $result['map'][(int)$result['cash']] = 'Cash-inhand';
        }

        return $result;
    }

    protected function _cleanupDuplicateReceiptLedgers($projectId, $canonicalLedgerIds = array())
    {
        $this->loadModel('Admin.Ardledger');
        $this->loadModel('Admin.Ardtransaction');
        $this->loadModel('DealsPayment');
        $projectId = (int)$projectId;
        $canonicalSet = array();
        foreach((array)$canonicalLedgerIds as $lid)
        {
            $lid = (int)$lid;
            if($lid > 0)
            {
                $canonicalSet[$lid] = true;
            }
        }
        $rows = $this->Ardledger->find('all', array(
            'fields' => array('Ardledger.*'),
            'conditions' => array(
                'Ardledger.project_id' => $projectId,
                'Ardledger.is_trashed' => 0,
                'Ardledger.type !=' => 'expense'
            ),
            'order' => array('Ardledger.id' => 'asc'),
            'recursive' => -1
        ));
        $trashed = 0;
        foreach((array)$rows as $row)
        {
            if(empty($row['Ardledger']['id']))
            {
                continue;
            }
            $ledgerId = (int)$row['Ardledger']['id'];
            if(isset($canonicalSet[$ledgerId]))
            {
                continue;
            }
            $name = trim((string)$row['Ardledger']['name']);
            $nameLower = strtolower($name);
            $categoryLower = strtolower(trim((string)$row['Ardledger']['category']));
            $nameKey = $this->_receiptLedgerNameKey($name);
            $isReceiptLike = (
                strpos($nameLower, 'receipt') !== false ||
                strpos($nameLower, 'cash') !== false ||
                strpos($nameLower, 'ubl') !== false ||
                strpos($categoryLower, 'auto receipt') !== false ||
                in_array($nameKey, array('generalreceiptaccount', 'generalreceipt', 'receiptaccount', 'cashinhand', 'cash', 'ubl'))
            );
            if(!$isReceiptLike)
            {
                continue;
            }
            $txCount = (int)$this->Ardtransaction->find('count', array(
                'conditions' => array('Ardtransaction.ledger_id' => $ledgerId),
                'recursive' => -1
            ));
            $paymentCount = (int)$this->DealsPayment->find('count', array(
                'conditions' => array('DealsPayment.ard_ledger_id' => $ledgerId),
                'recursive' => -1
            ));
            if($txCount > 0 || $paymentCount > 0)
            {
                continue;
            }
            $this->_storeTrashRecord('ardaccounts_ledgers', 'Ardledger', $row['Ardledger'], $name);
            $this->Ardledger->id = $ledgerId;
            if($this->Ardledger->saveField('is_trashed', 1, false))
            {
                $trashed++;
            }
        }
        return $trashed;
    }

    protected function _normalizeDealReceiptMappingsByProject($projectId)
    {
        $this->loadModel('DealsPayment');
        $this->loadModel('Admin.Ardtransaction');
        $this->loadModel('Admin.Ardledger');
        $this->loadModel('Admin.Ardjournalentry');
        $projectId = (int)$projectId;
        $summary = array(
            'payments_updated' => 0,
            'transactions_updated' => 0,
            'links_fixed' => 0,
            'duplicates_trashed' => 0,
            'errors' => 0
        );
        if($projectId <= 0)
        {
            return $summary;
        }

        $canon = $this->_getOrCreateCanonicalReceiptLedgers($projectId);
        $ublLedgerId = isset($canon['ubl']) ? (int)$canon['ubl'] : 0;
        $cashLedgerId = isset($canon['cash']) ? (int)$canon['cash'] : 0;
        if($ublLedgerId <= 0 || $cashLedgerId <= 0)
        {
            $summary['errors']++;
            return $summary;
        }
        $targetLedgerNameMap = isset($canon['map']) ? (array)$canon['map'] : array();
        $touchedLedgerIds = array($ublLedgerId => true, $cashLedgerId => true);

        $rows = $this->DealsPayment->find('all', array(
            'joins' => array(
                array('table' => 'deals', 'alias' => 'Deal', 'type' => 'LEFT', 'conditions' => array('Deal.id = DealsPayment.deal_id')),
                array('table' => 'properties', 'alias' => 'Property', 'type' => 'LEFT', 'conditions' => array('Property.id = Deal.property_id')),
                array('table' => 'paymenttypes', 'alias' => 'Paymenttype', 'type' => 'LEFT', 'conditions' => array('Paymenttype.id = DealsPayment.paymenttype_id'))
            ),
            'fields' => array(
                'DealsPayment.id',
                'DealsPayment.paymenttype_id',
                'DealsPayment.receipt_no',
                'DealsPayment.ard_ledger_id',
                'DealsPayment.ard_transaction_id',
                'Property.project_id',
                'Paymenttype.name'
            ),
            'conditions' => array('Property.project_id' => $projectId),
            'order' => array('DealsPayment.id' => 'asc'),
            'recursive' => -1
        ));

        foreach((array)$rows as $row)
        {
            try
            {
                if(empty($row['DealsPayment']['id']))
                {
                    continue;
                }
                $paymentId = (int)$row['DealsPayment']['id'];
                $ptypeName = isset($row['Paymenttype']['name']) ? (string)$row['Paymenttype']['name'] : '';
                $isCash = $this->_isCashReceiptPaymentType($ptypeName);
                $targetLedgerId = $isCash ? $cashLedgerId : $ublLedgerId;

                $currentLedgerId = isset($row['DealsPayment']['ard_ledger_id']) ? (int)$row['DealsPayment']['ard_ledger_id'] : 0;
                if($currentLedgerId !== $targetLedgerId)
                {
                    $this->DealsPayment->id = $paymentId;
                    if($this->DealsPayment->saveField('ard_ledger_id', $targetLedgerId, false))
                    {
                        $summary['payments_updated']++;
                        if($currentLedgerId > 0)
                        {
                            $touchedLedgerIds[$currentLedgerId] = true;
                        }
                    }
                }

                $txId = isset($row['DealsPayment']['ard_transaction_id']) ? (int)$row['DealsPayment']['ard_transaction_id'] : 0;
                if($txId <= 0)
                {
                    $receiptNo = trim((string)$row['DealsPayment']['receipt_no']);
                    if($receiptNo !== '')
                    {
                        $txByRef = $this->Ardtransaction->find('first', array(
                            'fields' => array('Ardtransaction.id'),
                            'conditions' => array(
                                'Ardtransaction.project_id' => $projectId,
                                'Ardtransaction.type' => 'income',
                                'Ardtransaction.ref_no' => $receiptNo
                            ),
                            'order' => array('Ardtransaction.id' => 'desc'),
                            'recursive' => -1
                        ));
                        if(!empty($txByRef['Ardtransaction']['id']))
                        {
                            $txId = (int)$txByRef['Ardtransaction']['id'];
                            $this->DealsPayment->id = $paymentId;
                            if($this->DealsPayment->saveField('ard_transaction_id', $txId, false))
                            {
                                $summary['links_fixed']++;
                            }
                        }
                    }
                }

                if($txId > 0)
                {
                    $txRow = $this->Ardtransaction->find('first', array(
                        'fields' => array('Ardtransaction.id','Ardtransaction.project_id','Ardtransaction.ledger_id'),
                        'conditions' => array('Ardtransaction.id' => $txId),
                        'recursive' => -1
                    ));
                    if(!empty($txRow['Ardtransaction']['id']) && (int)$txRow['Ardtransaction']['project_id'] === $projectId)
                    {
                        $oldTxLedgerId = (int)$txRow['Ardtransaction']['ledger_id'];
                        if($oldTxLedgerId !== $targetLedgerId)
                        {
                            $this->Ardtransaction->id = $txId;
                            if($this->Ardtransaction->saveField('ledger_id', $targetLedgerId, false))
                            {
                                $summary['transactions_updated']++;
                                if($oldTxLedgerId > 0)
                                {
                                    $touchedLedgerIds[$oldTxLedgerId] = true;
                                }
                            }
                        }

                        $debitName = isset($targetLedgerNameMap[$targetLedgerId]) ? (string)$targetLedgerNameMap[$targetLedgerId] : ($isCash ? 'Cash-inhand' : 'UBL');
                        try
                        {
                            $db = $this->Ardledger->getDataSource();
                            $creditQ = $db->value($debitName, 'string');
                            $this->Ardledger->query("UPDATE `ardaccounts_journal_entries` SET `debit_account`='Income Control', `credit_account`={$creditQ}, `modified`=NOW() WHERE `transaction_id`=".(int)$txId);
                        }
                        catch(Exception $e)
                        {
                            // Journal correction should not stop normalization.
                        }
                    }
                }
            }
            catch(Exception $e)
            {
                $summary['errors']++;
            }
        }

        foreach(array_keys($touchedLedgerIds) as $ledgerId)
        {
            $this->_recalculateLedgerBalance((int)$ledgerId);
        }

        $summary['duplicates_trashed'] = (int)$this->_cleanupDuplicateReceiptLedgers($projectId, array($ublLedgerId, $cashLedgerId));
        return $summary;
    }

    protected function _recalculateLedgerBalance($ledgerId)
    {
        return $this->_ardRecalculateLedgerBalanceCompat($ledgerId);
    }

    protected function _recalculatePurchaseInvoiceStatus($invoiceId)
    {
        $this->loadModel('Admin.Ardpurchaseinvoice');
        $this->loadModel('Admin.Ardpurchaseinvoicepayment');
        $invoiceId = (int)$invoiceId;
        if($invoiceId <= 0)
        {
            return;
        }
        $invoice = $this->Ardpurchaseinvoice->findById($invoiceId);
        if(empty($invoice))
        {
            return;
        }
        $paidRow = $this->Ardpurchaseinvoicepayment->find('first', array(
            'fields' => array('SUM(Ardpurchaseinvoicepayment.amount) AS paid_total'),
            'conditions' => array('Ardpurchaseinvoicepayment.purchase_invoice_id' => $invoiceId),
            'recursive' => -1
        ));
        $paidAmount = 0.0;
        if(isset($paidRow[0]['paid_total']))
        {
            $paidAmount = (float)$paidRow[0]['paid_total'];
        }
        $amount = (float)$invoice['Ardpurchaseinvoice']['amount'];
        $status = 'open';
        if($amount > 0 && $paidAmount >= $amount)
        {
            $status = 'paid';
        }
        elseif($paidAmount > 0)
        {
            $status = 'partial';
        }
        $this->Ardpurchaseinvoice->id = $invoiceId;
        $this->Ardpurchaseinvoice->save(array('Ardpurchaseinvoice' => array(
            'id' => $invoiceId,
            'paid_amount' => $paidAmount,
            'status' => $status
        )), false, array('paid_amount', 'status'));
    }

    protected function _recalculateHrPayrollStatus($payrollId)
    {
        $this->loadModel('Admin.Ardhpayroll');
        $this->loadModel('Admin.Ardhpayment');
        $payrollId = (int)$payrollId;
        if($payrollId <= 0)
        {
            return;
        }
        $payroll = $this->Ardhpayroll->findById($payrollId);
        if(empty($payroll))
        {
            return;
        }
        $paidRow = $this->Ardhpayment->find('first', array(
            'fields' => array('SUM(Ardhpayment.amount) AS paid_total'),
            'conditions' => array('Ardhpayment.payroll_id' => $payrollId),
            'recursive' => -1
        ));
        $paidAmount = 0.0;
        if(isset($paidRow[0]['paid_total']))
        {
            $paidAmount = (float)$paidRow[0]['paid_total'];
        }
        $netPay = (float)$payroll['Ardhpayroll']['net_pay'];
        $due = max(0, $netPay - $paidAmount);
        $status = 'unpaid';
        if($netPay > 0 && $paidAmount >= $netPay)
        {
            $status = 'paid';
        }
        elseif($paidAmount > 0)
        {
            $status = 'partial';
        }
        $this->Ardhpayroll->id = $payrollId;
        $this->Ardhpayroll->save(array('Ardhpayroll' => array(
            'id' => $payrollId,
            'paid_amount' => $paidAmount,
            'due_amount' => $due,
            'status' => $status
        )), false, array('paid_amount', 'due_amount', 'status'));
    }

    protected function _referenceSequenceMap()
    {
        return array(
            'income' => array('prefix_field' => 'income_voucher_prefix', 'next_no_field' => 'income_voucher_next_no'),
            'expense' => array('prefix_field' => 'expense_voucher_prefix', 'next_no_field' => 'expense_voucher_next_no'),
            'payroll_slip' => array('prefix_field' => 'payroll_slip_prefix', 'next_no_field' => 'payroll_slip_next_no'),
            'bill_receipt' => array('prefix_field' => 'bill_receipt_prefix', 'next_no_field' => 'bill_receipt_next_no'),
            'po' => array('prefix_field' => 'po_prefix', 'next_no_field' => 'po_next_no'),
            'grn' => array('prefix_field' => 'grn_prefix', 'next_no_field' => 'grn_next_no'),
            'purchase_invoice' => array('prefix_field' => 'purchase_invoice_prefix', 'next_no_field' => 'purchase_invoice_next_no'),
            'purchase_payment' => array('prefix_field' => 'purchase_payment_prefix', 'next_no_field' => 'purchase_payment_next_no'),
            'journal_voucher' => array('prefix_field' => 'journal_voucher_prefix', 'next_no_field' => 'journal_voucher_next_no'),
            'deal_payment_receipt' => array('prefix_field' => 'deal_payment_receipt_prefix', 'next_no_field' => 'deal_payment_receipt_next_no'),
            'employee_id' => array('prefix_field' => 'employee_code_prefix', 'next_no_field' => 'employee_code_next_no')
        );
    }

    protected function _peekReferenceNo($projectId, $sequenceKey, $fallbackPrefix = 'REF-')
    {
        $this->loadModel('Admin.Ardsetting');
        $projectId = (int)$projectId;
        if($projectId <= 0)
        {
            $fallbackPrefix = trim((string)$fallbackPrefix);
            if($fallbackPrefix === '')
            {
                $fallbackPrefix = 'REF-';
            }
            return $fallbackPrefix . date('YmdHis');
        }

        $sequenceMap = $this->_referenceSequenceMap();
        $sequenceKey = strtolower(trim((string)$sequenceKey));
        if(!isset($sequenceMap[$sequenceKey]))
        {
            $fallbackPrefix = trim((string)$fallbackPrefix);
            if($fallbackPrefix === '')
            {
                $fallbackPrefix = 'REF-';
            }
            return $fallbackPrefix . date('YmdHis');
        }
        if($sequenceKey === 'employee_id')
        {
            $employeeSeq = $this->_employeeCodeSequenceStateRaw($projectId, $fallbackPrefix);
            return $employeeSeq['prefix'] . $employeeSeq['next_no'];
        }

        $prefixField = $sequenceMap[$sequenceKey]['prefix_field'];
        $nextNoField = $sequenceMap[$sequenceKey]['next_no_field'];
        $defaults = $this->_defaultSettings();

        $settingRow = $this->Ardsetting->find('first', array(
            'conditions' => array('Ardsetting.project_id' => $projectId),
            'recursive' => -1
        ));
        $settingData = $defaults;
        if(!empty($settingRow['Ardsetting']))
        {
            $settingData = array_merge($settingData, $settingRow['Ardsetting']);
        }

        $prefix = trim((string)(isset($settingData[$prefixField]) ? $settingData[$prefixField] : ''));
        if($prefix === '')
        {
            $prefix = isset($defaults[$prefixField]) ? (string)$defaults[$prefixField] : trim((string)$fallbackPrefix);
        }
        if($prefix === '')
        {
            $prefix = 'REF-';
        }
        if(strlen($prefix) > 20)
        {
            $prefix = substr($prefix, 0, 20);
        }
        $nextNo = max(1, (int)(isset($settingData[$nextNoField]) ? $settingData[$nextNoField] : 1));
        return $prefix . $nextNo;
    }

    protected function _nextReferenceNo($projectId, $sequenceKey, $fallbackPrefix = 'REF-')
    {
        $this->loadModel('Admin.Ardsetting');
        $projectId = (int)$projectId;
        if($projectId <= 0)
        {
            $fallbackPrefix = trim((string)$fallbackPrefix);
            if($fallbackPrefix === '')
            {
                $fallbackPrefix = 'REF-';
            }
            return $fallbackPrefix . date('YmdHis');
        }

        $sequenceMap = $this->_referenceSequenceMap();
        $sequenceKey = strtolower(trim((string)$sequenceKey));
        if(!isset($sequenceMap[$sequenceKey]))
        {
            $fallbackPrefix = trim((string)$fallbackPrefix);
            if($fallbackPrefix === '')
            {
                $fallbackPrefix = 'REF-';
            }
            return $fallbackPrefix . date('YmdHis');
        }
        if($sequenceKey === 'employee_id')
        {
            $employeeSeq = $this->_employeeCodeSequenceStateRaw($projectId, $fallbackPrefix);
            $prefix = (string)$employeeSeq['prefix'];
            $nextNo = max(1, (int)$employeeSeq['next_no']);
            $refNo = $prefix . $nextNo;
            $saveNextNo = $nextNo + 1;
            $settingId = (int)$employeeSeq['setting_id'];
            $prefixQ = $this->Ardsetting->getDataSource()->value($prefix, 'string');
            if($settingId > 0)
            {
                $this->Ardsetting->query("UPDATE `ardaccounts_settings` SET `employee_code_prefix`={$prefixQ}, `employee_code_next_no`=".(int)$saveNextNo." WHERE `id`=".(int)$settingId." LIMIT 1");
            }
            else
            {
                $this->Ardsetting->query("INSERT INTO `ardaccounts_settings` (`project_id`, `employee_code_prefix`, `employee_code_next_no`) VALUES (".(int)$projectId.", {$prefixQ}, ".(int)$saveNextNo.")");
            }
            return $refNo;
        }

        $prefixField = $sequenceMap[$sequenceKey]['prefix_field'];
        $nextNoField = $sequenceMap[$sequenceKey]['next_no_field'];
        $defaults = $this->_defaultSettings();

        $settingRow = $this->Ardsetting->find('first', array(
            'conditions' => array('Ardsetting.project_id' => $projectId),
            'recursive' => -1
        ));
        $settingData = $defaults;
        if(!empty($settingRow['Ardsetting']))
        {
            $settingData = array_merge($settingData, $settingRow['Ardsetting']);
        }

        $prefix = trim((string)(isset($settingData[$prefixField]) ? $settingData[$prefixField] : ''));
        if($prefix === '')
        {
            $prefix = isset($defaults[$prefixField]) ? (string)$defaults[$prefixField] : trim((string)$fallbackPrefix);
        }
        if($prefix === '')
        {
            $prefix = 'REF-';
        }
        if(strlen($prefix) > 20)
        {
            $prefix = substr($prefix, 0, 20);
        }

        $nextNo = max(1, (int)(isset($settingData[$nextNoField]) ? $settingData[$nextNoField] : 1));
        $refNo = $prefix . $nextNo;

        $settingData[$prefixField] = $prefix;
        $settingData[$nextNoField] = $nextNo + 1;
        $settingData['project_id'] = $projectId;
        if(!empty($settingRow['Ardsetting']['id']))
        {
            $settingData['id'] = (int)$settingRow['Ardsetting']['id'];
        }

        $this->Ardsetting->create();
        $this->Ardsetting->save(array('Ardsetting' => $settingData), false);

        return $refNo;
    }

    protected function _employeeCodeSequenceStateRaw($projectId, $fallbackPrefix = 'EMP-')
    {
        $this->loadModel('Admin.Ardsetting');
        $projectId = (int)$projectId;
        $fallbackPrefix = trim((string)$fallbackPrefix);
        if($fallbackPrefix === '')
        {
            $fallbackPrefix = 'EMP-';
        }
        if(strlen($fallbackPrefix) > 20)
        {
            $fallbackPrefix = substr($fallbackPrefix, 0, 20);
        }

        $defaults = $this->_defaultSettings();
        $prefix = trim((string)(isset($defaults['employee_code_prefix']) ? $defaults['employee_code_prefix'] : $fallbackPrefix));
        if($prefix === '')
        {
            $prefix = $fallbackPrefix;
        }
        if(strlen($prefix) > 20)
        {
            $prefix = substr($prefix, 0, 20);
        }
        $nextNo = max(1, (int)(isset($defaults['employee_code_next_no']) ? $defaults['employee_code_next_no'] : 1));
        $settingId = 0;

        $rows = (array)$this->Ardsetting->query("SELECT `id`, `employee_code_prefix`, `employee_code_next_no` FROM `ardaccounts_settings` WHERE `project_id`=".(int)$projectId." ORDER BY `id` DESC LIMIT 1");
        if(!empty($rows))
        {
            $row = (array)$rows[0];
            if(isset($row['ardaccounts_settings']) && is_array($row['ardaccounts_settings']))
            {
                $row = (array)$row['ardaccounts_settings'];
            }
            elseif(isset($row['Ardsetting']) && is_array($row['Ardsetting']))
            {
                $row = (array)$row['Ardsetting'];
            }
            elseif(isset($row[0]) && is_array($row[0]))
            {
                $row = (array)$row[0];
            }
            if(isset($row['id']))
            {
                $settingId = (int)$row['id'];
            }
            $dbPrefix = trim((string)(isset($row['employee_code_prefix']) ? $row['employee_code_prefix'] : ''));
            if($dbPrefix !== '')
            {
                $prefix = (strlen($dbPrefix) > 20) ? substr($dbPrefix, 0, 20) : $dbPrefix;
            }
            $dbNextNo = isset($row['employee_code_next_no']) ? (int)$row['employee_code_next_no'] : 0;
            if($dbNextNo > 0)
            {
                $nextNo = $dbNextNo;
            }
        }

        return array(
            'setting_id' => (int)$settingId,
            'prefix' => (string)$prefix,
            'next_no' => (int)$nextNo
        );
    }

    protected function _nextVoucherReferenceNo($projectId, $type = 'expense')
    {
        $txType = (strtolower(trim((string)$type)) === 'income') ? 'income' : 'expense';
        return $this->_nextReferenceNo((int)$projectId, $txType, ($txType === 'income' ? 'INC-' : 'EXP-'));
    }

    protected function _syncJournalForTransaction($transactionId, $sourceType = 'voucher', $sourceId = 0)
    {
        $this->loadModel('Admin.Ardtransaction');
        $this->loadModel('Admin.Ardledger');
        $this->loadModel('Admin.Ardjournalentry');

        $transactionId = (int)$transactionId;
        if($transactionId <= 0)
        {
            return false;
        }

        $tx = $this->Ardtransaction->find('first', array(
            'conditions' => array('Ardtransaction.id' => $transactionId),
            'recursive' => -1
        ));
        if(empty($tx['Ardtransaction']))
        {
            return false;
        }
        $tx = $tx['Ardtransaction'];

        $ledgerName = 'Ledger #' . (int)$tx['ledger_id'];
        if((int)$tx['ledger_id'] > 0)
        {
            $ledger = $this->Ardledger->find('first', array(
                'fields' => array('Ardledger.name'),
                'conditions' => array('Ardledger.id' => (int)$tx['ledger_id']),
                'recursive' => -1
            ));
            if(!empty($ledger['Ardledger']['name']))
            {
                $ledgerName = trim((string)$ledger['Ardledger']['name']);
            }
        }
        $expenseLedgerName = '';
        $expenseLedgerId = isset($tx['expense_ledger_id']) ? (int)$tx['expense_ledger_id'] : 0;
        if($expenseLedgerId > 0)
        {
            $expenseLedger = $this->Ardledger->find('first', array(
                'fields' => array('Ardledger.name'),
                'conditions' => array('Ardledger.id' => $expenseLedgerId),
                'recursive' => -1
            ));
            if(!empty($expenseLedger['Ardledger']['name']))
            {
                $expenseLedgerName = trim((string)$expenseLedger['Ardledger']['name']);
            }
        }
        $incomeLedgerName = '';
        $incomeLedgerId = isset($tx['income_ledger_id']) ? (int)$tx['income_ledger_id'] : 0;
        if($incomeLedgerId > 0)
        {
            $incomeLedger = $this->Ardledger->find('first', array(
                'fields' => array('Ardledger.name'),
                'conditions' => array('Ardledger.id' => $incomeLedgerId),
                'recursive' => -1
            ));
            if(!empty($incomeLedger['Ardledger']['name']))
            {
                $incomeLedgerName = trim((string)$incomeLedger['Ardledger']['name']);
            }
        }

        $txType = strtolower(trim((string)$tx['type']));
        if($txType === 'income')
        {
            $debitAccount = $ledgerName;
            $creditAccount = ($incomeLedgerName !== '') ? $incomeLedgerName : 'Income Control';
            if($debitAccount === $creditAccount)
            {
                $debitAccount = 'General Receipt Account';
            }
        }
        else
        {
            $debitAccount = ($expenseLedgerName !== '') ? $expenseLedgerName : 'Expense Control';
            $creditAccount = $ledgerName;
            if($debitAccount === $creditAccount)
            {
                $creditAccount = 'Cash-inhand';
            }
        }

        $row = array(
            'project_id' => (int)$tx['project_id'],
            'transaction_id' => $transactionId,
            'source_type' => substr(trim((string)$sourceType), 0, 40),
            'source_id' => (int)$sourceId,
            'ref_no' => trim((string)$tx['ref_no']),
            'entry_date' => trim((string)$tx['entry_date']),
            'debit_account' => substr($debitAccount, 0, 160),
            'credit_account' => substr($creditAccount, 0, 160),
            'amount' => round((float)$tx['amount'], 2),
            'description' => trim((string)$tx['description'])
        );

        $exists = $this->Ardjournalentry->find('first', array(
            'fields' => array('Ardjournalentry.id'),
            'conditions' => array('Ardjournalentry.transaction_id' => $transactionId),
            'recursive' => -1
        ));
        if(!empty($exists['Ardjournalentry']['id']))
        {
            $row['id'] = (int)$exists['Ardjournalentry']['id'];
        }

        $this->Ardjournalentry->create();
        return (bool)$this->Ardjournalentry->save(array('Ardjournalentry' => $row), false);
    }

    protected function _deleteJournalForTransaction($transactionId)
    {
        $this->loadModel('Admin.Ardjournalentry');
        $transactionId = (int)$transactionId;
        if($transactionId <= 0)
        {
            return;
        }
        $this->Ardjournalentry->deleteAll(array('Ardjournalentry.transaction_id' => $transactionId), false);
    }

    protected function _buildTrashEntryTitle($modelAlias, $recordData)
    {
        $recordData = is_array($recordData) ? $recordData : array();
        $titleFields = array(
            'name',
            'title',
            'vendor_name',
            'site_name',
            'full_name',
            'template_name',
            'invoice_no',
            'po_no',
            'grn_no',
            'ref_no',
            'party_name',
            'budget_month',
            'payroll_month',
            'material_type'
        );
        foreach($titleFields as $field)
        {
            if(isset($recordData[$field]) && trim((string)$recordData[$field]) !== '')
            {
                return trim((string)$recordData[$field]);
            }
        }
        if(isset($recordData['id']) && (int)$recordData['id'] > 0)
        {
            return trim((string)$modelAlias) . ' #' . (int)$recordData['id'];
        }
        return trim((string)$modelAlias) !== '' ? trim((string)$modelAlias) : 'Record';
    }

    protected function _ensureTrashTable()
    {
        $this->loadModel('Admin.Ardledger');
        $sql = "CREATE TABLE IF NOT EXISTS `ardaccounts_trash_bin` (
            `id` bigint(20) NOT NULL AUTO_INCREMENT,
            `project_id` int(11) NOT NULL DEFAULT 0,
            `source_table` varchar(120) NOT NULL,
            `source_model` varchar(80) DEFAULT '',
            `source_id` bigint(20) NOT NULL DEFAULT 0,
            `entry_title` varchar(255) DEFAULT '',
            `payload_json` longtext,
            `deleted_by` int(11) NOT NULL DEFAULT 0,
            `deleted_at` datetime DEFAULT NULL,
            `created` datetime DEFAULT NULL,
            `modified` datetime DEFAULT NULL,
            PRIMARY KEY (`id`),
            KEY `project_id` (`project_id`),
            KEY `source_table` (`source_table`),
            KEY `source_id` (`source_id`),
            KEY `deleted_at` (`deleted_at`)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3";
        try
        {
            $this->Ardledger->query($sql);
        }
        catch(Exception $e)
        {
            // Keep flow alive if DB does not allow create/alter operations.
        }
    }

    protected function _canAccessTrashEntry($trashRecord)
    {
        $trashRecord = is_array($trashRecord) ? $trashRecord : array();
        $projectId = isset($trashRecord['project_id']) ? (int)$trashRecord['project_id'] : 0;
        if($this->userType === 'ADR')
        {
            if($projectId > 0 && !$this->_isAllowedProject($projectId))
            {
                return false;
            }
            return true;
        }
        if($projectId > 0 && !$this->_isAllowedProject($projectId))
        {
            return false;
        }
        return ((int)$this->luserId > 0 && (int)$trashRecord['deleted_by'] === (int)$this->luserId);
    }

    protected function _storeTrashRecord($tableName, $modelAlias, $recordData, $entryTitle = '', $extraData = array())
    {
        $tableName = strtolower(trim((string)$tableName));
        if($tableName === '' || strpos($tableName, 'ardaccounts_') !== 0)
        {
            return false;
        }
        $recordData = is_array($recordData) ? $recordData : array();
        if(empty($recordData))
        {
            return false;
        }
        $projectId = isset($recordData['project_id']) ? (int)$recordData['project_id'] : 0;
        if($projectId <= 0 || !$this->_isAllowedProject($projectId))
        {
            return false;
        }
        $this->_ensureTrashTable();
        $this->loadModel('Admin.Ardtrash');
        $payload = array('record' => $recordData);
        if(is_array($extraData) && !empty($extraData))
        {
            $payload['extra'] = $extraData;
        }
        $payloadJson = json_encode($payload);
        if($payloadJson === false)
        {
            $payloadJson = json_encode(array('record' => array()));
        }
        if($payloadJson === false)
        {
            $payloadJson = '{"record":{}}';
        }
        $row = array(
            'project_id' => $projectId,
            'source_table' => $tableName,
            'source_model' => trim((string)$modelAlias),
            'source_id' => isset($recordData['id']) ? (int)$recordData['id'] : 0,
            'entry_title' => trim((string)$entryTitle) !== '' ? trim((string)$entryTitle) : $this->_buildTrashEntryTitle($modelAlias, $recordData),
            'payload_json' => $payloadJson,
            'deleted_by' => isset($this->luserId) ? (int)$this->luserId : 0,
            'deleted_at' => date('Y-m-d H:i:s')
        );
        $this->Ardtrash->create();
        return (bool)$this->Ardtrash->save(array('Ardtrash' => $row), false);
    }

    protected function _trashPayloadDecode($payloadJson)
    {
        $payloadJson = trim((string)$payloadJson);
        if($payloadJson === '')
        {
            return array();
        }
        $payload = json_decode($payloadJson, true);
        return is_array($payload) ? $payload : array();
    }

    protected function _trashTextValueFromFields($source, $fields = array())
    {
        $source = is_array($source) ? $source : array();
        foreach((array)$fields as $field)
        {
            $field = trim((string)$field);
            if($field === '')
            {
                continue;
            }
            if(isset($source[$field]) && trim((string)$source[$field]) !== '')
            {
                return trim((string)$source[$field]);
            }
        }
        return '';
    }

    protected function _trashDisplayTitleParts($trashRow)
    {
        $trash = isset($trashRow['Ardtrash']) ? (array)$trashRow['Ardtrash'] : array();
        $entryTitle = isset($trash['entry_title']) ? trim((string)$trash['entry_title']) : '';
        $sourceModel = isset($trash['source_model']) ? (string)$trash['source_model'] : '';
        $sourceTable = isset($trash['source_table']) ? strtolower(trim((string)$trash['source_table'])) : '';
        $payload = $this->_trashPayloadDecode(isset($trash['payload_json']) ? $trash['payload_json'] : '');
        $record = (isset($payload['record']) && is_array($payload['record'])) ? $payload['record'] : array();
        $extra = (isset($payload['extra']) && is_array($payload['extra'])) ? $payload['extra'] : array();

        if($sourceTable === 'deals_payments' || strtolower($sourceModel) === 'dealspayment')
        {
            $receiptNo = $this->_trashTextValueFromFields($record, array('receipt_no','ref_no','reference_no','voucher_no'));
            if($receiptNo === '')
            {
                $receiptNo = $this->_trashTextValueFromFields($extra, array('receipt_no','ref_no','reference_no','voucher_no'));
            }
            $clientName = $this->_trashTextValueFromFields($extra, array('client_name','customer_name','member_name','buyer_name'));
            $dealInvoice = $this->_trashTextValueFromFields($extra, array('deal_invoice_no','invoice_no','membership_no'));
            $propertyName = $this->_trashTextValueFromFields($extra, array('property_name','file_name'));
            $dealId = isset($record['deal_id']) ? (int)$record['deal_id'] : 0;
            if(($clientName === '' || $dealInvoice === '' || $propertyName === '') && $dealId>0)
            {
                try
                {
                    $dealRows = (array)$this->Ardledger->query(
                        "SELECT `Deal`.`invoice_no`, `Client`.`name` AS client_name, `Property`.`name` AS property_name ".
                        "FROM `deals` AS `Deal` ".
                        "LEFT JOIN `clients` AS `Client` ON `Client`.`id`=`Deal`.`client_id` ".
                        "LEFT JOIN `properties` AS `Property` ON `Property`.`id`=`Deal`.`property_id` ".
                        "WHERE `Deal`.`id`=".$dealId." LIMIT 1"
                    );
                    if(!empty($dealRows[0][0]))
                    {
                        $dealInfo = $dealRows[0][0];
                        if($clientName === '' && !empty($dealInfo['client_name']))$clientName = trim((string)$dealInfo['client_name']);
                        if($dealInvoice === '' && !empty($dealInfo['invoice_no']))$dealInvoice = trim((string)$dealInfo['invoice_no']);
                        if($propertyName === '' && !empty($dealInfo['property_name']))$propertyName = trim((string)$dealInfo['property_name']);
                    }
                }
                catch(Exception $e)
                {
                    // Fall back to payload-only display.
                }
            }
            $amount = $this->_trashTextValueFromFields($record, array('amount','total_amount','emi'));
            $paymentDate = $this->_trashTextValueFromFields($record, array('payment_date','date'));
            $titleParts = array();
            if($receiptNo !== '')$titleParts[] = __('Receipt').': '.$receiptNo;
            if($clientName !== '')$titleParts[] = __('Client').': '.$clientName;
            if(empty($titleParts) && $entryTitle !== '')$titleParts[] = $entryTitle;
            $metaParts = array();
            if($dealInvoice !== '')$metaParts[] = __('Membership').': '.$dealInvoice;
            if($propertyName !== '')$metaParts[] = __('Property').': '.$propertyName;
            if($amount !== '')$metaParts[] = __('Amount').': '.$amount;
            if($paymentDate !== '')$metaParts[] = __('Date').': '.$paymentDate;
            return array(!empty($titleParts) ? implode(' | ', $titleParts) : __('Deleted Payment'), implode(' | ', $metaParts));
        }

        $clientName = $this->_trashTextValueFromFields($extra, array(
            'client_name','customer_name','member_name','contact_name','applicant_name','buyer_name'
        ));
        if($clientName === '')
        {
            $clientName = $this->_trashTextValueFromFields($record, array(
                'client_name','customer_name','member_name','contact_name','applicant_name','buyer_name','party_name','full_name','name'
            ));
        }

        if($clientName !== '')
        {
            $meta = '';
            if($entryTitle !== '' && strcasecmp($clientName, $entryTitle) !== 0)
            {
                $meta = $entryTitle;
            }
            return array($clientName, $meta);
        }

        $displayTitle = $entryTitle;
        if($displayTitle === '')
        {
            $displayTitle = $this->_buildTrashEntryTitle($sourceModel, $record);
        }
        if($displayTitle === '')
        {
            $displayTitle = __('Untitled Record');
        }
        return array($displayTitle, '');
    }

    protected function _trashDisplayDetails($trashRow, $ledgerNames = array())
    {
        $trash = isset($trashRow['Ardtrash']) ? (array)$trashRow['Ardtrash'] : array();
        $payload = $this->_trashPayloadDecode(isset($trash['payload_json']) ? $trash['payload_json'] : '');
        $record = (isset($payload['record']) && is_array($payload['record'])) ? $payload['record'] : array();
        $details = array();
        $usedFields = array();

        $append = function($label, $value, $field = '', $format = 'text') use (&$details, &$usedFields) {
            if(is_array($value) || is_object($value) || $value === null || trim((string)$value) === '')
            {
                return;
            }
            $value = trim((string)$value);
            if($format === 'date' && $value !== '0000-00-00' && $value !== '0000-00-00 00:00:00')
            {
                $timestamp = strtotime($value);
                if($timestamp !== false)
                {
                    $value = date((strlen($value) > 10 ? 'd-M-Y h:i A' : 'd-M-Y'), $timestamp);
                }
            }
            elseif($format === 'amount' && is_numeric(str_replace(',', '', $value)))
            {
                $number = (float)str_replace(',', '', $value);
                $value = 'Rs ' . number_format($number, ($number == floor($number) ? 0 : 2));
            }
            $details[] = array('label' => $label, 'value' => $value);
            if($field !== '')
            {
                $usedFields[$field] = true;
            }
        };

        $sourceTable = strtolower(trim((string)(isset($trash['source_table']) ? $trash['source_table'] : '')));
        if($sourceTable === 'ardaccounts_transactions')
        {
            $append(__('Reference'), isset($record['ref_no']) ? $record['ref_no'] : '', 'ref_no');
            $append(__('Date'), isset($record['entry_date']) ? $record['entry_date'] : '', 'entry_date', 'date');
            $append(__('Type'), isset($record['type']) ? ucfirst((string)$record['type']) : '', 'type');
            $append(__('Status'), isset($record['status']) ? ucfirst((string)$record['status']) : '', 'status');
            $append(__('Amount'), isset($record['amount']) ? $record['amount'] : '', 'amount', 'amount');
            $ledgerFields = array(
                'ledger_id' => __('Asset / Bank'),
                'expense_ledger_id' => __('Expense Account'),
                'income_ledger_id' => __('Income Account')
            );
            foreach($ledgerFields as $field => $label)
            {
                $ledgerId = isset($record[$field]) ? (int)$record[$field] : 0;
                if($ledgerId > 0)
                {
                    $ledgerLabel = isset($ledgerNames[$ledgerId]) ? $ledgerNames[$ledgerId] : __('Ledger #%d', $ledgerId);
                    $append($label, $ledgerLabel, $field);
                }
            }
            $append(__('Description'), isset($record['description']) ? $record['description'] : '', 'description');
        }

        $fieldMap = array(
            'receipt_no' => array(__('Receipt No.'), 'text'),
            'voucher_no' => array(__('Voucher No.'), 'text'),
            'ref_no' => array(__('Reference'), 'text'),
            'reference_no' => array(__('Reference'), 'text'),
            'invoice_no' => array(__('Invoice No.'), 'text'),
            'po_no' => array(__('PO No.'), 'text'),
            'grn_no' => array(__('GRN No.'), 'text'),
            'entry_date' => array(__('Date'), 'date'),
            'payment_date' => array(__('Payment Date'), 'date'),
            'date' => array(__('Date'), 'date'),
            'due_date' => array(__('Due Date'), 'date'),
            'type' => array(__('Type'), 'text'),
            'status' => array(__('Status'), 'text'),
            'vendor_name' => array(__('Vendor'), 'text'),
            'party_name' => array(__('Party'), 'text'),
            'client_name' => array(__('Client'), 'text'),
            'name' => array(__('Name'), 'text'),
            'amount' => array(__('Amount'), 'amount'),
            'total_amount' => array(__('Total Amount'), 'amount'),
            'paid_amount' => array(__('Paid Amount'), 'amount'),
            'balance' => array(__('Balance'), 'amount'),
            'quantity' => array(__('Quantity'), 'text'),
            'rate' => array(__('Rate'), 'amount'),
            'description' => array(__('Description'), 'text'),
            'remarks' => array(__('Remarks'), 'text'),
            'notes' => array(__('Notes'), 'text')
        );
        foreach($fieldMap as $field => $definition)
        {
            if(isset($usedFields[$field]) || !array_key_exists($field, $record))
            {
                continue;
            }
            $append($definition[0], $record[$field], $field, $definition[1]);
        }
        return $details;
    }

    protected function _trashTableColumns($tableName)
    {
        static $cache = array();
        $tableName = preg_replace('/[^a-zA-Z0-9_]/', '', strtolower(trim((string)$tableName)));
        if($tableName === '')
        {
            return array();
        }
        if(isset($cache[$tableName]))
        {
            return $cache[$tableName];
        }
        $columns = array();
        try
        {
            $rows = $this->Ardledger->query('SHOW COLUMNS FROM `' . $tableName . '`');
            foreach((array)$rows as $row)
            {
                if(isset($row[0]['Field']))
                {
                    $columns[] = $row[0]['Field'];
                }
                elseif(isset($row['COLUMNS']['Field']))
                {
                    $columns[] = $row['COLUMNS']['Field'];
                }
                else
                {
                    foreach((array)$row as $chunk)
                    {
                        if(is_array($chunk))
                        {
                            if(isset($chunk['Field']))
                            {
                                $columns[] = $chunk['Field'];
                                continue;
                            }
                            foreach($chunk as $chunkKey => $chunkVal)
                            {
                                if(strtolower((string)$chunkKey) === 'field')
                                {
                                    $columns[] = (string)$chunkVal;
                                    break;
                                }
                            }
                        }
                    }
                }
            }
        }
        catch(Exception $e)
        {
            $columns = array();
        }
        if(empty($columns))
        {
            try
            {
                $dbName = '';
                if(isset($this->Ardledger->useDbConfig))
                {
                    $source = ConnectionManager::getDataSource($this->Ardledger->useDbConfig);
                    if(!empty($source->config['database']))
                    {
                        $dbName = (string)$source->config['database'];
                    }
                }
                if($dbName === '')
                {
                    $dbName = (string)$this->Ardledger->query('SELECT DATABASE() AS dbname')[0][0]['dbname'];
                }
                if($dbName !== '')
                {
                    $dbName = preg_replace('/[^a-zA-Z0-9_]/', '', $dbName);
                    $metaRows = $this->Ardledger->query(
                        "SELECT COLUMN_NAME FROM information_schema.columns WHERE table_schema='" . $dbName . "' AND table_name='" . $tableName . "' ORDER BY ORDINAL_POSITION"
                    );
                    foreach((array)$metaRows as $metaRow)
                    {
                        if(isset($metaRow[0]['COLUMN_NAME']))
                        {
                            $columns[] = $metaRow[0]['COLUMN_NAME'];
                        }
                        elseif(isset($metaRow['columns']['COLUMN_NAME']))
                        {
                            $columns[] = $metaRow['columns']['COLUMN_NAME'];
                        }
                    }
                }
            }
            catch(Exception $e)
            {
                $columns = array();
            }
        }
        $columns = array_values(array_unique(array_filter(array_map('trim', (array)$columns))));
        $cache[$tableName] = $columns;
        return $columns;
    }

    protected function _trashInsertRecord($tableName, $recordData, &$error, $allowExistingId = false)
    {
        $error = '';
        $tableName = preg_replace('/[^a-zA-Z0-9_]/', '', strtolower(trim((string)$tableName)));
        if($tableName === '' || $tableName === 'ardaccounts_trash_bin')
        {
            $error = __('Invalid trash table.');
            return false;
        }
        $recordData = is_array($recordData) ? $recordData : array();
        if(empty($recordData))
        {
            $error = __('Trash record is empty.');
            return false;
        }
        $columns = $this->_trashTableColumns($tableName);
        if(empty($columns))
        {
            $error = __('Target table not found for restore.');
            return false;
        }
        $row = array();
        foreach($recordData as $field => $value)
        {
            if(in_array($field, $columns, true))
            {
                $row[$field] = $value;
            }
        }
        if(empty($row))
        {
            $error = __('No compatible fields found for restore.');
            return false;
        }
        if(isset($row['id']) && (int)$row['id'] > 0)
        {
            $exists = $this->Ardledger->query('SELECT `id` FROM `' . $tableName . '` WHERE `id`=' . (int)$row['id'] . ' LIMIT 1');
            if(!empty($exists))
            {
                if($allowExistingId)
                {
                    return true;
                }
                $error = __('Record already exists in target table.');
                return false;
            }
        }
        $ds = $this->Ardledger->getDataSource();
        $fieldSql = array();
        $valueSql = array();
        foreach($row as $field => $value)
        {
            $fieldSql[] = '`' . preg_replace('/[^a-zA-Z0-9_]/', '', $field) . '`';
            $valueSql[] = $ds->value($value);
        }
        $sql = 'INSERT INTO `' . $tableName . '` (' . implode(',', $fieldSql) . ') VALUES (' . implode(',', $valueSql) . ')';
        try
        {
            $this->Ardledger->query($sql);
        }
        catch(Exception $e)
        {
            $error = $e->getMessage();
            return false;
        }
        return true;
    }

    protected function _afterTrashRestore($tableName, $recordData, $extraData = array())
    {
        $tableName = strtolower(trim((string)$tableName));
        $recordData = is_array($recordData) ? $recordData : array();
        $extraData = is_array($extraData) ? $extraData : array();

        if($tableName === 'ardaccounts_transactions')
        {
            $ledgerId = isset($recordData['ledger_id']) ? (int)$recordData['ledger_id'] : 0;
            $expenseLedgerId = isset($recordData['expense_ledger_id']) ? (int)$recordData['expense_ledger_id'] : 0;
            $txType = strtolower(trim((string)(isset($recordData['type']) ? $recordData['type'] : '')));
            $transactionId = isset($recordData['id']) ? (int)$recordData['id'] : 0;
            $sourceType = isset($extraData['journal_source_type']) ? trim((string)$extraData['journal_source_type']) : 'voucher';
            $sourceId = isset($extraData['journal_source_id']) ? (int)$extraData['journal_source_id'] : $transactionId;
            if($transactionId > 0)
            {
                $this->_syncJournalForTransaction($transactionId, $sourceType !== '' ? $sourceType : 'voucher', $sourceId > 0 ? $sourceId : $transactionId);
            }
            if($ledgerId > 0)
            {
                $this->_recalculateLedgerBalance($ledgerId);
            }
            if($txType === 'expense' && $expenseLedgerId > 0 && $expenseLedgerId !== $ledgerId)
            {
                $this->_recalculateLedgerBalance($expenseLedgerId);
            }
            $this->_restoreDealRefundSchedulesForVoucher($recordData);
            return;
        }

        if($tableName === 'ardaccounts_construction_purchase_invoice_payments')
        {
            $invoiceId = isset($recordData['purchase_invoice_id']) ? (int)$recordData['purchase_invoice_id'] : 0;
            if($invoiceId > 0)
            {
                $this->_recalculatePurchaseInvoiceStatus($invoiceId);
            }
            if(!empty($extraData['linked_transaction']) && is_array($extraData['linked_transaction']))
            {
                $linkedLedgerId = isset($extraData['linked_transaction']['ledger_id']) ? (int)$extraData['linked_transaction']['ledger_id'] : 0;
                if($linkedLedgerId > 0)
                {
                    $this->_recalculateLedgerBalance($linkedLedgerId);
                }
            }
            return;
        }

        if($tableName === 'ardaccounts_hr_payments')
        {
            $payrollId = isset($recordData['payroll_id']) ? (int)$recordData['payroll_id'] : 0;
            if($payrollId > 0)
            {
                $this->_recalculateHrPayrollStatus($payrollId);
            }
            if(!empty($extraData['linked_transaction']) && is_array($extraData['linked_transaction']))
            {
                $linkedLedgerId = isset($extraData['linked_transaction']['ledger_id']) ? (int)$extraData['linked_transaction']['ledger_id'] : 0;
                if($linkedLedgerId > 0)
                {
                    $this->_recalculateLedgerBalance($linkedLedgerId);
                }
            }
            return;
        }

        if($tableName === 'ardaccounts_templates')
        {
            $projectId = isset($recordData['project_id']) ? (int)$recordData['project_id'] : 0;
            $templateType = isset($recordData['template_type']) ? trim((string)$recordData['template_type']) : '';
            $templateId = isset($recordData['id']) ? (int)$recordData['id'] : 0;
            if($projectId > 0 && $templateType !== '')
            {
                if(!empty($recordData['is_active']))
                {
                    $this->_syncSingleActiveTemplate($projectId, $templateType, $templateId);
                }
                else
                {
                    $this->_syncSingleActiveTemplate($projectId, $templateType, 0);
                }
            }
            return;
        }
    }

    protected function _restoreTrashRecord($trashRow, &$error)
    {
        $error = '';
        if(empty($trashRow['Ardtrash']))
        {
            $error = __('Invalid trash entry.');
            return false;
        }
        $trash = $trashRow['Ardtrash'];
        if(!$this->_canAccessTrashEntry($trash))
        {
            $error = __('Permission denied for trash restore.');
            return false;
        }
        $projectId = isset($trash['project_id']) ? (int)$trash['project_id'] : 0;
        $this->_ensureTrashTable();
        $this->loadModel('Admin.Ardtrash');
        $tableName = strtolower(trim((string)$trash['source_table']));
        $payload = $this->_trashPayloadDecode(isset($trash['payload_json']) ? $trash['payload_json'] : '');
        $recordData = (isset($payload['record']) && is_array($payload['record'])) ? $payload['record'] : array();
        $extraData = (isset($payload['extra']) && is_array($payload['extra'])) ? $payload['extra'] : array();
        if(empty($recordData))
        {
            $error = __('Trash payload is missing record data.');
            return false;
        }
        if(!isset($recordData['project_id']) || (int)$recordData['project_id'] <= 0)
        {
            $recordData['project_id'] = $projectId;
        }

        $ds = $this->Ardledger->getDataSource();
        $ds->begin();

        if(!$this->_trashInsertRecord($tableName, $recordData, $error, false))
        {
            $ds->rollback();
            return false;
        }

        if(!empty($extraData['linked_transaction']) && is_array($extraData['linked_transaction']))
        {
            $txError = '';
            if(!$this->_trashInsertRecord('ardaccounts_transactions', $extraData['linked_transaction'], $txError, true))
            {
                $error = $txError;
                $ds->rollback();
                return false;
            }
            $linkedTxId = isset($extraData['linked_transaction']['id']) ? (int)$extraData['linked_transaction']['id'] : 0;
            if($linkedTxId > 0)
            {
                $this->_syncJournalForTransaction($linkedTxId, 'voucher', $linkedTxId);
            }
        }

        if(!$this->Ardtrash->delete((int)$trash['id']))
        {
            $ds->rollback();
            $error = __('Unable to clear trash item after restore.');
            return false;
        }

        $ds->commit();
        $this->_afterTrashRestore($tableName, $recordData, $extraData);
        return true;
    }

    protected function _restoreDealRefundSchedulesForVoucher($transactionData)
    {
        $transactionData = is_array($transactionData) ? $transactionData : array();
        $transactionId = isset($transactionData['id']) ? (int)$transactionData['id'] : 0;
        if($transactionId <= 0)
        {
            return 0;
        }
        $this->loadModel('Admin.Dealrefundschedule');
        $conditions = array('OR' => array(
            'Dealrefundschedule.voucher_transaction_id' => $transactionId,
            'Dealrefundschedule.remarks LIKE' => '%voucher #'.$transactionId.'%'
        ));

        $description = isset($transactionData['description']) ? (string)$transactionData['description'] : '';
        $dealId = 0;
        $cycleNo = 0;
        if(preg_match('/Deal\s+#?([0-9]+)/i', $description, $m))
        {
            $dealId = (int)$m[1];
        }
        if(preg_match('/Cycle\s+([0-9]+)/i', $description, $m))
        {
            $cycleNo = (int)$m[1];
        }
        if($dealId > 0 && $cycleNo > 0)
        {
            $conditions['OR'][] = array(
                'Dealrefundschedule.deal_id' => $dealId,
                'Dealrefundschedule.cycle_no' => $cycleNo
            );
        }

        $scheduleRow = $this->Dealrefundschedule->find('first', array(
            'conditions' => $conditions,
            'order' => array(
                'CASE WHEN Dealrefundschedule.remarks LIKE "%voucher #'.$transactionId.'%" THEN 0 ELSE 1 END',
                'Dealrefundschedule.id' => 'desc'
            ),
            'recursive' => -1
        ));
        if(empty($scheduleRow['Dealrefundschedule']['id']))
        {
            return 0;
        }

        $schedule = $scheduleRow['Dealrefundschedule'];
        $paidAmount = isset($transactionData['amount']) ? round((float)$transactionData['amount'], 2) : 0.0;
        if($paidAmount <= 0)
        {
            $paidAmount = isset($schedule['amount']) ? round((float)$schedule['amount'], 2) : 0.0;
        }
        $paidDate = !empty($transactionData['entry_date']) ? (string)$transactionData['entry_date'] : date('Y-m-d');
        $paidLedgerId = isset($transactionData['ledger_id']) ? (int)$transactionData['ledger_id'] : 0;
        $remarks = trim((string)(isset($schedule['remarks']) ? $schedule['remarks'] : ''));
        $note = '['.date('Y-m-d H:i').'] '.__('Linked voucher #%s was restored. Schedule marked paid again.', $transactionId);
        $remarks = ($remarks === '') ? $note : $remarks."\n".$note;

        $this->Dealrefundschedule->id = (int)$schedule['id'];
        if($this->Dealrefundschedule->save(array('Dealrefundschedule' => array(
            'id' => (int)$schedule['id'],
            'amount' => $paidAmount,
            'status' => 'Paid',
            'paid_date' => $paidDate,
            'paid_amount' => $paidAmount,
            'paid_ledger_id' => $paidLedgerId,
            'voucher_transaction_id' => $transactionId,
            'remarks' => $remarks
        )), false, array('amount','status','paid_date','paid_amount','paid_ledger_id','voucher_transaction_id','remarks')))
        {
            $this->_reconcileDealRefundScheduleBalanceAfterVoucherEdit((int)$schedule['refund_id']);
            return 1;
        }
        return 0;
    }

    protected function _syncDealRefundScheduleForVoucherEdit($transactionId)
    {
        $transactionId = (int)$transactionId;
        if($transactionId <= 0)
        {
            return 0;
        }

        $this->loadModel('Admin.Ardtransaction');
        $txRow = $this->Ardtransaction->find('first', array(
            'conditions' => array('Ardtransaction.id' => $transactionId),
            'recursive' => -1
        ));
        if(empty($txRow['Ardtransaction']))
        {
            return 0;
        }
        $transaction = $txRow['Ardtransaction'];

        $this->loadModel('Admin.Dealrefundschedule');
        $conditions = array('OR' => array(
            'Dealrefundschedule.voucher_transaction_id' => $transactionId,
            'Dealrefundschedule.remarks LIKE' => '%voucher #'.$transactionId.'%'
        ));

        $description = isset($transaction['description']) ? (string)$transaction['description'] : '';
        $dealId = 0;
        $cycleNo = 0;
        if(preg_match('/Deal\s+#?([0-9]+)/i', $description, $m))
        {
            $dealId = (int)$m[1];
        }
        if(preg_match('/Cycle\s+([0-9]+)/i', $description, $m))
        {
            $cycleNo = (int)$m[1];
        }
        if($dealId > 0 && $cycleNo > 0)
        {
            $conditions['OR'][] = array(
                'Dealrefundschedule.deal_id' => $dealId,
                'Dealrefundschedule.cycle_no' => $cycleNo
            );
        }

        $scheduleRow = $this->Dealrefundschedule->find('first', array(
            'conditions' => $conditions,
            'order' => array(
                'CASE WHEN Dealrefundschedule.voucher_transaction_id='.(int)$transactionId.' THEN 0 ELSE 1 END',
                'CASE WHEN Dealrefundschedule.remarks LIKE "%voucher #'.(int)$transactionId.'%" THEN 0 ELSE 1 END',
                'Dealrefundschedule.id' => 'desc'
            ),
            'recursive' => -1
        ));
        if(empty($scheduleRow['Dealrefundschedule']['id']))
        {
            return 0;
        }

        $schedule = $scheduleRow['Dealrefundschedule'];
        $paidAmount = round((float)(isset($transaction['amount']) ? $transaction['amount'] : 0), 2);
        if($paidAmount <= 0)
        {
            return 0;
        }
        $paidDate = !empty($transaction['entry_date']) && (string)$transaction['entry_date'] !== '0000-00-00' ? (string)$transaction['entry_date'] : date('Y-m-d');
        $paidLedgerId = isset($transaction['ledger_id']) ? (int)$transaction['ledger_id'] : 0;

        $currentAmount = round((float)(isset($schedule['amount']) ? $schedule['amount'] : 0), 2);
        $currentPaidAmount = round((float)(isset($schedule['paid_amount']) ? $schedule['paid_amount'] : 0), 2);
        $currentPaidDate = !empty($schedule['paid_date']) && (string)$schedule['paid_date'] !== '0000-00-00' ? (string)$schedule['paid_date'] : '';
        $currentLedgerId = isset($schedule['paid_ledger_id']) ? (int)$schedule['paid_ledger_id'] : 0;
        $currentStatus = isset($schedule['status']) ? trim((string)$schedule['status']) : '';
        $currentVoucherId = isset($schedule['voucher_transaction_id']) ? (int)$schedule['voucher_transaction_id'] : 0;

        $hasChanged = (
            abs($currentAmount - $paidAmount) >= 0.01 ||
            abs($currentPaidAmount - $paidAmount) >= 0.01 ||
            $currentPaidDate !== $paidDate ||
            $currentLedgerId !== $paidLedgerId ||
            $currentStatus !== 'Paid' ||
            $currentVoucherId !== $transactionId
        );

        $remarks = isset($schedule['remarks']) ? (string)$schedule['remarks'] : '';
        if($hasChanged)
        {
            $remarks = $this->_appendDealRefundScheduleNote(
                $remarks,
                __('Linked voucher #%s was edited. Refund schedule updated with amount %s and paid date %s.', $transactionId, number_format($paidAmount, 2), $paidDate)
            );
        }

        $this->Dealrefundschedule->id = (int)$schedule['id'];
        $saved = $this->Dealrefundschedule->save(array('Dealrefundschedule' => array(
            'id' => (int)$schedule['id'],
            'amount' => $paidAmount,
            'status' => 'Paid',
            'paid_date' => $paidDate,
            'paid_amount' => $paidAmount,
            'paid_ledger_id' => $paidLedgerId,
            'voucher_transaction_id' => $transactionId,
            'remarks' => $remarks
        )), false, array('amount','status','paid_date','paid_amount','paid_ledger_id','voucher_transaction_id','remarks'));

        if($saved)
        {
            $this->_reconcileDealRefundScheduleBalanceAfterVoucherEdit((int)$schedule['refund_id']);
            return 1;
        }
        return 0;
    }

    protected function _appendDealRefundScheduleNote($existing, $note)
    {
        $existing = trim((string)$existing);
        $note = trim((string)$note);
        if($note === '')
        {
            return $existing;
        }
        $line = '['.date('Y-m-d H:i').'] '.$note;
        return ($existing === '') ? $line : $existing."\n".$line;
    }

    protected function _reconcileDealRefundScheduleBalanceAfterVoucherEdit($refundId)
    {
        $refundId = (int)$refundId;
        if($refundId <= 0)
        {
            return false;
        }

        $this->loadModel('Admin.Dealrefund');
        $this->loadModel('Admin.Dealrefundschedule');

        $refundRow = $this->Dealrefund->find('first', array(
            'conditions' => array('Dealrefund.id' => $refundId),
            'recursive' => -1
        ));
        if(empty($refundRow['Dealrefund']))
        {
            return false;
        }
        $refund = $refundRow['Dealrefund'];
        $scheduleRows = $this->Dealrefundschedule->find('all', array(
            'conditions' => array('Dealrefundschedule.refund_id' => $refundId),
            'order' => array('Dealrefundschedule.cycle_no' => 'asc', 'Dealrefundschedule.id' => 'asc'),
            'recursive' => -1
        ));
        if(empty($scheduleRows))
        {
            return false;
        }

        $netRefund = round((float)(isset($refund['net_refund']) ? $refund['net_refund'] : 0), 2);
        $paidTotal = 0.0;
        $unpaidTotal = 0.0;
        $futureRows = array();
        $lastSchedule = array();
        foreach((array)$scheduleRows as $row)
        {
            $schedule = isset($row['Dealrefundschedule']) ? $row['Dealrefundschedule'] : array();
            if(empty($schedule['id']))
            {
                continue;
            }
            $lastSchedule = $schedule;
            $status = isset($schedule['status']) ? trim((string)$schedule['status']) : '';
            $amount = round((float)(isset($schedule['amount']) ? $schedule['amount'] : 0), 2);
            if($status === 'Paid')
            {
                $txId = isset($schedule['voucher_transaction_id']) ? (int)$schedule['voucher_transaction_id'] : 0;
                if($txId <= 0)
                {
                    continue;
                }
                $paidAmount = round((float)(isset($schedule['paid_amount']) ? $schedule['paid_amount'] : 0), 2);
                if($paidAmount <= 0)
                {
                    $paidAmount = $amount;
                }
                $paidTotal = round($paidTotal + $paidAmount, 2);
            }
            elseif(in_array($status, array('Unpaid', 'Adjusted'), true))
            {
                if($status === 'Unpaid' && $amount > 0)
                {
                    $unpaidTotal = round($unpaidTotal + $amount, 2);
                }
                $futureRows[] = $schedule;
            }
        }

        $balance = round(max(0, $netRefund - $paidTotal), 2);
        $difference = round($balance - $unpaidTotal, 2);
        if(abs($difference) < 0.01)
        {
            return false;
        }

        if($difference > 0)
        {
            if(!empty($futureRows))
            {
                $target = $futureRows[0];
                $newAmount = round((float)(isset($target['amount']) ? $target['amount'] : 0) + $difference, 2);
                $remarks = $this->_appendDealRefundScheduleNote(
                    isset($target['remarks']) ? $target['remarks'] : '',
                    __('Refund balance updated after voucher edit. Carry forward added: %s', number_format($difference, 2))
                );
                $this->Dealrefundschedule->id = (int)$target['id'];
                return (bool)$this->Dealrefundschedule->save(array('Dealrefundschedule' => array(
                    'id' => (int)$target['id'],
                    'amount' => $newAmount,
                    'status' => 'Unpaid',
                    'remarks' => $remarks
                )), false, array('amount','status','remarks'));
            }
            return $this->_createDealRefundBalanceScheduleFromVoucherEdit($refund, $lastSchedule, $difference);
        }

        $remainingReduction = abs($difference);
        $changed = false;
        foreach($futureRows as $target)
        {
            if($remainingReduction <= 0.009)
            {
                break;
            }
            $amount = round((float)(isset($target['amount']) ? $target['amount'] : 0), 2);
            if($amount <= 0)
            {
                continue;
            }
            $reduceBy = min($amount, $remainingReduction);
            $newAmount = round($amount - $reduceBy, 2);
            $remainingReduction = round($remainingReduction - $reduceBy, 2);
            $newStatus = ($newAmount <= 0.009) ? 'Adjusted' : 'Unpaid';
            if($newStatus === 'Adjusted')
            {
                $newAmount = 0.0;
            }
            $remarks = $this->_appendDealRefundScheduleNote(
                isset($target['remarks']) ? $target['remarks'] : '',
                __('Refund balance updated after voucher edit. Upcoming amount reduced: %s', number_format($reduceBy, 2))
            );
            $this->Dealrefundschedule->id = (int)$target['id'];
            if($this->Dealrefundschedule->save(array('Dealrefundschedule' => array(
                'id' => (int)$target['id'],
                'amount' => $newAmount,
                'status' => $newStatus,
                'remarks' => $remarks
            )), false, array('amount','status','remarks')))
            {
                $changed = true;
            }
        }
        return $changed;
    }

    protected function _createDealRefundBalanceScheduleFromVoucherEdit($refund, $lastSchedule, $amount)
    {
        $refund = (array)$refund;
        $lastSchedule = (array)$lastSchedule;
        $amount = round((float)$amount, 2);
        if($amount <= 0)
        {
            return false;
        }

        $refundId = isset($refund['id']) ? (int)$refund['id'] : 0;
        if($refundId <= 0)
        {
            return false;
        }
        $lastCycleNo = !empty($lastSchedule['cycle_no']) ? (int)$lastSchedule['cycle_no'] : (int)(isset($refund['cycle_count']) ? $refund['cycle_count'] : 0);
        $lastDate = !empty($lastSchedule['scheduled_date']) && (string)$lastSchedule['scheduled_date'] !== '0000-00-00' ? (string)$lastSchedule['scheduled_date'] : (isset($refund['cycle_start_date']) ? (string)$refund['cycle_start_date'] : date('Y-m-d'));
        $nextCycleNo = $lastCycleNo + 1;
        $nextDate = $this->_nextDealRefundScheduleDateForAccounts(isset($refund['cycle_frequency']) ? $refund['cycle_frequency'] : 'Monthly', $lastDate);

        $newRow = array(
            'refund_id' => $refundId,
            'deal_id' => isset($refund['deal_id']) ? (int)$refund['deal_id'] : (isset($lastSchedule['deal_id']) ? (int)$lastSchedule['deal_id'] : 0),
            'client_id' => isset($refund['client_id']) ? (int)$refund['client_id'] : (isset($lastSchedule['client_id']) ? (int)$lastSchedule['client_id'] : 0),
            'project_id' => isset($refund['project_id']) ? (int)$refund['project_id'] : (isset($lastSchedule['project_id']) ? (int)$lastSchedule['project_id'] : 0),
            'cycle_no' => $nextCycleNo,
            'scheduled_date' => $nextDate,
            'amount' => $amount,
            'status' => 'Unpaid',
            'paid_amount' => 0,
            'paid_ledger_id' => 0,
            'voucher_transaction_id' => 0,
            'remarks' => $this->_appendDealRefundScheduleNote('', __('Auto created remaining balance after voucher edit: %s', number_format($amount, 2)))
        );

        $this->Dealrefundschedule->create();
        $saved = (bool)$this->Dealrefundschedule->save(array('Dealrefundschedule' => $newRow), false);
        if($saved)
        {
            $savedCycleCount = isset($refund['cycle_count']) ? (int)$refund['cycle_count'] : 0;
            $this->Dealrefund->id = $refundId;
            $this->Dealrefund->saveField('cycle_count', max($savedCycleCount, $nextCycleNo), array('validate' => false));
        }
        return $saved;
    }

    protected function _nextDealRefundScheduleDateForAccounts($frequency, $baseDate)
    {
        $baseDate = trim((string)$baseDate);
        if($baseDate === '' || $baseDate === '0000-00-00')
        {
            $baseDate = date('Y-m-d');
        }
        $frequency = strtolower(trim((string)$frequency));
        $monthStep = 1;
        if($frequency === 'quarterly')
        {
            $monthStep = 3;
        }
        elseif($frequency === 'biannually' || $frequency === 'bi-annual' || $frequency === 'bianuly')
        {
            $monthStep = 6;
        }
        elseif($frequency === 'yearly')
        {
            $monthStep = 12;
        }
        $ts = strtotime('+'.$monthStep.' months', strtotime($baseDate));
        if($ts === false)
        {
            $ts = strtotime('+'.$monthStep.' months');
        }
        return date('Y-m-d', $ts);
    }

    protected function _deleteTrashRecord($trashRow, &$error)
    {
        $error = '';
        if(empty($trashRow['Ardtrash']))
        {
            $error = __('Invalid trash entry.');
            return false;
        }
        $trash = $trashRow['Ardtrash'];
        if(!$this->_canAccessTrashEntry($trash))
        {
            $error = __('Permission denied for trash action.');
            return false;
        }
        $this->_ensureTrashTable();
        $this->loadModel('Admin.Ardtrash');
        if(!$this->Ardtrash->delete((int)$trash['id']))
        {
            $error = __('Unable to delete trash entry.');
            return false;
        }
        return true;
    }

    public function index($id = null)
    {
        $redirect = array('action' => 'dashboard');
        if($id !== null && $id !== '')
        {
            $redirect[] = $id;
        }
        if(!empty($this->request->query))
        {
            $redirect['?'] = $this->request->query;
        }
        return $this->redirect($redirect);
    }

    public function dashboard($id = null)
    {
        $this->loadModel('Admin.Ardledger');
        $this->loadModel('Admin.Ardtransaction');
        $this->loadModel('Admin.Ardsite');
        $this->loadModel('Admin.Ardstock');
        $this->loadModel('Admin.Ardvendor');
        $id = $this->_activeProjectId($id);
        if((int)$id > 0)
        {
            $this->Session->write('Ardaccounts.current_project_id', (int)$id);
        }
        else
        {
            $this->Session->delete('Ardaccounts.current_project_id');
        }

        $scopeLedger = $this->_scopeCondition('Ardledger.project_id', $id);
        $scopeTransaction = $this->_scopeCondition('Ardtransaction.project_id', $id);
        $scopeSite = $this->_scopeCondition('Ardsite.project_id', $id > 0 ? $id : null);
        $scopeStock = $this->_scopeCondition('Ardstock.project_id', $id);
        $scopeVendor = $this->_scopeCondition('Ardvendor.project_id', $id);
        $projectFilter = $this->_projectSqlCondition('project_id', $id);
        $dateRange = $this->_reportResolveDateRange(
            isset($this->request->query['preset']) ? $this->request->query['preset'] : 'monthly',
            isset($this->request->query['start']) ? $this->request->query['start'] : '',
            isset($this->request->query['end']) ? $this->request->query['end'] : ''
        );
        $txRangeConditions = array($scopeTransaction);
        $stockRangeConditions = array($scopeStock);
        if($dateRange['start'] !== '')
        {
            $txRangeConditions['Ardtransaction.entry_date >='] = $dateRange['start'];
            $stockRangeConditions['Ardstock.movement_date >='] = $dateRange['start'];
        }
        if($dateRange['end'] !== '')
        {
            $txRangeConditions['Ardtransaction.entry_date <='] = $dateRange['end'];
            $stockRangeConditions['Ardstock.movement_date <='] = $dateRange['end'];
        }

        $txTotals = $this->Ardtransaction->find('first', array(
            'fields' => array(
                'SUM(CASE WHEN Ardtransaction.type="income" THEN Ardtransaction.amount ELSE 0 END) AS income_total',
                'SUM(CASE WHEN Ardtransaction.type="expense" THEN Ardtransaction.amount ELSE 0 END) AS expense_total'
            ),
            'conditions' => $txRangeConditions,
            'recursive' => -1
        ));
        $txTypeStats = $this->Ardtransaction->find('first', array(
            'fields' => array(
                'SUM(CASE WHEN Ardtransaction.type="income" THEN 1 ELSE 0 END) AS income_count',
                'SUM(CASE WHEN Ardtransaction.type="expense" THEN 1 ELSE 0 END) AS expense_count',
                'SUM(CASE WHEN Ardtransaction.type IN ("transfer_in","transfer_out") THEN 1 ELSE 0 END) AS transfer_count',
                'COUNT(Ardtransaction.id) AS total_count'
            ),
            'conditions' => $txRangeConditions,
            'recursive' => -1
        ));
        $bankTotals = $this->Ardledger->find('first', array(
            'fields' => array(
                'SUM(CASE WHEN Ardledger.type="bank" THEN Ardledger.balance ELSE 0 END) AS bank_total'
            ),
            'conditions' => array($scopeLedger, 'Ardledger.is_trashed' => 0),
            'recursive' => -1
        ));
        $stockTotals = $this->Ardstock->find('first', array(
            'fields' => array(
                'SUM(CASE WHEN Ardstock.movement_type="in" THEN Ardstock.total_cost ELSE 0 END) AS stock_in_total'
            ),
            'conditions' => $stockRangeConditions,
            'recursive' => -1
        ));
        $purchaseDueRow = $this->Ardledger->query("SELECT SUM(CASE WHEN status<>'paid' THEN (amount-paid_amount) ELSE 0 END) AS due_total FROM ardaccounts_construction_purchase_invoices WHERE {$projectFilter}");
        $payrollDueRow = $this->Ardledger->query("SELECT SUM(due_amount) AS due_total FROM ardaccounts_hr_payroll WHERE {$projectFilter}");
        $lowStockRow = $this->Ardledger->query("SELECT COUNT(*) AS low_count FROM ardaccounts_construction_reorder_rules WHERE {$projectFilter} AND enabled=1");
        $arapRow = $this->Ardledger->query("SELECT
            SUM(CASE WHEN entry_type='receivable' AND status<>'paid' THEN (amount-paid_amount) ELSE 0 END) AS receivable_total,
            SUM(CASE WHEN entry_type='payable' AND status<>'paid' THEN (amount-paid_amount) ELSE 0 END) AS payable_total
            FROM ardaccounts_arap_entries WHERE {$projectFilter}");
        $siteVarianceRow = $this->Ardledger->query("SELECT
            COALESCE((SELECT SUM(budget_amount) FROM ardaccounts_budget_entries WHERE {$projectFilter}),0) AS budget_total,
            COALESCE((SELECT SUM(total_cost) FROM ardaccounts_construction_stock WHERE {$projectFilter}),0) +
            COALESCE((SELECT SUM(amount) FROM ardaccounts_construction_labour_payments WHERE {$projectFilter}),0) AS actual_total");

        $this->set('currentProjectId', $id);
        $this->set('projectName', $this->_projectList());
        $receiptLedgerList = array();
        if((int)$id > 0)
        {
            $receiptLedgerList = (array)$this->Ardledger->find('list', array(
                'fields' => array('Ardledger.id', 'Ardledger.name'),
                'conditions' => array(
                    'Ardledger.project_id' => (int)$id,
                    'Ardledger.is_trashed' => 0,
                    'Ardledger.type !=' => 'expense'
                ),
                'order' => array('Ardledger.name' => 'asc'),
                'recursive' => -1
            ));
        }
        $this->set('receiptLedgerList', $receiptLedgerList);
        $this->set('counts', array(
            'ledgers' => $this->Ardledger->find('count', array('conditions' => array($scopeLedger, 'Ardledger.is_trashed' => 0))),
            'transactions' => $this->Ardtransaction->find('count', array('conditions' => $txRangeConditions)),
            'sites' => $this->Ardsite->find('count', array('conditions' => array($scopeSite))),
            'stock' => $this->Ardstock->find('count', array('conditions' => $stockRangeConditions)),
            'vendors' => $this->Ardvendor->find('count', array('conditions' => array($scopeVendor)))
        ));
        $incomeTotal = (float)$txTotals[0]['income_total'];
        $expenseTotal = (float)$txTotals[0]['expense_total'];
        $this->set('stats', array(
            'total_assets' => $incomeTotal,
            'total_expenses' => $expenseTotal,
            'net_balance' => $incomeTotal - $expenseTotal,
            'cash_in_hand' => (float)$bankTotals[0]['bank_total'],
            'receivables' => (float)$arapRow[0][0]['receivable_total'],
            'payables' => (float)$arapRow[0][0]['payable_total'],
            'construction_spend' => (float)$stockTotals[0]['stock_in_total'],
            'construction_due' => (float)$purchaseDueRow[0][0]['due_total'],
            'payroll_due' => (float)$payrollDueRow[0][0]['due_total'],
            'site_cost_variance' => (float)$siteVarianceRow[0][0]['actual_total'] - (float)$siteVarianceRow[0][0]['budget_total'],
            'low_stock_count' => (int)$lowStockRow[0][0]['low_count']
        ));
        $this->set('recentTransactions', $this->Ardtransaction->find('all', array(
            'joins' => array(
                array('table' => 'ardaccounts_ledgers', 'alias' => 'Ardledger', 'type' => 'LEFT', 'conditions' => array('Ardledger.id=Ardtransaction.ledger_id'))
            ),
            'fields' => array('Ardtransaction.*', 'Ardledger.name'),
            'conditions' => $txRangeConditions,
            'order' => array('Ardtransaction.entry_date' => 'desc', 'Ardtransaction.id' => 'desc'),
            'limit' => 12,
            'recursive' => -1
        )));
        $incomeCount = (int)(isset($txTypeStats[0]['income_count']) ? $txTypeStats[0]['income_count'] : 0);
        $expenseCount = (int)(isset($txTypeStats[0]['expense_count']) ? $txTypeStats[0]['expense_count'] : 0);
        $transferCount = (int)(isset($txTypeStats[0]['transfer_count']) ? $txTypeStats[0]['transfer_count'] : 0);
        $totalCount = (int)(isset($txTypeStats[0]['total_count']) ? $txTypeStats[0]['total_count'] : 0);
        $this->set('dashboardFilter', array(
            'preset' => $dateRange['preset'],
            'start' => $dateRange['start'],
            'end' => $dateRange['end']
        ));
        $this->set('dashboardChart', array(
            'income_amount' => $incomeTotal,
            'expense_amount' => $expenseTotal,
            'income_count' => $incomeCount,
            'expense_count' => $expenseCount,
            'transfer_count' => $transferCount,
            'total_count' => $totalCount
        ));
    }

    public function normalizereceiptaccounts($id = null)
    {
        $returnToSettings = !empty($this->request->data['return_to_settings']) || !empty($this->request->query['return_to_settings']);
        $returnTab = isset($this->request->data['return_tab']) ? strtolower(trim((string)$this->request->data['return_tab'])) : (isset($this->request->query['return_tab']) ? strtolower(trim((string)$this->request->query['return_tab'])) : 'general');
        if($returnTab === '')
        {
            $returnTab = 'general';
        }
        if(!$this->request->is('post'))
        {
            throw new MethodNotAllowedException(__('Invalid request method.'));
        }
        if(!$this->_isGlobalAdmin())
        {
            $this->Session->setFlash(__('Only Super Admin can run receipt normalization or manual receipt ledger merge.'), 'flash', array('alert' => 'danger'));
            $fallbackProjectId = $this->_activeProjectId($id);
            if($returnToSettings)
            {
                return $this->redirect(array('action' => 'settings', $fallbackProjectId, '?' => array('tab' => $returnTab)));
            }
            return $this->redirect(array('action' => 'dashboard', $fallbackProjectId));
        }
        $projectId = 0;
        if(isset($id) && (int)$id > 0)
        {
            $projectId = (int)$id;
        }
        if($projectId <= 0 && isset($this->request->query['project_id']) && (int)$this->request->query['project_id'] > 0)
        {
            $projectId = (int)$this->request->query['project_id'];
        }
        if($projectId <= 0 && isset($this->request->data['project_id']) && (int)$this->request->data['project_id'] > 0)
        {
            $projectId = (int)$this->request->data['project_id'];
        }
        if($projectId <= 0)
        {
            $projectId = $this->_activeProjectId($id);
        }
        if($projectId <= 0)
        {
            $projectId = (int)$this->Session->read('Ardaccounts.current_project_id');
        }
        if($projectId <= 0)
        {
            $this->Session->setFlash(__('Please select a valid agency/project first.'), 'flash', array('alert' => 'danger'));
            if($returnToSettings)
            {
                return $this->redirect(array('action' => 'settings', 0, '?' => array('tab' => $returnTab)));
            }
            return $this->redirect(array('action' => 'dashboard'));
        }
        if(!$this->_isAllowedProject($projectId))
        {
            $this->Session->setFlash(__('Permission denied.'), 'flash', array('alert' => 'danger'));
            if($returnToSettings)
            {
                return $this->redirect(array('action' => 'settings', $projectId, '?' => array('tab' => $returnTab)));
            }
            return $this->redirect(array('action' => 'dashboard'));
        }

        $isManualMergeRequest = !empty($this->request->data['manual_merge']);
        if($isManualMergeRequest)
        {
            $sourceLedgerId = (int)(isset($this->request->data['source_ledger_id']) ? $this->request->data['source_ledger_id'] : 0);
            $targetLedgerId = (int)(isset($this->request->data['target_ledger_id']) ? $this->request->data['target_ledger_id'] : 0);
            $mergeMode = isset($this->request->data['merge_mode']) ? strtolower(trim((string)$this->request->data['merge_mode'])) : 'all';
            if(!in_array($mergeMode, array('all', 'selected_receipts', 'selected_transactions'), true))
            {
                $mergeMode = 'all';
            }
            $selectedTxIds = $this->_parseManualListValues(isset($this->request->data['selected_transaction_ids']) ? $this->request->data['selected_transaction_ids'] : '', true);
            $selectedRefs = $this->_parseManualListValues(isset($this->request->data['selected_receipt_refs']) ? $this->request->data['selected_receipt_refs'] : '', false);

            if($sourceLedgerId <= 0 || $targetLedgerId <= 0 || $sourceLedgerId === $targetLedgerId)
            {
                $this->Session->setFlash(__('Please select valid source and target receipt ledgers (different ledgers).'), 'flash', array('alert' => 'danger'));
                if($returnToSettings)
                {
                    return $this->redirect(array('action' => 'settings', $projectId, '?' => array('tab' => $returnTab)));
                }
                return $this->redirect(array('action' => 'dashboard', $projectId));
            }
            if($mergeMode === 'selected_transactions' && empty($selectedTxIds))
            {
                $this->Session->setFlash(__('Please enter transaction IDs to move, or choose "All Receipt Entries".'), 'flash', array('alert' => 'danger'));
                if($returnToSettings)
                {
                    return $this->redirect(array('action' => 'settings', $projectId, '?' => array('tab' => $returnTab)));
                }
                return $this->redirect(array('action' => 'dashboard', $projectId));
            }
            if($mergeMode === 'selected_receipts' && empty($selectedRefs))
            {
                $this->Session->setFlash(__('Please enter receipt/reference numbers to move, or choose "All Receipt Entries".'), 'flash', array('alert' => 'danger'));
                if($returnToSettings)
                {
                    return $this->redirect(array('action' => 'settings', $projectId, '?' => array('tab' => $returnTab)));
                }
                return $this->redirect(array('action' => 'dashboard', $projectId));
            }

            $ds = ConnectionManager::getDataSource('default');
            try
            {
                @set_time_limit(0);
                $ds->begin();
                $summary = $this->_manualMergeReceiptLedger($projectId, $sourceLedgerId, $targetLedgerId, $mergeMode, $selectedTxIds, $selectedRefs);
                if((int)$summary['errors'] > 0)
                {
                    throw new Exception('Invalid merge request or ledger mapping.');
                }
                $ds->commit();
                $this->Session->setFlash(
                    sprintf(
                        __('Receipt ledger merge completed. Transactions moved: %d, Payments moved: %d, Receipt refs included: %d. Dates remain unchanged for sorting.'),
                        (int)$summary['moved_transactions'],
                        (int)$summary['moved_payments'],
                        (int)$summary['moved_receipt_refs']
                    ),
                    'flash',
                    array('alert' => 'success')
                );
            }
            catch(Exception $e)
            {
                $ds->rollback();
                $this->Session->setFlash(__('Receipt ledger merge failed. ').$e->getMessage(), 'flash', array('alert' => 'danger'));
            }
            if($returnToSettings)
            {
                return $this->redirect(array('action' => 'settings', $projectId, '?' => array('tab' => $returnTab)));
            }
            return $this->redirect(array('action' => 'dashboard', $projectId));
        }

        $ds = ConnectionManager::getDataSource('default');
        try
        {
            @set_time_limit(0);
            $ds->begin();
            $summary = $this->_normalizeDealReceiptMappingsByProject($projectId);
            $ds->commit();
            if((int)$summary['errors'] > 0)
            {
                $this->Session->setFlash(
                    sprintf(
                        __('Receipt account normalization completed with warnings. Payments updated: %d, Transactions updated: %d, Linked by receipt no: %d, Duplicate ledgers moved to trash: %d, Errors: %d.'),
                        (int)$summary['payments_updated'],
                        (int)$summary['transactions_updated'],
                        (int)$summary['links_fixed'],
                        (int)$summary['duplicates_trashed'],
                        (int)$summary['errors']
                    ),
                    'flash',
                    array('alert' => 'warning')
                );
            }
            else
            {
                $this->Session->setFlash(
                    sprintf(
                        __('Receipt account normalization completed. Payments updated: %d, Transactions updated: %d, Linked by receipt no: %d, Duplicate ledgers moved to trash: %d.'),
                        (int)$summary['payments_updated'],
                        (int)$summary['transactions_updated'],
                        (int)$summary['links_fixed'],
                        (int)$summary['duplicates_trashed']
                    ),
                    'flash',
                    array('alert' => 'success')
                );
            }
        }
        catch(Exception $e)
        {
            $ds->rollback();
            $this->Session->setFlash(__('Receipt account normalization failed. ').$e->getMessage(), 'flash', array('alert' => 'danger'));
        }
        if($returnToSettings)
        {
            return $this->redirect(array('action' => 'settings', $projectId, '?' => array('tab' => $returnTab)));
        }
        return $this->redirect(array('action' => 'dashboard', $projectId));
    }

    public function receiptmergeentries($id = null)
    {
        $this->autoRender = false;
        $this->response->type('json');
        if(!$this->_isGlobalAdmin())
        {
            $payload = array('ok' => 0, 'message' => __('Only Super Admin can access manual receipt merge picker.'), 'rows' => array());
            $this->response->body(json_encode($payload));
            return $this->response;
        }

        $projectId = 0;
        if(isset($id) && (int)$id > 0)
        {
            $projectId = (int)$id;
        }
        if($projectId <= 0 && isset($this->request->query['project_id']) && (int)$this->request->query['project_id'] > 0)
        {
            $projectId = (int)$this->request->query['project_id'];
        }
        if($projectId <= 0)
        {
            $projectId = $this->_activeProjectId($id);
        }
        if($projectId <= 0 || !$this->_isAllowedProject($projectId))
        {
            $payload = array('ok' => 0, 'message' => __('Permission denied or invalid project.'), 'rows' => array());
            $this->response->body(json_encode($payload));
            return $this->response;
        }

        $sourceLedgerId = isset($this->request->query['source_ledger_id']) ? (int)$this->request->query['source_ledger_id'] : 0;
        if($sourceLedgerId <= 0)
        {
            $payload = array('ok' => 0, 'message' => __('Please select source ledger first.'), 'rows' => array());
            $this->response->body(json_encode($payload));
            return $this->response;
        }
        $limit = isset($this->request->query['limit']) ? (int)$this->request->query['limit'] : 600;
        if($limit <= 0)
        {
            $limit = 600;
        }
        if($limit > 3000)
        {
            $limit = 3000;
        }

        $this->loadModel('Admin.Ardledger');
        $this->loadModel('Admin.Ardtransaction');
        $this->loadModel('DealsPayment');

        $sourceLedger = $this->Ardledger->find('first', array(
            'fields' => array('Ardledger.id', 'Ardledger.name'),
            'conditions' => array(
                'Ardledger.id' => $sourceLedgerId,
                'Ardledger.project_id' => $projectId,
                'Ardledger.is_trashed' => 0,
                'Ardledger.type !=' => 'expense'
            ),
            'recursive' => -1
        ));
        if(empty($sourceLedger['Ardledger']['id']))
        {
            $payload = array('ok' => 0, 'message' => __('Invalid source ledger for selected agency.'), 'rows' => array());
            $this->response->body(json_encode($payload));
            return $this->response;
        }

        $paymentRows = $this->DealsPayment->find('all', array(
            'joins' => array(
                array('table' => 'deals', 'alias' => 'Deal', 'type' => 'INNER', 'conditions' => array('Deal.id = DealsPayment.deal_id')),
                array('table' => 'properties', 'alias' => 'Property', 'type' => 'INNER', 'conditions' => array('Property.id = Deal.property_id'))
            ),
            'fields' => array('DealsPayment.ard_transaction_id', 'DealsPayment.receipt_no', 'COUNT(DealsPayment.id) AS total_rows'),
            'conditions' => array(
                'Property.project_id' => $projectId,
                'DealsPayment.ard_ledger_id' => $sourceLedgerId
            ),
            'group' => array('DealsPayment.ard_transaction_id', 'DealsPayment.receipt_no'),
            'recursive' => -1
        ));
        $linkedTxIds = array();
        $paymentCountByTxId = array();
        $paymentCountByRef = array();
        foreach((array)$paymentRows as $paymentRow)
        {
            $txId = (int)(isset($paymentRow['DealsPayment']['ard_transaction_id']) ? $paymentRow['DealsPayment']['ard_transaction_id'] : 0);
            $refNo = trim((string)(isset($paymentRow['DealsPayment']['receipt_no']) ? $paymentRow['DealsPayment']['receipt_no'] : ''));
            $rowCount = (int)(isset($paymentRow[0]['total_rows']) ? $paymentRow[0]['total_rows'] : 0);
            if($txId > 0)
            {
                $linkedTxIds[$txId] = $txId;
                $paymentCountByTxId[$txId] = (int)(isset($paymentCountByTxId[$txId]) ? $paymentCountByTxId[$txId] : 0) + $rowCount;
            }
            if($refNo !== '')
            {
                $paymentCountByRef[$refNo] = (int)(isset($paymentCountByRef[$refNo]) ? $paymentCountByRef[$refNo] : 0) + $rowCount;
            }
        }
        $linkedTxIds = array_values($linkedTxIds);

        $txConditions = array(
            'Ardtransaction.project_id' => $projectId,
            'Ardtransaction.type' => 'income',
            'Ardtransaction.ledger_id' => $sourceLedgerId,
            'OR' => array(
                array('Ardtransaction.ref_no !=' => ''),
                array('Ardtransaction.id' => empty($linkedTxIds) ? array(0) : $linkedTxIds)
            )
        );

        $txRows = $this->Ardtransaction->find('all', array(
            'fields' => array('Ardtransaction.id', 'Ardtransaction.entry_date', 'Ardtransaction.ref_no', 'Ardtransaction.amount', 'Ardtransaction.description'),
            'conditions' => $txConditions,
            'order' => array('Ardtransaction.entry_date' => 'desc', 'Ardtransaction.id' => 'desc'),
            'limit' => $limit,
            'recursive' => -1
        ));

        $rows = array();
        foreach((array)$txRows as $txRow)
        {
            $txId = (int)(isset($txRow['Ardtransaction']['id']) ? $txRow['Ardtransaction']['id'] : 0);
            if($txId <= 0)
            {
                continue;
            }
            $refNo = trim((string)(isset($txRow['Ardtransaction']['ref_no']) ? $txRow['Ardtransaction']['ref_no'] : ''));
            $paymentLinks = 0;
            if($txId > 0 && isset($paymentCountByTxId[$txId]))
            {
                $paymentLinks += (int)$paymentCountByTxId[$txId];
            }
            if($refNo !== '' && isset($paymentCountByRef[$refNo]))
            {
                $paymentLinks = max($paymentLinks, (int)$paymentCountByRef[$refNo]);
            }
            $rows[] = array(
                'id' => $txId,
                'entry_date' => (string)(isset($txRow['Ardtransaction']['entry_date']) ? $txRow['Ardtransaction']['entry_date'] : ''),
                'ref_no' => $refNo,
                'amount' => (float)(isset($txRow['Ardtransaction']['amount']) ? $txRow['Ardtransaction']['amount'] : 0),
                'description' => trim((string)(isset($txRow['Ardtransaction']['description']) ? $txRow['Ardtransaction']['description'] : '')),
                'payment_links' => $paymentLinks
            );
        }

        $payload = array(
            'ok' => 1,
            'message' => '',
            'source_ledger_id' => $sourceLedgerId,
            'source_ledger_name' => (string)(isset($sourceLedger['Ardledger']['name']) ? $sourceLedger['Ardledger']['name'] : ''),
            'rows' => $rows
        );
        $this->response->body(json_encode($payload));
        return $this->response;
    }

    public function ledgers($id = null)
    {
        $this->loadModel('Admin.Ardledger');
        $this->loadModel('Admin.Ardsetting');
        $this->loadModel('Admin.Ardhremployee');
        $id = $this->_activeProjectId($id);
        $isLedgerSystemManager = $this->_isAgencySystemManagerRoleContext((array)$this->adminValue);
        $ledgerAgencyOptions = $isLedgerSystemManager
            ? (array)$this->_assignedAgencyProjectList((int)$this->luserId)
            : (array)$this->_projectList();
        $canFilterLedgerAgency = $this->_isGlobalAdmin() || $isLedgerSystemManager;

        if($canFilterLedgerAgency && array_key_exists('project_id', $this->request->query))
        {
            $requestedProjectId = max(0, (int)$this->request->query['project_id']);
            $id = ($requestedProjectId > 0 && isset($ledgerAgencyOptions[$requestedProjectId]))
                ? $requestedProjectId
                : 0;
        }
        elseif($isLedgerSystemManager && empty($this->request->params['pass'][0]))
        {
            $id = 0;
        }

        $ledgerScope = function($field) use ($id, $isLedgerSystemManager, $ledgerAgencyOptions)
        {
            if($isLedgerSystemManager)
            {
                if((int)$id > 0)
                {
                    return array($field => (int)$id);
                }
                $assignedIds = array_map('intval', array_keys($ledgerAgencyOptions));
                return array($field => !empty($assignedIds) ? $assignedIds : array(-1));
            }
            return $this->_scopeCondition($field, $id);
        };

        $this->set('projectName', $ledgerAgencyOptions);
        $this->set('ledgerAgencyOptions', $ledgerAgencyOptions);
        $this->set('canFilterLedgerAgency', $canFilterLedgerAgency);
        $this->set('selectedLedgerAgencyId', (int)$id);
        $this->set('agencyId', $this->agencyId);
        $this->set('currentProjectId', $id);

        $defaults = $this->_defaultSettings();
        $defaultAssetCategories = $this->_lineTextToOptionList(isset($defaults['ledger_asset_categories']) ? $defaults['ledger_asset_categories'] : '');
        $defaultExpenseCategories = $this->_lineTextToOptionList(isset($defaults['ledger_expense_categories']) ? $defaults['ledger_expense_categories'] : '');
        $projectIdsForCategory = array();
        if($canFilterLedgerAgency)
        {
            foreach($ledgerAgencyOptions as $projectIdKey => $projectTitle)
            {
                $projectIdKey = (int)$projectIdKey;
                if($projectIdKey > 0)
                {
                    $projectIdsForCategory[] = $projectIdKey;
                }
            }
        }
        else
        {
            $projectIdsForCategory[] = (int)$this->agencyId;
        }
        if((int)$id > 0)
        {
            $projectIdsForCategory[] = (int)$id;
        }
        $projectIdsForCategory = array_values(array_unique(array_filter($projectIdsForCategory)));
        $ledgerCategoryOptionsByProject = array();
        foreach($projectIdsForCategory as $projectIdForCategory)
        {
            if(!$this->_isAllowedProject((int)$projectIdForCategory))
            {
                continue;
            }
            $settingsRow = $this->_fetchArdSettingsRowRaw((int)$projectIdForCategory);
            $settingsData = $this->_normalizeArdSettingsWithDefaults($settingsRow, $defaults);
            $assetOptions = $this->_lineTextToOptionList(isset($settingsData['ledger_asset_categories']) ? $settingsData['ledger_asset_categories'] : '');
            $expenseOptions = $this->_lineTextToOptionList(isset($settingsData['ledger_expense_categories']) ? $settingsData['ledger_expense_categories'] : '');
            if(empty($assetOptions))
            {
                $assetOptions = $defaultAssetCategories;
            }
            if(empty($expenseOptions))
            {
                $expenseOptions = $defaultExpenseCategories;
            }
            $ledgerCategoryOptionsByProject[(int)$projectIdForCategory] = array(
                'bank' => $assetOptions,
                'expense' => $expenseOptions
            );
        }
        if(empty($ledgerCategoryOptionsByProject))
        {
            $fallbackProjectId = (int)$id > 0 ? (int)$id : (int)$this->agencyId;
            if($fallbackProjectId <= 0)
            {
                $fallbackProjectId = 1;
            }
            $ledgerCategoryOptionsByProject[$fallbackProjectId] = array(
                'bank' => $defaultAssetCategories,
                'expense' => $defaultExpenseCategories
            );
        }
        $currentCategorySet = array('bank' => $defaultAssetCategories, 'expense' => $defaultExpenseCategories);
        if((int)$id > 0 && isset($ledgerCategoryOptionsByProject[(int)$id]))
        {
            $currentCategorySet = $ledgerCategoryOptionsByProject[(int)$id];
        }
        else
        {
            $firstCategorySet = reset($ledgerCategoryOptionsByProject);
            if(is_array($firstCategorySet))
            {
                $currentCategorySet = array_merge($currentCategorySet, $firstCategorySet);
            }
        }
        $this->set('ledgerCategoryOptionsByProject', $ledgerCategoryOptionsByProject);
        $this->set('ledgerAssetCategoryOptions', isset($currentCategorySet['bank']) ? (array)$currentCategorySet['bank'] : array());
        $this->set('ledgerExpenseCategoryOptions', isset($currentCategorySet['expense']) ? (array)$currentCategorySet['expense'] : array());

        if($this->request->is('post'))
        {
            $row = isset($this->request->data['Ardledger']) ? $this->request->data['Ardledger'] : array();
            $row['project_id'] = $this->_resolveProjectId(isset($row['project_id']) ? $row['project_id'] : null);
            if(!$this->_isAllowedProject($row['project_id']))
            {
                $this->Session->setFlash(__('Please select valid agency/project.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            $row['type'] = (isset($row['type']) && strtolower(trim((string)$row['type'])) === 'expense') ? 'expense' : 'bank';
            $row['category'] = trim((string)(isset($row['category']) ? $row['category'] : ''));
            $row['is_trashed'] = 0;
            if(isset($row['id']) && (int)$row['id'] > 0)
            {
                $exists = $this->Ardledger->findById((int)$row['id']);
                if(empty($exists))
                {
                    $this->Session->setFlash(__('Invalid ledger.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect($this->referer());
                }
                if(!$this->_isAllowedProject((int)$exists['Ardledger']['project_id']))
                {
                    $this->Session->setFlash(__('Permission denied for this ledger.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect($this->referer());
                }
            }
            $this->Ardledger->create();
            if($this->Ardledger->save(array('Ardledger' => $row)))
            {
                $this->Session->setFlash(__('Ledger saved successfully.'), 'flash', array('alert' => 'success'));
            }
            else
            {
                $this->Session->setFlash(__('Unable to save ledger.'), 'flash', array('alert' => 'danger'));
            }
            return $this->redirect(array('action' => 'ledgers', $id));
        }

        $scope = $ledgerScope('Ardledger.project_id');
        $this->Paginator->settings = array(
            'page' => 1,
            'order' => array('Ardledger.id' => 'desc'),
            'limit' => $this->pageLimit,
            'maxLimit' => $this->maxLimit,
            'conditions' => array($scope, 'Ardledger.is_trashed' => 0)
        );
        $rows = $this->Paginator->paginate('Ardledger');

        // Keep list balances accurate even if old stale balances exist in DB.
        if(!empty($rows))
        {
            foreach($rows as $rowIndex => $rowValue)
            {
                $ledgerId = isset($rowValue['Ardledger']['id']) ? (int)$rowValue['Ardledger']['id'] : 0;
                if($ledgerId <= 0)
                {
                    continue;
                }
                $this->_recalculateLedgerBalance($ledgerId);
                $freshBalance = $this->Ardledger->field('balance', array('Ardledger.id' => $ledgerId));
                if($freshBalance !== false && $freshBalance !== null)
                {
                    $rows[$rowIndex]['Ardledger']['balance'] = (float)$freshBalance;
                }
            }
        }
        $this->set('rows', $rows);

        $assetRows = array();
        $expenseRows = array();
        $ledgerIds = array();
        foreach($rows as $row)
        {
            $ledgerType = strtolower(trim((string)$row['Ardledger']['type'])) === 'expense' ? 'expense' : 'bank';
            if($ledgerType === 'expense')
            {
                $expenseRows[] = $row;
            }
            else
            {
                $assetRows[] = $row;
            }
            $ledgerIds[] = (int)$row['Ardledger']['id'];
        }
        $isHrLabourLedger = function($ledgerRow){
            $ledgerData = isset($ledgerRow['Ardledger']) ? (array)$ledgerRow['Ardledger'] : array();
            $ledgerName = strtolower(trim((string)(isset($ledgerData['name']) ? $ledgerData['name'] : '')));
            $ledgerCategory = strtolower(trim((string)(isset($ledgerData['category']) ? $ledgerData['category'] : '')));

            if($ledgerName !== '')
            {
                if(strpos($ledgerName, 'hr -') === 0 || strpos($ledgerName, 'labour -') === 0 || strpos($ledgerName, 'labor -') === 0)
                {
                    return true;
                }
                if($ledgerName === 'hr employee' || $ledgerName === 'labour' || $ledgerName === 'labor')
                {
                    return true;
                }
            }
            if($ledgerCategory !== '')
            {
                if($ledgerCategory === 'hr employee' || $ledgerCategory === 'hr' || $ledgerCategory === 'labour' || $ledgerCategory === 'labor')
                {
                    return true;
                }
            }
            return false;
        };
        $moveHrLabourAtBottom = function($rowList) use ($isHrLabourLedger){
            $normalRows = array();
            $hrLabourRows = array();
            foreach((array)$rowList as $rowItem)
            {
                if($isHrLabourLedger($rowItem))
                {
                    $hrLabourRows[] = $rowItem;
                }
                else
                {
                    $normalRows[] = $rowItem;
                }
            }
            return array_merge($normalRows, $hrLabourRows);
        };
        $assetRows = $moveHrLabourAtBottom($assetRows);
        $expenseRows = $moveHrLabourAtBottom($expenseRows);

        $ledgerEntryCounts = array();
        if(!empty($ledgerIds))
        {
            $this->loadModel('Admin.Ardtransaction');
            $sourceEntryRows = $this->Ardtransaction->find('all', array(
                'fields' => array('Ardtransaction.ledger_id', 'COUNT(Ardtransaction.id) AS entry_count'),
                'conditions' => array('Ardtransaction.ledger_id' => $ledgerIds),
                'group' => array('Ardtransaction.ledger_id'),
                'recursive' => -1
            ));
            foreach($sourceEntryRows as $entryRow)
            {
                $ledgerKey = (int)$entryRow['Ardtransaction']['ledger_id'];
                $ledgerEntryCounts[$ledgerKey] = isset($entryRow[0]['entry_count']) ? (int)$entryRow[0]['entry_count'] : 0;
            }
            $expenseEntryRows = $this->Ardtransaction->find('all', array(
                'fields' => array('Ardtransaction.expense_ledger_id', 'COUNT(Ardtransaction.id) AS entry_count'),
                'conditions' => array('Ardtransaction.type' => 'expense', 'Ardtransaction.expense_ledger_id' => $ledgerIds),
                'group' => array('Ardtransaction.expense_ledger_id'),
                'recursive' => -1
            ));
            foreach($expenseEntryRows as $entryRow)
            {
                $ledgerKey = (int)$entryRow['Ardtransaction']['expense_ledger_id'];
                if($ledgerKey <= 0)
                {
                    continue;
                }
                $ledgerEntryCounts[$ledgerKey] = (int)(isset($ledgerEntryCounts[$ledgerKey]) ? $ledgerEntryCounts[$ledgerKey] : 0) + (int)(isset($entryRow[0]['entry_count']) ? $entryRow[0]['entry_count'] : 0);
            }
        }
        $employeeLedgerMetaByLedgerId = array();
        if(!empty($ledgerIds))
        {
            $employeeLedgerConditions = array(
                'Ardhremployee.labour_ledger_id >' => 0,
                'Ardhremployee.labour_ledger_id' => $ledgerIds
            );
            $employeeScopeCondition = $ledgerScope('Ardhremployee.project_id');
            if(!empty($employeeScopeCondition))
            {
                $employeeLedgerConditions[] = $employeeScopeCondition;
            }
            $employeeLedgerRows = (array)$this->Ardhremployee->find('all', array(
                'fields' => array(
                    'Ardhremployee.id',
                    'Ardhremployee.project_id',
                    'Ardhremployee.labour_ledger_id',
                    'Ardhremployee.full_name',
                    'Ardhremployee.employee_code',
                    'Ardhremployee.salary_type'
                ),
                'conditions' => $employeeLedgerConditions,
                'order' => array('Ardhremployee.id' => 'desc'),
                'recursive' => -1
            ));
            foreach((array)$employeeLedgerRows as $employeeLedgerRow)
            {
                $employeeData = isset($employeeLedgerRow['Ardhremployee']) ? (array)$employeeLedgerRow['Ardhremployee'] : array();
                $ledgerIdKey = isset($employeeData['labour_ledger_id']) ? (int)$employeeData['labour_ledger_id'] : 0;
                if($ledgerIdKey <= 0 || isset($employeeLedgerMetaByLedgerId[$ledgerIdKey]))
                {
                    continue;
                }
                $employeeLedgerMetaByLedgerId[$ledgerIdKey] = array(
                    'employee_id' => isset($employeeData['id']) ? (int)$employeeData['id'] : 0,
                    'project_id' => isset($employeeData['project_id']) ? (int)$employeeData['project_id'] : 0,
                    'full_name' => trim((string)(isset($employeeData['full_name']) ? $employeeData['full_name'] : '')),
                    'employee_code' => trim((string)(isset($employeeData['employee_code']) ? $employeeData['employee_code'] : '')),
                    'salary_type' => strtolower(trim((string)(isset($employeeData['salary_type']) ? $employeeData['salary_type'] : 'monthly')))
                );
            }
        }
        $this->set('assetRows', $assetRows);
        $this->set('expenseRows', $expenseRows);
        $this->set('ledgerEntryCounts', $ledgerEntryCounts);
        $this->set('employeeLedgerMetaByLedgerId', $employeeLedgerMetaByLedgerId);

        $formMode = 'add';
        $editId = isset($this->request->params['named']['edit']) ? (int)$this->request->params['named']['edit'] : 0;
        if($editId > 0)
        {
            $editRow = $this->Ardledger->findById($editId);
            if(!empty($editRow) && $this->_isAllowedProject((int)$editRow['Ardledger']['project_id']))
            {
                $this->request->data = $editRow;
                $formMode = 'edit';
            }
        }

        $viewId = isset($this->request->params['named']['view']) ? (int)$this->request->params['named']['view'] : 0;
        if($viewId > 0)
        {
            $viewRow = $this->Ardledger->findById($viewId);
            if(!empty($viewRow) && $this->_isAllowedProject((int)$viewRow['Ardledger']['project_id']))
            {
                $this->request->data = $viewRow;
                $formMode = 'view';
            }
        }
        $this->set('ledgerFormMode', $formMode);
    }

    public function deleteledger($id = null, $projectId = null)
    {
        $this->loadModel('Admin.Ardledger');
        $this->loadModel('Admin.Ardtransaction');
        $row = $this->Ardledger->findById($id);
        if(empty($row) || !$this->_isAllowedProject((int)$row['Ardledger']['project_id']))
        {
            $this->Session->setFlash(__('Invalid ledger.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'ledgers', $projectId));
        }
        $entryCount = $this->Ardtransaction->find('count', array(
            'conditions' => array(
                'OR' => array(
                    'Ardtransaction.ledger_id' => (int)$id,
                    'Ardtransaction.expense_ledger_id' => (int)$id,
                    'Ardtransaction.income_ledger_id' => (int)$id
                )
            ),
            'recursive' => -1
        ));
        $hasBalance = isset($row['Ardledger']['balance']) && abs((float)$row['Ardledger']['balance']) > 0.001;
        if($entryCount > 0 || $hasBalance)
        {
            $this->Session->setFlash(__('This ledger cannot be deleted because transactions or a non-zero balance are recorded in it.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'ledgers', $projectId));
        }
        $this->_storeTrashRecord(
            'ardaccounts_ledgers',
            'Ardledger',
            $row['Ardledger'],
            isset($row['Ardledger']['name']) ? (string)$row['Ardledger']['name'] : ''
        );
        $this->Ardledger->delete($id);
        $this->Session->setFlash(__('Ledger deleted. You can restore it from Trash.'), 'flash', array('alert' => 'success'));
        return $this->redirect(array('action' => 'ledgers', $projectId));
    }

    public function ledgerstatement($ledgerId = null, $id = null)
    {
        $this->loadModel('Admin.Ardledger');
        $this->loadModel('Admin.Ardtransaction');
        $this->loadModel('Admin.Agency');
        $this->loadModel('Admin.Ardsetting');

        $ledgerId = (int)$ledgerId;
        $id = $this->_activeProjectId($id);
        if($ledgerId <= 0)
        {
            $this->Session->setFlash(__('Invalid ledger.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'ledgers', $id));
        }

        $scope = $this->_scopeCondition('Ardledger.project_id', $id);
        $ledgerConditions = array(
            'Ardledger.id' => $ledgerId,
            'Ardledger.is_trashed' => 0
        );
        if(!empty($scope))
        {
            $ledgerConditions[] = $scope;
        }
        $ledger = $this->Ardledger->find('first', array(
            'conditions' => $ledgerConditions,
            'recursive' => -1
        ));
        if(empty($ledger) || !$this->_isAllowedProject((int)$ledger['Ardledger']['project_id']))
        {
            $this->Session->setFlash(__('Invalid ledger.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'ledgers', $id));
        }
        $this->_recalculateLedgerBalance($ledgerId);
        $freshBalance = $this->Ardledger->field('balance', array('Ardledger.id' => $ledgerId));
        if($freshBalance !== false && $freshBalance !== null)
        {
            $ledger['Ardledger']['balance'] = (float)$freshBalance;
        }

        $projectId = (int)$ledger['Ardledger']['project_id'];
        $this->set('projectName', $this->_projectList());
        $this->set('agencyId', $this->agencyId);
        $this->set('currentProjectId', $projectId);

        $agency = $this->Agency->find('first', array(
            'conditions' => array('Agency.id' => $projectId),
            'recursive' => -1
        ));
        $settings = $this->Ardsetting->find('first', array(
            'conditions' => array('Ardsetting.project_id' => $projectId),
            'order' => array('Ardsetting.id' => 'desc'),
            'recursive' => -1
        ));

        $allowedPeriods = array('daily', 'monthly', 'yearly', 'lifetime', 'custom');
        $filterPeriod = isset($this->request->query['period']) ? strtolower(trim((string)$this->request->query['period'])) : 'lifetime';
        if(!in_array($filterPeriod, $allowedPeriods))
        {
            $filterPeriod = 'lifetime';
        }
        $startRaw = isset($this->request->query['start_date']) ? trim((string)$this->request->query['start_date']) : '';
        $endRaw = isset($this->request->query['end_date']) ? trim((string)$this->request->query['end_date']) : '';
        $normalizeDate = function($value) {
            $value = trim((string)$value);
            if($value === '')
            {
                return '';
            }
            $value = str_replace('/', '-', $value);
            $ts = strtotime($value);
            if($ts === false)
            {
                return '';
            }
            return date('Y-m-d', $ts);
        };
        $startDate = $normalizeDate($startRaw);
        $endDate = $normalizeDate($endRaw);

        $todayDate = date('Y-m-d');
        if($filterPeriod === 'daily')
        {
            if($startDate === '' && $endDate === '')
            {
                $startDate = $todayDate;
                $endDate = $todayDate;
            }
            elseif($startDate !== '' && $endDate === '')
            {
                $endDate = $startDate;
            }
            elseif($startDate === '' && $endDate !== '')
            {
                $startDate = $endDate;
            }
        }
        elseif($filterPeriod === 'monthly')
        {
            $baseDate = ($startDate !== '' ? $startDate : ($endDate !== '' ? $endDate : $todayDate));
            $startDate = date('Y-m-01', strtotime($baseDate));
            $endDate = date('Y-m-t', strtotime($baseDate));
        }
        elseif($filterPeriod === 'yearly')
        {
            $baseDate = ($startDate !== '' ? $startDate : ($endDate !== '' ? $endDate : $todayDate));
            $year = date('Y', strtotime($baseDate));
            $startDate = $year . '-01-01';
            $endDate = $year . '-12-31';
        }
        elseif($filterPeriod === 'lifetime')
        {
            $startDate = '';
            $endDate = '';
        }

        if($startDate !== '' && $endDate !== '' && strtotime($startDate) > strtotime($endDate))
        {
            $tempDate = $startDate;
            $startDate = $endDate;
            $endDate = $tempDate;
        }

        $txConditions = array(
            'Ardtransaction.project_id' => $projectId,
            'NOT' => array('Ardtransaction.status' => array('Void', 'Reversed')),
            'OR' => array(
                'Ardtransaction.ledger_id' => $ledgerId,
                array(
                    'Ardtransaction.type' => 'expense',
                    'Ardtransaction.expense_ledger_id' => $ledgerId
                ),
                array(
                    'Ardtransaction.type' => 'income',
                    'Ardtransaction.income_ledger_id' => $ledgerId
                )
            )
        );
        $txScope = $this->_scopeCondition('Ardtransaction.project_id', $projectId);
        if(!empty($txScope))
        {
            $txConditions[] = $txScope;
        }
        if($startDate !== '')
        {
            $txConditions['Ardtransaction.entry_date >='] = $startDate;
        }
        if($endDate !== '')
        {
            $txConditions['Ardtransaction.entry_date <='] = $endDate;
        }

        $txRows = $this->Ardtransaction->find('all', array(
            'fields' => array(
                'Ardtransaction.*'
            ),
            'conditions' => $txConditions,
            'order' => array('Ardtransaction.entry_date' => 'asc', 'Ardtransaction.id' => 'asc'),
            'recursive' => -1
        ));

        $accType = !empty($ledger['Ardledger']['account_type']) ? strtolower(trim((string)$ledger['Ardledger']['account_type'])) : (!empty($ledger['Ardledger']['type']) ? strtolower(trim((string)$ledger['Ardledger']['type'])) : 'asset');
        $legacyType = !empty($ledger['Ardledger']['type']) ? strtolower(trim((string)$ledger['Ardledger']['type'])) : '';
        $isExpenseLedger = ($legacyType === 'expense' || $accType === 'expense');

        $debitTotal = 0.0;
        $creditTotal = 0.0;
        $runningBalance = 0.0;
        $statementRows = array();
        foreach($txRows as $txRow)
        {
            $tx = $txRow['Ardtransaction'];
            $amount = (float)$tx['amount'];
            $txType = strtolower(trim((string)$tx['type']));
            $sourceLedgerId = (int)(isset($tx['ledger_id']) ? $tx['ledger_id'] : 0);
            $expenseLedgerId = (int)(isset($tx['expense_ledger_id']) ? $tx['expense_ledger_id'] : 0);
            $incomeLedgerId = (int)(isset($tx['income_ledger_id']) ? $tx['income_ledger_id'] : 0);
            $isSourceSide = ($sourceLedgerId === $ledgerId);
            $isExpenseSide = ($txType === 'expense' && $expenseLedgerId === $ledgerId && !$isSourceSide);
            $isIncomeSide = ($txType === 'income' && $incomeLedgerId === $ledgerId && !$isSourceSide);
            $isTransferInSide = ($txType === 'transfer' && $expenseLedgerId === $ledgerId && !$isSourceSide);
            if(!$isSourceSide && !$isExpenseSide && !$isIncomeSide && !$isTransferInSide)
            {
                continue;
            }
            $debitAmount = 0.0;
            $creditAmount = 0.0;
            if($isSourceSide)
            {
                if($txType === 'income' || $txType === 'transfer_in')
                {
                    $debitAmount = $amount;
                    $runningBalance += $amount;
                }
                else
                {
                    $creditAmount = $amount;
                    $runningBalance -= $amount;
                }
            }
            elseif($isExpenseSide)
            {
                $debitAmount = $amount;
                if($isExpenseLedger)
                {
                    $runningBalance += $amount;
                }
                else
                {
                    $runningBalance -= $amount;
                }
            }
            elseif($isIncomeSide)
            {
                $creditAmount = $amount;
                $runningBalance += $amount;
            }
            elseif($isTransferInSide)
            {
                $debitAmount = $amount;
                $runningBalance += $amount;
            }

            $debitTotal += $debitAmount;
            $creditTotal += $creditAmount;
            $tx['debit_amount'] = $debitAmount;
            $tx['credit_amount'] = $creditAmount;
            $tx['running_balance'] = $runningBalance;
            $statementRows[] = $tx;
        }
        $closingBalance = $runningBalance;

        $exportType = isset($this->request->query['export']) ? strtolower(trim((string)$this->request->query['export'])) : '';
        if($exportType === 'csv')
        {
            $currencySymbol = trim((string)$this->currency);
            $currencySymbol = trim(strip_tags($currencySymbol));
            if($currencySymbol === '')
            {
                $currencySymbol = 'Rs';
            }

            $csvHandle = fopen('php://temp', 'r+');
            fputcsv($csvHandle, array('Ledger Statement', isset($ledger['Ardledger']['name']) ? $ledger['Ardledger']['name'] : ''));
            fputcsv($csvHandle, array('Type', (isset($ledger['Ardledger']['type']) && strtolower((string)$ledger['Ardledger']['type']) === 'expense') ? 'Expense' : 'Bank/Asset'));
            fputcsv($csvHandle, array('Filter', ucfirst($filterPeriod)));
            if($filterPeriod === 'custom')
            {
                $startDateLabel = ($startDate !== '' && strtotime($startDate) !== false) ? date('d-M-Y', strtotime($startDate)) : '';
                $endDateLabel = ($endDate !== '' && strtotime($endDate) !== false) ? date('d-M-Y', strtotime($endDate)) : '';
                fputcsv($csvHandle, array('Start Date', $startDateLabel));
                fputcsv($csvHandle, array('End Date', $endDateLabel));
            }
            fputcsv($csvHandle, array());
            fputcsv($csvHandle, array('#', 'Date', 'Reference', 'Type', 'Description', 'Debit', 'Credit', 'Balance'));

            $rowNo = 0;
            foreach($statementRows as $tx)
            {
                $rowNo++;
                $txDate = '';
                if(!empty($tx['entry_date']) && $tx['entry_date'] !== '0000-00-00')
                {
                    $txDate = date('d-M-Y', strtotime((string)$tx['entry_date']));
                }
                $debitText = ((float)$tx['debit_amount'] > 0) ? ($currencySymbol . ' ' . number_format((float)$tx['debit_amount'], 2, '.', ',')) : '';
                $creditText = ((float)$tx['credit_amount'] > 0) ? ($currencySymbol . ' ' . number_format((float)$tx['credit_amount'], 2, '.', ',')) : '';
                $balanceText = $currencySymbol . ' ' . number_format((float)$tx['running_balance'], 2, '.', ',');
                fputcsv($csvHandle, array(
                    $rowNo,
                    $txDate,
                    isset($tx['ref_no']) ? (string)$tx['ref_no'] : '',
                    isset($tx['type']) ? ucwords(str_replace('_', ' ', (string)$tx['type'])) : '',
                    isset($tx['description']) ? (string)$tx['description'] : '',
                    $debitText,
                    $creditText,
                    $balanceText
                ));
            }

            fputcsv($csvHandle, array('', '', '', '', 'Totals', $currencySymbol . ' ' . number_format($debitTotal, 2, '.', ','), $currencySymbol . ' ' . number_format($creditTotal, 2, '.', ','), $currencySymbol . ' ' . number_format($closingBalance, 2, '.', ',')));
            rewind($csvHandle);
            $csvOutput = stream_get_contents($csvHandle);
            fclose($csvHandle);

            $safeLedgerName = preg_replace('/[^A-Za-z0-9_-]/', '_', (string)$ledger['Ardledger']['name']);
            if(trim((string)$safeLedgerName) === '')
            {
                $safeLedgerName = 'ledger';
            }
            $filename = 'ledger_statement_' . $safeLedgerName . '_' . date('Ymd_His') . '.csv';
            $this->response->type('csv');
            $this->response->download($filename);
            $this->response->body($csvOutput);
            return $this->response;
        }

        $this->set('ledger', $ledger['Ardledger']);
        $this->set('agency', !empty($agency['Agency']) ? $agency['Agency'] : array());
        $this->set('ardSettings', !empty($settings['Ardsetting']) ? $settings['Ardsetting'] : array());
        $this->set('statementRows', $statementRows);
        $this->set('debitTotal', $debitTotal);
        $this->set('creditTotal', $creditTotal);
        $this->set('closingBalance', $closingBalance);
        $this->set('statementFilter', array(
            'period' => $filterPeriod,
            'start_date' => $startDate,
            'end_date' => $endDate
        ));
    }

    public function expenseapprovals($id = null)
    {
        $this->loadModel('Admin.Ardexpenseapprovalrequest');
        $this->loadModel('Admin.Ardexpenseapprovalhistory');
        $this->loadModel('User');
        $projectOptions = $this->_activeAgencyProjectList();
        $id = $this->_activeProjectId($id);
        if($this->_isGlobalAdmin() && !empty($projectOptions) && ($id <= 0 || !isset($projectOptions[$id])))
        {
            $projectIds = array_keys($projectOptions);
            return $this->redirect(array('action' => 'expenseapprovals', (int)reset($projectIds)));
        }
        if(!$this->_isAllowedProject($id) || !isset($projectOptions[$id]))
        {
            throw new ForbiddenException(__('You are not allowed to access this agency approval queue.'));
        }
        $actor = $this->_expenseApprovalActor();
        $canCreate = $this->_isExpenseApprovalAccountant($actor);
        $canVerify = $this->_isExpenseApprovalManager($actor);
        $canFinalApprove = $this->_isExpenseApprovalCeo($id, $actor);
        if(!$canCreate && !$canVerify && !$canFinalApprove && empty($actor['is_super']))
        {
            throw new ForbiddenException(__('Your role is not assigned to the expense approval workflow.'));
        }

        $conditions = array('Ardexpenseapprovalrequest.project_id' => $id);
        $statusFilter = !empty($this->request->query['status']) ? trim((string)$this->request->query['status']) : '';
        $validStatuses = array('Pending Manager', 'Pending CEO', 'Approved', 'Rejected');
        if(in_array($statusFilter, $validStatuses, true))
        {
            $conditions['Ardexpenseapprovalrequest.status'] = $statusFilter;
        }
        $this->Paginator->settings = array(
            'conditions' => $conditions,
            'order' => array('Ardexpenseapprovalrequest.id' => 'desc'),
            'limit' => $this->pageLimit,
            'maxLimit' => $this->maxLimit,
            'recursive' => 0
        );
        $requests = $this->Paginator->paginate('Ardexpenseapprovalrequest');
        $requestIds = array();
        foreach((array)$requests as $requestRow)
        {
            if(!empty($requestRow['Ardexpenseapprovalrequest']['id']))
            {
                $requestIds[] = (int)$requestRow['Ardexpenseapprovalrequest']['id'];
            }
        }
        $historyMap = array();
        if(!empty($requestIds))
        {
            $historyRows = $this->Ardexpenseapprovalhistory->find('all', array(
                'conditions' => array('Ardexpenseapprovalhistory.project_id' => $id, 'Ardexpenseapprovalhistory.request_id' => $requestIds),
                'order' => array('Ardexpenseapprovalhistory.created' => 'asc', 'Ardexpenseapprovalhistory.id' => 'asc'),
                'recursive' => 0
            ));
            foreach((array)$historyRows as $historyRow)
            {
                $requestId = (int)$historyRow['Ardexpenseapprovalhistory']['request_id'];
                if(!isset($historyMap[$requestId])) { $historyMap[$requestId] = array(); }
                $historyMap[$requestId][] = $historyRow;
            }
        }
        $ceoOptions = $this->_expenseApprovalUserOptions($id);
        $roleReadiness = $this->_expenseApprovalRoleReadiness($id);
        $approvalConfig = $this->_expenseApprovalConfig($id);
        $statusCounts = array_fill_keys($validStatuses, 0);
        $countRows = $this->Ardexpenseapprovalrequest->find('all', array(
            'fields' => array('Ardexpenseapprovalrequest.status', 'COUNT(Ardexpenseapprovalrequest.id) AS total'),
            'conditions' => array('Ardexpenseapprovalrequest.project_id' => $id),
            'group' => array('Ardexpenseapprovalrequest.status'),
            'recursive' => -1
        ));
        foreach((array)$countRows as $countRow)
        {
            $status = isset($countRow['Ardexpenseapprovalrequest']['status']) ? $countRow['Ardexpenseapprovalrequest']['status'] : '';
            if(array_key_exists($status, $statusCounts))
            {
                $statusCounts[$status] = !empty($countRow[0]['total']) ? (int)$countRow[0]['total'] : 0;
            }
        }
        $this->set('currentProjectId', $id);
        $this->set('agencyId', $this->agencyId);
        $this->set(compact('projectOptions', 'requests', 'historyMap', 'approvalConfig', 'ceoOptions', 'roleReadiness', 'statusCounts', 'statusFilter', 'actor', 'canCreate', 'canVerify', 'canFinalApprove'));
    }

    public function expenseapprovalsettings()
    {
        if(!$this->request->is('post'))
        {
            throw new MethodNotAllowedException();
        }
        if(!$this->_isGlobalAdmin())
        {
            throw new ForbiddenException(__('Only Super Admin can change expense approval settings.'));
        }
        $posted = isset($this->request->data['ExpenseApprovalSetting']) ? (array)$this->request->data['ExpenseApprovalSetting'] : array();
        $projectId = !empty($posted['project_id']) ? (int)$posted['project_id'] : 0;
        $enabled = !empty($posted['enabled']) ? 1 : 0;
        $ceoUserId = !empty($posted['ceo_user_id']) ? (int)$posted['ceo_user_id'] : 0;
        if($projectId <= 0)
        {
            throw new NotFoundException(__('Invalid agency.'));
        }
        $activeProjects = $this->_activeAgencyProjectList();
        if(!isset($activeProjects[$projectId]))
        {
            throw new NotFoundException(__('This agency is no longer active.'));
        }
        if($ceoUserId > 0)
        {
            $this->loadModel('User');
            if(!$this->User->userHasProjectAccess($ceoUserId, $projectId))
            {
                $this->Session->setFlash(__('Selected CEO does not have access to this agency.'), 'flash', array('alert' => 'danger'));
                return $this->redirect(array('action' => 'settings', $projectId, '?' => array('tab' => 'general')));
            }
        }
        if($enabled)
        {
            $roleReadiness = $this->_expenseApprovalRoleReadiness($projectId);
            $hasCeo = $ceoUserId > 0 || !empty($roleReadiness['ceos']);
            if(empty($roleReadiness['accountants']) || empty($roleReadiness['managers']) || !$hasCeo)
            {
                $this->Session->setFlash(__('Assign at least one Accountant, one Manager, and one CEO/Agency Owner to this agency before enabling the workflow.'), 'flash', array('alert' => 'danger'));
                return $this->redirect(array('action' => 'settings', $projectId, '?' => array('tab' => 'general')));
            }
        }
        $this->loadModel('Admin.Ardsetting');
        $this->Ardsetting->query(
            "INSERT INTO `ardaccounts_settings` (`project_id`,`expense_approval_enabled`,`expense_approval_ceo_user_id`,`created`,`modified`) VALUES (".$projectId.",".$enabled.",".$ceoUserId.",NOW(),NOW()) "
            ."ON DUPLICATE KEY UPDATE `expense_approval_enabled`=VALUES(`expense_approval_enabled`),`expense_approval_ceo_user_id`=VALUES(`expense_approval_ceo_user_id`),`modified`=NOW()"
        );
        $this->Session->setFlash(__('Expense approval workflow settings have been saved.'), 'flash', array('alert' => 'success'));
        return $this->redirect(array('action' => 'settings', $projectId, '?' => array('tab' => 'general')));
    }

    public function verifyexpenseapproval($requestId = null)
    {
        if(!$this->request->is('post')) { throw new MethodNotAllowedException(); }
        return $this->_transitionExpenseApproval((int)$requestId, 'verify');
    }

    public function reviewexpenseapproval($requestId = null)
    {
        $this->loadModel('Admin.Ardexpenseapprovalrequest');
        $this->loadModel('Admin.Ardledger');
        $this->loadModel('Admin.Ardsite');
        $requestId = (int)$requestId;
        $row = $this->_expenseApprovalDetailRow($requestId);
        if(empty($row['Ardexpenseapprovalrequest']['id']))
        {
            throw new NotFoundException(__('Expense approval request was not found.'));
        }
        $request = (array)$row['Ardexpenseapprovalrequest'];
        $projectId = (int)$request['project_id'];
        if(!$this->_isAllowedProject($projectId))
        {
            throw new ForbiddenException(__('You are not allowed to review this agency request.'));
        }
        $actor = $this->_expenseApprovalActor();
        if(!$this->_isExpenseApprovalManager($actor))
        {
            throw new ForbiddenException(__('Only a Manager can edit an expense approval request.'));
        }
        if(!in_array($request['status'], array('Pending Manager', 'Pending CEO'), true) || (int)$request['transaction_id'] > 0)
        {
            $this->Session->setFlash(__('Only an unposted request awaiting approval can be edited.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'expenseapprovals', $projectId));
        }
        if(empty($actor['is_super']) && (int)$request['created_by'] === (int)$actor['user_id'])
        {
            throw new ForbiddenException(__('The requester cannot review their own expense request.'));
        }

        if($this->request->is(array('post', 'put')))
        {
            $posted = isset($this->request->data['ExpenseApprovalEdit']) ? (array)$this->request->data['ExpenseApprovalEdit'] : array();
            $entryDate = $this->_reportNormalizeDate(isset($posted['entry_date']) ? $posted['entry_date'] : '', false);
            $ledgerId = !empty($posted['ledger_id']) ? (int)$posted['ledger_id'] : 0;
            $expenseLedgerId = !empty($posted['expense_ledger_id']) ? (int)$posted['expense_ledger_id'] : 0;
            $siteId = !empty($posted['construction_site_id']) ? (int)$posted['construction_site_id'] : 0;
            $sourceValid = $this->Ardledger->find('count', array('conditions' => array('Ardledger.id' => $ledgerId, 'Ardledger.project_id' => $projectId, 'Ardledger.is_trashed' => 0, 'Ardledger.type' => array('asset', 'bank')), 'recursive' => -1));
            $expenseValid = $this->Ardledger->find('count', array('conditions' => array('Ardledger.id' => $expenseLedgerId, 'Ardledger.project_id' => $projectId, 'Ardledger.is_trashed' => 0, 'Ardledger.type' => 'expense'), 'recursive' => -1));
            $siteValid = $siteId <= 0 || $this->Ardsite->find('count', array('conditions' => array('Ardsite.id' => $siteId, 'Ardsite.project_id' => $projectId), 'recursive' => -1));
            if($entryDate === '' || !$sourceValid || !$expenseValid || !$siteValid)
            {
                $this->Session->setFlash(__('Please select a valid date, Asset/Bank account, Expense account, and Stock Store for this agency.'), 'flash', array('alert' => 'danger'));
            }
            else
            {
                $db = $this->Ardexpenseapprovalrequest->getDataSource();
                $db->begin();
                try
                {
                    $lockedRows = $this->Ardexpenseapprovalrequest->query("SELECT * FROM `ardaccounts_expense_approval_requests` WHERE `id`=".$requestId." AND `project_id`=".$projectId." LIMIT 1 FOR UPDATE");
                    $locked = !empty($lockedRows[0]['ardaccounts_expense_approval_requests']) ? $lockedRows[0]['ardaccounts_expense_approval_requests'] : (!empty($lockedRows[0][0]) ? $lockedRows[0][0] : array());
                    if(empty($locked['id']) || !in_array($locked['status'], array('Pending Manager', 'Pending CEO'), true) || (int)$locked['transaction_id'] > 0 || (int)$locked['ceo_approved_by'] > 0)
                    {
                        throw new Exception(__('This request changed and can no longer be edited.'));
                    }
                    $save = array(
                        'id' => $requestId,
                        'entry_date' => $entryDate,
                        'ledger_id' => $ledgerId,
                        'expense_ledger_id' => $expenseLedgerId,
                        'construction_site_id' => $siteId,
                        'ref_no' => substr(trim((string)(isset($posted['ref_no']) ? $posted['ref_no'] : '')), 0, 80),
                        'description' => trim((string)(isset($posted['description']) ? $posted['description'] : ''))
                    );
                    if(!$this->Ardexpenseapprovalrequest->save(array('Ardexpenseapprovalrequest' => $save), array('validate' => false, 'callbacks' => false)))
                    {
                        throw new Exception(__('Manager changes could not be saved.'));
                    }
                    if(!$this->_saveExpenseApprovalHistory($requestId, $projectId, 'Manager Edited', $locked['status'], $locked['status'], __('Manager updated voucher details. Amount remained locked.'), (int)$actor['user_id']))
                    {
                        throw new Exception(__('Approval timeline could not be saved.'));
                    }
                    $db->commit();
                    if($locked['status'] === 'Pending CEO')
                    {
                        $this->_dispatchExpenseApprovalNotifications($requestId, 'ceo');
                    }
                    $this->Session->setFlash(__('Expense request details have been updated. The amount was not changed.'), 'flash', array('alert' => 'success'));
                    return $this->redirect(array('action' => 'expenseapprovals', $projectId));
                }
                catch(Exception $e)
                {
                    $db->rollback();
                    CakeLog::write('error', 'Expense approval Manager edit failed: '.$e->getMessage());
                    $this->Session->setFlash($e->getMessage(), 'flash', array('alert' => 'danger'));
                }
            }
            $request = array_merge($request, $posted);
            $request['entry_date'] = $entryDate !== '' ? $entryDate : $request['entry_date'];
            $row['Ardexpenseapprovalrequest'] = $request;
        }

        $sourceLedgers = $this->Ardledger->find('list', array('fields' => array('Ardledger.id', 'Ardledger.name'), 'conditions' => array('Ardledger.project_id' => $projectId, 'Ardledger.is_trashed' => 0, 'Ardledger.type' => array('asset', 'bank')), 'order' => array('Ardledger.name' => 'asc'), 'recursive' => -1));
        $expenseLedgers = $this->Ardledger->find('list', array('fields' => array('Ardledger.id', 'Ardledger.name'), 'conditions' => array('Ardledger.project_id' => $projectId, 'Ardledger.is_trashed' => 0, 'Ardledger.type' => 'expense'), 'order' => array('Ardledger.name' => 'asc'), 'recursive' => -1));
        $siteList = $this->Ardsite->find('list', array('fields' => array('Ardsite.id', 'Ardsite.site_name'), 'conditions' => array('Ardsite.project_id' => $projectId), 'order' => array('Ardsite.site_name' => 'asc'), 'recursive' => -1));
        $this->set(compact('row', 'request', 'sourceLedgers', 'expenseLedgers', 'siteList', 'projectId'));
    }

    public function unverifyexpenseapproval($requestId = null)
    {
        if(!$this->request->is('post')) { throw new MethodNotAllowedException(); }
        $this->loadModel('Admin.Ardexpenseapprovalrequest');
        $requestId = (int)$requestId;
        $initial = $this->_expenseApprovalDetailRow($requestId);
        $projectId = !empty($initial['Ardexpenseapprovalrequest']['project_id']) ? (int)$initial['Ardexpenseapprovalrequest']['project_id'] : 0;
        if($projectId <= 0 || !$this->_isAllowedProject($projectId))
        {
            throw new NotFoundException(__('Invalid expense approval request.'));
        }
        $actor = $this->_expenseApprovalActor();
        if(!$this->_isExpenseApprovalManager($actor))
        {
            throw new ForbiddenException(__('Only a Manager can return this request to unapproved.'));
        }
        $db = $this->Ardexpenseapprovalrequest->getDataSource();
        $db->begin();
        try
        {
            $lockedRows = $this->Ardexpenseapprovalrequest->query("SELECT * FROM `ardaccounts_expense_approval_requests` WHERE `id`=".$requestId." AND `project_id`=".$projectId." LIMIT 1 FOR UPDATE");
            $request = !empty($lockedRows[0]['ardaccounts_expense_approval_requests']) ? $lockedRows[0]['ardaccounts_expense_approval_requests'] : (!empty($lockedRows[0][0]) ? $lockedRows[0][0] : array());
            if(empty($request['id']) || $request['status'] !== 'Pending CEO' || (int)$request['transaction_id'] > 0 || (int)$request['ceo_approved_by'] > 0)
            {
                throw new Exception(__('Only an unposted request awaiting CEO approval can be returned.'));
            }
            if(!$this->Ardexpenseapprovalrequest->save(array('Ardexpenseapprovalrequest' => array('id' => $requestId, 'status' => 'Pending Manager', 'manager_verified_by' => 0, 'manager_verified_at' => null)), array('validate' => false, 'callbacks' => false)))
            {
                throw new Exception(__('The request could not be returned to unapproved.'));
            }
            if(!$this->_saveExpenseApprovalHistory($requestId, $projectId, 'Returned to Unapproved', 'Pending CEO', 'Pending Manager', __('Manager approval was withdrawn before CEO approval.'), (int)$actor['user_id']))
            {
                throw new Exception(__('Approval timeline could not be saved.'));
            }
            $db->commit();
            $this->Session->setFlash(__('Manager approval has been withdrawn. The request is Pending Manager again.'), 'flash', array('alert' => 'success'));
        }
        catch(Exception $e)
        {
            $db->rollback();
            CakeLog::write('error', 'Expense approval return failed: '.$e->getMessage());
            $this->Session->setFlash($e->getMessage(), 'flash', array('alert' => 'danger'));
        }
        return $this->redirect(array('action' => 'expenseapprovals', $projectId));
    }

