    {
        if(!$this->request->is('post')) { throw new MethodNotAllowedException(); }
        return $this->_transitionExpenseApproval((int)$requestId, 'reject');
    }

    protected function _expenseApprovalUserOptions($projectId)
    {
        $this->loadModel('User');
        $conditions = array('User.status' => 'Active', 'User.deleted IS NULL');
        $membership = $this->User->projectMembershipCondition((int)$projectId, 'User');
        if($membership !== '') { $conditions[] = $membership; }
        $rows = $this->User->find('all', array('fields' => array('User.id', 'User.name', 'User.username', 'Ugroup.name'), 'conditions' => $conditions, 'order' => array('User.name' => 'asc'), 'recursive' => 0));
        $options = array();
        foreach((array)$rows as $row)
        {
            $user = $row['User'];
            $label = trim((string)$user['name']) !== '' ? $user['name'] : $user['username'];
            if(!empty($row['Ugroup']['name'])) { $label .= ' - '.$row['Ugroup']['name']; }
            $options[(int)$user['id']] = $label;
        }
        return $options;
    }

    protected function _expenseApprovalRoleReadiness($projectId)
    {
        $this->loadModel('User');
        $conditions = array('User.status' => 'Active', 'User.deleted IS NULL');
        $membership = $this->User->projectMembershipCondition((int)$projectId, 'User');
        if($membership !== '') { $conditions[] = $membership; }
        $rows = $this->User->find('all', array('fields' => array('User.id', 'User.name', 'User.username', 'User.ugroup_id', 'Ugroup.name'), 'conditions' => $conditions, 'recursive' => 0));
        $roles = array('accountants' => array(), 'managers' => array(), 'ceos' => array());
        foreach((array)$rows as $row)
        {
            $user = $row['User'];
            $groupId = (int)$user['ugroup_id'];
            $groupName = strtolower(trim((string)(isset($row['Ugroup']['name']) ? $row['Ugroup']['name'] : '')));
            $label = trim((string)$user['name']) !== '' ? $user['name'] : $user['username'];
            if($groupId === 6 || strpos($groupName, 'account') !== false) { $roles['accountants'][(int)$user['id']] = $label; }
            if($groupId === 3 || strpos($groupName, 'manager') !== false) { $roles['managers'][(int)$user['id']] = $label; }
            if($groupId === 4 || $groupName === 'ceo' || $groupName === 'agency') { $roles['ceos'][(int)$user['id']] = $label; }
        }
        return $roles;
    }

