    protected function _expenseApprovalVoucherHtml($row)
    {
        $request = !empty($row['Ardexpenseapprovalrequest']) ? (array)$row['Ardexpenseapprovalrequest'] : array();
        if(empty($request['id']))
        {
            return '';
        }
        $agency = !empty($row['Agency']) ? (array)$row['Agency'] : array();
        $source = !empty($row['SourceLedger']) ? (array)$row['SourceLedger'] : array();
        $expense = !empty($row['ExpenseLedger']) ? (array)$row['ExpenseLedger'] : array();
        $creator = !empty($row['Creator']) ? (array)$row['Creator'] : array();
        $manager = !empty($row['ManagerVerifier']) ? (array)$row['ManagerVerifier'] : array();
        $ceo = !empty($row['CeoApprover']) ? (array)$row['CeoApprover'] : array();
        $status = trim((string)(isset($request['status']) ? $request['status'] : 'Pending Manager'));
        $isApproved = ($status === 'Approved');
        $isRejected = ($status === 'Rejected');
        $watermark = $isApproved ? 'APPROVED' : ($isRejected ? 'REJECTED' : 'UN-APPROVED');
        $statusColor = $isApproved ? '#15803d' : ($isRejected ? '#b91c1c' : '#b45309');
        $entryTime = !empty($request['entry_date']) ? strtotime($request['entry_date']) : false;
        $voucherDate = $entryTime ? date('d-M-Y', $entryTime) : '-';
        $currencySymbol = trim(strip_tags((string)$this->currency));
        if($currencySymbol === '') { $currencySymbol = 'Rs'; }
        $amount = $currencySymbol.' '.number_format((float)$request['amount'], 2, '.', ',');
        $personName = function($person) {
            $name = trim((string)(isset($person['name']) ? $person['name'] : ''));
            if($name === '') { $name = trim((string)(isset($person['username']) ? $person['username'] : '')); }
            return $name !== '' ? $name : '-';
        };
        $managerAt = !empty($request['manager_verified_at']) ? date('d-M-Y h:i A', strtotime($request['manager_verified_at'])) : '-';
        $approvedAt = !empty($request['ceo_approved_at']) ? date('d-M-Y h:i A', strtotime($request['ceo_approved_at'])) : '-';
        $submittedAt = !empty($request['submitted_at']) ? date('d-M-Y h:i A', strtotime($request['submitted_at'])) : '-';
        $footer = $isApproved
            ? 'Approved by '.h($personName($ceo)).' on '.h($approvedAt)
            : ($isRejected ? 'Rejected on '.h(!empty($request['rejected_at']) ? date('d-M-Y h:i A', strtotime($request['rejected_at'])) : '-').' - '.h((string)$request['rejection_reason']) : 'This voucher is awaiting final approval and is not posted to Accounts.');

        return '<style type="text/css">'
            .'.eav{font-family:Arial,sans-serif;color:#172033;border:1px solid #cbd5e1;max-width:820px;margin:12px auto;position:relative;background:#fff;overflow:hidden}.eav *{box-sizing:border-box}.eav-wm{color:'.$statusColor.';font-size:54px;font-weight:900;left:50%;opacity:.09;position:absolute;top:47%;transform:translate(-50%,-50%) rotate(-24deg);white-space:nowrap;z-index:0}.eav-head,.eav-body,.eav-foot{position:relative;z-index:1}.eav-head{text-align:center;border-bottom:2px solid #0b2344;padding:18px}.eav-head h2{font-size:22px;margin:0 0 5px}.eav-head p{font-size:12px;margin:2px 0}.eav-status{color:'.$statusColor.';font-weight:900}.eav-body{padding:16px}.eav-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0;border-left:1px solid #dbe3ee;border-top:1px solid #dbe3ee}.eav-field{border-bottom:1px solid #dbe3ee;border-right:1px solid #dbe3ee;padding:9px}.eav-field.full{grid-column:1/-1}.eav-field small{color:#64748b;display:block;font-size:9px;font-weight:800;margin-bottom:3px;text-transform:uppercase}.eav-field strong{font-size:12px}.eav-amount{font-size:18px!important}.eav-trail{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:15px}.eav-sign{border-top:1px solid #94a3b8;padding-top:6px;text-align:center}.eav-sign strong,.eav-sign small{display:block;font-size:10px}.eav-sign small{color:#64748b;margin-top:3px}.eav-foot{background:#f8fafc;border-top:1px solid #cbd5e1;color:'.$statusColor.';font-size:11px;font-weight:800;padding:11px 16px;text-align:center}@media(max-width:600px){.eav-grid,.eav-trail{grid-template-columns:1fr}.eav-field.full{grid-column:auto}.eav-wm{font-size:34px}}'
            .'</style><div class="eav"><div class="eav-wm">'.h($watermark).'</div><div class="eav-head"><h2>'.h(!empty($agency['name']) ? $agency['name'] : 'White Villas').'</h2><p><strong>EXPENSE APPROVAL VOUCHER</strong></p><p>Reference: '.h((string)$request['ref_no']).' &nbsp; | &nbsp; Status: <span class="eav-status">'.h($status).'</span></p></div><div class="eav-body"><div class="eav-grid">'
            .'<div class="eav-field"><small>Voucher Date</small><strong>'.h($voucherDate).'</strong></div><div class="eav-field"><small>Submitted At</small><strong>'.h($submittedAt).'</strong></div>'
            .'<div class="eav-field"><small>Payment From</small><strong>'.h(!empty($source['name']) ? $source['name'] : '-').'</strong></div><div class="eav-field"><small>Expense Account</small><strong>'.h(!empty($expense['name']) ? $expense['name'] : '-').'</strong></div>'
            .'<div class="eav-field full"><small>Amount</small><strong class="eav-amount">'.h($amount).'</strong></div><div class="eav-field full"><small>Description</small><strong>'.nl2br(h((string)$request['description'])).'</strong></div>'
            .'</div><div class="eav-trail"><div class="eav-sign"><strong>'.h($personName($creator)).'</strong><small>Created by Accountant</small></div><div class="eav-sign"><strong>'.h($personName($manager)).'</strong><small>Manager Verified: '.h($managerAt).'</small></div><div class="eav-sign"><strong>'.h($personName($ceo)).'</strong><small>CEO Approved: '.h($approvedAt).'</small></div></div></div><div class="eav-foot">'.$footer.'</div></div>';
    }

    protected function _expenseApprovalRecipientRows($projectId, $stage)
    {
        $roleReadiness = $this->_expenseApprovalRoleReadiness((int)$projectId);
        $ids = array();
        if($stage === 'manager')
        {
            $ids = array_keys((array)$roleReadiness['managers']);
        }
        elseif($stage === 'ceo')
        {
            $config = $this->_expenseApprovalConfig((int)$projectId);
            $ids = !empty($config['ceo_user_id']) ? array((int)$config['ceo_user_id']) : array_keys((array)$roleReadiness['ceos']);
        }
        $ids = array_values(array_unique(array_filter(array_map('intval', $ids))));
        if(empty($ids))
        {
            return array();
        }
        $this->loadModel('User');
        return (array)$this->User->find('all', array(
            'fields' => array('User.id', 'User.name', 'User.username', 'User.email', 'User.mobile', 'User.phone'),
            'conditions' => array('User.id' => $ids, 'User.status' => 'Active', 'User.deleted IS NULL'),
            'recursive' => -1
        ));
    }

    protected function _expenseApprovalTemplate($modelName, $type, $projectId)
    {
        $this->loadModel($modelName);
        $alias = $this->{$modelName}->alias;
        return (array)$this->{$modelName}->find('first', array(
            'conditions' => array(
                $alias.'.type' => strtoupper((string)$type),
                $alias.'.status' => 'Published',
                'OR' => array(
                    array($alias.'.project_id' => (int)$projectId),
                    array($alias.'.project_id IS NULL'),
                    array($alias.'.project_id' => 0)
                )
            ),
            'order' => array($alias.'.project_id' => 'desc', $alias.'.id' => 'desc'),
            'recursive' => -1
        ));
    }

    protected function _expenseApprovalNotificationTokens($row, $recipient, $stage)
    {
        $request = (array)$row['Ardexpenseapprovalrequest'];
        $personName = function($person) {
            $name = trim((string)(isset($person['name']) ? $person['name'] : ''));
            return $name !== '' ? $name : trim((string)(isset($person['username']) ? $person['username'] : ''));
        };
        $currencySymbol = trim(strip_tags((string)$this->currency));
        if($currencySymbol === '') { $currencySymbol = 'Rs'; }
        $projectId = (int)$request['project_id'];
        $approvalUrl = Router::url(array('plugin' => 'admin', 'admin' => true, 'controller' => 'Ardaccounts', 'action' => 'expenseapprovals', $projectId, '?' => array('status' => $stage === 'manager' ? 'Pending Manager' : 'Pending CEO')), true);
        $voucherUrl = Router::url(array('plugin' => 'admin', 'admin' => true, 'controller' => 'Ardaccounts', 'action' => 'expenseapprovalvoucher', (int)$request['id']), true);
        return array(
            '$recipientName' => $personName($recipient),
            '$referenceNo' => (string)$request['ref_no'],
            '$agencyName' => !empty($row['Agency']['name']) ? (string)$row['Agency']['name'] : '',
            '$voucherDate' => !empty($request['entry_date']) ? date('d-M-Y', strtotime($request['entry_date'])) : '',
            '$amount' => number_format((float)$request['amount'], 2, '.', ','),
            '$amountWithCurrency' => $currencySymbol.' '.number_format((float)$request['amount'], 2, '.', ','),
            '$sourceAccount' => !empty($row['SourceLedger']['name']) ? (string)$row['SourceLedger']['name'] : '',
            '$expenseAccount' => !empty($row['ExpenseLedger']['name']) ? (string)$row['ExpenseLedger']['name'] : '',
            '$requesterName' => $personName(!empty($row['Creator']) ? $row['Creator'] : array()),
            '$managerName' => $personName(!empty($row['ManagerVerifier']) ? $row['ManagerVerifier'] : array()),
            '$description' => (string)$request['description'],
            '$approvalUrl' => $approvalUrl,
            '$voucherUrl' => $voucherUrl,
            '$voucherHtml' => $this->_expenseApprovalVoucherHtml($row),
            '$siteName' => (string)$this->siteName,
            '$emailHeading' => $stage === 'manager' ? 'Expense Approval Required' : 'Final Expense Approval Required',
            '$emailIntro' => $stage === 'manager' ? 'A new expense voucher is waiting for Manager verification.' : 'A verified expense voucher is waiting for CEO approval.',
            '$emailMessage' => $stage === 'manager' ? 'Please review the complete voucher below and verify or reject it.' : 'Please review the Manager-verified voucher below and give the final decision.'
        );
    }

    protected function _expenseApprovalSendWhatsapp($mobile, $message)
    {
        $this->loadModel('Admin.PaymentReminderSetting');
        $settings = (array)$this->PaymentReminderSetting->currentSettings();
        if(empty($settings['send_whatsapp']) || empty($settings['whatsapp_mode']) || $settings['whatsapp_mode'] !== 'api' || empty($settings['whatsapp_api']))
        {
            return false;
        }
        $mobile = preg_replace('/[^0-9]/', '', (string)$mobile);
        if($mobile === '') { return false; }
        $mobileParam = !empty($settings['whatsapp_mobile_param']) ? trim((string)$settings['whatsapp_mobile_param']) : 'number';
        $messageParam = !empty($settings['whatsapp_message_param']) ? trim((string)$settings['whatsapp_message_param']) : 'message';
        $payload = array($mobileParam => $mobile, $messageParam => (string)$message);
        foreach(preg_split('/\r\n|\r|\n/', (string)$settings['whatsapp_extra_params']) as $line)
        {
            if(strpos($line, '=') !== false)
            {
                list($key, $value) = explode('=', $line, 2);
                if(trim($key) !== '') { $payload[trim($key)] = trim($value); }
            }
        }
        $headers = array();
        if(!empty($settings['whatsapp_token']))
        {
            if(!empty($settings['whatsapp_token_header'])) { $headers[trim((string)$settings['whatsapp_token_header'])] = trim((string)$settings['whatsapp_token']); }
            else { $payload['token'] = trim((string)$settings['whatsapp_token']); }
        }
        $socket = new HttpSocket(array('timeout' => 20));
        $requestOptions = !empty($headers) ? array('header' => $headers) : array();
        $response = strtolower(trim((string)$settings['whatsapp_type'])) === 'get'
            ? $socket->get($settings['whatsapp_api'], $payload, $requestOptions)
            : $socket->post($settings['whatsapp_api'], $payload, $requestOptions);
        if($response === false || (isset($response->code) && (int)$response->code >= 400))
        {
            throw new Exception(__('WhatsApp gateway rejected the approval notification.'));
        }
        return true;
    }

    protected function _dispatchExpenseApprovalNotifications($requestId, $stage)
    {
        try
        {
            $row = $this->_expenseApprovalDetailRow((int)$requestId);
            if(empty($row['Ardexpenseapprovalrequest']['id'])) { return; }
            $projectId = (int)$row['Ardexpenseapprovalrequest']['project_id'];
            $smsType = $stage === 'manager' ? 'EAM' : 'EAC';
            $whatsappType = $stage === 'manager' ? 'WAM' : 'WAC';
            $smsTemplate = $this->_expenseApprovalTemplate('Smstemplate', $smsType, $projectId);
            $whatsappTemplate = $this->_expenseApprovalTemplate('Smstemplate', $whatsappType, $projectId);
            $emailTemplate = $this->_expenseApprovalTemplate('Emailtemplate', $smsType, $projectId);
            foreach($this->_expenseApprovalRecipientRows($projectId, $stage) as $recipientRow)
            {
                $recipient = (array)$recipientRow['User'];
                $tokens = $this->_expenseApprovalNotificationTokens($row, $recipient, $stage);
                $mobile = trim((string)(!empty($recipient['mobile']) ? $recipient['mobile'] : $recipient['phone']));
                if($mobile !== '' && !empty($this->smsNotification) && !empty($smsTemplate['Smstemplate']['description']))
                {
                    try { $this->CustomFunction->sendSms($mobile, strtr($smsTemplate['Smstemplate']['description'], $tokens), $this->smsSettingArr); }
                    catch(Exception $e) { CakeLog::write('error', 'Expense approval SMS failed for user '.$recipient['id'].': '.$e->getMessage()); }
                }
                if($mobile !== '' && !empty($whatsappTemplate['Smstemplate']['description']))
                {
                    try { $this->_expenseApprovalSendWhatsapp($mobile, strtr($whatsappTemplate['Smstemplate']['description'], $tokens)); }
                    catch(Exception $e) { CakeLog::write('error', 'Expense approval WhatsApp failed for user '.$recipient['id'].': '.$e->getMessage()); }
                }
                if(!empty($recipient['email']) && !empty($this->emailNotification) && !empty($emailTemplate['Emailtemplate']['description']))
                {
                    try
                    {
                        $Email = new CakeEmail();
                        $Email->transport($this->emailSettype);
                        if(strtoupper((string)$this->emailSettype) === 'SMTP')
                        {
                            $Email->config(array('host' => $this->emailHost, 'port' => $this->emailPort, 'username' => $this->emailUsername, 'password' => $this->emailPassword));
                        }
                        $Email->from(array($this->siteEmail => $this->siteName));
                        $Email->to(trim((string)$recipient['email']));
                        $Email->emailFormat('html');
                        $Email->subject(strtr((string)$emailTemplate['Emailtemplate']['name'], $tokens));
                        $Email->send(strtr((string)$emailTemplate['Emailtemplate']['description'], $tokens));
                    }
                    catch(Exception $e) { CakeLog::write('error', 'Expense approval email failed for user '.$recipient['id'].': '.$e->getMessage()); }
                }
            }
        }
        catch(Exception $e)
        {
            CakeLog::write('error', 'Expense approval notification dispatch failed: '.$e->getMessage());
        }
    }

    protected function _createExpenseApprovalRequest($row)
    {
        $actor = $this->_expenseApprovalActor();
        if(!$this->_isExpenseApprovalAccountant($actor))
        {
            return array('success' => false, 'message' => __('Only an Accountant can create an expense payment request while approval workflow is enabled.'));
        }
        $this->loadModel('Admin.Ardexpenseapprovalrequest');
        $this->loadModel('Admin.Ardexpenseapprovalhistory');
        $db = $this->Ardexpenseapprovalrequest->getDataSource();
        $db->begin();
        try
        {
            $this->Ardexpenseapprovalrequest->create();
            $requestData = array(
                'project_id' => (int)$row['project_id'],
                'ref_no' => trim((string)$row['ref_no']),
                'entry_date' => trim((string)$row['entry_date']),
                'ledger_id' => (int)$row['ledger_id'],
                'expense_ledger_id' => (int)$row['expense_ledger_id'],
                'amount' => round((float)$row['amount'], 2),
                'description' => trim((string)(isset($row['description']) ? $row['description'] : '')),
                'construction_site_id' => (int)$row['construction_site_id'],
                'source_type' => 'manual_expense',
                'source_id' => 0,
                'status' => 'Pending Manager',
                'created_by' => (int)$actor['user_id'],
                'submitted_at' => date('Y-m-d H:i:s')
            );
            if(!$this->Ardexpenseapprovalrequest->save(array('Ardexpenseapprovalrequest' => $requestData), false))
            {
                throw new Exception(__('Expense request could not be saved.'));
            }
            $requestId = (int)$this->Ardexpenseapprovalrequest->id;
            if(!$this->_saveExpenseApprovalHistory($requestId, (int)$row['project_id'], 'Submitted', 'Draft', 'Pending Manager', __('Submitted by Accountant.'), (int)$actor['user_id']))
            {
                throw new Exception(__('Expense request timeline could not be saved.'));
            }
            $db->commit();
            $this->_dispatchExpenseApprovalNotifications($requestId, 'manager');
            return array('success' => true, 'request_id' => $requestId);
        }
        catch(Exception $e)
        {
            $db->rollback();
            CakeLog::write('error', 'Expense approval request failed: '.$e->getMessage());
            return array('success' => false, 'message' => $e->getMessage());
        }
    }

    protected function _saveExpenseApprovalHistory($requestId, $projectId, $action, $fromStatus, $toStatus, $comment, $actorUserId)
    {
        $this->loadModel('Admin.Ardexpenseapprovalhistory');
        $this->Ardexpenseapprovalhistory->create();
        return (bool)$this->Ardexpenseapprovalhistory->save(array('Ardexpenseapprovalhistory' => array(
            'project_id' => (int)$projectId,
            'request_id' => (int)$requestId,
            'actor_user_id' => (int)$actorUserId,
            'action' => substr(trim((string)$action), 0, 40),
            'from_status' => substr(trim((string)$fromStatus), 0, 30),
            'to_status' => substr(trim((string)$toStatus), 0, 30),
            'comment' => trim((string)$comment),
            'created' => date('Y-m-d H:i:s')
        )), false);
    }

    protected function _transitionExpenseApproval($requestId, $action)
    {
        $this->loadModel('Admin.Ardexpenseapprovalrequest');
        $this->loadModel('Admin.Ardexpenseapprovalhistory');
        $this->loadModel('Admin.Ardtransaction');
        $this->loadModel('Admin.Ardledger');
        $requestId = (int)$requestId;
        $initial = $this->Ardexpenseapprovalrequest->find('first', array('conditions' => array('Ardexpenseapprovalrequest.id' => $requestId), 'recursive' => -1));
        $projectId = !empty($initial['Ardexpenseapprovalrequest']['project_id']) ? (int)$initial['Ardexpenseapprovalrequest']['project_id'] : 0;
        if($projectId <= 0 || !$this->_isAllowedProject($projectId))
        {
            throw new NotFoundException(__('Invalid expense approval request.'));
        }
        $actor = $this->_expenseApprovalActor();
        $comment = isset($this->request->data['ApprovalAction']['comment']) ? trim((string)$this->request->data['ApprovalAction']['comment']) : '';
        if($action === 'reject' && $comment === '')
        {
            $this->Session->setFlash(__('A rejection reason is required.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'expenseapprovals', $projectId));
        }
        $db = $this->Ardexpenseapprovalrequest->getDataSource();
        $db->begin();
        try
        {
            $rows = $this->Ardexpenseapprovalrequest->query("SELECT * FROM `ardaccounts_expense_approval_requests` WHERE `id`=".$requestId." AND `project_id`=".$projectId." LIMIT 1 FOR UPDATE");
            $request = !empty($rows[0]['ardaccounts_expense_approval_requests']) ? $rows[0]['ardaccounts_expense_approval_requests'] : (!empty($rows[0][0]) ? $rows[0][0] : array());
            if(empty($request['id']))
            {
                throw new Exception(__('Expense approval request was not found.'));
            }
            $fromStatus = trim((string)$request['status']);
            $actorId = (int)$actor['user_id'];
            if($actorId <= 0)
            {
                throw new Exception(__('Invalid approval user.'));
            }

            if($action === 'verify')
            {
                if(!$this->_isExpenseApprovalManager($actor))
                {
                    throw new Exception(__('Only a Manager can verify this expense request.'));
                }
                if($fromStatus !== 'Pending Manager')
                {
                    throw new Exception(__('Only requests pending Manager verification can be verified.'));
                }
                if((int)$request['created_by'] === $actorId)
                {
                    throw new Exception(__('The requester cannot verify their own expense request.'));
                }
                $toStatus = 'Pending CEO';
                if(!$this->Ardexpenseapprovalrequest->save(array('Ardexpenseapprovalrequest' => array(
                    'id' => $requestId,
                    'status' => $toStatus,
                    'manager_verified_by' => $actorId,
                    'manager_verified_at' => date('Y-m-d H:i:s')
                )), false))
                {
                    throw new Exception(__('Manager verification could not be saved.'));
                }
                if(!$this->_saveExpenseApprovalHistory($requestId, $projectId, 'Manager Verified', $fromStatus, $toStatus, $comment, $actorId))
                {
                    throw new Exception(__('Approval timeline could not be saved.'));
                }
                $successMessage = __('Expense request has been verified and sent to CEO.');
            }
            elseif($action === 'approve')
            {
                if(!$this->_isExpenseApprovalCeo($projectId, $actor))
                {
                    throw new Exception(__('Only the assigned CEO can give final approval.'));
                }
                if($fromStatus !== 'Pending CEO')
                {
                    throw new Exception(__('Only requests pending CEO approval can be approved.'));
                }
                if((int)$request['created_by'] === $actorId || (int)$request['manager_verified_by'] === $actorId)
                {
                    throw new Exception(__('CEO approval must be completed by a different user from the requester and Manager verifier.'));
                }
                if((int)$request['transaction_id'] > 0)
                {
                    throw new Exception(__('This expense request has already been posted.'));
                }
                $sourceLedger = $this->Ardledger->find('first', array('conditions' => array('Ardledger.id' => (int)$request['ledger_id'], 'Ardledger.project_id' => $projectId, 'Ardledger.is_trashed' => 0, 'Ardledger.type' => array('asset', 'bank')), 'recursive' => -1));
                $expenseLedger = $this->Ardledger->find('first', array('conditions' => array('Ardledger.id' => (int)$request['expense_ledger_id'], 'Ardledger.project_id' => $projectId, 'Ardledger.is_trashed' => 0, 'Ardledger.type' => 'expense'), 'recursive' => -1));
                if(empty($sourceLedger['Ardledger']['id']) || empty($expenseLedger['Ardledger']['id']) || (float)$request['amount'] <= 0)
                {
                    throw new Exception(__('The request contains an invalid source account, expense account, or amount.'));
                }
                $txPayload = array(
                    'project_id' => $projectId,
                    'ledger_id' => (int)$request['ledger_id'],
                    'expense_ledger_id' => (int)$request['expense_ledger_id'],
                    'income_ledger_id' => 0,
                    'type' => 'expense',
                    'status' => 'Posted',
                    'amount' => round((float)$request['amount'], 2),
                    'description' => trim((string)$request['description']),
                    'ref_no' => trim((string)$request['ref_no']),
                    'entry_date' => trim((string)$request['entry_date']),
                    'construction_site_id' => (int)$request['construction_site_id']
                );
                $txPayload = $this->_ardDecorateTransactionPayload($txPayload, array('status' => 'Posted', 'source_type' => 'expense_approval', 'source_id' => $requestId));
                $txPayload['approved_by'] = $actorId;
                $txPayload['approved_at'] = date('Y-m-d H:i:s');
                $txPayload['posted_by'] = $actorId;
                $txPayload['posted_at'] = date('Y-m-d H:i:s');
                $this->Ardtransaction->create();
                if(!$this->Ardtransaction->save(array('Ardtransaction' => $txPayload), false))
                {
                    throw new Exception(__('Approved expense voucher could not be posted.'));
                }
                $transactionId = (int)$this->Ardtransaction->id;
                if(!$this->_syncJournalForTransaction($transactionId, 'expense_approval', $requestId))
                {
                    throw new Exception(__('Approved expense journal could not be posted.'));
                }
                $toStatus = 'Approved';
                if(!$this->Ardexpenseapprovalrequest->save(array('Ardexpenseapprovalrequest' => array(
                    'id' => $requestId,
                    'status' => $toStatus,
                    'ceo_approved_by' => $actorId,
                    'ceo_approved_at' => date('Y-m-d H:i:s'),
                    'transaction_id' => $transactionId
                )), false))
                {
                    throw new Exception(__('Final approval could not be linked to the posted voucher.'));
                }
                if(!$this->_saveExpenseApprovalHistory($requestId, $projectId, 'CEO Approved & Posted', $fromStatus, $toStatus, $comment, $actorId))
                {
                    throw new Exception(__('Approval timeline could not be saved.'));
                }
                $this->_recalculateLedgerBalance((int)$request['ledger_id']);
                $this->_recalculateLedgerBalance((int)$request['expense_ledger_id']);
                $successMessage = __('CEO approved the request and the expense voucher has been posted.');
            }
            elseif($action === 'reject')
            {
                if($fromStatus === 'Pending Manager')
                {
                    if(!$this->_isExpenseApprovalManager($actor))
                    {
                        throw new Exception(__('Only a Manager can reject at the verification step.'));
                    }
                    if((int)$request['created_by'] === $actorId)
                    {
                        throw new Exception(__('The requester cannot reject their own expense request.'));
                    }
                }
                elseif($fromStatus === 'Pending CEO')
                {
                    if(!$this->_isExpenseApprovalCeo($projectId, $actor))
                    {
                        throw new Exception(__('Only the assigned CEO can reject at the final approval step.'));
                    }
                    if((int)$request['created_by'] === $actorId || (int)$request['manager_verified_by'] === $actorId)
                    {
                        throw new Exception(__('The final decision must be made by a different user.'));
                    }
                }
                else
                {
                    throw new Exception(__('Only pending requests can be rejected.'));
                }
                $toStatus = 'Rejected';
                if(!$this->Ardexpenseapprovalrequest->save(array('Ardexpenseapprovalrequest' => array(
                    'id' => $requestId,
                    'status' => $toStatus,
                    'rejected_by' => $actorId,
                    'rejected_at' => date('Y-m-d H:i:s'),
                    'rejection_reason' => $comment
                )), false))
                {
                    throw new Exception(__('Rejection could not be saved.'));
                }
                if(!$this->_saveExpenseApprovalHistory($requestId, $projectId, 'Rejected', $fromStatus, $toStatus, $comment, $actorId))
                {
                    throw new Exception(__('Approval timeline could not be saved.'));
                }
                $successMessage = __('Expense request has been rejected.');
            }
            else
            {
                throw new Exception(__('Invalid approval action.'));
            }
            $db->commit();
            if($action === 'verify')
            {
                $this->_dispatchExpenseApprovalNotifications($requestId, 'ceo');
            }
            $this->Session->setFlash($successMessage, 'flash', array('alert' => 'success'));
        }
        catch(Exception $e)
        {
            $db->rollback();
            CakeLog::write('error', 'Expense approval transition failed: '.$e->getMessage());
            $this->Session->setFlash($e->getMessage(), 'flash', array('alert' => 'danger'));
        }
        return $this->redirect(array('action' => 'expenseapprovals', $projectId));
    }

    public function expenseapprovalvoucher($requestId = null)
    {
        $requestId = (int)$requestId;
        $row = $this->_expenseApprovalDetailRow($requestId);
        if(empty($row['Ardexpenseapprovalrequest']['id']))
        {
            throw new NotFoundException(__('Expense approval voucher was not found.'));
        }
        $projectId = (int)$row['Ardexpenseapprovalrequest']['project_id'];
        if(!$this->_isAllowedProject($projectId))
        {
            throw new ForbiddenException(__('You are not allowed to print this approval voucher.'));
        }
        $actor = $this->_expenseApprovalActor();
        if(empty($actor['is_super']) && !$this->_isExpenseApprovalAccountant($actor) && !$this->_isExpenseApprovalManager($actor) && !$this->_isExpenseApprovalCeo($projectId, $actor))
        {
            throw new ForbiddenException(__('Your role is not assigned to this approval workflow.'));
        }
        $this->layout = false;
        $this->set('voucherHtml', $this->_expenseApprovalVoucherHtml($row));
        $this->set('approvalRequest', $row);
    }

    public function transactions($id = null)
    {
        $this->loadModel('Admin.Ardtransaction');
        $this->loadModel('Admin.Ardledger');
        $this->loadModel('Admin.Ardsite');
        $this->loadModel('Admin.Agency');
        if(isset($this->request->query['project_id']))
        {
            $qProj = trim((string)$this->request->query['project_id']);
            if($qProj === 'all' || $qProj === '0' || $qProj === '')
            {
                $id = $this->_isGlobalAdmin() ? 0 : (int)$this->agencyId;
            }
            elseif((int)$qProj > 0 && $this->_isAllowedProject((int)$qProj))
            {
                $id = (int)$qProj;
            }
            else
            {
                $id = $this->_activeProjectId($id);
            }
        }
        else
        {
            $id = $this->_activeProjectId($id);
        }

        $scopeLedger = $this->_scopeCondition('Ardledger.project_id', $id > 0 ? $id : null);
        $sourceLedgerList = array();
        $approvalSourceLedgerList = array();
        $expenseLedgerList = array();
        $sourceLedgerListByProject = array();
        $approvalSourceLedgerListByProject = array();
        $expenseLedgerListByProject = array();
        if($this->userType === 'ADR')
        {
            $ledgerRows = $this->Ardledger->find('all', array(
                'joins' => array(
                    array('table' => 'projects', 'alias' => 'Agency', 'type' => 'LEFT', 'conditions' => array('Agency.id=Ardledger.project_id'))
                ),
                'fields' => array('Ardledger.id', 'Ardledger.name', 'Ardledger.project_id', 'Ardledger.type', 'Agency.name'),
                'conditions' => array($scopeLedger, 'Ardledger.is_trashed' => 0),
                'order' => array('Agency.name' => 'asc', 'Ardledger.name' => 'asc'),
                'recursive' => -1
            ));
            foreach((array)$ledgerRows as $ledgerRow)
            {
                if(empty($ledgerRow['Ardledger']['id']))
                {
                    continue;
                }
                $ledgerId = (int)$ledgerRow['Ardledger']['id'];
                $projectId = (int)$ledgerRow['Ardledger']['project_id'];
                $ledgerName = trim((string)$ledgerRow['Ardledger']['name']);
                $agencyName = trim(isset($ledgerRow['Agency']['name']) ? (string)$ledgerRow['Agency']['name'] : '');
                if($agencyName === '' && $projectId > 0)
                {
                    $agencyName = 'Agency #'.$projectId;
                }
                $typeLabel = (strtolower(trim((string)$ledgerRow['Ardledger']['type'])) === 'expense') ? 'Expense' : 'Bank/Asset';
                $label = $ledgerName;
                if($agencyName !== '')
                {
                    $label = $agencyName.' | '.$ledgerName.' ('.$typeLabel.')';
                }
                $isExpenseLedger = (strtolower(trim((string)$ledgerRow['Ardledger']['type'])) === 'expense');
                if(!isset($sourceLedgerListByProject[$projectId]))
                {
                    $sourceLedgerListByProject[$projectId] = array();
                }
                if(!isset($expenseLedgerListByProject[$projectId]))
                {
                    $expenseLedgerListByProject[$projectId] = array();
                }
                if(!isset($approvalSourceLedgerListByProject[$projectId]))
                {
                    $approvalSourceLedgerListByProject[$projectId] = array();
                }
                if($isExpenseLedger)
                {
                    $expenseLedgerList[$ledgerId] = $label;
                    $expenseLedgerListByProject[$projectId][$ledgerId] = $label;
                }
                else
                {
                    $sourceLedgerList[$ledgerId] = $label;
                    $sourceLedgerListByProject[$projectId][$ledgerId] = $label;
                    $ledgerType = strtolower(trim((string)$ledgerRow['Ardledger']['type']));
                    if(in_array($ledgerType, array('asset', 'bank'), true))
                    {
                        $approvalSourceLedgerList[$ledgerId] = $label;
                        $approvalSourceLedgerListByProject[$projectId][$ledgerId] = $label;
                    }
                }
            }
        }
        else
        {
            $ledgerRows = $this->Ardledger->find('all', array(
                'fields' => array('Ardledger.id', 'Ardledger.name', 'Ardledger.type'),
                'conditions' => array($scopeLedger, 'Ardledger.is_trashed' => 0),
                'order' => array('Ardledger.name' => 'asc'),
                'recursive' => -1
            ));
            foreach((array)$ledgerRows as $ledgerRow)
            {
                if(empty($ledgerRow['Ardledger']['id']))
                {
                    continue;
                }
                $ledgerId = (int)$ledgerRow['Ardledger']['id'];
                $label = trim((string)$ledgerRow['Ardledger']['name']);
                if($label === '')
                {
                    $label = 'Ledger #' . $ledgerId;
                }
                if(strtolower(trim((string)$ledgerRow['Ardledger']['type'])) === 'expense')
                {
                    $expenseLedgerList[$ledgerId] = $label;
                }
                else
                {
                    $sourceLedgerList[$ledgerId] = $label;
                    $ledgerType = strtolower(trim((string)$ledgerRow['Ardledger']['type']));
                    if(in_array($ledgerType, array('asset', 'bank'), true))
                    {
                        $approvalSourceLedgerList[$ledgerId] = $label;
                    }
                }
            }
            if((int)$this->agencyId > 0)
            {
                $sourceLedgerListByProject[(int)$this->agencyId] = $sourceLedgerList;
                $approvalSourceLedgerListByProject[(int)$this->agencyId] = $approvalSourceLedgerList;
                $expenseLedgerListByProject[(int)$this->agencyId] = $expenseLedgerList;
            }
        }
        $activeExpenseProjectId = (int)$id;
        if($activeExpenseProjectId <= 0 && (int)$this->agencyId > 0)
        {
            $activeExpenseProjectId = (int)$this->agencyId;
        }
        if($activeExpenseProjectId > 0 && (!isset($expenseLedgerListByProject[$activeExpenseProjectId]) || empty($expenseLedgerListByProject[$activeExpenseProjectId])))
        {
            $autoExpenseLedgerId = $this->_getOrCreateDefaultExpenseLedger($activeExpenseProjectId);
            if($autoExpenseLedgerId > 0)
            {
                $autoExpenseLedger = $this->Ardledger->find('first', array(
                    'fields' => array('Ardledger.id', 'Ardledger.name', 'Ardledger.project_id'),
                    'conditions' => array('Ardledger.id' => (int)$autoExpenseLedgerId),
                    'recursive' => -1
                ));
                if(!empty($autoExpenseLedger['Ardledger']['id']))
                {
                    $autoLabel = trim((string)$autoExpenseLedger['Ardledger']['name']);
                    if($autoLabel === '')
                    {
                        $autoLabel = 'Ledger #' . (int)$autoExpenseLedger['Ardledger']['id'];
                    }
                    if($this->userType === 'ADR')
                    {
                        $autoAgencyName = trim((string)$this->Agency->field('name', array('Agency.id' => (int)$autoExpenseLedger['Ardledger']['project_id'])));
                        if($autoAgencyName !== '')
                        {
                            $autoLabel = $autoAgencyName . ' | ' . $autoLabel . ' (Expense)';
                        }
                    }
                    $expenseLedgerList[(int)$autoExpenseLedger['Ardledger']['id']] = $autoLabel;
                    if(!isset($expenseLedgerListByProject[$activeExpenseProjectId]))
                    {
                        $expenseLedgerListByProject[$activeExpenseProjectId] = array();
                    }
                    $expenseLedgerListByProject[$activeExpenseProjectId][(int)$autoExpenseLedger['Ardledger']['id']] = $autoLabel;
                }
            }
        }
        $this->set('ledgerList', $sourceLedgerList);
        $this->set('ledgerListByProject', $sourceLedgerListByProject);
        $this->set('approvalSourceLedgerList', $approvalSourceLedgerList);
        $this->set('approvalSourceLedgerListByProject', $approvalSourceLedgerListByProject);
        $this->set('expenseLedgerList', $expenseLedgerList);
        $this->set('expenseLedgerListByProject', $expenseLedgerListByProject);
        $expenseApprovalEnabledByProject = array();
        $approvalProjectIds = array_unique(array_merge(array_keys($sourceLedgerListByProject), array_keys($expenseLedgerListByProject)));
        foreach($approvalProjectIds as $approvalProjectId)
        {
            $projectApprovalConfig = $this->_expenseApprovalConfig((int)$approvalProjectId);
            $expenseApprovalEnabledByProject[(int)$approvalProjectId] = !empty($projectApprovalConfig['enabled']) ? 1 : 0;
        }
        $this->set('expenseApprovalEnabledByProject', $expenseApprovalEnabledByProject);

        $scopeSite = $this->_scopeCondition('Ardsite.project_id', $id > 0 ? $id : null);
        $this->set('siteList', $this->Ardsite->find('list', array(
            'fields' => array('Ardsite.id', 'Ardsite.site_name'),
            'conditions' => array($scopeSite),
            'order' => array('Ardsite.site_name' => 'asc')
        )));

        $this->set('projectName', $this->_projectList());
        $this->set('agencyId', $this->agencyId);
        $this->set('currentProjectId', $id);
        $expenseApprovalConfig = $this->_expenseApprovalConfig((int)$id);
        $expenseApprovalActor = $this->_expenseApprovalActor();
        $this->set('expenseApprovalEnabled', !empty($expenseApprovalConfig['enabled']));
        $this->set('canCreateExpenseApproval', $this->_isExpenseApprovalAccountant($expenseApprovalActor));
        $this->set('date', CakeTime::format($this->dtFormat, CakeTime::convert(time(), $this->siteTimezone)));
        $constructionOptions = $this->_constructionMaterialUnitOptions((int)$id);
        $this->set('constructionMaterialOptions', $constructionOptions['materials']);
        $this->set('constructionUnitOptions', $constructionOptions['units']);
        $this->set('constructionMaterialUnitMap', isset($constructionOptions['material_units']) ? $constructionOptions['material_units'] : array());

        if($this->request->is('post'))
        {
            $row = isset($this->request->data['Ardtransaction']) ? $this->request->data['Ardtransaction'] : array();
            $existingForFallback = array();
            if(isset($row['id']) && (int)$row['id'] > 0)
            {
                $existingForFallback = $this->Ardtransaction->findById((int)$row['id']);
            }
            $row['project_id'] = $this->_resolveProjectId(isset($row['project_id']) ? $row['project_id'] : null);
            if(!$this->_isAllowedProject($row['project_id']))
            {
                $this->Session->setFlash(__('Please select valid agency/project.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            if(!isset($row['type']) || trim((string)$row['type']) === '')
            {
                if(!empty($existingForFallback['Ardtransaction']['type']))
                {
                    $row['type'] = strtolower(trim((string)$existingForFallback['Ardtransaction']['type']));
                }
            }
            $row['type'] = (isset($row['type']) && strtolower(trim((string)$row['type'])) === 'income') ? 'income' : 'expense';
            if($row['type'] === 'expense' && !empty($row['ledger_id']))
            {
                $chkLedgerType = strtolower(trim((string)$this->Ardledger->field('type', array('Ardledger.id' => (int)$row['ledger_id']))));
                if($chkLedgerType === 'income')
                {
                    $row['type'] = 'income';
                }
            }
            $earlyApprovalConfig = $this->_expenseApprovalConfig((int)$row['project_id']);
            $isNewExpense = (empty($row['id']) || (int)$row['id'] <= 0) && $row['type'] === 'expense';
            if($isNewExpense && !empty($earlyApprovalConfig['enabled']) && !$this->_isExpenseApprovalAccountant())
            {
                $this->Session->setFlash(__('Only an Accountant can create an expense payment request while approval workflow is enabled.'), 'flash', array('alert' => 'danger'));
                return $this->redirect(array('action' => 'expenseapprovals', (int)$row['project_id']));
            }
            $row['amount'] = round((float)(isset($row['amount']) ? $row['amount'] : 0), 2);
            $postedEntryDate = isset($row['entry_date']) ? trim((string)$row['entry_date']) : '';
            if(
                $postedEntryDate === '' &&
                !empty($existingForFallback['Ardtransaction']['entry_date']) &&
                (string)$existingForFallback['Ardtransaction']['entry_date'] !== '0000-00-00'
            )
            {
                // On edit, keep existing voucher date when browser posts empty date.
                $normalizedEntryDate = trim((string)$existingForFallback['Ardtransaction']['entry_date']);
            }
            else
            {
                $normalizedEntryDate = $this->_reportNormalizeDate($postedEntryDate, false);
                if($normalizedEntryDate === '')
                {
                    $normalizedEntryDate = date('Y-m-d');
                }
            }
            $row['entry_date'] = $normalizedEntryDate;
            $row['construction_site_id'] = (int)(isset($row['construction_site_id']) ? $row['construction_site_id'] : 0);
            $row['ledger_id'] = (int)(isset($row['ledger_id']) ? $row['ledger_id'] : 0);
            $row['expense_ledger_id'] = (int)(isset($row['expense_ledger_id']) ? $row['expense_ledger_id'] : 0);
            $row['income_ledger_id'] = (int)(isset($row['income_ledger_id']) ? $row['income_ledger_id'] : 0);
            $row['status'] = $this->_ardNormalizeVoucherStatus(isset($row['status']) ? $row['status'] : 'Posted', 'Posted');
            if($isNewExpense && !empty($earlyApprovalConfig['enabled']))
            {
                $row['type'] = 'expense';
                $row['income_ledger_id'] = 0;
                $row['status'] = 'Draft';
            }
            $legacyExpenseSourceAdjusted = false;
            if($row['ledger_id'] <= 0 && !empty($existingForFallback['Ardtransaction']['ledger_id']))
            {
                // On edit, keep already linked source ledger if browser posts empty by mistake.
                $row['ledger_id'] = (int)$existingForFallback['Ardtransaction']['ledger_id'];
            }
            if($row['amount']<=0)
            {
                $this->Session->setFlash(__('Please enter valid source ledger and amount.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            if($row['type'] === 'income')
            {
                $row['expense_ledger_id'] = 0;
                if($row['income_ledger_id'] <= 0 && !empty($existingForFallback['Ardtransaction']['income_ledger_id']))
                {
                    $row['income_ledger_id'] = (int)$existingForFallback['Ardtransaction']['income_ledger_id'];
                }
                if($row['income_ledger_id'] <= 0)
                {
                    $row['income_ledger_id'] = $this->_ardDefaultLedgerId((int)$row['project_id'], 'installment_income_ledger_id', 'General Income', 'income');
                }
            }
            elseif($row['expense_ledger_id'] <= 0 && !empty($existingForFallback['Ardtransaction']['expense_ledger_id']))
            {
                // Keep already linked expense ledger on edit if browser posts empty by mistake.
                $row['expense_ledger_id'] = (int)$existingForFallback['Ardtransaction']['expense_ledger_id'];
            }
            if($row['type'] === 'expense' && !empty($existingForFallback['Ardtransaction']['id']))
            {
                $existingSourceLedgerId = (int)(isset($existingForFallback['Ardtransaction']['ledger_id']) ? $existingForFallback['Ardtransaction']['ledger_id'] : 0);
                if($existingSourceLedgerId > 0)
                {
                    $existingSourceType = strtolower(trim((string)$this->Ardledger->field('type', array('Ardledger.id' => $existingSourceLedgerId))));
                    // Legacy compatibility: old rows may have expense account saved in source ledger field.
                    if($existingSourceType === 'expense' && ($row['ledger_id'] <= 0 || (int)$row['ledger_id'] === $existingSourceLedgerId))
                    {
                        $replacementSourceLedgerId = $this->_getDefaultExpenseSourceLedger((int)$row['project_id'], $existingSourceLedgerId);
                        if($replacementSourceLedgerId > 0)
                        {
                            $row['ledger_id'] = (int)$replacementSourceLedgerId;
                            $legacyExpenseSourceAdjusted = true;
                        }
                    }
                }
            }
            if($row['ledger_id'] <= 0)
            {
                $this->Session->setFlash(__('Please enter valid source ledger and amount.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            $sourceLedger = $this->Ardledger->findById($row['ledger_id']);
            if(empty($sourceLedger) || !$this->_isAllowedProject((int)$sourceLedger['Ardledger']['project_id']))
            {
                $this->Session->setFlash(__('Invalid source ledger selected.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            if((int)$sourceLedger['Ardledger']['project_id'] !== (int)$row['project_id'])
            {
                $this->Session->setFlash(__('Source ledger must belong to selected agency/project.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            if($isNewExpense && !empty($earlyApprovalConfig['enabled']) && !in_array(strtolower(trim((string)$sourceLedger['Ardledger']['type'])), array('asset', 'bank'), true))
            {
                $this->Session->setFlash(__('Approval expense source must be an Asset or Bank account.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            if($row['type'] === 'expense')
            {
                if(strtolower(trim((string)$sourceLedger['Ardledger']['type'])) === 'expense')
                {
                    // Legacy fallback for old records that were posted with expense source ledger.
                    if(!empty($existingForFallback['Ardtransaction']['id']))
                    {
                        $replacementSourceLedgerId = $this->_getDefaultExpenseSourceLedger((int)$row['project_id'], (int)$sourceLedger['Ardledger']['id']);
                        if($replacementSourceLedgerId > 0)
                        {
                            $replacementSourceLedger = $this->Ardledger->findById((int)$replacementSourceLedgerId);
                            if(!empty($replacementSourceLedger) && strtolower(trim((string)$replacementSourceLedger['Ardledger']['type'])) !== 'expense')
                            {
                                $row['ledger_id'] = (int)$replacementSourceLedgerId;
                                $sourceLedger = $replacementSourceLedger;
                                $legacyExpenseSourceAdjusted = true;
                            }
                        }
                    }
                }
                if(strtolower(trim((string)$sourceLedger['Ardledger']['type'])) === 'expense')
                {
                    $this->Session->setFlash(__('For Expense voucher, source ledger must be Bank/Asset.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect($this->referer());
                }
                if($row['expense_ledger_id'] <= 0)
                {
                    $autoExpenseLedgerId = $this->_getOrCreateDefaultExpenseLedger((int)$row['project_id']);
                    if($autoExpenseLedgerId > 0)
                    {
                        $row['expense_ledger_id'] = (int)$autoExpenseLedgerId;
                    }
                    else
                    {
                        $this->Session->setFlash(__('Please select Expense Account for Expense voucher.'), 'flash', array('alert' => 'danger'));
                        return $this->redirect($this->referer());
                    }
                }
                $expenseLedger = $this->Ardledger->findById($row['expense_ledger_id']);
                if(empty($expenseLedger) || !$this->_isAllowedProject((int)$expenseLedger['Ardledger']['project_id']))
                {
                    $this->Session->setFlash(__('Invalid expense account selected.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect($this->referer());
                }
                if((int)$expenseLedger['Ardledger']['project_id'] !== (int)$row['project_id'])
                {
                    $autoExpenseLedgerId = $this->_getOrCreateDefaultExpenseLedger((int)$row['project_id']);
                    if($autoExpenseLedgerId > 0)
                    {
                        $row['expense_ledger_id'] = (int)$autoExpenseLedgerId;
                        $expenseLedger = $this->Ardledger->findById($row['expense_ledger_id']);
                    }
                    if(empty($expenseLedger) || (int)$expenseLedger['Ardledger']['project_id'] !== (int)$row['project_id'])
                    {
                        $this->Session->setFlash(__('Expense account must belong to selected agency/project.'), 'flash', array('alert' => 'danger'));
                        return $this->redirect($this->referer());
                    }
                }
                if(strtolower(trim((string)$expenseLedger['Ardledger']['type'])) !== 'expense')
                {
                    $this->Session->setFlash(__('Selected expense account must be of type Expense.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect($this->referer());
                }
                if((int)$row['ledger_id'] === (int)$row['expense_ledger_id'])
                {
                    $this->Session->setFlash(__('Source account and Expense account cannot be the same.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect($this->referer());
                }
            }
            else
            {
                $row['expense_ledger_id'] = 0;
            }
            if($row['type'] === 'income')
            {
                $incomeLedger = $this->Ardledger->findById($row['income_ledger_id']);
                if(empty($incomeLedger) || !$this->_isAllowedProject((int)$incomeLedger['Ardledger']['project_id']))
                {
                    $this->Session->setFlash(__('Invalid income account selected.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect($this->referer());
                }
                if((int)$incomeLedger['Ardledger']['project_id'] !== (int)$row['project_id'])
                {
                    $this->Session->setFlash(__('Income account must belong to selected agency/project.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect($this->referer());
                }
                if(strtolower(trim((string)$incomeLedger['Ardledger']['type'])) === 'expense')
                {
                    $this->Session->setFlash(__('Selected income account cannot be an Expense account.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect($this->referer());
                }
                if((int)$row['ledger_id'] === (int)$row['income_ledger_id'])
                {
                    $this->Session->setFlash(__('Receipt account and Income account cannot be the same.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect($this->referer());
                }
            }

            $oldLedgerId = 0;
            $oldExpenseLedgerId = 0;
            $oldIncomeLedgerId = 0;
            $expenseLedgerChangedOnEdit = false;
            $oldExpenseLedgerName = '';
            $newExpenseLedgerName = '';
            $existing = array();
            if(isset($row['id']) && (int)$row['id']>0)
            {
                $existing = $this->Ardtransaction->findById((int)$row['id']);
                if(empty($existing) || !$this->_isAllowedProject((int)$existing['Ardtransaction']['project_id']))
                {
                    $this->Session->setFlash(__('Invalid transaction.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect($this->referer());
                }
                $lockMessage = $this->_ardTransactionLockedMessage($existing['Ardtransaction'], (int)$existing['Ardtransaction']['project_id']);
                if($lockMessage !== '')
                {
                    $this->Session->setFlash($lockMessage, 'flash', array('alert' => 'danger'));
                    return $this->redirect(array('action' => 'transactions', $id));
                }
                $oldLedgerId = (int)$existing['Ardtransaction']['ledger_id'];
                $oldExpenseLedgerId = (int)(isset($existing['Ardtransaction']['expense_ledger_id']) ? $existing['Ardtransaction']['expense_ledger_id'] : 0);
                $oldIncomeLedgerId = (int)(isset($existing['Ardtransaction']['income_ledger_id']) ? $existing['Ardtransaction']['income_ledger_id'] : 0);
                if($oldExpenseLedgerId <= 0 && strtolower(trim((string)$existing['Ardtransaction']['type'])) === 'expense')
                {
                    $oldLedgerType = strtolower(trim((string)$this->Ardledger->field('type', array('Ardledger.id' => $oldLedgerId))));
                    if($oldLedgerType === 'expense')
                    {
                        // Legacy rows stored expense side in source ledger column.
                        $oldExpenseLedgerId = $oldLedgerId;
                    }
                }
                $newExpenseLedgerIdForEdit = ($row['type'] === 'expense') ? (int)$row['expense_ledger_id'] : 0;
                if($newExpenseLedgerIdForEdit > 0 && $oldExpenseLedgerId > 0 && $oldExpenseLedgerId !== $newExpenseLedgerIdForEdit)
                {
                    $expenseLedgerChangedOnEdit = true;
                    $oldExpenseLedgerName = trim((string)$this->Ardledger->field('name', array('Ardledger.id' => $oldExpenseLedgerId)));
                    $newExpenseLedgerName = trim((string)$this->Ardledger->field('name', array('Ardledger.id' => $newExpenseLedgerIdForEdit)));
                }
            }

            $row['ref_no'] = trim((string)(isset($row['ref_no']) ? $row['ref_no'] : ''));
            if($row['ref_no'] === '')
            {
                if(!empty($existing['Ardtransaction']['ref_no']))
                {
                    $row['ref_no'] = trim((string)$existing['Ardtransaction']['ref_no']);
                }
                if($row['ref_no'] === '')
                {
                    $row['ref_no'] = $this->_nextVoucherReferenceNo($row['project_id'], $row['type']);
                }
            }

            $isUpdate = !empty($existing['Ardtransaction']['id']);
            $postedApprovalConfig = $this->_expenseApprovalConfig((int)$row['project_id']);
            if(!$isUpdate && $row['type'] === 'expense' && !empty($postedApprovalConfig['enabled']))
            {
                $requestResult = $this->_createExpenseApprovalRequest($row);
                if(!empty($requestResult['success']))
                {
                    $this->Session->setFlash(__('Expense payment request has been submitted to the Manager. No account balance was changed.'), 'flash', array('alert' => 'success'));
                    return $this->redirect(array('action' => 'expenseapprovals', (int)$row['project_id']));
                }
                $message = !empty($requestResult['message']) ? $requestResult['message'] : __('Expense payment request could not be submitted.');
                $this->Session->setFlash($message, 'flash', array('alert' => 'danger'));
                return $this->redirect(array('action' => 'transactions', (int)$row['project_id'], '?' => array('kind' => 'expense')));
            }

            if($isUpdate)
            {
                $row['id'] = (int)$existing['Ardtransaction']['id'];
                $this->Ardtransaction->id = (int)$row['id'];
            }
            else
            {
                if(isset($row['id']))
                {
                    unset($row['id']);
                }
                $this->Ardtransaction->create();
            }
            $row = $this->_ardDecorateTransactionPayload($row, array('status' => $row['status'], 'source_type' => 'voucher', 'source_id' => !empty($row['id']) ? (int)$row['id'] : 0));

            $saveSucceeded = false;
            $savedTransactionId = 0;
            if($this->Ardtransaction->save(array('Ardtransaction' => $row), false))
            {
                $saveSucceeded = true;
                $savedTransactionId = (int)$this->Ardtransaction->id;
            }
            elseif($isUpdate && !empty($row['id']))
            {
                // Fallback update path: keep edit working even when model save() returns false on legacy rows.
                $ds = $this->Ardtransaction->getDataSource();
                $updateData = array(
                    'Ardtransaction.project_id' => (int)$row['project_id'],
                    'Ardtransaction.ledger_id' => (int)$row['ledger_id'],
                    'Ardtransaction.expense_ledger_id' => (int)$row['expense_ledger_id'],
                    'Ardtransaction.income_ledger_id' => (int)$row['income_ledger_id'],
                    'Ardtransaction.type' => $ds->value((string)$row['type']),
                    'Ardtransaction.status' => $ds->value((string)$row['status']),
                    'Ardtransaction.amount' => round((float)$row['amount'], 2),
                    'Ardtransaction.description' => $ds->value((string)(isset($row['description']) ? $row['description'] : '')),
                    'Ardtransaction.ref_no' => $ds->value((string)$row['ref_no']),
                    'Ardtransaction.entry_date' => $ds->value((string)$row['entry_date']),
                    'Ardtransaction.construction_site_id' => (int)$row['construction_site_id'],
                    'Ardtransaction.modified_by' => (int)(isset($row['modified_by']) ? $row['modified_by'] : 0),
                    'Ardtransaction.modified' => $ds->value(date('Y-m-d H:i:s'))
                );
                if($this->Ardtransaction->updateAll($updateData, array('Ardtransaction.id' => (int)$row['id'])))
                {
                    $saveSucceeded = true;
                    $savedTransactionId = (int)$row['id'];
                    $this->Ardtransaction->id = $savedTransactionId;
                }
            }
            if($saveSucceeded)
            {
                if($savedTransactionId > 0 && $row['type'] === 'expense' && (int)$row['expense_ledger_id'] > 0)
                {
                    // Enforce selected expense ledger persistence for expense vouchers.
                    $this->Ardtransaction->query(
                        "UPDATE `ardaccounts_transactions` SET `expense_ledger_id`=".(int)$row['expense_ledger_id']." WHERE `id`=".(int)$savedTransactionId
                    );
                }
                $this->_recalculateLedgerBalance($row['ledger_id']);
                if($oldLedgerId>0 && $oldLedgerId!==$row['ledger_id'])
                {
                    $this->_recalculateLedgerBalance($oldLedgerId);
                }
                $newExpenseLedgerId = ($row['type'] === 'expense') ? (int)$row['expense_ledger_id'] : 0;
                $newIncomeLedgerId = ($row['type'] === 'income') ? (int)$row['income_ledger_id'] : 0;
                if($newExpenseLedgerId > 0)
                {
                    $this->_recalculateLedgerBalance($newExpenseLedgerId);
                }
                if($oldExpenseLedgerId > 0 && $oldExpenseLedgerId !== $newExpenseLedgerId)
                {
                    $this->_recalculateLedgerBalance($oldExpenseLedgerId);
                }
                if($newIncomeLedgerId > 0)
                {
                    $this->_recalculateLedgerBalance($newIncomeLedgerId);
                }
                if($oldIncomeLedgerId > 0 && $oldIncomeLedgerId !== $newIncomeLedgerId)
                {
                    $this->_recalculateLedgerBalance($oldIncomeLedgerId);
                }
                if($savedTransactionId > 0)
                {
                    try
                    {
                        $this->_syncJournalForTransaction($savedTransactionId, 'voucher', $savedTransactionId);
                    }
                    catch(Exception $e)
                    {
                        CakeLog::write('error', 'Voucher journal sync failed for transaction '.$savedTransactionId.': '.$e->getMessage());
                    }
                    try
                    {
                        $this->_syncDealRefundScheduleForVoucherEdit($savedTransactionId);
                    }
                    catch(Exception $e)
                    {
                        CakeLog::write('error', 'Refund schedule voucher sync failed for transaction '.$savedTransactionId.': '.$e->getMessage());
                    }
                }
                if($expenseLedgerChangedOnEdit)
                {
                    if($oldExpenseLedgerName === '')
                    {
                        $oldExpenseLedgerName = 'Previous Expense Ledger';
                    }
                    if($newExpenseLedgerName === '')
                    {
                        $newExpenseLedgerName = 'New Expense Ledger';
                    }
                    $this->Session->setFlash(sprintf(__('Expense voucher updated and moved from %s to %s.'), $oldExpenseLedgerName, $newExpenseLedgerName), 'flash', array('alert' => 'success'));
                }
                elseif($legacyExpenseSourceAdjusted && $row['type'] === 'expense')
                {
                    $this->Session->setFlash(__('Expense voucher updated and source account corrected successfully.'), 'flash', array('alert' => 'success'));
                }
                else
                {
                    $this->Session->setFlash($isUpdate ? __('Voucher updated successfully.') : __('Voucher saved successfully.'), 'flash', array('alert' => 'success'));
                }
            }
            else
            {
                $this->Session->setFlash(__('Unable to save voucher. Please try again.'), 'flash', array('alert' => 'danger'));
            }
            if(strtolower($this->action) === 'expensetransactions')
            {
                $redirectAction = 'expensetransactions';
            }
            elseif(strtolower($this->action) === 'incometransactions')
            {
                $redirectAction = 'incometransactions';
            }
            else
            {
                $redirectAction = 'transactions';
            }
            return $this->redirect(array('action' => $redirectAction, $id));
        }

        $scope = $this->_scopeCondition('Ardtransaction.project_id', $id > 0 ? $id : null);
        $conditions = array();
        if(!empty($scope))
        {
            $conditions[] = $scope;
        }
        $isExpenseAction = (strtolower((string)$this->action) === 'expensetransactions' || !empty($this->viewVars['isExpenseMode']));
        $isIncomeAction = (strtolower((string)$this->action) === 'incometransactions' || !empty($this->viewVars['isIncomeMode']));

        if($isExpenseAction)
        {
            $typeFilter = 'expense';
            $this->request->query['type'] = 'expense';
            $this->set('isExpenseMode', true);
        }
        elseif($isIncomeAction)
        {
            $typeFilter = 'income';
            $this->request->query['type'] = 'income';
            $this->set('isIncomeMode', true);
        }
        else
        {
            $typeFilter = isset($this->request->query['type']) ? strtolower(trim((string)$this->request->query['type'])) : '';
            if($typeFilter === '' && isset($this->request->params['named']['type']))
            {
                $typeFilter = strtolower(trim((string)$this->request->params['named']['type']));
            }
        }

        if($typeFilter === 'expense')
        {
            $conditions['Ardtransaction.type'] = 'expense';
            // Strictly exclude income ledgers and deal receipts from expense transactions
            $conditions['AND'][] = array(
                'OR' => array(
                    'Ardledger.type !=' => 'income',
                    'Ardledger.type' => null
                )
            );
            $conditions['AND'][] = array(
                'OR' => array(
                    'Ardledger.account_type !=' => 'income',
                    'Ardledger.account_type' => null
                )
            );
            $conditions['AND'][] = array(
                'OR' => array(
                    'Ardtransaction.source_type !=' => 'deal_receipt',
                    'Ardtransaction.source_type' => null
                )
            );
        }
        elseif($typeFilter === 'income')
        {
            $conditions['Ardtransaction.type'] = 'income';
            // Strictly exclude expense ledgers from income transactions
            $conditions['AND'][] = array(
                'OR' => array(
                    'Ardledger.type !=' => 'expense',
                    'Ardledger.type' => null
                )
            );
            $conditions['AND'][] = array(
                'OR' => array(
                    'Ardledger.account_type !=' => 'expense',
                    'Ardledger.account_type' => null
                )
            );
        }

        // Date filter: Today, Week, Month, Year, Custom
        $datePreset = isset($this->request->query['date_preset']) ? strtolower(trim((string)$this->request->query['date_preset'])) : '';
        $startRaw = isset($this->request->query['start_date']) ? trim((string)$this->request->query['start_date']) : '';
        $endRaw = isset($this->request->query['end_date']) ? trim((string)$this->request->query['end_date']) : '';
        $filterStartDate = '';
        $filterEndDate = '';

        if($datePreset === 'today')
        {
            $filterStartDate = date('Y-m-d');
            $filterEndDate = date('Y-m-d');
        }
        elseif($datePreset === 'week')
        {
            $dayOfWeek = (int)date('N');
            $filterStartDate = date('Y-m-d', strtotime('-' . ($dayOfWeek - 1) . ' days'));
            $filterEndDate = date('Y-m-d', strtotime($filterStartDate . ' +6 days'));
        }
        elseif($datePreset === 'month')
        {
            $filterStartDate = date('Y-m-01');
            $filterEndDate = date('Y-m-t');
        }
        elseif($datePreset === 'year')
        {
            $filterStartDate = date('Y-01-01');
            $filterEndDate = date('Y-12-31');
        }
        elseif($datePreset === 'all' || $datePreset === 'lifetime')
        {
            $filterStartDate = '';
            $filterEndDate = '';
        }
        else
        {
            $filterStartDate = $this->_reportNormalizeDate($startRaw, false);
            $filterEndDate = $this->_reportNormalizeDate($endRaw, false);
            if($filterStartDate !== '' || $filterEndDate !== '')
            {
                $datePreset = 'custom';
            }
        }

        if($filterStartDate !== '' && $filterEndDate !== '' && $filterStartDate > $filterEndDate)
        {
            $tmp = $filterStartDate;
            $filterStartDate = $filterEndDate;
            $filterEndDate = $tmp;
        }

        if($filterStartDate !== '')
        {
            $conditions['Ardtransaction.entry_date >='] = $filterStartDate;
        }
        if($filterEndDate !== '')
        {
            $conditions['Ardtransaction.entry_date <='] = $filterEndDate;
        }

        // Sorting according to applied filter
        $sortFilter = isset($this->request->query['sort']) ? trim((string)$this->request->query['sort']) : 'date_desc';
        switch($sortFilter)
        {
            case 'date_asc':
                $order = array('Ardtransaction.entry_date' => 'asc', 'Ardtransaction.id' => 'asc');
                break;
            case 'amount_desc':
                $order = array('Ardtransaction.amount' => 'desc', 'Ardtransaction.entry_date' => 'desc', 'Ardtransaction.id' => 'desc');
                break;
            case 'amount_asc':
                $order = array('Ardtransaction.amount' => 'asc', 'Ardtransaction.entry_date' => 'asc', 'Ardtransaction.id' => 'asc');
                break;
            case 'id_desc':
                $order = array('Ardtransaction.id' => 'desc');
                break;
            case 'id_asc':
                $order = array('Ardtransaction.id' => 'asc');
                break;
            case 'date_desc':
            default:
                $order = array('Ardtransaction.entry_date' => 'desc', 'Ardtransaction.id' => 'desc');
                $sortFilter = 'date_desc';
                break;
        }

        $this->Paginator->settings = array(
            'page' => 1,
            'order' => $order,
            'limit' => $this->pageLimit,
            'maxLimit' => $this->maxLimit,
            'joins' => array(
                array('table' => 'ardaccounts_ledgers', 'alias' => 'Ardledger', 'type' => 'LEFT', 'conditions' => array('Ardledger.id=Ardtransaction.ledger_id')),
                array('table' => 'ardaccounts_ledgers', 'alias' => 'ExpenseLedger', 'type' => 'LEFT', 'conditions' => array('ExpenseLedger.id=Ardtransaction.expense_ledger_id')),
                array('table' => 'ardaccounts_ledgers', 'alias' => 'IncomeLedger', 'type' => 'LEFT', 'conditions' => array('IncomeLedger.id=Ardtransaction.income_ledger_id')),
                array('table' => 'ardaccounts_construction_sites', 'alias' => 'Ardsite', 'type' => 'LEFT', 'conditions' => array('Ardsite.id=Ardtransaction.construction_site_id')),
                array('table' => 'projects', 'alias' => 'Agency', 'type' => 'LEFT', 'conditions' => array('Agency.id=Ardtransaction.project_id'))
            ),
            'fields' => array('Ardtransaction.*', 'Ardledger.name', 'ExpenseLedger.name', 'IncomeLedger.name', 'Ardsite.site_name', 'Agency.name'),
            'conditions' => $conditions
        );
        $this->set('rows', $this->Paginator->paginate('Ardtransaction'));
        $this->set('typeFilter', $typeFilter);
        $this->set('filterProjectId', ($id > 0 ? (int)$id : 'all'));
        $this->set('filterDatePreset', $datePreset);
        $this->set('filterStartDate', $filterStartDate);
        $this->set('filterEndDate', $filterEndDate);
        $this->set('filterSort', $sortFilter);

        $editId = isset($this->request->params['named']['edit']) ? (int)$this->request->params['named']['edit'] : 0;
        if($editId > 0)
        {
            $editRow = $this->Ardtransaction->findById($editId);
            if(!empty($editRow) && $this->_isAllowedProject((int)$editRow['Ardtransaction']['project_id']))
            {
                $this->request->data = $editRow;
            }
        }
        elseif(!$this->request->is('post'))
        {
            $kind = isset($this->request->query['kind']) ? strtolower(trim((string)$this->request->query['kind'])) : '';
            if($kind === '' && !empty($typeFilter))
            {
                $kind = $typeFilter;
            }
            if($kind === 'income' || $kind === 'expense')
            {
                $this->request->data['Ardtransaction']['type'] = $kind;
            }
        }
    }

    public function expensetransactions($id = null)
    {
        $this->request->query['type'] = 'expense';
        $this->set('isExpenseMode', true);
        $this->set('typeFilter', 'expense');
        $this->set('pageTitleCustom', __('Expense Transactions'));
        $this->transactions($id);
        if($this->autoRender !== false)
        {
            $this->render('transactions');
        }
    }

    public function incometransactions($id = null)
    {
        $this->request->query['type'] = 'income';
        $this->set('isIncomeMode', true);
        $this->set('typeFilter', 'income');
        $this->set('pageTitleCustom', __('Income Transactions'));
        $this->transactions($id);
        if($this->autoRender !== false)
        {
            $this->render('transactions');
        }
    }

    public function bulkvouchers($id = null)
    {
        $this->loadModel('Admin.Ardtransaction');
        $this->loadModel('Admin.Ardledger');
        $this->loadModel('Admin.Ardsite');
        $this->loadModel('Admin.Ardsetting');
        $this->loadModel('Admin.Agency');

        // Resolve Project ID with multi-tenancy & access control
        $id = $this->_activeProjectId($id);
        if(!$this->_isGlobalAdmin())
        {
            $id = (int)$this->agencyId;
        }

        $projectList = $this->_activeAgencyProjectList();
        $this->set('projectName', $projectList);
        $this->set('agencyId', $this->agencyId);
        $this->set('currentProjectId', $id);
        $this->set('isGlobalAdmin', $this->_isGlobalAdmin());

        $defaults = $this->_defaultSettings();
        $settingsRow = ((int)$id > 0) ? $this->_fetchArdSettingsRowRaw((int)$id) : array();
        $settings = !empty($settingsRow) ? $this->_normalizeArdSettingsWithDefaults($settingsRow, $defaults) : $defaults;

        $allowCustomDate = !empty($settings['bulk_voucher_custom_date_enabled']);
        $defaultSourceLedgerId = !empty($settings['bulk_default_source_ledger_id']) ? (int)$settings['bulk_default_source_ledger_id'] : 0;
        $configuredBulkExpenseIds = array_filter(array_map('intval', explode(',', (string)$settings['bulk_expense_ledger_ids'])));
        $configuredBulkIncomeIds = array_filter(array_map('intval', explode(',', (string)$settings['bulk_income_ledger_ids'])));

        // Handle POST submission
        if($this->request->is(array('post', 'put')))
        {
            $posted = isset($this->request->data['BulkVoucher']) ? (array)$this->request->data['BulkVoucher'] : array();
            $targetProjectId = isset($posted['project_id']) ? (int)$posted['project_id'] : (int)$id;
            if(!$this->_isGlobalAdmin())
            {
                $targetProjectId = (int)$this->agencyId;
            }

            if(!$this->_isAllowedProject($targetProjectId))
            {
                $this->Session->setFlash(__('Please select valid agency/project.'), 'flash', array('alert' => 'danger'));
                return $this->redirect(array('action' => 'bulkvouchers', $id));
            }

            $voucherType = (isset($posted['type']) && strtolower(trim((string)$posted['type'])) === 'income') ? 'income' : 'expense';

            // Resolve Voucher Date
            $rawDate = isset($posted['entry_date']) ? trim((string)$posted['entry_date']) : '';
            if($allowCustomDate && $rawDate !== '')
            {
                $entryDate = $this->_reportNormalizeDate($rawDate, false);
                if($entryDate === '')
                {
                    $entryDate = date('Y-m-d');
                }
            }
            else
            {
                $entryDate = date('Y-m-d');
            }

            // Check Fiscal Lock Date
            $fiscalLockDate = trim((string)(isset($settings['fiscal_lock_date']) ? $settings['fiscal_lock_date'] : ''));
            if($fiscalLockDate !== '' && $fiscalLockDate !== '0000-00-00')
            {
                if(strtotime($entryDate) <= strtotime($fiscalLockDate))
                {
                    $this->Session->setFlash(sprintf(__('The fiscal books are locked up to %s. Transactions cannot be posted on or before this date.'), $fiscalLockDate), 'flash', array('alert' => 'danger'));
                    return $this->redirect(array('action' => 'bulkvouchers', $targetProjectId));
                }
            }

            // Source Ledger (Cash / Bank)
            $sourceLedgerId = isset($posted['source_ledger_id']) ? (int)$posted['source_ledger_id'] : 0;
            if($sourceLedgerId <= 0)
            {
                $this->Session->setFlash(__('Please select a valid Cash or Bank Account as Payment/Receipt source.'), 'flash', array('alert' => 'danger'));
                return $this->redirect(array('action' => 'bulkvouchers', $targetProjectId));
            }

            $sourceLedger = $this->Ardledger->find('first', array(
                'conditions' => array(
                    'Ardledger.id' => $sourceLedgerId,
                    'Ardledger.project_id' => $targetProjectId,
                    'Ardledger.is_trashed' => 0
                ),
                'recursive' => -1
            ));
            if(empty($sourceLedger['Ardledger']['id']))
            {
                $this->Session->setFlash(__('Selected Source Account does not belong to this agency.'), 'flash', array('alert' => 'danger'));
                return $this->redirect(array('action' => 'bulkvouchers', $targetProjectId));
            }
            $sourceType = strtolower(trim((string)$sourceLedger['Ardledger']['type']));
            if($sourceType === 'expense')
            {
                $this->Session->setFlash(__('Source Account cannot be an Expense account. Please select a Cash or Bank account.'), 'flash', array('alert' => 'danger'));
                return $this->redirect(array('action' => 'bulkvouchers', $targetProjectId));
            }

            // Process Rows: STRICT SAFEGUARD - Filter out amount <= 0 or empty rows
            $rawRows = isset($posted['rows']) && is_array($posted['rows']) ? $posted['rows'] : array();
            $validRows = array();
            $skippedZeroCount = 0;
            $grandTotal = 0.0;

            foreach($rawRows as $r)
            {
                $r = is_array($r) ? $r : array();
                $destLedgerId = isset($r['ledger_id']) ? (int)$r['ledger_id'] : 0;
                $amount = round((float)(isset($r['amount']) ? $r['amount'] : 0), 2);
                $description = isset($r['description']) ? trim((string)$r['description']) : '';
                $refNo = isset($r['ref_no']) ? trim((string)$r['ref_no']) : '';
                $siteId = isset($r['construction_site_id']) ? (int)$r['construction_site_id'] : 0;

                // SAFEGUARD: If no amount, zero amount, negative amount, or no ledger, safely ignore!
                if($amount <= 0 || $destLedgerId <= 0)
                {
                    $skippedZeroCount++;
                    continue;
                }

                // Verify destination ledger belongs to this project
                $destLedger = $this->Ardledger->find('first', array(
                    'fields' => array('Ardledger.id', 'Ardledger.name', 'Ardledger.type'),
                    'conditions' => array(
                        'Ardledger.id' => $destLedgerId,
                        'Ardledger.project_id' => $targetProjectId,
                        'Ardledger.is_trashed' => 0
                    ),
                    'recursive' => -1
                ));
                if(empty($destLedger['Ardledger']['id']))
                {
                    $skippedZeroCount++;
                    continue;
                }

                // Prevent source and destination being the same account
                if($destLedgerId === $sourceLedgerId)
                {
                    $skippedZeroCount++;
                    continue;
                }

                $grandTotal += $amount;
                $validRows[] = array(
                    'ledger_id' => $destLedgerId,
                    'ledger_name' => trim((string)$destLedger['Ardledger']['name']),
                    'amount' => $amount,
                    'description' => $description,
                    'ref_no' => $refNo,
                    'construction_site_id' => $siteId
                );
            }

            if(empty($validRows))
            {
                $this->Session->setFlash(__('No vouchers were posted. All rows had 0.00 or empty amounts. No ledger entries were created.'), 'flash', array('alert' => 'warning'));
                return $this->redirect(array('action' => 'bulkvouchers', $targetProjectId));
            }

            // Post all valid vouchers in database transaction
            $ds = $this->Ardtransaction->getDataSource();
            $ds->begin();
            try
            {
                $postedCount = 0;
                $affectedLedgerIds = array($sourceLedgerId);

                foreach($validRows as $item)
                {
                    $itemRefNo = $item['ref_no'];
                    if($itemRefNo === '')
                    {
                        $itemRefNo = $this->_nextVoucherReferenceNo($targetProjectId, $voucherType);
                    }

                    $txDesc = $item['description'];
                    if($txDesc === '')
                    {
                        $txDesc = ($voucherType === 'expense')
                            ? sprintf(__('Bulk Expense: %s'), $item['ledger_name'])
                            : sprintf(__('Bulk Income: %s'), $item['ledger_name']);
                    }

                    $txData = array(
                        'project_id' => $targetProjectId,
                        'ledger_id' => $sourceLedgerId,
                        'expense_ledger_id' => ($voucherType === 'expense') ? $item['ledger_id'] : 0,
                        'income_ledger_id' => ($voucherType === 'income') ? $item['ledger_id'] : 0,
                        'type' => $voucherType,
                        'status' => 'Posted',
                        'amount' => $item['amount'],
                        'description' => $txDesc,
                        'ref_no' => $itemRefNo,
                        'entry_date' => $entryDate,
                        'construction_site_id' => $item['construction_site_id'],
                        'source_type' => 'bulk_voucher',
                        'created_by' => (int)$this->userId,
                        'modified_by' => (int)$this->userId
                    );

                    $txData = $this->_ardDecorateTransactionPayload($txData, array(
                        'status' => 'Posted',
                        'source_type' => 'bulk_voucher'
                    ));

                    $this->Ardtransaction->create();
                    $saved = $this->Ardtransaction->save(array('Ardtransaction' => $txData), false);
                    if(!$saved)
                    {
                        throw new Exception(sprintf(__('Failed to save voucher for ledger %s'), $item['ledger_name']));
                    }

                    $savedTxId = (int)$this->Ardtransaction->id;

                    if($voucherType === 'expense')
                    {
                        $this->Ardtransaction->query(
                            "UPDATE `ardaccounts_transactions` SET `expense_ledger_id`=".(int)$item['ledger_id']." WHERE `id`=".(int)$savedTxId
                        );
                    }
                    elseif($voucherType === 'income')
                    {
                        $this->Ardtransaction->query(
                            "UPDATE `ardaccounts_transactions` SET `income_ledger_id`=".(int)$item['ledger_id']." WHERE `id`=".(int)$savedTxId
                        );
                    }

                    // Double-entry journal sync
                    $this->_syncJournalForTransaction($savedTxId, 'voucher', $savedTxId);

                    $affectedLedgerIds[] = $item['ledger_id'];
                    $postedCount++;
                }

                // Recalculate balances for all affected ledgers
                foreach(array_unique($affectedLedgerIds) as $affLedgerId)
                {
                    $this->_recalculateLedgerBalance($affLedgerId);
                }

                $ds->commit();

                $successMsg = sprintf(
                    __('Successfully posted %d %s vouchers (Total PKR %s). %d zero/empty rows were safely ignored.'),
                    $postedCount,
                    ucfirst($voucherType),
                    number_format($grandTotal, 2),
                    $skippedZeroCount
                );
                $this->Session->setFlash($successMsg, 'flash', array('alert' => 'success'));

                $redirectAction = ($voucherType === 'expense') ? 'expensetransactions' : 'incometransactions';
                return $this->redirect(array('action' => $redirectAction, $targetProjectId));
            }
            catch(Exception $e)
            {
                $ds->rollback();
                $this->Session->setFlash(__('Bulk voucher posting failed: ') . $e->getMessage(), 'flash', array('alert' => 'danger'));
                return $this->redirect(array('action' => 'bulkvouchers', $targetProjectId));
            }
        }

        // GET: Prepare Data
        // 1. Source Accounts (Bank & Asset)
        $sourceLedgers = $this->Ardledger->find('all', array(
            'fields' => array('Ardledger.id', 'Ardledger.name', 'Ardledger.type', 'Ardledger.balance'),
            'conditions' => array(
                'Ardledger.project_id' => $id,
                'Ardledger.is_trashed' => 0,
                'Ardledger.type IN' => array('asset', 'bank')
            ),
            'order' => array('Ardledger.name' => 'asc'),
            'recursive' => -1
        ));
        $sourceOptions = array();
        $sourceBalances = array();
        foreach($sourceLedgers as $sl)
        {
            $sId = (int)$sl['Ardledger']['id'];
            $sName = trim((string)$sl['Ardledger']['name']);
            $sBal = (float)$sl['Ardledger']['balance'];
            $sourceOptions[$sId] = $sName;
            $sourceBalances[$sId] = $sBal;
        }

        // 2. All Expense Ledgers (for extra rows & presets)
        $allExpenseLedgers = $this->Ardledger->find('all', array(
            'fields' => array('Ardledger.id', 'Ardledger.name', 'Ardledger.category', 'Ardledger.account_code'),
            'conditions' => array(
                'Ardledger.project_id' => $id,
                'Ardledger.is_trashed' => 0,
                'Ardledger.type' => 'expense'
            ),
            'order' => array('Ardledger.name' => 'asc'),
            'recursive' => -1
        ));

        // 3. All Income Ledgers (for extra rows & presets)
        $allIncomeLedgers = $this->Ardledger->find('all', array(
            'fields' => array('Ardledger.id', 'Ardledger.name', 'Ardledger.category', 'Ardledger.account_code'),
            'conditions' => array(
                'Ardledger.project_id' => $id,
                'Ardledger.is_trashed' => 0,
                'Ardledger.type' => 'income'
            ),
            'order' => array('Ardledger.name' => 'asc'),
            'recursive' => -1
        ));

        // 4. Construction Sites
        $siteOptions = $this->Ardsite->find('list', array(
            'fields' => array('Ardsite.id', 'Ardsite.site_name'),
            'conditions' => array(
                'Ardsite.project_id' => $id,
                'Ardsite.status' => 'Active'
            ),
            'order' => array('Ardsite.site_name' => 'asc')
        ));

        // 5. Build Preset Rows for Expense
        $presetExpenseRows = array();
        if(!empty($configuredBulkExpenseIds))
        {
            $configuredExpLedgers = $this->Ardledger->find('all', array(
                'fields' => array('Ardledger.id', 'Ardledger.name', 'Ardledger.category', 'Ardledger.account_code'),
                'conditions' => array(
                    'Ardledger.id' => $configuredBulkExpenseIds,
                    'Ardledger.project_id' => $id,
                    'Ardledger.is_trashed' => 0
                ),
                'recursive' => -1
            ));
            // Preserve configured order
            $expMap = array();
            foreach($configuredExpLedgers as $el)
            {
                $expMap[(int)$el['Ardledger']['id']] = $el['Ardledger'];
            }
            foreach($configuredBulkExpenseIds as $cfgId)
            {
                if(isset($expMap[$cfgId]))
                {
                    $presetExpenseRows[] = $expMap[$cfgId];
                }
            }
        }
        // If not configured, auto-detect common heads matching prompt (Office, Motor Cycle/Bike, Kitchen/Grocery/Tea, Car Fuel, Advertisement/Marketing, Material)
        if(empty($presetExpenseRows))
        {
            $defaultKeywords = array('office', 'bike', 'motor', 'car', 'fuel', 'grocery', 'tea', 'kitchen', 'marketing', 'advertis', 'material', 'cement', 'general');
            foreach($allExpenseLedgers as $el)
            {
                $nameLower = strtolower($el['Ardledger']['name']);
                $catLower = strtolower((string)$el['Ardledger']['category']);
                foreach($defaultKeywords as $kw)
                {
                    if(strpos($nameLower, $kw) !== false || strpos($catLower, $kw) !== false)
                    {
                        $presetExpenseRows[] = $el['Ardledger'];
                        break;
                    }
                }
            }
            if(empty($presetExpenseRows) && !empty($allExpenseLedgers))
            {
                $presetExpenseRows = array_slice(array_map(function($r){ return $r['Ardledger']; }, $allExpenseLedgers), 0, 5);
            }
        }

        // 6. Build Preset Rows for Income
        $presetIncomeRows = array();
        if(!empty($configuredBulkIncomeIds))
        {
            $configuredIncLedgers = $this->Ardledger->find('all', array(
                'fields' => array('Ardledger.id', 'Ardledger.name', 'Ardledger.category', 'Ardledger.account_code'),
                'conditions' => array(
                    'Ardledger.id' => $configuredBulkIncomeIds,
                    'Ardledger.project_id' => $id,
                    'Ardledger.is_trashed' => 0
                ),
                'recursive' => -1
            ));
            $incMap = array();
            foreach($configuredIncLedgers as $il)
            {
                $incMap[(int)$il['Ardledger']['id']] = $il['Ardledger'];
            }
            foreach($configuredBulkIncomeIds as $cfgId)
            {
                if(isset($incMap[$cfgId]))
                {
                    $presetIncomeRows[] = $incMap[$cfgId];
                }
            }
        }
        if(empty($presetIncomeRows))
        {
            $defaultIncKeywords = array('booking', 'installment', 'rental', 'transfer', 'fee', 'sales', 'commission', 'charges');
            foreach($allIncomeLedgers as $il)
            {
                $nameLower = strtolower($il['Ardledger']['name']);
                $catLower = strtolower((string)$il['Ardledger']['category']);
                foreach($defaultIncKeywords as $kw)
                {
                    if(strpos($nameLower, $kw) !== false || strpos($catLower, $kw) !== false)
                    {
                        $presetIncomeRows[] = $il['Ardledger'];
                        break;
                    }
                }
            }
            if(empty($presetIncomeRows) && !empty($allIncomeLedgers))
            {
                $presetIncomeRows = array_slice(array_map(function($r){ return $r['Ardledger']; }, $allIncomeLedgers), 0, 5);
            }
        }

        $activeKind = isset($this->request->query['type']) && strtolower(trim((string)$this->request->query['type'])) === 'income' ? 'income' : 'expense';

        $this->set(compact(
            'sourceOptions',
            'sourceBalances',
            'defaultSourceLedgerId',
            'allowCustomDate',
            'allExpenseLedgers',
            'allIncomeLedgers',
            'presetExpenseRows',
            'presetIncomeRows',
            'siteOptions',
            'activeKind',
            'settings'
        ));
    }

    protected function _defaultVoucherTemplateContent()
    {
        return <<<'HTML'
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>{{company_name}} - Voucher</title>
    <style>
        body{font-family:Arial,Helvetica,sans-serif;background:#f2f6fb;margin:0;padding:20px;color:#1b2f4a}
        .no-print{max-width:920px;margin:0 auto 12px;text-align:right}
        .no-print .btn{background:#133a66;color:#fff;border:none;border-radius:6px;padding:10px 14px;font-weight:700;cursor:pointer}
        .wrap{max-width:920px;margin:0 auto;background:#fff;border:1px solid #d8e2f0;border-radius:12px;overflow:hidden}
        .head{padding:18px 22px;border-bottom:1px solid #e8edf6}
        .head-grid{display:flex;align-items:center;gap:14px}
        .head-main{flex:1;min-width:0}
        .logo-box{width:82px;height:82px;border:1px solid #dbe5f3;border-radius:10px;background:#fff;display:flex;align-items:center;justify-content:center;overflow:hidden;position:relative}
        .logo-box img{max-width:100%;max-height:100%;object-fit:contain;display:block}
        .logo-box .logo-fallback{position:absolute;inset:0;display:none;align-items:center;justify-content:center;text-align:center;font-size:10px;font-weight:700;color:#6e8098;padding:6px}
        .logo-box img[src=""]{display:none}
        .logo-box img[src=""] + .logo-fallback{display:flex}
        .head h1{margin:0;font-size:28px;color:#163357}
        .head p{margin:5px 0 0;color:#4a607f;font-size:12px}
        .title{padding:12px 22px;background:#f7faff;border-bottom:1px solid #e8edf6;display:flex;justify-content:space-between;gap:10px;align-items:center}
        .title h2{margin:0;font-size:22px;color:#112f55}
        .title .meta{font-size:13px;color:#375071;font-weight:700}
        .info{padding:16px 22px;border-bottom:1px solid #edf2fa}
        .row{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:8px}
        .row:last-child{margin-bottom:0}
        .card{flex:1 1 30%;min-width:220px;border:1px solid #dbe5f3;border-radius:8px;padding:10px;background:#fbfdff}
        .card .k{display:block;font-size:11px;color:#6a7f9a;text-transform:uppercase;letter-spacing:.08em}
        .card .v{display:block;margin-top:6px;font-size:16px;font-weight:700;color:#203b60;word-break:break-word}
        .narration{padding:14px 22px;border-bottom:1px solid #edf2fa}
        .narration h3{margin:0 0 7px;font-size:14px;color:#203b60}
        .narration p{margin:0;font-size:14px;color:#2f4a6a;line-height:1.6;white-space:pre-wrap}
        .foot{padding:12px 22px;font-size:12px;color:#5d7392;display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap;background:#f8fbff}
        @media print{
            @page { size: A4 portrait; margin: 8mm; }
            body{background:#fff;padding:0}
            .no-print{display:none}
            .wrap{max-width:none;border:none;border-radius:0}
        }
    </style>
</head>
<body>
    <div class="no-print">
        <button class="btn" onclick="window.print()">Print Voucher</button>
    </div>
    <div class="wrap">
        <div class="head">
            <div class="head-grid">
                <div class="logo-box">
                    <img src="{{agency_logo_url}}" alt="Agency Logo" onerror="this.style.display='none';if(this.nextElementSibling){this.nextElementSibling.style.display='flex';}">
                    <div class="logo-fallback">Agency Logo</div>
                </div>
                <div class="head-main">
                    <h1>{{agency_name}}</h1>
                    <p>{{agency_address}}</p>
                    <p>{{agency_phone}} | {{agency_email}}</p>
                </div>
            </div>
        </div>
        <div class="title">
            <h2>{{voucher_type}}</h2>
            <div class="meta">Voucher: {{voucher_no}} | Date: {{entry_date}}</div>
        </div>
        <div class="info">
            <div class="row">
                <div class="card"><span class="k">Ledger</span><span class="v">{{ledger_name}}</span></div>
                <div class="card"><span class="k">Stock Store</span><span class="v">{{site_name}}</span></div>
                <div class="card"><span class="k">Amount</span><span class="v">{{amount_with_currency}}</span></div>
            </div>
            <div class="row">
                <div class="card"><span class="k">Account Code</span><span class="v">{{account_code}}</span></div>
                <div class="card"><span class="k">Account / Head</span><span class="v">{{account_no}}</span></div>
                <div class="card"><span class="k">Pay To</span><span class="v">{{pay_to}}</span></div>
            </div>
            <div class="row">
                <div class="card"><span class="k">Amount in Words</span><span class="v">{{amount_words}}</span></div>
            </div>
        </div>
        <div class="narration">
            <h3>Narration</h3>
            <p>{{narration}}</p>
        </div>
        <div class="foot" style="align-items:center;">
            <span>Reference: {{reference_no}}</span>
            <div style="text-align:center;">{{barcode_svg}}</div>
            <span>Generated: {{generated_at}}</span>
        </div>
    </div>
</body>
</html>
HTML;
    }

