    {
        return <<<'HTML'
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>{{company_name}} - Salary Slip</title>
    <style>
        body{font-family:Arial,Helvetica,sans-serif;background:#f2f6fb;margin:0;padding:20px;color:#1b2f4a}
        .no-print{max-width:920px;margin:0 auto 12px;text-align:right}
        .no-print .btn{background:#1f4f82;color:#fff;border:none;border-radius:6px;padding:10px 14px;font-weight:700;cursor:pointer}
        .wrap{max-width:920px;margin:0 auto;background:#fff;border:1px solid #d8e2f0;border-radius:12px;overflow:hidden}
