            body{background:#fff;padding:0}
            .no-print{display:none}
            .wrap{max-width:none;border:none;border-radius:0}
        }
    </style>
</head>
<body>
    <div class="no-print"><button class="btn" onclick="window.print()">Print Salary Slip</button></div>
    <div class="wrap">
        <div class="head">
            <div class="head-grid">
                <div class="logo-box">
                    <img src="{{agency_logo_url}}" alt="Agency Logo" onerror="this.style.display='none';if(this.nextElementSibling){this.nextElementSibling.style.display='flex';}">
                    <div class="logo-fallback">Agency Logo</div>
                </div>
                <div class="head-main">
                    <h1>{{agency_name}}</h1>
                    <p>{{agency_address}}</p>
                    <p>{{agency_phone}} | {{agency_email}}</p>
                </div>
            </div>
        </div>
        <div class="title">
            <h2>Salary Slip</h2>
            <div class="meta">Month: {{payroll_month}} | Date: {{payment_date}}</div>
        </div>
        <div class="grid">
            <div class="row">
                <div class="card"><span class="k">Employee</span><span class="v">{{employee_name}}</span></div>
                <div class="card"><span class="k">Employee Code</span><span class="v">{{employee_code}}</span></div>
                <div class="card"><span class="k">Department / Designation</span><span class="v">{{department}} / {{designation}}</span></div>
            </div>
            <div class="row">
                <div class="card"><span class="k">Working / Present Days</span><span class="v">{{working_days}} / {{present_days}}</span></div>
                <div class="card"><span class="k">Payment Method</span><span class="v">{{payment_method}}</span></div>
                <div class="card"><span class="k">Status</span><span class="v">{{status}}</span></div>
            </div>
        </div>
        <div class="tbl">
            <table>
                <thead>
                    <tr>
                        <th>Details</th>
                        <th class="tr">Amount</th>
                    </tr>
                </thead>
                <tbody>
                    <tr><td>Base Salary</td><td class="tr">{{base_salary}}</td></tr>
                    <tr><td>Bonus</td><td class="tr">{{bonus}}</td></tr>
                    <tr><td>Commission</td><td class="tr">{{commission_amount}}</td></tr>
                    <tr><td>Overtime ({{overtime_hours}} hrs)</td><td class="tr">{{overtime_amount}}</td></tr>
                    <tr><td>Deductions</td><td class="tr">{{deductions}}</td></tr>
                    <tr><td><strong>Net Pay</strong></td><td class="tr"><strong>{{net_pay}}</strong></td></tr>
