    protected function _defaultTemplateContentByType($templateType)
    {
        $templateType = strtolower(trim((string)$templateType));
        if($templateType === 'voucher')
        {
            return $this->_defaultVoucherTemplateContent();
        }
        if($templateType === 'salary')
        {
            return $this->_defaultSalaryTemplateContent();
        }
        if($templateType === 'stock_purchase')
        {
            return $this->_defaultStockPurchaseTemplateContent();
        }
        return '';
    }

    protected function _ensureDefaultTemplatesForProject($projectId, $templateTypes = array('salary', 'stock_purchase'))
    {
        $this->loadModel('Admin.Ardtemplate');
        $projectId = (int)$projectId;
        if($projectId <= 0)
        {
            return;
        }
        $allowedTypes = $this->_templateTypeOptions();
        foreach((array)$templateTypes as $templateType)
        {
            $templateType = strtolower(trim((string)$templateType));
            if($templateType === '' || !isset($allowedTypes[$templateType]))
            {
                continue;
            }
            $existing = $this->Ardtemplate->find('first', array(
                'fields' => array('Ardtemplate.id'),
                'conditions' => array(
                    'Ardtemplate.project_id' => $projectId,
                    'Ardtemplate.template_type' => $templateType
                ),
                'order' => array('Ardtemplate.is_active' => 'desc', 'Ardtemplate.id' => 'asc'),
                'recursive' => -1
            ));
            if(!empty($existing['Ardtemplate']['id']))
            {
                continue;
            }
            $templateContent = $this->_defaultTemplateContentByType($templateType);
            if(trim((string)$templateContent) === '')
            {
                continue;
            }
            $templateName = 'Default ' . trim((string)$allowedTypes[$templateType]);
            $row = array(
                'project_id' => $projectId,
                'template_type' => $templateType,
                'template_name' => $templateName,
                'template_content' => $templateContent,
                'is_active' => 1
            );
            $this->Ardtemplate->create();
            if($this->Ardtemplate->save(array('Ardtemplate' => $row), false))
            {
                $savedTemplateId = (int)$this->Ardtemplate->id;
                if($savedTemplateId > 0)
                {
                    $this->_syncSingleActiveTemplate($projectId, $templateType, $savedTemplateId);
                }
            }
        }
    }

    protected function _renderVoucherTemplateTokens($templateContent, $tokenMap = array())
    {
        $templateContent = (string)$templateContent;
        if($templateContent === '')
        {
            return '';
        }

        // Handle escaped newlines if template was saved with literal \n text.
        if(strpos($templateContent, '\n') !== false || strpos($templateContent, '\r') !== false)
        {
            $templateContent = str_replace(array('\r\n', '\n', '\r'), array("\n", "\n", "\n"), $templateContent);
        }

        $search = array();
        $replace = array();
        $rawKeys = array('barcode_svg', 'agency_logo_img');
        foreach((array)$tokenMap as $key => $value)
        {
            $k = trim((string)$key);
            $search[] = '{{' . $k . '}}';
            if(in_array($k, $rawKeys, true) || substr($k, -4) === '_raw' || substr($k, -4) === '_svg' || substr($k, -4) === '_img')
            {
                $replace[] = (string)$value;
            }
            else
            {
                $replace[] = htmlspecialchars(trim((string)$value), ENT_QUOTES, 'UTF-8');
            }
        }
        return str_replace($search, $replace, $templateContent);
    }

    protected function _applyVoucherDateMonthStyle($html)
    {
        $html = (string)$html;
        if($html === '')
        {
            return $html;
        }
        $html = str_replace('Acc/Balance', 'Acc/From', $html);
        if(stripos($html, 'wv-voucher-date-month-style') !== false)
        {
            return $html;
        }

        $style = '<style id="wv-voucher-date-month-style">.date-box .date-cell:nth-child(3),.date-box .date-cell:nth-child(4){background:rgba(128,128,128,.5)!important;}</style>';
        if(stripos($html, '</head>') !== false)
        {
            return preg_replace('/<\/head>/i', $style.'</head>', $html, 1);
        }
        return $style.$html;
    }

    protected function _voucherAmountInWords($amount, $currencySymbol = 'Rs')
    {
        $amount = round(abs((float)$amount), 2);
        $whole = (int)floor($amount);
        $fraction = (int)round(($amount - $whole) * 100);
        if($fraction >= 100)
        {
            $whole++;
            $fraction = 0;
        }

        $currencyWord = $this->_voucherCurrencyWord($currencySymbol);
        $words = $this->_voucherIntegerInWords($whole) . ' ' . $currencyWord;
        if($fraction > 0)
        {
            $words .= ' And ' . $this->_voucherIntegerInWords($fraction) . ' Paisa';
        }
        return trim($words) . ' Only';
    }

    protected function _voucherCurrencyWord($currencySymbol)
    {
        $symbol = strtoupper(trim(strip_tags((string)$currencySymbol)));
        if(in_array($symbol, array('RS', 'RS.', 'PKR', 'RUPEE', 'RUPEES'), true))
        {
            return 'Rupees';
        }
        if(in_array($symbol, array('$', 'USD'), true))
        {
            return 'Dollars';
        }
        if(in_array($symbol, array('AED', 'DH', 'DIRHAM', 'DIRHAMS'), true))
        {
            return 'Dirhams';
        }
        if($symbol === '')
        {
            return 'Rupees';
        }
        return ucwords(strtolower($symbol));
    }

    protected function _voucherIntegerInWords($number)
    {
        $number = (int)$number;
        if($number === 0)
        {
            return 'Zero';
        }

        $labels = array('', 'Thousand', 'Lakh', 'Crore', 'Arab', 'Kharab');
        $groups = array();
        $groups[] = array($number % 1000, $labels[0]);
        $number = (int)floor($number / 1000);
        $labelIndex = 1;
        while($number > 0)
        {
            $groups[] = array($number % 100, isset($labels[$labelIndex]) ? $labels[$labelIndex] : '');
            $number = (int)floor($number / 100);
            $labelIndex++;
        }

        $parts = array();
        for($i = count($groups) - 1; $i >= 0; $i--)
        {
            $chunk = (int)$groups[$i][0];
            if($chunk <= 0)
            {
                continue;
            }
            $chunkWords = $this->_voucherNumberBelowThousandInWords($chunk);
            $label = trim((string)$groups[$i][1]);
            $parts[] = trim($chunkWords . ($label !== '' ? ' ' . $label : ''));
        }
        return implode(' ', $parts);
    }

    protected function _voucherNumberBelowThousandInWords($number)
    {
        $number = (int)$number;
        $ones = array(
            0 => '',
            1 => 'One',
            2 => 'Two',
            3 => 'Three',
            4 => 'Four',
            5 => 'Five',
            6 => 'Six',
            7 => 'Seven',
            8 => 'Eight',
            9 => 'Nine',
            10 => 'Ten',
            11 => 'Eleven',
            12 => 'Twelve',
            13 => 'Thirteen',
            14 => 'Fourteen',
            15 => 'Fifteen',
            16 => 'Sixteen',
            17 => 'Seventeen',
            18 => 'Eighteen',
            19 => 'Nineteen'
        );
        $tens = array(
            2 => 'Twenty',
            3 => 'Thirty',
            4 => 'Forty',
            5 => 'Fifty',
            6 => 'Sixty',
            7 => 'Seventy',
            8 => 'Eighty',
            9 => 'Ninety'
        );

        $parts = array();
        if($number >= 100)
        {
            $parts[] = $ones[(int)floor($number / 100)] . ' Hundred';
            $number = $number % 100;
        }
        if($number > 0)
        {
            if($number < 20)
            {
                $parts[] = $ones[$number];
            }
            else
            {
                $ten = (int)floor($number / 10);
                $unit = $number % 10;
                $parts[] = trim($tens[$ten] . ($unit > 0 ? ' ' . $ones[$unit] : ''));
            }
        }
        return implode(' ', $parts);
    }

    protected function _templateTypeOptions()
    {
        return array(
            'voucher' => __('Voucher'),
            'salary' => __('Salary Slip'),
            'stock_purchase' => __('Stock Purchase')
        );
    }

    protected function _syncSingleActiveTemplate($projectId, $templateType, $preferredTemplateId = 0)
    {
        $this->loadModel('Admin.Ardtemplate');
        $projectId = (int)$projectId;
        $templateType = trim((string)$templateType);
        $preferredTemplateId = (int)$preferredTemplateId;
        if($projectId <= 0 || $templateType === '')
        {
            return 0;
        }

        $this->Ardtemplate->cacheQueries = false;

        if($preferredTemplateId > 0)
        {
            $this->Ardtemplate->updateAll(
                array('Ardtemplate.is_active' => 0),
                array(
                    'Ardtemplate.project_id' => $projectId,
                    'Ardtemplate.template_type' => $templateType,
                    'Ardtemplate.id <>' => $preferredTemplateId
                )
            );
            $this->Ardtemplate->updateAll(
                array('Ardtemplate.is_active' => 1),
                array(
                    'Ardtemplate.project_id' => $projectId,
                    'Ardtemplate.template_type' => $templateType,
                    'Ardtemplate.id' => $preferredTemplateId
                )
            );
            return $preferredTemplateId;
        }

        $activeRows = $this->Ardtemplate->find('all', array(
            'fields' => array('Ardtemplate.id'),
            'conditions' => array(
                'Ardtemplate.project_id' => $projectId,
                'Ardtemplate.template_type' => $templateType,
                'Ardtemplate.is_active' => 1
            ),
            'order' => array('Ardtemplate.id' => 'desc'),
            'recursive' => -1
        ));
        if(!empty($activeRows))
        {
            $keepId = (int)$activeRows[0]['Ardtemplate']['id'];
            if(count($activeRows) > 1)
            {
                $this->Ardtemplate->updateAll(
                    array('Ardtemplate.is_active' => 0),
                    array(
                        'Ardtemplate.project_id' => $projectId,
                        'Ardtemplate.template_type' => $templateType,
                        'Ardtemplate.is_active' => 1,
                        'Ardtemplate.id <>' => $keepId
                    )
                );
            }
            return $keepId;
        }

        $fallbackRow = $this->Ardtemplate->find('first', array(
            'fields' => array('Ardtemplate.id'),
            'conditions' => array(
                'Ardtemplate.project_id' => $projectId,
                'Ardtemplate.template_type' => $templateType
            ),
            'order' => array('Ardtemplate.id' => 'desc'),
            'recursive' => -1
        ));
        if(!empty($fallbackRow['Ardtemplate']['id']))
        {
            $fallbackId = (int)$fallbackRow['Ardtemplate']['id'];
            $this->Ardtemplate->updateAll(
                array('Ardtemplate.is_active' => 1),
                array('Ardtemplate.id' => $fallbackId)
            );
            return $fallbackId;
        }
        return 0;
    }

