    public function printvoucher($transactionId = null, $projectId = null)
    {
        $this->loadModel('Admin.Ardtransaction');
        $this->loadModel('Admin.Ardledger');
        $this->loadModel('Admin.Ardsite');
        $this->loadModel('Admin.Agency');
        $this->loadModel('Admin.Ardsetting');
        $this->loadModel('Admin.Ardtemplate');

        $transactionId = (int)$transactionId;
        if($transactionId <= 0)
        {
            $this->Session->setFlash(__('Invalid voucher.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'transactions', $this->_activeProjectId($projectId)));
        }

        $row = $this->Ardtransaction->find('first', array(
            'joins' => array(
                array('table' => 'ardaccounts_ledgers', 'alias' => 'Ardledger', 'type' => 'LEFT', 'conditions' => array('Ardledger.id=Ardtransaction.ledger_id')),
                array('table' => 'ardaccounts_ledgers', 'alias' => 'ExpenseLedger', 'type' => 'LEFT', 'conditions' => array('ExpenseLedger.id=Ardtransaction.expense_ledger_id')),
                array('table' => 'ardaccounts_ledgers', 'alias' => 'IncomeLedger', 'type' => 'LEFT', 'conditions' => array('IncomeLedger.id=Ardtransaction.income_ledger_id')),
                array('table' => 'ardaccounts_construction_sites', 'alias' => 'Ardsite', 'type' => 'LEFT', 'conditions' => array('Ardsite.id=Ardtransaction.construction_site_id'))
            ),
            'fields' => array(
                'Ardtransaction.*',
                'Ardledger.id',
                'Ardledger.name',
                'Ardledger.account_code',
                'Ardledger.account_type',
                'Ardledger.account_no',
                'Ardledger.mobile_no',
                'Ardledger.address',
                'ExpenseLedger.id',
                'ExpenseLedger.name',
                'ExpenseLedger.account_code',
                'ExpenseLedger.account_type',
                'ExpenseLedger.account_no',
                'IncomeLedger.id',
                'IncomeLedger.name',
                'IncomeLedger.account_code',
                'IncomeLedger.account_type',
                'IncomeLedger.account_no',
                'Ardsite.site_name'
            ),
            'conditions' => array('Ardtransaction.id' => $transactionId),
            'recursive' => -1
        ));

        if(empty($row) || empty($row['Ardtransaction']))
        {
            $this->Session->setFlash(__('Voucher record not found.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'transactions', $this->_activeProjectId($projectId)));
        }

        $tx = $row['Ardtransaction'];
        $txProjectId = (int)$tx['project_id'];
        if(!$this->_isAllowedProject($txProjectId))
        {
            $this->Session->setFlash(__('You are not allowed to access this voucher.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'transactions', $this->_activeProjectId($projectId)));
        }

        $agency = $this->Agency->find('first', array(
            'conditions' => array('Agency.id' => $txProjectId),
            'recursive' => -1
        ));
        $settings = $this->Ardsetting->find('first', array(
            'conditions' => array('Ardsetting.project_id' => $txProjectId),
            'order' => array('Ardsetting.id' => 'desc'),
            'recursive' => -1
        ));
        $this->_syncSingleActiveTemplate($txProjectId, 'voucher', 0);
        $this->Ardtemplate->cacheQueries = false;
        $templateRow = $this->Ardtemplate->find('first', array(
            'conditions' => array(
                'Ardtemplate.project_id' => $txProjectId,
                'Ardtemplate.template_type' => 'voucher',
                'Ardtemplate.is_active' => 1
            ),
            'order' => array('Ardtemplate.id' => 'desc'),
            'recursive' => -1
        ));
        if(empty($templateRow))
        {
            $templateRow = $this->Ardtemplate->find('first', array(
                'conditions' => array(
                    'Ardtemplate.project_id' => $txProjectId,
                    'Ardtemplate.template_type' => 'voucher'
                ),
                'order' => array('Ardtemplate.is_active' => 'desc', 'Ardtemplate.id' => 'desc'),
                'recursive' => -1
            ));
        }

        $templateContent = '';
        if(!empty($templateRow['Ardtemplate']['template_content']))
        {
            $templateContent = (string)$templateRow['Ardtemplate']['template_content'];
        }
        if(trim($templateContent) === '')
        {
            $templateContent = $this->_defaultVoucherTemplateContent();
        }
        $txType = strtolower(trim((string)$tx['type']));
        $sourceLedgerName = isset($row['Ardledger']['name']) ? trim((string)$row['Ardledger']['name']) : '';
        $expenseLedgerName = isset($row['ExpenseLedger']['name']) ? trim((string)$row['ExpenseLedger']['name']) : '';
        $incomeLedgerName = isset($row['IncomeLedger']['name']) ? trim((string)$row['IncomeLedger']['name']) : '';

        $sourceAccountCode = isset($row['Ardledger']['account_code']) ? trim((string)$row['Ardledger']['account_code']) : '';
        $expenseAccountCode = isset($row['ExpenseLedger']['account_code']) ? trim((string)$row['ExpenseLedger']['account_code']) : '';
        $incomeAccountCode = isset($row['IncomeLedger']['account_code']) ? trim((string)$row['IncomeLedger']['account_code']) : '';

        $sourceAccountNo = isset($row['Ardledger']['account_no']) ? trim((string)$row['Ardledger']['account_no']) : '';
        $expenseAccountNo = isset($row['ExpenseLedger']['account_no']) ? trim((string)$row['ExpenseLedger']['account_no']) : '';
        $incomeAccountNo = isset($row['IncomeLedger']['account_no']) ? trim((string)$row['IncomeLedger']['account_no']) : '';

        $ledgerName = $sourceLedgerName;
        $accountCode = $sourceAccountCode;
        $accountNo = $sourceAccountNo;
        $accountBoxLabel = 'Acc / From';

        if($txType === 'expense')
        {
            $accountBoxLabel = 'Acc / To';
            if($expenseLedgerName !== '')
            {
                $ledgerName = $expenseLedgerName;
            }
            if($expenseAccountCode !== '')
            {
                $accountCode = $expenseAccountCode;
            }
            if($expenseAccountNo !== '')
            {
                $accountNo = $expenseAccountNo;
            }
        }
        elseif($txType === 'income')
        {
            $accountBoxLabel = 'Acc / From';
            if($accountCode === '' && $incomeAccountCode !== '')
            {
                $accountCode = $incomeAccountCode;
            }
            if($ledgerName === '' && $incomeLedgerName !== '')
            {
                $ledgerName = $incomeLedgerName;
            }
            if($accountNo === '' && $incomeAccountNo !== '')
            {
                $accountNo = $incomeAccountNo;
            }
        }

        if($accountCode === '')
        {
            $activeLedgerId = ($txType === 'expense' && !empty($tx['expense_ledger_id'])) ? (int)$tx['expense_ledger_id'] : (int)$tx['ledger_id'];
            if($activeLedgerId > 0)
            {
                $accCodeField = $this->Ardledger->field('account_code', array('Ardledger.id' => $activeLedgerId));
                if(!empty($accCodeField))
                {
                    $accountCode = trim((string)$accCodeField);
                }
            }
        }

        if($accountNo === '' || $accountNo === '-')
        {
            $accountDisplayNo = ($accountCode !== '') ? $accountCode : '-';
        }
        else
        {
            $accountDisplayNo = ($accountCode !== '') ? ($accountCode . ' - ' . $accountNo) : $accountNo;
        }

        $siteName = isset($row['Ardsite']['site_name']) ? trim((string)$row['Ardsite']['site_name']) : '';
        $entryDate = isset($tx['entry_date']) ? trim((string)$tx['entry_date']) : '';
        if($entryDate === '' || $entryDate === '0000-00-00')
        {
            $entryDate = date('Y-m-d');
        }
        $entryTimestamp = strtotime($entryDate);
        if($entryTimestamp === false)
        {
            $entryTimestamp = time();
        }
        $entryDateLabel = date('d-M-Y', $entryTimestamp);
        $dateDigits = str_pad(date('dmY', $entryTimestamp), 8, '0', STR_PAD_RIGHT);

        $amount = round((float)$tx['amount'], 2);
        $amountFormatted = number_format($amount, 2, '.', ',');
        $currencySymbol = trim(strip_tags((string)$this->currency));
        if($currencySymbol === '')
        {
            $currencySymbol = 'Rs';
        }
        $amountWithCurrency = $currencySymbol . ' ' . $amountFormatted;

        $voucherType = 'Voucher';
        if($txType === 'income')
        {
            $voucherType = 'Income Voucher';
        }
        elseif($txType === 'expense')
        {
            $voucherType = 'Expense Voucher';
        }
        elseif($txType !== '')
        {
            $voucherType = ucwords(str_replace('_', ' ', $txType)) . ' Voucher';
        }

        $agencyRow = !empty($agency['Agency']) ? $agency['Agency'] : array();
        $settingsRow = !empty($settings['Ardsetting']) ? $settings['Ardsetting'] : array();
        $companyName = !empty($settingsRow['company_name']) ? trim((string)$settingsRow['company_name']) : '';
        if($companyName === '')
        {
            $companyName = !empty($agencyRow['name']) ? trim((string)$agencyRow['name']) : 'White Villas';
        }
        $resolveImagePath = function($candidates = array()) {
            foreach((array)$candidates as $candidate)
            {
                if(!is_string($candidate))
                {
                    continue;
                }
                $cleanPath = trim(str_replace('\\', '/', (string)$candidate), '/');
                if($cleanPath === '')
                {
                    continue;
                }
                $fullPath = WWW_ROOT . 'img' . DS . str_replace('/', DS, $cleanPath);
                if(file_exists($fullPath))
                {
                    return $cleanPath;
                }
            }
            return '';
        };
        $agencyLogoFile = '';
        if($txProjectId > 0)
        {
            try
            {
                $this->loadModel('User');
                $userFields = array('User.id');
                if($this->User->hasField('photo'))
                {
                    $userFields[] = 'User.photo';
                }
                $baseConditions = array(
                    'User.project_id' => $txProjectId,
                    'User.photo <>' => ''
                );
                $agencyUserRow = array();
                if($this->User->hasField('ugroup_id'))
                {
                    $agencyUserRow = $this->User->find('first', array(
                        'fields' => $userFields,
                        'conditions' => array_merge($baseConditions, array('User.ugroup_id' => 4)),
                        'order' => array('User.id' => 'asc'),
                        'recursive' => -1
                    ));
                }
                if(empty($agencyUserRow))
                {
                    $agencyUserRow = $this->User->find('first', array(
                        'fields' => $userFields,
                        'conditions' => $baseConditions,
                        'order' => array('User.id' => 'asc'),
                        'recursive' => -1
                    ));
                }
                if(!empty($agencyUserRow['User']['photo']))
                {
                    $agencyLogoFile = trim((string)$agencyUserRow['User']['photo']);
                }
            }
            catch(Exception $e)
            {
                $agencyLogoFile = '';
            }
        }
        $agencyLogoPath = $resolveImagePath(array(
            ($agencyLogoFile !== '' ? 'user_thumb/' . $agencyLogoFile : ''),
            ($agencyLogoFile !== '' ? 'user/' . $agencyLogoFile : ''),
            ($agencyLogoFile !== '' ? $agencyLogoFile : ''),
            !empty($agencyRow['photo']) ? 'agency_thumb/' . $agencyRow['photo'] : '',
            !empty($agencyRow['photo']) ? 'agency/' . $agencyRow['photo'] : '',
            !empty($agencyRow['photo']) ? $agencyRow['photo'] : ''
        ));
        $agencyLogoUrl = ($agencyLogoPath !== '') ? Router::url('/img/' . $agencyLogoPath, true) : '';

        $sessionUser = (array)$this->Session->read('User');
        $sessionUserRow = !empty($sessionUser['User']) ? (array)$sessionUser['User'] : array();
        $agentPhotoPath = $resolveImagePath(array(
            !empty($sessionUserRow['photo']) ? 'user_thumb/' . $sessionUserRow['photo'] : '',
            !empty($sessionUserRow['photo']) ? 'user/' . $sessionUserRow['photo'] : '',
            !empty($sessionUserRow['photo']) ? $sessionUserRow['photo'] : ''
        ));
        $agentPhotoUrl = ($agentPhotoPath !== '') ? Router::url('/img/' . $agentPhotoPath, true) : '';
        $agentName = !empty($sessionUserRow['name']) ? trim((string)$sessionUserRow['name']) : '-';
        $agentUsername = !empty($sessionUserRow['username']) ? trim((string)$sessionUserRow['username']) : '-';
        $agentEmail = !empty($sessionUserRow['email']) ? trim((string)$sessionUserRow['email']) : '-';
        $agentPhone = !empty($sessionUserRow['phone']) ? trim((string)$sessionUserRow['phone']) : '-';
        $agentMobile = !empty($sessionUserRow['mobile']) ? trim((string)$sessionUserRow['mobile']) : '-';
        $agentAddress = !empty($sessionUserRow['address']) ? trim((string)$sessionUserRow['address']) : '-';

        $refNo = isset($tx['ref_no']) ? trim((string)$tx['ref_no']) : '';
        if($refNo === '')
        {
            $refNo = 'VCH-' . (int)$tx['id'];
        }
        $description = isset($tx['description']) ? trim((string)$tx['description']) : '';
        if($description === '')
        {
            $description = '-';
        }
        $payTo = $ledgerName !== '' ? $ledgerName : '-';
        $agencyLogoImgTag = '';
        if($agencyLogoUrl !== '')
        {
            $agencyLogoImgTag = '<img src="' . htmlspecialchars($agencyLogoUrl, ENT_QUOTES, 'UTF-8') . '" alt="Agency Logo" style="max-width:100%;max-height:100%;object-fit:contain;" />';
        }

        $barcodeSvg = $this->_generateCode128BarcodeSvg($refNo, 36, 2);

        $tokenMap = array(
            'company_name' => $companyName,
            'agency_name' => !empty($agencyRow['name']) ? $agencyRow['name'] : $companyName,
            'agency_logo_url' => $agencyLogoUrl,
            'agency_logo' => $agencyLogoUrl,
            'agency_logo_img' => $agencyLogoImgTag,
            'agency_address' => !empty($agencyRow['address']) ? $agencyRow['address'] : '-',
            'agency_phone' => !empty($agencyRow['phone']) ? $agencyRow['phone'] : '-',
            'agency_mobile' => !empty($agencyRow['mobile']) ? $agencyRow['mobile'] : '-',
            'agency_email' => !empty($agencyRow['email']) ? $agencyRow['email'] : '-',
            'agency_id' => $txProjectId,
            'agent_name' => $agentName,
            'agent_username' => $agentUsername,
            'agent_email' => $agentEmail,
            'agent_phone' => $agentPhone,
            'agent_mobile' => $agentMobile,
            'agent_address' => $agentAddress,
            'agent_photo_url' => $agentPhotoUrl,
            'agent_logo_url' => $agentPhotoUrl,
            'voucher_no' => $refNo,
            'reference_no' => $refNo,
            'voucher_type' => $voucherType,
            'entry_date' => $entryDateLabel,
            'generated_at' => date('d-M-Y H:i:s'),
            'pay_to' => $payTo,
            'ledger_name' => ($ledgerName !== '' ? $ledgerName : '-'),
            'source_ledger_name' => ($sourceLedgerName !== '' ? $sourceLedgerName : '-'),
            'expense_ledger_name' => ($expenseLedgerName !== '' ? $expenseLedgerName : '-'),
            'site_name' => ($siteName !== '' ? $siteName : '-'),
            'narration' => $description,
            'description' => $description,
            'amount' => $amountFormatted,
            'amount_number' => $amountFormatted,
            'amount_with_currency' => $amountWithCurrency,
            'amount_words' => $this->_voucherAmountInWords($amount, $currencySymbol),
            'currency_symbol' => $currencySymbol,
            'account_code' => ($accountCode !== '' ? $accountCode : '-'),
            'account_no' => $accountDisplayNo,
            'account_display_no' => $accountDisplayNo,
            'account_head_name' => ($ledgerName !== '' ? $ledgerName : '-'),
            'account_box_label' => $accountBoxLabel,
            'barcode_svg' => $barcodeSvg,
            'barcode_text' => $refNo,
            'debit_amount' => ($txType === 'expense') ? $amountWithCurrency : '-',
            'credit_amount' => ($txType === 'income') ? $amountWithCurrency : '-',
            'd1' => substr($dateDigits, 0, 1),
            'd2' => substr($dateDigits, 1, 1),
            'd3' => substr($dateDigits, 2, 1),
            'd4' => substr($dateDigits, 3, 1),
            'd5' => substr($dateDigits, 4, 1),
            'd6' => substr($dateDigits, 5, 1),
            'd7' => substr($dateDigits, 6, 1),
            'd8' => substr($dateDigits, 7, 1)
        );

        // Self-healing for legacy template markups (hardcoded barcodes and bare account boxes)
        $legacyBarcodePattern = '/<svg[^>]*viewBox="0 0 400 32"[^>]*>.*?<\/svg>/s';
        if(preg_match($legacyBarcodePattern, $templateContent))
        {
            $templateContent = preg_replace($legacyBarcodePattern, '{{barcode_svg}}', $templateContent);
            $templateContent = str_replace('tracking-[0.8em]', 'tracking-[0.25em]', $templateContent);
            $templateContent = str_replace('text-gray-500 uppercase">{{barcode_text}}', 'text-gray-700 uppercase font-extrabold">{{barcode_text}}', $templateContent);
        }
        $legacyAccBoxPattern = '/<div class="w-64 border-2 border-black p-3 h-20 flex flex-col justify-between bg-white">\s*<span class="text-\[9px\] font-black uppercase text-gray-400 tracking-widest">Acc\/From<\/span>\s*<span class="font-bold tracking-\[0\.2em\] text-lg">\{\{account_no\}\}<\/span>\s*<\/div>/s';
        if(preg_match($legacyAccBoxPattern, $templateContent))
        {
            $newAccBoxMarkup = '<div class="w-64 border-2 border-black p-2.5 h-20 flex flex-col justify-between bg-white">' .
                '<div class="flex justify-between items-center border-b border-gray-200 pb-0.5">' .
                '<span class="text-[9px] font-black uppercase text-gray-500 tracking-widest">{{account_box_label}}</span>' .
                '<span class="text-[10px] font-mono font-bold text-gray-700 tracking-wider">A/C: <strong class="text-black font-extrabold">{{account_code}}</strong></span>' .
                '</div>' .
                '<div class="flex flex-col justify-end">' .
                '<span class="font-mono font-bold tracking-[0.2em] text-lg text-black leading-tight">{{account_display_no}}</span>' .
                '<span class="text-[9px] font-bold text-gray-500 uppercase tracking-wider truncate mt-0.5">{{account_head_name}}</span>' .
                '</div>' .
                '</div>';
            $templateContent = preg_replace($legacyAccBoxPattern, $newAccBoxMarkup, $templateContent);
        }

        $html = $this->_renderVoucherTemplateTokens($templateContent, $tokenMap);
        if(stripos($html, '<html') === false)
        {
            $html = '<!DOCTYPE html><html><head><meta charset="UTF-8"><title>' .
                htmlspecialchars($tokenMap['voucher_no'], ENT_QUOTES, 'UTF-8') .
                '</title></head><body>' . $html . '</body></html>';
        }
        $html = $this->_applyVoucherDateMonthStyle($html);

        $this->layout = false;
        $this->autoRender = false;
        $this->response->type('html');
        $this->response->body($html);
        return $this->response;
    }

    public function deletetransaction($id = null, $projectId = null)
    {
        $this->loadModel('Admin.Ardtransaction');
        $this->loadModel('Admin.Ardjournalentry');
        $row = $this->Ardtransaction->findById($id);
        if(empty($row) || !$this->_isAllowedProject((int)$row['Ardtransaction']['project_id']))
        {
            $this->Session->setFlash(__('Invalid voucher.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'transactions', $projectId));
        }
        $lockMessage = $this->_ardTransactionLockedMessage($row['Ardtransaction'], (int)$row['Ardtransaction']['project_id']);
        if($lockMessage !== '')
        {
            $this->Session->setFlash($lockMessage, 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'transactions', $projectId));
        }
        $journalMeta = array();
        $journalRow = $this->Ardjournalentry->find('first', array(
            'fields' => array('Ardjournalentry.source_type', 'Ardjournalentry.source_id'),
            'conditions' => array('Ardjournalentry.transaction_id' => (int)$row['Ardtransaction']['id']),
            'recursive' => -1
        ));
        if(!empty($journalRow['Ardjournalentry']))
        {
            $journalMeta['journal_source_type'] = trim((string)$journalRow['Ardjournalentry']['source_type']);
            $journalMeta['journal_source_id'] = (int)$journalRow['Ardjournalentry']['source_id'];
        }
        $this->_storeTrashRecord(
            'ardaccounts_transactions',
            'Ardtransaction',
            $row['Ardtransaction'],
            isset($row['Ardtransaction']['ref_no']) ? (string)$row['Ardtransaction']['ref_no'] : '',
            $journalMeta
        );
        $ledgerId = (int)$row['Ardtransaction']['ledger_id'];
        $expenseLedgerId = (int)(isset($row['Ardtransaction']['expense_ledger_id']) ? $row['Ardtransaction']['expense_ledger_id'] : 0);
        $incomeLedgerId = (int)(isset($row['Ardtransaction']['income_ledger_id']) ? $row['Ardtransaction']['income_ledger_id'] : 0);
        $txType = strtolower(trim((string)(isset($row['Ardtransaction']['type']) ? $row['Ardtransaction']['type'] : '')));
        $transactionId = (int)$row['Ardtransaction']['id'];
        $this->Ardtransaction->delete($id);
        $this->_deleteJournalForTransaction($transactionId);
        $this->_resetDealRefundSchedulesForDeletedVoucher($transactionId);
        $this->_recalculateLedgerBalance($ledgerId);
        if($txType === 'expense' && $expenseLedgerId > 0 && $expenseLedgerId !== $ledgerId)
        {
            $this->_recalculateLedgerBalance($expenseLedgerId);
        }
        if($txType === 'income' && $incomeLedgerId > 0 && $incomeLedgerId !== $ledgerId)
        {
            $this->_recalculateLedgerBalance($incomeLedgerId);
        }
        $redirectAction = 'transactions';
        $referer = strtolower((string)$this->referer());
        if(strpos($referer, 'expensetransactions') !== false)
        {
            $redirectAction = 'expensetransactions';
        }
        elseif(strpos($referer, 'incometransactions') !== false)
        {
            $redirectAction = 'incometransactions';
        }
        $this->Session->setFlash(__('Voucher deleted. You can restore it from Trash.'), 'flash', array('alert' => 'success'));
        return $this->redirect(array('action' => $redirectAction, $projectId));
    }

    protected function _resetDealRefundSchedulesForDeletedVoucher($transactionId)
    {
        $transactionId = (int)$transactionId;
        if($transactionId <= 0)
        {
            return 0;
        }
        $this->loadModel('Admin.Dealrefundschedule');
        $rows = $this->Dealrefundschedule->find('all', array(
            'conditions' => array(
                'Dealrefundschedule.voucher_transaction_id' => $transactionId,
                'Dealrefundschedule.status' => 'Paid'
            ),
            'recursive' => -1
        ));
        $count = 0;
        foreach((array)$rows as $row)
        {
            $schedule = isset($row['Dealrefundschedule']) ? $row['Dealrefundschedule'] : array();
            if(empty($schedule['id']))
            {
                continue;
            }
            $remarks = trim((string)(isset($schedule['remarks']) ? $schedule['remarks'] : ''));
            $note = '['.date('Y-m-d H:i').'] '.__('Linked voucher #%s was deleted. Schedule reset to unpaid.', $transactionId);
            $remarks = ($remarks === '') ? $note : $remarks."\n".$note;
            $this->Dealrefundschedule->id = (int)$schedule['id'];
            if($this->Dealrefundschedule->save(array('Dealrefundschedule' => array(
                'id' => (int)$schedule['id'],
                'status' => 'Unpaid',
                'paid_date' => null,
                'paid_amount' => 0,
                'paid_ledger_id' => 0,
                'voucher_transaction_id' => 0,
                'remarks' => $remarks
            )), false, array('status','paid_date','paid_amount','paid_ledger_id','voucher_transaction_id','remarks')))
            {
                $count++;
            }
        }
        return $count;
    }

    public function trash($id = null)
    {
        $this->_ensureTrashTable();
        $this->loadModel('Admin.Ardtrash');
        $id = $this->_activeProjectId($id);
        $this->set('projectName', $this->_projectList());
        $this->set('agencyId', $this->agencyId);
        $this->set('currentProjectId', $id);

        if($this->request->is('post'))
        {
            $bulkAction = '';
            if(isset($this->request->data['Ardtrash']['bulk_action']))
            {
                $bulkAction = strtolower(trim((string)$this->request->data['Ardtrash']['bulk_action']));
            }
            elseif(isset($this->request->data['bulk_action']))
            {
                $bulkAction = strtolower(trim((string)$this->request->data['bulk_action']));
            }

            $selectedIds = array();
            if(isset($this->request->data['trash_ids']) && is_array($this->request->data['trash_ids']))
            {
                $selectedIds = $this->request->data['trash_ids'];
            }
            elseif(isset($this->request->data['Ardtrash']['trash_ids']) && is_array($this->request->data['Ardtrash']['trash_ids']))
            {
                $selectedIds = $this->request->data['Ardtrash']['trash_ids'];
            }
            elseif(isset($this->request->params['form']['trash_ids']) && is_array($this->request->params['form']['trash_ids']))
            {
                $selectedIds = $this->request->params['form']['trash_ids'];
            }
            elseif(isset($_POST['trash_ids']) && is_array($_POST['trash_ids']))
            {
                $selectedIds = $_POST['trash_ids'];
            }
            else
            {
                $selectedCsv = '';
                if(isset($this->request->data['selected_ids_csv']))
                {
                    $selectedCsv = (string)$this->request->data['selected_ids_csv'];
                }
                elseif(isset($this->request->data['Ardtrash']['selected_ids_csv']))
                {
                    $selectedCsv = (string)$this->request->data['Ardtrash']['selected_ids_csv'];
                }
                elseif(isset($this->request->params['form']['selected_ids_csv']))
                {
                    $selectedCsv = (string)$this->request->params['form']['selected_ids_csv'];
                }
                elseif(isset($_POST['selected_ids_csv']))
                {
                    $selectedCsv = (string)$_POST['selected_ids_csv'];
                }
                $selectedCsv = trim($selectedCsv);
                if($selectedCsv !== '')
                {
                    $selectedIds = explode(',', $selectedCsv);
                }
            }
            $selectedIds = array_values(array_unique(array_map('intval', $selectedIds)));
            $selectedIds = array_filter($selectedIds, function($trashId){ return $trashId > 0; });

            if(empty($selectedIds))
            {
                $this->Session->setFlash(__('Please select at least one trash item.'), 'flash', array('alert' => 'danger'));
                return $this->redirect(array('action' => 'trash', $id));
            }
            if(!in_array($bulkAction, array('restore', 'delete')))
            {
                $this->Session->setFlash(__('Please select valid bulk action.'), 'flash', array('alert' => 'danger'));
                return $this->redirect(array('action' => 'trash', $id));
            }

            $successCount = 0;
            $failedCount = 0;
            $firstError = '';
            foreach($selectedIds as $trashId)
            {
                $trashRow = $this->Ardtrash->find('first', array(
                    'conditions' => array('Ardtrash.id' => (int)$trashId),
                    'recursive' => -1
                ));
                $error = '';
                $ok = false;
                if(!empty($trashRow['Ardtrash']))
                {
                    if($bulkAction === 'restore')
                    {
                        $ok = $this->_restoreTrashRecord($trashRow, $error);
                    }
                    else
                    {
                        $ok = $this->_deleteTrashRecord($trashRow, $error);
                    }
                }
                else
                {
                    $error = __('Trash entry not found.');
                }

                if($ok)
                {
                    $successCount++;
                }
                else
                {
                    $failedCount++;
                    if($firstError === '' && $error !== '')
                    {
                        $firstError = $error;
                    }
                }
            }

            if($failedCount > 0)
            {
                $message = ($bulkAction === 'restore') ? __('Bulk restore completed.') : __('Bulk delete completed.');
                $message .= ' ' . __('Success: %d, Failed: %d.', $successCount, $failedCount);
                if($firstError !== '')
                {
                    $message .= ' ' . __('First error: %s', $firstError);
                }
                $this->Session->setFlash($message, 'flash', array('alert' => 'danger'));
            }
            else
            {
                if($bulkAction === 'restore')
                {
                    $this->Session->setFlash(__('Selected trash records restored successfully.'), 'flash', array('alert' => 'success'));
                }
                else
                {
                    $this->Session->setFlash(__('Selected trash records deleted permanently.'), 'flash', array('alert' => 'success'));
                }
            }
            return $this->redirect(array('action' => 'trash', $id));
        }

        $conditions = array();
        $scope = $this->_scopeCondition('Ardtrash.project_id', $id);
        if($this->userType === 'ADR')
        {
            if(!empty($scope))
            {
                $conditions[] = $scope;
            }
        }
        else
        {
            if(!empty($scope))
            {
                $conditions[] = array('OR' => array($scope, array('Ardtrash.project_id' => 0)));
            }
            $conditions['Ardtrash.deleted_by'] = (int)$this->luserId;
        }
        $this->Paginator->settings = array(
            'page' => 1,
            'order' => array('Ardtrash.id' => 'desc'),
            'limit' => $this->pageLimit,
            'maxLimit' => $this->maxLimit,
            'conditions' => $conditions
        );
        $rows = array();
        try
        {
            $rows = $this->Paginator->paginate('Ardtrash');
        }
        catch(Exception $e)
        {
            $message = (string)$e->getMessage();
            if(stripos($message, 'ardaccounts_trash_bin') !== false)
            {
                $this->_ensureTrashTable();
                try
                {
                    ClassRegistry::removeObject('Ardtrash');
                }
                catch(Exception $ignore)
                {
                    // Ignore cache clear issue and continue retry.
                }
                $this->loadModel('Admin.Ardtrash');
                try
                {
                    $rows = $this->Paginator->paginate('Ardtrash');
                }
                catch(Exception $e2)
                {
                    $rows = array();
                    $this->Session->setFlash(__('Trash table is not ready yet. Please refresh again.'), 'flash', array('alert' => 'danger'));
                }
            }
            else
            {
                $rows = array();
                $this->Session->setFlash(__('Unable to load trash right now.'), 'flash', array('alert' => 'danger'));
            }
        }
        if(!empty($rows))
        {
            $deletedByIds = array();
            $trashLedgerIds = array();
            foreach($rows as $k => $rowItem)
            {
                $display = $this->_trashDisplayTitleParts($rowItem);
                $rows[$k]['Ardtrash']['display_title'] = isset($display[0]) ? (string)$display[0] : '';
                $rows[$k]['Ardtrash']['display_meta'] = isset($display[1]) ? (string)$display[1] : '';
                $trashPayload = $this->_trashPayloadDecode(isset($rowItem['Ardtrash']['payload_json']) ? $rowItem['Ardtrash']['payload_json'] : '');
                $trashRecord = (isset($trashPayload['record']) && is_array($trashPayload['record'])) ? $trashPayload['record'] : array();
                foreach(array('ledger_id','expense_ledger_id','income_ledger_id') as $trashLedgerField)
                {
                    if(!empty($trashRecord[$trashLedgerField]))
                    {
                        $trashLedgerIds[] = (int)$trashRecord[$trashLedgerField];
                    }
                }
                if(!empty($rowItem['Ardtrash']['deleted_by']))
                {
                    $deletedByIds[] = (int)$rowItem['Ardtrash']['deleted_by'];
                }
            }
            $deletedByNames = array();
            $deletedByRoles = array();
            $deletedByIds = array_values(array_unique(array_filter($deletedByIds)));
            if(!empty($deletedByIds))
            {
                try
                {
                    $this->loadModel('User');
                    $userRows = $this->User->find('all', array(
                        'fields' => array('User.id', 'User.name', 'User.username', 'Ugroup.name', 'Ugroup.type'),
                        'conditions' => array('User.id' => $deletedByIds),
                        'recursive' => 0
                    ));
                    foreach((array)$userRows as $userRow)
                    {
                        if(empty($userRow['User']['id']))
                        {
                            continue;
                        }
                        $name = !empty($userRow['User']['name']) ? $userRow['User']['name'] : (isset($userRow['User']['username']) ? $userRow['User']['username'] : '');
                        $deletedByNames[(int)$userRow['User']['id']] = trim((string)$name);
                        $role = '';
                        if(!empty($userRow['Ugroup']['name']))
                        {
                            $role = trim((string)$userRow['Ugroup']['name']);
                        }
                        elseif(!empty($userRow['Ugroup']['type']))
                        {
                            $role = trim((string)$userRow['Ugroup']['type']);
                        }
                        $deletedByRoles[(int)$userRow['User']['id']] = $role;
                    }
                }
                catch(Exception $e)
                {
                    $deletedByNames = array();
                    $deletedByRoles = array();
                }
            }
            $trashLedgerNames = array();
            $trashLedgerIds = array_values(array_unique(array_filter($trashLedgerIds)));
            if(!empty($trashLedgerIds))
            {
                try
                {
                    $this->loadModel('Admin.Ardledger');
                    $trashLedgerNames = $this->Ardledger->find('list', array(
                        'fields' => array('Ardledger.id', 'Ardledger.name'),
                        'conditions' => array('Ardledger.id' => $trashLedgerIds),
                        'recursive' => -1
                    ));
                }
                catch(Exception $e)
                {
                    $trashLedgerNames = array();
                }
            }
            foreach($rows as $k => $rowItem)
            {
                $deletedById = !empty($rowItem['Ardtrash']['deleted_by']) ? (int)$rowItem['Ardtrash']['deleted_by'] : 0;
                $deletedByName = ($deletedById > 0 && isset($deletedByNames[$deletedById]) && $deletedByNames[$deletedById] !== '') ? $deletedByNames[$deletedById] : ($deletedById > 0 ? '#'.$deletedById : '-');
                $deletedByRole = ($deletedById > 0 && isset($deletedByRoles[$deletedById])) ? $deletedByRoles[$deletedById] : '';
                $rows[$k]['Ardtrash']['deleted_by_name'] = $deletedByName;
                $rows[$k]['Ardtrash']['deleted_by_role'] = $deletedByRole;
                $rows[$k]['Ardtrash']['display_details'] = $this->_trashDisplayDetails($rowItem, $trashLedgerNames);
            }
        }
        $this->set('rows', $rows);
    }

    public function viewtrash($trashId = null, $projectId = null)
    {
        $this->_ensureTrashTable();
        $this->loadModel('Admin.Ardtrash');
        $trashId = (int)$trashId;
        $projectId = $this->_activeProjectId($projectId);
        $this->set('currentProjectId', $projectId);
        $this->set('isError', false);
        $this->set('errorMessage', '');

        if($trashId <= 0)
        {
            $this->set('isError', true);
            $this->set('errorMessage', __('Invalid trash record.'));
            return;
        }

        $trashRow = $this->Ardtrash->find('first', array(
            'conditions' => array('Ardtrash.id' => $trashId),
            'recursive' => -1
        ));
        if(empty($trashRow['Ardtrash']))
        {
            $this->set('isError', true);
            $this->set('errorMessage', __('Trash record not found.'));
            return;
        }
        if(!$this->_canAccessTrashEntry($trashRow['Ardtrash']))
        {
            $this->set('isError', true);
            $this->set('errorMessage', __('Permission denied for trash record.'));
            return;
        }

        $display = $this->_trashDisplayTitleParts($trashRow);
        $payload = $this->_trashPayloadDecode(isset($trashRow['Ardtrash']['payload_json']) ? $trashRow['Ardtrash']['payload_json'] : '');
        $recordData = (isset($payload['record']) && is_array($payload['record'])) ? $payload['record'] : array();
        $extraData = (isset($payload['extra']) && is_array($payload['extra'])) ? $payload['extra'] : array();
        $deletedByName = '-';
        $deletedById = isset($trashRow['Ardtrash']['deleted_by']) ? (int)$trashRow['Ardtrash']['deleted_by'] : 0;
        if($deletedById > 0)
        {
            try
            {
                $this->loadModel('User');
                $deletedBy = $this->User->find('first', array(
                    'fields' => array('User.name', 'User.username'),
                    'conditions' => array('User.id' => $deletedById),
                    'recursive' => -1
                ));
                if(!empty($deletedBy['User']['name']))
                {
                    $deletedByName = $deletedBy['User']['name'];
                }
                elseif(!empty($deletedBy['User']['username']))
                {
                    $deletedByName = $deletedBy['User']['username'];
                }
            }
            catch(Exception $e)
            {
                $deletedByName = '#'.$deletedById;
            }
        }

        $this->set('trashRow', $trashRow);
        $this->set('trash', $trashRow['Ardtrash']);
        $this->set('recordData', $recordData);
        $this->set('extraData', $extraData);
        $this->set('displayTitle', isset($display[0]) ? (string)$display[0] : '');
        $this->set('displayMeta', isset($display[1]) ? (string)$display[1] : '');
        $this->set('deletedByName', $deletedByName);
    }

    public function restoretrash($trashId = null, $projectId = null)
    {
        $this->_ensureTrashTable();
        $this->loadModel('Admin.Ardtrash');
        $trashId = (int)$trashId;
        $projectId = $this->_activeProjectId($projectId);
        if($trashId <= 0)
        {
            $this->Session->setFlash(__('Invalid trash record.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'trash', $projectId));
        }
        $trashRow = $this->Ardtrash->find('first', array(
            'conditions' => array('Ardtrash.id' => $trashId),
            'recursive' => -1
        ));
        $error = '';
        if(empty($trashRow['Ardtrash']) || !$this->_restoreTrashRecord($trashRow, $error))
        {
            if($error === '')
            {
                $error = __('Unable to restore trash record.');
            }
            $this->Session->setFlash($error, 'flash', array('alert' => 'danger'));
        }
        else
        {
            $this->Session->setFlash(__('Trash record restored successfully.'), 'flash', array('alert' => 'success'));
        }
        return $this->redirect(array('action' => 'trash', $projectId));
    }

