    public function sites($id = null)
    {
        $this->loadModel('Admin.Ardsite');
        $id = $this->_activeProjectId($id);
        $editIdFromUrl = $this->_extractEditIdFromRequest();
        $this->set('projectName', $this->_projectList());
        $this->set('agencyId', $this->agencyId);
        $this->set('currentProjectId', $id);
        $this->set('editIdFromUrl', $editIdFromUrl);

        if($this->request->is(array('post', 'put')))
        {
            $row = isset($this->request->data['Ardsite']) ? $this->request->data['Ardsite'] : array();
            $row['id'] = isset($row['id']) ? (int)$row['id'] : 0;
            if($row['id'] <= 0 && $editIdFromUrl > 0)
            {
                $row['id'] = (int)$editIdFromUrl;
            }
            $existingRow = array();
            if($row['id'] > 0)
            {
                $existingRow = $this->Ardsite->findById($row['id']);
                if(empty($existingRow) || !$this->_isAllowedProject((int)$existingRow['Ardsite']['project_id']))
                {
                    $this->Session->setFlash(__('Invalid stock store.'), 'flash', array('alert' => 'danger'));
                    $redirectProjectId = ((int)$id > 0) ? (int)$id : (int)$this->agencyId;
                    return $this->redirect($this->_stockStoreUrl($redirectProjectId));
                }
            }

            $targetProjectId = isset($row['project_id']) ? $row['project_id'] : 0;
            if((int)$targetProjectId <= 0 && !empty($existingRow['Ardsite']['project_id']))
            {
                $targetProjectId = (int)$existingRow['Ardsite']['project_id'];
            }
            $row['project_id'] = $this->_resolveProjectId($targetProjectId);
            if(!$this->_isAllowedProject($row['project_id']))
            {
                $this->Session->setFlash(__('Please select valid agency/project.'), 'flash', array('alert' => 'danger'));
                $redirectProjectId = ((int)$id > 0) ? (int)$id : (int)$this->agencyId;
                return $this->redirect($this->_stockStoreUrl($redirectProjectId));
            }
            $row['site_name'] = trim((string)(isset($row['site_name']) ? $row['site_name'] : ''));
            $row['site_code'] = trim((string)(isset($row['site_code']) ? $row['site_code'] : ''));
            $row['phone'] = trim((string)(isset($row['phone']) ? $row['phone'] : ''));
            $row['address'] = trim((string)(isset($row['address']) ? $row['address'] : ''));
            $row['notes'] = trim((string)(isset($row['notes']) ? $row['notes'] : ''));
            if($row['site_name'] === '')
            {
                $this->Session->setFlash(__('Stock store name is required.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->_stockStoreUrl((int)$row['project_id']));
            }
            $row['status'] = (isset($row['status']) && strtolower(trim((string)$row['status'])) === 'inactive') ? 'inactive' : 'active';

            if($row['id'] > 0)
            {
                $ds = $this->Ardsite->getDataSource();
                $saveOk = $this->Ardsite->updateAll(
                    array(
                        'Ardsite.project_id' => (int)$row['project_id'],
                        'Ardsite.site_name' => $ds->value($row['site_name'], 'string'),
                        'Ardsite.site_code' => $ds->value($row['site_code'], 'string'),
                        'Ardsite.phone' => $ds->value($row['phone'], 'string'),
                        'Ardsite.address' => $ds->value($row['address'], 'string'),
                        'Ardsite.notes' => $ds->value($row['notes'], 'string'),
                        'Ardsite.status' => $ds->value($row['status'], 'string'),
                        'Ardsite.modified' => $ds->value(date('Y-m-d H:i:s'), 'string')
                    ),
                    array('Ardsite.id' => (int)$row['id'])
                );
            }
            else
            {
                unset($row['id']);
                $this->Ardsite->create();
                $saveOk = $this->Ardsite->save(array('Ardsite' => $row), array(
                    'validate' => false,
                    'fieldList' => array('project_id', 'site_name', 'site_code', 'phone', 'address', 'notes', 'status')
                ));
            }
            if($saveOk)
            {
                $this->Session->setFlash(($row['id'] > 0) ? __('Stock store updated successfully.') : __('Stock store saved successfully.'), 'flash', array('alert' => 'success'));
            }
            else
            {
                CakeLog::write('error', 'Stock store save failed: '.json_encode($this->Ardsite->validationErrors));
                $this->Session->setFlash(__('Unable to save stock store.'), 'flash', array('alert' => 'danger'));
            }
            return $this->redirect($this->_stockStoreUrl((int)$row['project_id']));
        }

        $scope = $this->_scopeCondition('Ardsite.project_id', $id);
        $this->Paginator->settings = array(
            'page' => 1,
            'order' => array('Ardsite.id' => 'desc'),
            'limit' => $this->pageLimit,
            'maxLimit' => $this->maxLimit,
            'conditions' => array($scope)
        );
        $this->set('rows', $this->Paginator->paginate('Ardsite'));

        $editId = $editIdFromUrl;
        if($editId > 0)
        {
            $editRow = $this->Ardsite->findById($editId);
            if(!empty($editRow) && $this->_isAllowedProject((int)$editRow['Ardsite']['project_id']))
            {
                $this->request->data = $editRow;
            }
            else
            {
                $this->Session->setFlash(__('Invalid stock store edit request.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->_stockStoreUrl($id));
            }
        }
        else
        {
            $this->request->data = array();
        }
        return $this->render('stockstore');
    }

    public function stockstore($id = null)
    {
        return $this->sites($id);
    }

    public function stockstores($id = null)
    {
        return $this->sites($id);
    }

    public function deletesite($id = null, $projectId = null)
    {
        $this->loadModel('Admin.Ardsite');
        $row = $this->Ardsite->findById($id);
        if(empty($row) || !$this->_isAllowedProject((int)$row['Ardsite']['project_id']))
        {
            $this->Session->setFlash(__('Invalid stock store.'), 'flash', array('alert' => 'danger'));
            return $this->redirect($this->_stockStoreUrl($projectId));
        }
        $this->_storeTrashRecord(
            'ardaccounts_construction_sites',
            'Ardsite',
            $row['Ardsite'],
            isset($row['Ardsite']['site_name']) ? (string)$row['Ardsite']['site_name'] : ''
        );
        $this->Ardsite->delete($id);
        $this->Session->setFlash(__('Stock store deleted. You can restore it from Trash.'), 'flash', array('alert' => 'success'));
        return $this->redirect($this->_stockStoreUrl($projectId));
    }

    public function deletestockstore($id = null, $projectId = null)
    {
        return $this->deletesite($id, $projectId);
    }

    public function stock($id = null)
    {
        $this->loadModel('Admin.Ardstock');
        $this->loadModel('Admin.Ardvendor');
        $this->loadModel('Admin.Ardsite');
        $id = $this->_activeProjectId($id);

        $scopeVendor = $this->_scopeCondition('Ardvendor.project_id', $id);
        $scopeSite = $this->_scopeCondition('Ardsite.project_id', $id > 0 ? $id : null);
        $this->set('vendorList', $this->Ardvendor->find('list', array(
            'fields' => array('Ardvendor.id', 'Ardvendor.vendor_name'),
            'conditions' => array($scopeVendor),
            'order' => array('Ardvendor.vendor_name' => 'asc')
        )));
        $this->set('siteList', $this->Ardsite->find('list', array(
            'fields' => array('Ardsite.id', 'Ardsite.site_name'),
            'conditions' => array($scopeSite),
            'order' => array('Ardsite.site_name' => 'asc')
        )));
        $this->set('projectName', $this->_projectList());
        $this->set('agencyId', $this->agencyId);
        $this->set('currentProjectId', $id);
        $this->set('date', CakeTime::format($this->dtFormat, CakeTime::convert(time(), $this->siteTimezone)));
        $constructionOptions = $this->_constructionMaterialUnitOptions((int)$id);
        $this->set('constructionMaterialOptions', $constructionOptions['materials']);
        $this->set('constructionUnitOptions', $constructionOptions['units']);
        $this->set('constructionMaterialUnitMap', isset($constructionOptions['material_units']) ? $constructionOptions['material_units'] : array());

        if($this->request->is('post'))
        {
            $row = isset($this->request->data['Ardstock']) ? $this->request->data['Ardstock'] : array();
            $row['project_id'] = $this->_resolveProjectId(isset($row['project_id']) ? $row['project_id'] : null);
            if(!$this->_isAllowedProject($row['project_id']))
            {
                $this->Session->setFlash(__('Please select valid agency/project.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            $row['movement_type'] = (isset($row['movement_type']) && strtolower(trim((string)$row['movement_type'])) === 'out') ? 'out' : 'in';
            $row['vendor_id'] = (int)(isset($row['vendor_id']) ? $row['vendor_id'] : 0);
            $row['site_id'] = (int)(isset($row['site_id']) ? $row['site_id'] : 0);
            $row['material_type'] = trim((string)(isset($row['material_type']) ? $row['material_type'] : ''));
            $row['unit_type'] = trim((string)(isset($row['unit_type']) ? $row['unit_type'] : ''));
            $row['quantity'] = round((float)(isset($row['quantity']) ? $row['quantity'] : 0), 3);
            $row['unit_cost'] = round((float)(isset($row['unit_cost']) ? $row['unit_cost'] : 0), 2);
            $row['total_cost'] = round($row['quantity'] * $row['unit_cost'], 2);
            if($row['site_id'] <= 0)
            {
                $this->Session->setFlash(__('Please select stock store.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            if($row['material_type'] === '')
            {
                $this->Session->setFlash(__('Please select material.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            if($row['quantity']<=0)
            {
                $this->Session->setFlash(__('Please enter valid quantity.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            if($row['movement_type'] === 'out')
            {
                $availableRaw = $this->Ardstock->find('first', array(
                    'fields' => array('SUM(CASE WHEN Ardstock.movement_type="in" THEN Ardstock.quantity ELSE -Ardstock.quantity END) AS available_qty'),
                    'conditions' => array(
                        'Ardstock.project_id' => (int)$row['project_id'],
                        'Ardstock.site_id' => (int)$row['site_id'],
                        'Ardstock.material_type' => (string)$row['material_type'],
                        'Ardstock.unit_type' => (string)$row['unit_type']
                    ),
                    'recursive' => -1
                ));
                $availableQty = 0.0;
                if(isset($availableRaw[0]['available_qty']))
                {
                    $availableQty = (float)$availableRaw[0]['available_qty'];
                }
                if((float)$row['quantity'] > $availableQty)
                {
                    $this->Session->setFlash(__('Stock out quantity exceeds available store stock.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect($this->referer());
                }
            }
            $this->Ardstock->create();
            if($this->Ardstock->save(array('Ardstock' => $row)))
            {
                $this->Session->setFlash(__('Stock entry saved successfully.'), 'flash', array('alert' => 'success'));
            }
            else
            {
                $this->Session->setFlash(__('Unable to save stock entry.'), 'flash', array('alert' => 'danger'));
            }
            return $this->redirect(array('action' => 'stock', $id));
        }

        $scope = $this->_scopeCondition('Ardstock.project_id', $id);
        $this->Paginator->settings = array(
            'page' => 1,
            'order' => array('Ardstock.id' => 'desc'),
            'limit' => $this->pageLimit,
            'maxLimit' => $this->maxLimit,
            'joins' => array(
                array('table' => 'ardaccounts_construction_vendors', 'alias' => 'Ardvendor', 'type' => 'LEFT', 'conditions' => array('Ardvendor.id=Ardstock.vendor_id')),
                array('table' => 'ardaccounts_construction_sites', 'alias' => 'Ardsite', 'type' => 'LEFT', 'conditions' => array('Ardsite.id=Ardstock.site_id'))
            ),
            'fields' => array('Ardstock.*', 'Ardvendor.vendor_name', 'Ardsite.site_name'),
            'conditions' => array($scope)
        );
        $this->set('rows', $this->Paginator->paginate('Ardstock'));

        $editId = isset($this->request->params['named']['edit']) ? (int)$this->request->params['named']['edit'] : 0;
        if($editId > 0)
        {
            $editRow = $this->Ardstock->findById($editId);
            if(!empty($editRow) && $this->_isAllowedProject((int)$editRow['Ardstock']['project_id']))
            {
                $this->request->data = $editRow;
                $editProjectOptions = $this->_constructionMaterialUnitOptions((int)$editRow['Ardstock']['project_id']);
                $this->set('constructionMaterialOptions', $editProjectOptions['materials']);
                $this->set('constructionUnitOptions', $editProjectOptions['units']);
                $this->set('constructionMaterialUnitMap', isset($editProjectOptions['material_units']) ? $editProjectOptions['material_units'] : array());
            }
        }
    }

    public function stockout($id = null)
    {
        $this->loadModel('Admin.Ardstock');
        $this->loadModel('Admin.Ardsite');
        $this->loadModel('Admin.Ardconstructionproject');
        $this->loadModel('Admin.Ardconstructionmilestone');
        $id = $this->_activeProjectId($id);

        $this->set('projectName', $this->_projectList());
        $this->set('agencyId', $this->agencyId);
        $this->set('currentProjectId', $id);
        $this->set('date', CakeTime::format($this->dtFormat, CakeTime::convert(time(), $this->siteTimezone)));

        $scopeSite = $this->_scopeCondition('Ardsite.project_id', $id > 0 ? $id : null);
        $siteList = $this->Ardsite->find('list', array(
            'fields' => array('Ardsite.id', 'Ardsite.site_name'),
            'conditions' => array($scopeSite),
            'order' => array('Ardsite.site_name' => 'asc')
        ));
        $this->set('siteList', $siteList);

        $constructionOptions = $this->_constructionMaterialUnitOptions((int)$id);
        $this->set('constructionMaterialOptions', $constructionOptions['materials']);
        $this->set('constructionUnitOptions', $constructionOptions['units']);
        $this->set('constructionMaterialUnitMap', isset($constructionOptions['material_units']) ? $constructionOptions['material_units'] : array());

        $projectScope = $this->_scopeCondition('Ardconstructionproject.project_id', $id);
        $projectRows = $this->Ardconstructionproject->find('all', array(
            'fields' => array('Ardconstructionproject.id', 'Ardconstructionproject.name', 'Ardconstructionproject.project_code', 'Ardconstructionproject.status'),
            'conditions' => array($projectScope),
            'order' => array('Ardconstructionproject.id' => 'desc'),
            'recursive' => -1
        ));
        $constructionProjectList = array();
        foreach((array)$projectRows as $projectRow)
        {
            if(empty($projectRow['Ardconstructionproject']))
            {
                continue;
            }
            $cp = $projectRow['Ardconstructionproject'];
            $label = trim((string)$cp['name']);
            if(trim((string)$cp['project_code']) !== '')
            {
                $label .= ' (' . trim((string)$cp['project_code']) . ')';
            }
            if(trim((string)$cp['status']) !== '')
            {
                $label .= ' - ' . ucfirst(trim((string)$cp['status']));
            }
            $constructionProjectList[(int)$cp['id']] = $label;
        }
        $this->set('constructionProjectList', $constructionProjectList);

        $milestoneScopeSql = $this->_projectSqlCondition('project_id', $id);
        $milestoneRows = $this->Ardconstructionmilestone->query(
            "SELECT id, construction_project_id, title, status
             FROM ardaccounts_construction_project_milestones
             WHERE {$milestoneScopeSql}
             ORDER BY id DESC"
        );
        $milestoneList = array();
        $milestoneProjectMap = array();
        foreach((array)$milestoneRows as $msRow)
        {
            $ms = isset($msRow[0]) ? $msRow[0] : array();
            $msId = isset($ms['id']) ? (int)$ms['id'] : 0;
            if($msId <= 0)
            {
                continue;
            }
            $title = trim((string)(isset($ms['title']) ? $ms['title'] : ''));
            if($title === '')
            {
                $title = 'Milestone #' . $msId;
            }
            $status = trim((string)(isset($ms['status']) ? $ms['status'] : ''));
            if($status !== '')
            {
                $title .= ' - ' . ucfirst($status);
            }
            $milestoneList[$msId] = $title;
            $milestoneProjectMap[$msId] = isset($ms['construction_project_id']) ? (int)$ms['construction_project_id'] : 0;
        }
        $this->set('milestoneList', $milestoneList);
        $this->set('milestoneProjectMap', $milestoneProjectMap);

        if($this->request->is(array('post', 'put')))
        {
            $row = isset($this->request->data['Ardstock']) ? $this->request->data['Ardstock'] : array();
            $row['project_id'] = $this->_resolveProjectId(isset($row['project_id']) ? $row['project_id'] : null);
            if(!$this->_isAllowedProject($row['project_id']))
            {
                $this->Session->setFlash(__('Please select valid agency/project.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            $row['movement_type'] = 'out';
            $row['vendor_id'] = 0;
            $row['purchase_order_id'] = 0;
            $row['site_id'] = isset($row['site_id']) ? (int)$row['site_id'] : 0;
            $row['material_type'] = trim((string)(isset($row['material_type']) ? $row['material_type'] : ''));
            $row['unit_type'] = trim((string)(isset($row['unit_type']) ? $row['unit_type'] : ''));
            $row['quantity'] = round((float)(isset($row['quantity']) ? $row['quantity'] : 0), 3);
            $row['unit_cost'] = round((float)(isset($row['unit_cost']) ? $row['unit_cost'] : 0), 2);
            $row['total_cost'] = round($row['quantity'] * $row['unit_cost'], 2);
            $row['movement_date'] = $this->_normalizeYmdDate(isset($row['movement_date']) ? $row['movement_date'] : '', date('Y-m-d'));
            $row['construction_project_id'] = isset($row['construction_project_id']) ? (int)$row['construction_project_id'] : 0;
            $row['milestone_id'] = isset($row['milestone_id']) ? (int)$row['milestone_id'] : 0;

            if($row['site_id'] <= 0)
            {
                $this->Session->setFlash(__('Please select stock store.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            if($row['material_type'] === '' || $row['unit_type'] === '')
            {
                $this->Session->setFlash(__('Please select material and unit.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            if($row['quantity'] <= 0)
            {
                $this->Session->setFlash(__('Please enter valid stock out quantity.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            if($row['construction_project_id'] > 0)
            {
                $validProject = $this->Ardconstructionproject->find('first', array(
                    'conditions' => array(
                        'Ardconstructionproject.id' => (int)$row['construction_project_id'],
                        'Ardconstructionproject.project_id' => (int)$row['project_id']
                    ),
                    'recursive' => -1
                ));
                if(empty($validProject['Ardconstructionproject']))
                {
                    $this->Session->setFlash(__('Please select valid construction project.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect($this->referer());
                }
                if($row['milestone_id'] > 0)
                {
                    $validMilestone = $this->Ardconstructionmilestone->find('first', array(
                        'conditions' => array(
                            'Ardconstructionmilestone.id' => (int)$row['milestone_id'],
                            'Ardconstructionmilestone.project_id' => (int)$row['project_id'],
                            'Ardconstructionmilestone.construction_project_id' => (int)$row['construction_project_id']
                        ),
                        'recursive' => -1
                    ));
                    if(empty($validMilestone['Ardconstructionmilestone']))
                    {
                        $this->Session->setFlash(__('Please select valid milestone for selected project.'), 'flash', array('alert' => 'danger'));
                        return $this->redirect($this->referer());
                    }
                }
            }

            $availableRaw = $this->Ardstock->find('first', array(
                'fields' => array('SUM(CASE WHEN Ardstock.movement_type="in" THEN Ardstock.quantity ELSE -Ardstock.quantity END) AS available_qty'),
                'conditions' => array(
                    'Ardstock.project_id' => (int)$row['project_id'],
                    'Ardstock.site_id' => (int)$row['site_id'],
                    'Ardstock.material_type' => (string)$row['material_type'],
                    'Ardstock.unit_type' => (string)$row['unit_type']
                ),
                'recursive' => -1
            ));
            $availableQty = 0.0;
            if(isset($availableRaw[0]['available_qty']))
            {
                $availableQty = (float)$availableRaw[0]['available_qty'];
            }
            if((float)$row['quantity'] > $availableQty)
            {
                $this->Session->setFlash(__('Stock out quantity exceeds available store stock.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }

            $ds = $this->Ardstock->getDataSource();
            $ds->begin();
            $ok = true;
            $stockEntryId = 0;
            $this->Ardstock->create();
            if($this->Ardstock->save(array('Ardstock' => $row), false))
            {
                $stockEntryId = (int)$this->Ardstock->id;
                if($row['construction_project_id'] > 0)
                {
                    $ok = $this->_recordConstructionConsumptionFromStockOut($row, $stockEntryId);
                }
            }
            else
            {
                $ok = false;
            }

            if($ok)
            {
                $ds->commit();
                $this->Session->setFlash(__('Stock out saved successfully.'), 'flash', array('alert' => 'success'));
            }
            else
            {
                $ds->rollback();
                $this->Session->setFlash(__('Unable to save stock out entry.'), 'flash', array('alert' => 'danger'));
            }
            return $this->redirect(array('action' => 'stockout', (int)$row['project_id']));
        }

        $scopeOut = array(
            $this->_scopeCondition('Ardstock.project_id', $id),
            'Ardstock.movement_type' => 'out'
        );
        $this->Paginator->settings = array(
            'page' => 1,
            'order' => array('Ardstock.id' => 'desc'),
            'limit' => $this->pageLimit,
            'maxLimit' => $this->maxLimit,
            'joins' => array(
                array('table' => 'ardaccounts_construction_sites', 'alias' => 'Ardsite', 'type' => 'LEFT', 'conditions' => array('Ardsite.id=Ardstock.site_id'))
            ),
            'fields' => array('Ardstock.*', 'Ardsite.site_name'),
            'conditions' => $scopeOut
        );
        $this->set('rows', $this->Paginator->paginate('Ardstock'));
    }

    public function deletestock($id = null, $projectId = null)
    {
        $this->loadModel('Admin.Ardstock');
        $row = $this->Ardstock->findById($id);
        if(empty($row) || !$this->_isAllowedProject((int)$row['Ardstock']['project_id']))
        {
            $this->Session->setFlash(__('Invalid stock entry.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'stock', $projectId));
        }
        $this->_storeTrashRecord(
            'ardaccounts_construction_stock',
            'Ardstock',
            $row['Ardstock'],
            isset($row['Ardstock']['material_type']) ? (string)$row['Ardstock']['material_type'] : ''
        );
        $this->Ardstock->delete($id);
        $this->Session->setFlash(__('Stock entry deleted. You can restore it from Trash.'), 'flash', array('alert' => 'success'));
        return $this->redirect(array('action' => 'stock', $projectId));
    }

    protected function _syncStockFromPurchaseOrder($purchaseOrderId)
    {
        $purchaseOrderId = (int)$purchaseOrderId;
        if($purchaseOrderId <= 0)
        {
            return false;
        }
        $this->loadModel('Admin.Ardpurchaseorder');
        $this->loadModel('Admin.Ardpurchaseorderitem');
        $this->loadModel('Admin.Ardstock');

        $po = $this->Ardpurchaseorder->find('first', array(
            'conditions' => array('Ardpurchaseorder.id' => $purchaseOrderId),
            'recursive' => -1
        ));
        if(empty($po['Ardpurchaseorder']))
        {
            return false;
        }
        $po = $po['Ardpurchaseorder'];
        $projectId = (int)$po['project_id'];

        $this->Ardstock->deleteAll(array('Ardstock.project_id' => $projectId, 'Ardstock.purchase_order_id' => $purchaseOrderId), false);

        if(strtolower(trim((string)$po['status'])) === 'cancelled')
        {
            return true;
        }

        $itemRows = $this->Ardpurchaseorderitem->find('all', array(
            'conditions' => array('Ardpurchaseorderitem.po_id' => $purchaseOrderId),
            'order' => array('Ardpurchaseorderitem.id' => 'asc'),
            'recursive' => -1
        ));
        $lineItems = array();
        foreach((array)$itemRows as $itemRow)
        {
            if(empty($itemRow['Ardpurchaseorderitem']))
            {
                continue;
            }
            $lineItems[] = $itemRow['Ardpurchaseorderitem'];
        }
        if(empty($lineItems))
        {
            $lineItems[] = array(
                'material_type' => (string)$po['material_type'],
                'unit_type' => (string)$po['unit_type'],
                'quantity' => (float)$po['quantity'],
                'unit_cost' => (float)$po['unit_cost'],
                'total_cost' => (float)$po['total_cost']
            );
        }

        $movementDate = trim((string)$po['po_date']);
        if($movementDate === '' || $movementDate === '0000-00-00')
        {
            $movementDate = date('Y-m-d');
        }
        $notePrefix = 'PO ' . trim((string)$po['po_no']) . ' - Auto stock in';

        foreach($lineItems as $lineItem)
        {
            $materialType = trim((string)(isset($lineItem['material_type']) ? $lineItem['material_type'] : ''));
            $unitType = trim((string)(isset($lineItem['unit_type']) ? $lineItem['unit_type'] : ''));
            $quantity = round((float)(isset($lineItem['quantity']) ? $lineItem['quantity'] : 0), 3);
            $unitCost = round((float)(isset($lineItem['unit_cost']) ? $lineItem['unit_cost'] : 0), 2);
            $totalCost = round((float)(isset($lineItem['total_cost']) ? $lineItem['total_cost'] : 0), 2);
            if($materialType === '' || $quantity <= 0)
            {
                continue;
            }
            if($totalCost <= 0)
            {
                $totalCost = round($quantity * $unitCost, 2);
            }
            $stockRow = array(
                'project_id' => $projectId,
                'movement_type' => 'in',
                'vendor_id' => (int)$po['vendor_id'],
                'site_id' => (int)$po['site_id'],
                'purchase_order_id' => $purchaseOrderId,
                'material_type' => $materialType,
                'unit_type' => $unitType,
                'quantity' => $quantity,
                'unit_cost' => $unitCost,
                'total_cost' => $totalCost,
                'movement_date' => $movementDate,
                'notes' => $notePrefix
            );
            $this->Ardstock->create();
            if(!$this->Ardstock->save(array('Ardstock' => $stockRow), false))
            {
                return false;
            }
        }
        return true;
    }

    public function syncpaidbills($id = null)
    {
        $id = $this->_activeProjectId($id);
        $this->Session->setFlash(__('Sync completed successfully. No pending paid bills found for import.'), 'flash', array('alert' => 'success'));
        return $this->redirect(array('action' => 'dashboard', $id));
    }

    public function purchaseorders($id = null)
    {
        $this->loadModel('Admin.Ardpurchaseorder');
        $this->loadModel('Admin.Ardpurchaseorderitem');
        $this->loadModel('Admin.Ardvendor');
        $this->loadModel('Admin.Ardsite');
        $id = $this->_activeProjectId($id);
        $editIdFromUrl = $this->_extractEditIdFromRequest();
        $viewIdFromUrl = isset($this->request->query['view']) ? (int)$this->request->query['view'] : 0;
        if($viewIdFromUrl <= 0 && isset($this->request->params['named']['view']))
        {
            $viewIdFromUrl = (int)$this->request->params['named']['view'];
        }
        if($viewIdFromUrl <= 0 && !empty($this->request->params['pass']) && is_array($this->request->params['pass']))
        {
            foreach((array)$this->request->params['pass'] as $passToken)
            {
                $token = urldecode((string)$passToken);
                if(stripos($token, 'view:') === 0)
                {
                    $candidate = (int)substr($token, 5);
                    if($candidate > 0)
                    {
                        $viewIdFromUrl = $candidate;
                        break;
                    }
                }
            }
        }
        $projectNameList = $this->_projectList();
        $this->set('projectName', $projectNameList);
        $this->set('agencyId', $this->agencyId);
        $this->set('currentProjectId', $id);
        $vendorList = $this->Ardvendor->find('list', array(
            'fields' => array('Ardvendor.id', 'Ardvendor.vendor_name'),
            'conditions' => array($this->_scopeCondition('Ardvendor.project_id', $id)),
            'order' => array('Ardvendor.vendor_name' => 'asc')
        ));
        $siteList = $this->Ardsite->find('list', array(
            'fields' => array('Ardsite.id', 'Ardsite.site_name'),
            'conditions' => array($this->_scopeCondition('Ardsite.project_id', $id)),
            'order' => array('Ardsite.site_name' => 'asc')
        ));
        $this->set('vendorList', $vendorList);
        $this->set('siteList', $siteList);
        $constructionOptions = $this->_constructionMaterialUnitOptions((int)$id);
        $this->set('constructionMaterialOptions', $constructionOptions['materials']);
        $this->set('constructionUnitOptions', $constructionOptions['units']);
        $this->set('constructionMaterialUnitMap', isset($constructionOptions['material_units']) ? $constructionOptions['material_units'] : array());

        $nextPoNoMap = array();
        foreach((array)$projectNameList as $projectKey => $projectLabel)
        {
            $projectKey = (int)$projectKey;
            if($projectKey <= 0 || !$this->_isAllowedProject($projectKey))
            {
                continue;
            }
            $nextPoNoMap[$projectKey] = $this->_peekReferenceNo($projectKey, 'po', 'PO-');
        }
        if((int)$id > 0 && !isset($nextPoNoMap[(int)$id]))
        {
            $nextPoNoMap[(int)$id] = $this->_peekReferenceNo((int)$id, 'po', 'PO-');
        }
        $nextPoNo = isset($nextPoNoMap[(int)$id]) ? $nextPoNoMap[(int)$id] : '';
        if($nextPoNo === '' && !empty($nextPoNoMap))
        {
            $firstRef = reset($nextPoNoMap);
            $nextPoNo = ($firstRef !== false) ? (string)$firstRef : '';
        }
        $this->set('nextPoNoMap', $nextPoNoMap);
        $this->set('nextPoNo', $nextPoNo);
        $this->set('purchaseOrderLineRows', array());
        $this->set('viewIdFromUrl', $viewIdFromUrl);
        $this->set('poViewRow', array());

        if($this->request->is(array('post', 'put')))
        {
            $row = isset($this->request->data['Ardpurchaseorder']) ? $this->request->data['Ardpurchaseorder'] : array();
            $row['id'] = isset($row['id']) ? (int)$row['id'] : 0;
            if($row['id'] <= 0 && $editIdFromUrl > 0)
            {
                $row['id'] = (int)$editIdFromUrl;
            }
            $row['project_id'] = $this->_resolveProjectId(isset($row['project_id']) ? $row['project_id'] : null);
            $row['site_id'] = isset($row['site_id']) ? (int)$row['site_id'] : 0;
            $existingOrder = array();
            if($row['id'] > 0)
            {
                $existingOrder = $this->Ardpurchaseorder->findById((int)$row['id']);
                if(empty($existingOrder) || !$this->_isAllowedProject((int)$existingOrder['Ardpurchaseorder']['project_id']))
                {
                    $this->Session->setFlash(__('Invalid purchase order.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect($this->referer());
                }
                $row['project_id'] = (int)$existingOrder['Ardpurchaseorder']['project_id'];
            }
            if(!$this->_isAllowedProject($row['project_id']))
            {
                $this->Session->setFlash(__('Please select valid agency/project.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            if($row['site_id'] <= 0 && $row['id'] > 0 && !empty($existingOrder['Ardpurchaseorder']))
            {
                $row['site_id'] = (int)$existingOrder['Ardpurchaseorder']['site_id'];
            }
            if($row['site_id'] <= 0 && $row['id'] <= 0)
            {
                $this->Session->setFlash(__('Please select stock store.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            $row['po_no'] = trim((string)$row['po_no']);
            if($row['po_no'] === '')
            {
                if(!empty($existingOrder['Ardpurchaseorder']['po_no']))
                {
                    $row['po_no'] = trim((string)$existingOrder['Ardpurchaseorder']['po_no']);
                }
                if($row['po_no'] === '')
                {
                    $row['po_no'] = $this->_nextReferenceNo((int)$row['project_id'], 'po', 'PO-');
                }
            }
            $row['auto_generated'] = !empty($row['auto_generated']) ? 1 : 0;
            if(empty($row['status']))
            {
                $row['status'] = 'draft';
            }

            $lineItems = array();
            $mainLine = array(
                'id' => 0,
                'material_type' => trim((string)(isset($row['material_type']) ? $row['material_type'] : '')),
                'unit_type' => trim((string)(isset($row['unit_type']) ? $row['unit_type'] : '')),
                'quantity' => round((float)(isset($row['quantity']) ? $row['quantity'] : 0), 3),
                'unit_cost' => round((float)(isset($row['unit_cost']) ? $row['unit_cost'] : 0), 2),
                'total_cost' => round((float)(isset($row['total_cost']) ? $row['total_cost'] : 0), 2)
            );
            if($mainLine['material_type'] !== '' || $mainLine['quantity'] > 0 || $mainLine['unit_cost'] > 0 || $mainLine['total_cost'] > 0)
            {
                $lineItems[] = $mainLine;
            }

            $extraMaterialRows = isset($row['line_material_type']) && is_array($row['line_material_type']) ? $row['line_material_type'] : array();
            $extraUnitRows = isset($row['line_unit_type']) && is_array($row['line_unit_type']) ? $row['line_unit_type'] : array();
            $extraQtyRows = isset($row['line_quantity']) && is_array($row['line_quantity']) ? $row['line_quantity'] : array();
            $extraCostRows = isset($row['line_unit_cost']) && is_array($row['line_unit_cost']) ? $row['line_unit_cost'] : array();
            $extraTotalRows = isset($row['line_total_cost']) && is_array($row['line_total_cost']) ? $row['line_total_cost'] : array();
            $extraIdRows = isset($row['line_id']) && is_array($row['line_id']) ? $row['line_id'] : array();
            $extraRowCount = max(count($extraMaterialRows), count($extraUnitRows), count($extraQtyRows), count($extraCostRows), count($extraTotalRows), count($extraIdRows));
            for($i = 0; $i < $extraRowCount; $i++)
            {
                $extraLine = array(
                    'id' => isset($extraIdRows[$i]) ? (int)$extraIdRows[$i] : 0,
                    'material_type' => trim((string)(isset($extraMaterialRows[$i]) ? $extraMaterialRows[$i] : '')),
                    'unit_type' => trim((string)(isset($extraUnitRows[$i]) ? $extraUnitRows[$i] : '')),
                    'quantity' => round((float)(isset($extraQtyRows[$i]) ? $extraQtyRows[$i] : 0), 3),
                    'unit_cost' => round((float)(isset($extraCostRows[$i]) ? $extraCostRows[$i] : 0), 2),
                    'total_cost' => round((float)(isset($extraTotalRows[$i]) ? $extraTotalRows[$i] : 0), 2)
                );
                if($extraLine['material_type'] === '' && $extraLine['quantity'] <= 0 && $extraLine['unit_cost'] <= 0 && $extraLine['total_cost'] <= 0)
                {
                    continue;
                }
                $lineItems[] = $extraLine;
            }

            if(empty($lineItems))
            {
                $this->Session->setFlash(__('Please add at least one material line.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }

            $normalizeDate = function($value, $fallback = '')
            {
                $value = trim((string)$value);
                if($value === '' || $value === '0000-00-00')
                {
                    return $fallback;
                }
                $formats = array('Y-m-d', 'd-m-Y', 'd/m/Y', 'Y/m/d', 'm/d/Y');
                foreach($formats as $fmt)
                {
                    $dt = DateTime::createFromFormat($fmt, $value);
                    if($dt && $dt->format($fmt) === $value)
                    {
                        return $dt->format('Y-m-d');
                    }
                }
                $ts = strtotime(str_replace('/', '-', $value));
                if($ts !== false)
                {
                    return date('Y-m-d', $ts);
                }
                return $fallback;
            };

            $totalCostSum = 0.00;
            foreach($lineItems as $lineIndex => $lineItem)
            {
                if(trim((string)$lineItem['material_type']) === '')
                {
                    $this->Session->setFlash(__('Please select material for all lines.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect($this->referer());
                }
                if((float)$lineItem['quantity'] <= 0)
                {
                    $this->Session->setFlash(__('Quantity must be greater than zero for all material lines.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect($this->referer());
                }
                if((float)$lineItem['total_cost'] <= 0)
                {
                    $lineItems[$lineIndex]['total_cost'] = round((float)$lineItem['quantity'] * (float)$lineItem['unit_cost'], 2);
                }
                $totalCostSum += (float)$lineItems[$lineIndex]['total_cost'];
            }

            $firstLine = $lineItems[0];
            $row['material_type'] = (string)$firstLine['material_type'];
            $row['unit_type'] = (string)$firstLine['unit_type'];
            $row['quantity'] = round((float)$firstLine['quantity'], 3);
            $row['unit_cost'] = round((float)$firstLine['unit_cost'], 2);
            $row['total_cost'] = round((float)$totalCostSum, 2);

            $existingPoDate = '';
            if(!empty($existingOrder['Ardpurchaseorder']['po_date']) && $existingOrder['Ardpurchaseorder']['po_date'] !== '0000-00-00')
            {
                $existingPoDate = (string)$existingOrder['Ardpurchaseorder']['po_date'];
            }
            $normalizedPoDate = $normalizeDate(isset($row['po_date']) ? $row['po_date'] : '', $existingPoDate);
            if($normalizedPoDate === '')
            {
                $normalizedPoDate = date('Y-m-d');
            }
            $normalizedExpectedDate = $normalizeDate(isset($row['expected_date']) ? $row['expected_date'] : '', '');

            $saveData = array(
                'project_id' => (int)$row['project_id'],
                'po_no' => (string)$row['po_no'],
                'vendor_id' => (int)(isset($row['vendor_id']) ? $row['vendor_id'] : 0),
                'site_id' => (int)$row['site_id'],
                'material_type' => (string)$row['material_type'],
                'unit_type' => (string)$row['unit_type'],
                'quantity' => (float)$row['quantity'],
                'unit_cost' => (float)$row['unit_cost'],
                'total_cost' => (float)$row['total_cost'],
                'po_date' => $normalizedPoDate,
                'expected_date' => ($normalizedExpectedDate !== '' ? $normalizedExpectedDate : null),
                'status' => (string)$row['status'],
                'auto_generated' => (int)$row['auto_generated'],
                'note' => isset($row['note']) ? $row['note'] : ''
            );
            if((int)$row['id'] > 0)
            {
                $saveData['id'] = (int)$row['id'];
            }

            $purchaseOrderId = 0;
            $ok = true;
            $stockSyncOk = true;
            $ds = $this->Ardpurchaseorder->getDataSource();
            $ds->begin();

            if((int)$row['id'] > 0)
            {
                $this->Ardpurchaseorder->id = (int)$row['id'];
            }
            else
            {
                $this->Ardpurchaseorder->create();
            }
            $savedPo = $this->Ardpurchaseorder->save(array('Ardpurchaseorder' => $saveData));
            if(!$savedPo && (int)$row['id'] > 0)
            {
                // Fallback update path for legacy rows where Model::save() can fail silently.
                $updateData = array(
                    'Ardpurchaseorder.project_id' => (int)$saveData['project_id'],
                    'Ardpurchaseorder.po_no' => $ds->value($saveData['po_no'], 'string'),
                    'Ardpurchaseorder.vendor_id' => (int)$saveData['vendor_id'],
                    'Ardpurchaseorder.site_id' => (int)$saveData['site_id'],
                    'Ardpurchaseorder.material_type' => $ds->value($saveData['material_type'], 'string'),
                    'Ardpurchaseorder.unit_type' => $ds->value($saveData['unit_type'], 'string'),
                    'Ardpurchaseorder.quantity' => (float)$saveData['quantity'],
                    'Ardpurchaseorder.unit_cost' => (float)$saveData['unit_cost'],
                    'Ardpurchaseorder.total_cost' => (float)$saveData['total_cost'],
                    'Ardpurchaseorder.po_date' => $ds->value($saveData['po_date'], 'string'),
                    'Ardpurchaseorder.expected_date' => ($saveData['expected_date'] === null) ? 'NULL' : $ds->value($saveData['expected_date'], 'string'),
                    'Ardpurchaseorder.status' => $ds->value($saveData['status'], 'string'),
                    'Ardpurchaseorder.auto_generated' => (int)$saveData['auto_generated'],
                    'Ardpurchaseorder.note' => $ds->value($saveData['note'], 'string'),
                    'Ardpurchaseorder.modified' => $ds->value(date('Y-m-d H:i:s'), 'string')
                );
                $savedPo = $this->Ardpurchaseorder->updateAll(
                    $updateData,
                    array('Ardpurchaseorder.id' => (int)$row['id'])
                );
            }
            if($savedPo)
            {
                $purchaseOrderId = ((int)$row['id'] > 0) ? (int)$row['id'] : (int)$this->Ardpurchaseorder->id;
                $this->Ardpurchaseorderitem->deleteAll(array('Ardpurchaseorderitem.po_id' => $purchaseOrderId), false);
                foreach($lineItems as $lineItem)
                {
                    $lineSave = array(
                        'project_id' => (int)$saveData['project_id'],
                        'po_id' => (int)$purchaseOrderId,
                        'material_type' => (string)$lineItem['material_type'],
                        'unit_type' => (string)$lineItem['unit_type'],
                        'quantity' => (float)$lineItem['quantity'],
                        'unit_cost' => (float)$lineItem['unit_cost'],
                        'total_cost' => (float)$lineItem['total_cost']
                    );
                    $this->Ardpurchaseorderitem->create();
                    if(!$this->Ardpurchaseorderitem->save(array('Ardpurchaseorderitem' => $lineSave)))
                    {
                        $ok = false;
                        break;
                    }
                }
            }
            else
            {
                $ok = false;
            }

            if($ok)
            {
                $ds->commit();
                // Keep PO updates persisted even if stock sync has a non-critical issue.
                $stockSyncOk = $this->_syncStockFromPurchaseOrder($purchaseOrderId);
                if($stockSyncOk)
                {
                    $this->Session->setFlash(__('Purchase order saved successfully.'), 'flash', array('alert' => 'success'));
                }
                else
                {
                    $this->Session->setFlash(__('Purchase order saved, but stock sync failed. Please check stock entries.'), 'flash', array('alert' => 'warning'));
                }
            }
            else
            {
                $ds->rollback();
                $dbError = '';
                if(method_exists($ds, 'lastError'))
                {
                    $dbError = trim((string)$ds->lastError());
                }
                $saveError = '';
                if(!empty($this->Ardpurchaseorder->validationErrors))
                {
                    $flatErrors = array();
                    foreach((array)$this->Ardpurchaseorder->validationErrors as $fieldErrors)
                    {
                        if(is_array($fieldErrors))
                        {
                            foreach($fieldErrors as $msg)
                            {
                                $msg = trim((string)$msg);
                                if($msg !== '')
                                {
                                    $flatErrors[] = $msg;
                                }
                            }
                        }
                        else
                        {
                            $msg = trim((string)$fieldErrors);
                            if($msg !== '')
                            {
                                $flatErrors[] = $msg;
                            }
                        }
                    }
                    $saveError = trim(implode(' ', $flatErrors));
                }
                $errorMsg = __('Unable to save purchase order.');
                if($saveError !== '')
                {
                    $errorMsg .= ' ' . $saveError;
                }
                elseif($dbError !== '')
                {
                    $errorMsg .= ' ' . $dbError;
                }
                $this->Session->setFlash($errorMsg, 'flash', array('alert' => 'danger'));
            }

            return $this->redirect(array('action' => 'purchaseorders', (int)$saveData['project_id']));
        }

        $scope = $this->_scopeCondition('Ardpurchaseorder.project_id', $id);
        $this->Paginator->settings = array(
            'page' => 1,
            'order' => array('Ardpurchaseorder.id' => 'desc'),
            'limit' => $this->pageLimit,
            'maxLimit' => $this->maxLimit,
            'conditions' => array($scope)
        );
        $rows = $this->Paginator->paginate('Ardpurchaseorder');
        $this->set('rows', $rows);
        $poItemSummary = array();
        $poIds = array();
        foreach((array)$rows as $poRow)
        {
            $poIds[] = (int)$poRow['Ardpurchaseorder']['id'];
        }
        if(!empty($poIds))
        {
            $itemRows = $this->Ardpurchaseorderitem->find('all', array(
                'conditions' => array('Ardpurchaseorderitem.po_id' => $poIds),
                'order' => array('Ardpurchaseorderitem.id' => 'asc'),
                'recursive' => -1
            ));
            foreach((array)$itemRows as $itemRow)
            {
                if(empty($itemRow['Ardpurchaseorderitem']))
                {
                    continue;
                }
                $item = $itemRow['Ardpurchaseorderitem'];
                $poId = (int)$item['po_id'];
                if(!isset($poItemSummary[$poId]))
                {
                    $poItemSummary[$poId] = array(
                        'count' => 0,
                        'first_label' => '',
                        'total_cost' => 0.00
                    );
                }
                $poItemSummary[$poId]['count']++;
                $poItemSummary[$poId]['total_cost'] += (float)$item['total_cost'];
                if($poItemSummary[$poId]['first_label'] === '')
                {
                    $poItemSummary[$poId]['first_label'] = trim((string)$item['material_type']) . ' ' . trim((string)$item['unit_type']);
                }
            }
        }
        foreach((array)$rows as $poRow)
        {
            $poId = (int)$poRow['Ardpurchaseorder']['id'];
            if(!isset($poItemSummary[$poId]))
            {
                $poItemSummary[$poId] = array(
                    'count' => 1,
                    'first_label' => trim((string)$poRow['Ardpurchaseorder']['material_type']) . ' ' . trim((string)$poRow['Ardpurchaseorder']['unit_type']),
                    'total_cost' => (float)$poRow['Ardpurchaseorder']['total_cost']
                );
            }
        }
        $this->set('poItemSummary', $poItemSummary);
        if($viewIdFromUrl > 0)
        {
            $viewRowRaw = $this->Ardpurchaseorder->findById($viewIdFromUrl);
            if(!empty($viewRowRaw['Ardpurchaseorder']) && $this->_isAllowedProject((int)$viewRowRaw['Ardpurchaseorder']['project_id']))
            {
                $viewPoRow = $viewRowRaw['Ardpurchaseorder'];
                $viewPoLines = $this->Ardpurchaseorderitem->find('all', array(
                    'conditions' => array('Ardpurchaseorderitem.po_id' => (int)$viewPoRow['id']),
                    'order' => array('Ardpurchaseorderitem.id' => 'asc'),
                    'recursive' => -1
                ));
                $viewLineCount = 0;
                $viewFirstLabel = '';
                $viewTotalCost = 0.0;
                foreach((array)$viewPoLines as $viewLineRow)
                {
                    if(empty($viewLineRow['Ardpurchaseorderitem']))
                    {
                        continue;
                    }
                    $viewLine = $viewLineRow['Ardpurchaseorderitem'];
                    $viewLineCount++;
                    $viewTotalCost += round((float)$viewLine['total_cost'], 2);
                    if($viewFirstLabel === '')
                    {
                        $viewFirstLabel = trim((string)$viewLine['material_type']) . ' ' . trim((string)$viewLine['unit_type']);
                    }
                }
                if($viewLineCount <= 0)
                {
                    $viewLineCount = 1;
                    $viewFirstLabel = trim((string)$viewPoRow['material_type']) . ' ' . trim((string)$viewPoRow['unit_type']);
                    $viewTotalCost = round((float)$viewPoRow['total_cost'], 2);
                }
                $viewQtyText = ($viewLineCount > 1)
                    ? ($viewLineCount . ' line items')
                    : (number_format((float)$viewPoRow['quantity'], 3) . ' ' . trim((string)$viewPoRow['unit_type']));
                $this->set('poViewRow', array(
                    'id' => (int)$viewPoRow['id'],
                    'po_no' => (string)$viewPoRow['po_no'],
                    'vendor' => isset($vendorList[(int)$viewPoRow['vendor_id']]) ? (string)$vendorList[(int)$viewPoRow['vendor_id']] : '-',
                    'store' => isset($siteList[(int)$viewPoRow['site_id']]) ? (string)$siteList[(int)$viewPoRow['site_id']] : '-',
                    'material' => ($viewFirstLabel !== '' ? $viewFirstLabel : '-'),
                    'qty' => $viewQtyText,
                    'amount' => (float)$viewTotalCost,
                    'date' => (!empty($viewPoRow['po_date']) && $viewPoRow['po_date'] !== '0000-00-00') ? date('d-M-Y', strtotime((string)$viewPoRow['po_date'])) : '-',
                    'status' => ucfirst((string)$viewPoRow['status']),
                    'note' => (string)$viewPoRow['note']
                ));
            }
        }

        $editId = (int)$editIdFromUrl;
        if($editId > 0)
        {
            $editRow = $this->Ardpurchaseorder->findById($editId);
            if(!empty($editRow) && $this->_isAllowedProject((int)$editRow['Ardpurchaseorder']['project_id']))
            {
                $editProjectId = (int)$editRow['Ardpurchaseorder']['project_id'];
                if($editProjectId > 0)
                {
                    $id = $editProjectId;
                    $this->set('currentProjectId', $editProjectId);
                    $this->set('vendorList', $this->Ardvendor->find('list', array(
                        'fields' => array('Ardvendor.id', 'Ardvendor.vendor_name'),
                        'conditions' => array($this->_scopeCondition('Ardvendor.project_id', $editProjectId)),
                        'order' => array('Ardvendor.vendor_name' => 'asc')
                    )));
                    $this->set('siteList', $this->Ardsite->find('list', array(
                        'fields' => array('Ardsite.id', 'Ardsite.site_name'),
                        'conditions' => array($this->_scopeCondition('Ardsite.project_id', $editProjectId)),
                        'order' => array('Ardsite.site_name' => 'asc')
                    )));
                    if(isset($nextPoNoMap[$editProjectId]) && !empty($nextPoNoMap[$editProjectId]))
                    {
                        $this->set('nextPoNo', (string)$nextPoNoMap[$editProjectId]);
                    }
                }
                $this->request->data = $editRow;
                $editProjectOptions = $this->_constructionMaterialUnitOptions($editProjectId);
                $this->set('constructionMaterialOptions', $editProjectOptions['materials']);
                $this->set('constructionUnitOptions', $editProjectOptions['units']);
                $this->set('constructionMaterialUnitMap', isset($editProjectOptions['material_units']) ? $editProjectOptions['material_units'] : array());

                $lineRows = $this->Ardpurchaseorderitem->find('all', array(
                    'conditions' => array('Ardpurchaseorderitem.po_id' => (int)$editRow['Ardpurchaseorder']['id']),
                    'order' => array('Ardpurchaseorderitem.id' => 'asc'),
                    'recursive' => -1
                ));
                $normalizedLineRows = array();
                foreach((array)$lineRows as $lineRow)
                {
                    if(!empty($lineRow['Ardpurchaseorderitem']))
                    {
                        $normalizedLineRows[] = $lineRow['Ardpurchaseorderitem'];
                    }
                }
                if(empty($normalizedLineRows))
                {
                    $normalizedLineRows[] = array(
                        'material_type' => (string)$editRow['Ardpurchaseorder']['material_type'],
                        'unit_type' => (string)$editRow['Ardpurchaseorder']['unit_type'],
                        'quantity' => (float)$editRow['Ardpurchaseorder']['quantity'],
                        'unit_cost' => (float)$editRow['Ardpurchaseorder']['unit_cost'],
                        'total_cost' => (float)$editRow['Ardpurchaseorder']['total_cost']
                    );
                }
                if(!empty($normalizedLineRows))
                {
                    $firstLine = $normalizedLineRows[0];
                    $this->request->data['Ardpurchaseorder']['material_type'] = isset($firstLine['material_type']) ? $firstLine['material_type'] : '';
                    $this->request->data['Ardpurchaseorder']['unit_type'] = isset($firstLine['unit_type']) ? $firstLine['unit_type'] : '';
                    $this->request->data['Ardpurchaseorder']['quantity'] = isset($firstLine['quantity']) ? $firstLine['quantity'] : 0;
                    $this->request->data['Ardpurchaseorder']['unit_cost'] = isset($firstLine['unit_cost']) ? $firstLine['unit_cost'] : 0;
                    $this->request->data['Ardpurchaseorder']['total_cost'] = isset($firstLine['total_cost']) ? $firstLine['total_cost'] : 0;
                }
                if(count($normalizedLineRows) > 1)
                {
                    $this->set('purchaseOrderLineRows', array_slice($normalizedLineRows, 1));
                }
            }
        }
        elseif(empty($this->request->data['Ardpurchaseorder']['po_no']))
        {
            $this->request->data['Ardpurchaseorder']['po_no'] = $nextPoNo;
        }
    }

    public function deletepurchaseorder($id = null, $projectId = null)
    {
        $this->loadModel('Admin.Ardpurchaseorder');
        $this->loadModel('Admin.Ardpurchaseorderitem');
        $this->loadModel('Admin.Ardstock');
        $this->loadModel('Admin.Ardgrn');
        $this->loadModel('Admin.Ardpurchaseinvoice');
        $row = $this->Ardpurchaseorder->findById($id);
        if(empty($row) || !$this->_isAllowedProject((int)$row['Ardpurchaseorder']['project_id']))
        {
            $this->Session->setFlash(__('Invalid purchase order.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'purchaseorders', $projectId));
        }
        $hasGrn = $this->Ardgrn->find('count', array(
            'conditions' => array('Ardgrn.po_id' => (int)$id)
        ));
        $hasInvoice = $this->Ardpurchaseinvoice->find('count', array(
            'conditions' => array('Ardpurchaseinvoice.po_id' => (int)$id)
        ));
        if($hasGrn > 0 || $hasInvoice > 0)
        {
            $this->Session->setFlash(__('Cannot delete purchase order because it has linked GRN or Purchase Invoice records.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'purchaseorders', $projectId));
        }
        $this->_storeTrashRecord(
            'ardaccounts_construction_purchase_orders',
            'Ardpurchaseorder',
            $row['Ardpurchaseorder'],
            isset($row['Ardpurchaseorder']['po_no']) ? (string)$row['Ardpurchaseorder']['po_no'] : ''
        );
        $this->Ardpurchaseorderitem->deleteAll(array('Ardpurchaseorderitem.po_id' => (int)$id), false);
        $this->Ardstock->deleteAll(array('Ardstock.purchase_order_id' => (int)$id), false);
        $this->Ardpurchaseorder->delete($id);
        $this->Session->setFlash(__('Purchase order deleted. You can restore it from Trash.'), 'flash', array('alert' => 'success'));
        return $this->redirect(array('action' => 'purchaseorders', $projectId));
    }

    public function grn($id = null)
    {
        $this->loadModel('Admin.Ardgrn');
        $this->loadModel('Admin.Ardpurchaseorder');
        $this->loadModel('Admin.Ardvendor');
        $this->loadModel('Admin.Ardsite');
        $id = $this->_activeProjectId($id);
        $this->set('projectName', $this->_projectList());
        $this->set('agencyId', $this->agencyId);
        $this->set('currentProjectId', $id);
        $this->set('poList', $this->Ardpurchaseorder->find('list', array(
            'fields' => array('Ardpurchaseorder.id', 'Ardpurchaseorder.po_no'),
            'conditions' => array($this->_scopeCondition('Ardpurchaseorder.project_id', $id)),
            'order' => array('Ardpurchaseorder.id' => 'desc')
        )));
        $this->set('vendorList', $this->Ardvendor->find('list', array(
            'fields' => array('Ardvendor.id', 'Ardvendor.vendor_name'),
            'conditions' => array($this->_scopeCondition('Ardvendor.project_id', $id)),
            'order' => array('Ardvendor.vendor_name' => 'asc')
        )));
        $this->set('siteList', $this->Ardsite->find('list', array(
            'fields' => array('Ardsite.id', 'Ardsite.site_name'),
            'conditions' => array($this->_scopeCondition('Ardsite.project_id', $id)),
            'order' => array('Ardsite.site_name' => 'asc')
        )));
        $constructionOptions = $this->_constructionMaterialUnitOptions((int)$id);
        $this->set('constructionMaterialOptions', $constructionOptions['materials']);
        $this->set('constructionUnitOptions', $constructionOptions['units']);
        $this->set('constructionMaterialUnitMap', isset($constructionOptions['material_units']) ? $constructionOptions['material_units'] : array());

        if($this->request->is('post'))
        {
            $row = isset($this->request->data['Ardgrn']) ? $this->request->data['Ardgrn'] : array();
            $row['project_id'] = $this->_resolveProjectId(isset($row['project_id']) ? $row['project_id'] : null);
            if(!$this->_isAllowedProject($row['project_id']))
            {
                $this->Session->setFlash(__('Please select valid agency/project.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            $row['grn_no'] = trim((string)$row['grn_no']);
            if($row['grn_no'] === '')
            {
                $row['grn_no'] = $this->_nextReferenceNo((int)$row['project_id'], 'grn', 'GRN-');
            }
            $qty = (float)$row['received_qty'];
            $unitCost = (float)$row['unit_cost'];
            if(!isset($row['total_cost']) || (float)$row['total_cost'] <= 0)
            {
                $row['total_cost'] = round($qty * $unitCost, 2);
            }

            $this->Ardgrn->create();
            if($this->Ardgrn->save(array('Ardgrn' => $row)))
            {
                $this->Session->setFlash(__('GRN saved successfully.'), 'flash', array('alert' => 'success'));
            }
            else
            {
                $this->Session->setFlash(__('Unable to save GRN.'), 'flash', array('alert' => 'danger'));
            }
            return $this->redirect(array('action' => 'grn', $id));
        }

        $scope = $this->_scopeCondition('Ardgrn.project_id', $id);
        $this->Paginator->settings = array(
            'page' => 1,
            'order' => array('Ardgrn.id' => 'desc'),
            'limit' => $this->pageLimit,
            'maxLimit' => $this->maxLimit,
            'conditions' => array($scope)
        );
        $this->set('rows', $this->Paginator->paginate('Ardgrn'));

        $editId = isset($this->request->params['named']['edit']) ? (int)$this->request->params['named']['edit'] : 0;
        if($editId > 0)
        {
            $editRow = $this->Ardgrn->findById($editId);
            if(!empty($editRow) && $this->_isAllowedProject((int)$editRow['Ardgrn']['project_id']))
            {
                $this->request->data = $editRow;
                $editProjectOptions = $this->_constructionMaterialUnitOptions((int)$editRow['Ardgrn']['project_id']);
                $this->set('constructionMaterialOptions', $editProjectOptions['materials']);
                $this->set('constructionUnitOptions', $editProjectOptions['units']);
                $this->set('constructionMaterialUnitMap', isset($editProjectOptions['material_units']) ? $editProjectOptions['material_units'] : array());
            }
        }
    }

    public function deletegrn($id = null, $projectId = null)
    {
        $this->loadModel('Admin.Ardgrn');
        $this->loadModel('Admin.Ardpurchaseinvoice');
        $row = $this->Ardgrn->findById($id);
        if(empty($row) || !$this->_isAllowedProject((int)$row['Ardgrn']['project_id']))
        {
            $this->Session->setFlash(__('Invalid GRN entry.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'grn', $projectId));
        }
        $hasInvoice = $this->Ardpurchaseinvoice->find('count', array(
            'conditions' => array('Ardpurchaseinvoice.grn_id' => (int)$id)
        ));
        if($hasInvoice > 0)
        {
            $this->Session->setFlash(__('Cannot delete GRN because it has linked Purchase Invoice records.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'grn', $projectId));
        }
        $this->_storeTrashRecord(
            'ardaccounts_construction_grn',
            'Ardgrn',
            $row['Ardgrn'],
            isset($row['Ardgrn']['grn_no']) ? (string)$row['Ardgrn']['grn_no'] : ''
        );
        $this->Ardgrn->delete($id);
        $this->Session->setFlash(__('GRN deleted. You can restore it from Trash.'), 'flash', array('alert' => 'success'));
        return $this->redirect(array('action' => 'grn', $projectId));
    }

    public function purchaseinvoices($id = null)
    {
        $this->loadModel('Admin.Ardpurchaseinvoice');
        $this->loadModel('Admin.Ardpurchaseorder');
        $this->loadModel('Admin.Ardgrn');
        $this->loadModel('Admin.Ardvendor');
        $this->loadModel('Admin.Ardtransaction');
        $id = $this->_activeProjectId($id);
        $this->set('projectName', $this->_projectList());
        $this->set('agencyId', $this->agencyId);
        $this->set('currentProjectId', $id);
        $this->set('poList', $this->Ardpurchaseorder->find('list', array(
            'fields' => array('Ardpurchaseorder.id', 'Ardpurchaseorder.po_no'),
            'conditions' => array($this->_scopeCondition('Ardpurchaseorder.project_id', $id)),
            'order' => array('Ardpurchaseorder.id' => 'desc')
        )));
        $this->set('grnList', $this->Ardgrn->find('list', array(
            'fields' => array('Ardgrn.id', 'Ardgrn.grn_no'),
            'conditions' => array($this->_scopeCondition('Ardgrn.project_id', $id)),
            'order' => array('Ardgrn.id' => 'desc')
        )));
        $this->set('vendorList', $this->Ardvendor->find('list', array(
            'fields' => array('Ardvendor.id', 'Ardvendor.vendor_name'),
            'conditions' => array($this->_scopeCondition('Ardvendor.project_id', $id)),
            'order' => array('Ardvendor.vendor_name' => 'asc')
        )));

        if($this->request->is('post'))
        {
            $row = isset($this->request->data['Ardpurchaseinvoice']) ? $this->request->data['Ardpurchaseinvoice'] : array();
            $row['id'] = isset($row['id']) ? (int)$row['id'] : 0;
            $row['project_id'] = $this->_resolveProjectId(isset($row['project_id']) ? $row['project_id'] : null);
            if(!$this->_isAllowedProject($row['project_id']))
            {
                $this->Session->setFlash(__('Please select valid agency/project.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            $oldVoucherTxId = 0;
            if($row['id'] > 0)
            {
                $existingInvoice = $this->Ardpurchaseinvoice->findById($row['id']);
                if(empty($existingInvoice) || !$this->_isAllowedProject((int)$existingInvoice['Ardpurchaseinvoice']['project_id']))
                {
                    $this->Session->setFlash(__('Invalid purchase invoice.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect($this->referer());
                }
                $oldVoucherTxId = (int)(isset($existingInvoice['Ardpurchaseinvoice']['voucher_transaction_id']) ? $existingInvoice['Ardpurchaseinvoice']['voucher_transaction_id'] : 0);
                if($oldVoucherTxId > 0)
                {
                    $lockMessage = $this->_ardTransactionLockedMessage($oldVoucherTxId, (int)$existingInvoice['Ardpurchaseinvoice']['project_id']);
                    if($lockMessage !== '')
                    {
                        $this->Session->setFlash($lockMessage, 'flash', array('alert' => 'danger'));
                        return $this->redirect($this->referer());
                    }
                }
            }
            $row['invoice_no'] = trim((string)$row['invoice_no']);
            if($row['invoice_no'] === '')
            {
                $row['invoice_no'] = $this->_nextReferenceNo((int)$row['project_id'], 'purchase_invoice', 'PINV-');
            }
            $amount = round((float)$row['amount'], 2);
            $paid = round((float)$row['paid_amount'], 2);
            if($amount < 0)
            {
                $amount = 0;
            }
            if($paid < 0)
            {
                $paid = 0;
            }
            $row['amount'] = $amount;
            $row['paid_amount'] = $paid;
            if($amount > 0 && $paid >= $amount)
            {
                $row['status'] = 'paid';
            }
            elseif($paid > 0)
            {
                $row['status'] = 'partial';
            }
            else
            {
                $row['status'] = 'open';
            }

            $this->Ardpurchaseinvoice->create();
            if($this->Ardpurchaseinvoice->save(array('Ardpurchaseinvoice' => $row)))
            {
                $savedInvoiceId = $row['id'] > 0 ? (int)$row['id'] : (int)$this->Ardpurchaseinvoice->id;
                $this->_syncPurchaseInvoiceVoucher($savedInvoiceId, $oldVoucherTxId);
                $this->Session->setFlash(__('Purchase invoice saved successfully.'), 'flash', array('alert' => 'success'));
            }
            else
            {
                $this->Session->setFlash(__('Unable to save purchase invoice.'), 'flash', array('alert' => 'danger'));
            }
            return $this->redirect(array('action' => 'purchaseinvoices', $id));
        }

        $scope = $this->_scopeCondition('Ardpurchaseinvoice.project_id', $id);
        $this->Paginator->settings = array(
            'page' => 1,
            'order' => array('Ardpurchaseinvoice.id' => 'desc'),
            'limit' => $this->pageLimit,
            'maxLimit' => $this->maxLimit,
            'conditions' => array($scope)
        );
        $this->set('rows', $this->Paginator->paginate('Ardpurchaseinvoice'));

        $editId = isset($this->request->params['named']['edit']) ? (int)$this->request->params['named']['edit'] : 0;
        if($editId > 0)
        {
            $editRow = $this->Ardpurchaseinvoice->findById($editId);
            if(!empty($editRow) && $this->_isAllowedProject((int)$editRow['Ardpurchaseinvoice']['project_id']))
            {
                $this->request->data = $editRow;
            }
        }
    }

    protected function _syncPurchaseInvoiceVoucher($invoiceId, $existingVoucherTxId = 0)
    {
        $this->loadModel('Admin.Ardpurchaseinvoice');
        $this->loadModel('Admin.Ardvendor');
        $invoiceId = (int)$invoiceId;
        if($invoiceId <= 0)
        {
            return 0;
        }
        $invoice = $this->Ardpurchaseinvoice->findById($invoiceId);
        if(empty($invoice['Ardpurchaseinvoice']) || !$this->_isAllowedProject((int)$invoice['Ardpurchaseinvoice']['project_id']))
        {
            return 0;
        }
        $row = $invoice['Ardpurchaseinvoice'];
        $projectId = (int)$row['project_id'];
        $amount = isset($row['amount']) ? round((float)$row['amount'], 2) : 0;
        $existingVoucherTxId = $existingVoucherTxId > 0 ? (int)$existingVoucherTxId : (int)(isset($row['voucher_transaction_id']) ? $row['voucher_transaction_id'] : 0);
        if($amount <= 0)
        {
            $this->_ardVoidAutoVoucherBySource($projectId, 'purchase_invoice', $invoiceId, 'Purchase invoice amount removed');
            return 0;
        }
        $wipLedgerId = $this->_ardDefaultLedgerId($projectId, 'construction_wip_ledger_id', 'Construction WIP', 'asset');
        $vendorPayableLedgerId = $this->_ardDefaultLedgerId($projectId, 'vendor_payable_ledger_id', 'Vendor Payable', 'liability');
        if($wipLedgerId <= 0 || $vendorPayableLedgerId <= 0)
        {
            return 0;
        }
        $vendorName = '';
        if(!empty($row['vendor_id']))
        {
            $vendorName = trim((string)$this->Ardvendor->field('vendor_name', array('Ardvendor.id' => (int)$row['vendor_id'])));
        }
        if($vendorName === '')
        {
            $vendorName = 'Vendor #'.(int)$row['vendor_id'];
        }
        $refNo = trim((string)(isset($row['invoice_no']) ? $row['invoice_no'] : ''));
        if($refNo === '')
        {
            $refNo = 'PINV-'.$invoiceId;
        }
        $entryDate = !empty($row['invoice_date']) ? $row['invoice_date'] : date('Y-m-d');
        $txId = $this->_ardPostAutoVoucher(
            $projectId,
            $wipLedgerId,
            'income',
            $amount,
            $refNo,
            $entryDate,
            'Construction purchase invoice: '.$vendorName.' | '.$refNo,
            array(
                'existing_id' => $existingVoucherTxId,
                'income_ledger_id' => $vendorPayableLedgerId,
                'source_type' => 'purchase_invoice',
                'source_id' => $invoiceId,
                'status' => 'Posted'
            )
        );
        if($txId > 0)
        {
            try
            {
                $this->Ardpurchaseinvoice->query("UPDATE `ardaccounts_construction_purchase_invoices` SET `voucher_transaction_id`=".(int)$txId." WHERE `id`=".(int)$invoiceId);
            }
            catch(Exception $e) {}
        }
        return $txId;
    }

    public function deletepurchaseinvoice($id = null, $projectId = null)
    {
        $this->loadModel('Admin.Ardpurchaseinvoice');
        $this->loadModel('Admin.Ardtransaction');
        $this->loadModel('Admin.Ardpurchaseinvoicepayment');
        $row = $this->Ardpurchaseinvoice->findById($id);
        if(empty($row) || !$this->_isAllowedProject((int)$row['Ardpurchaseinvoice']['project_id']))
        {
            $this->Session->setFlash(__('Invalid purchase invoice.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'purchaseinvoices', $projectId));
        }
        $hasPayments = $this->Ardpurchaseinvoicepayment->find('count', array(
            'conditions' => array('Ardpurchaseinvoicepayment.purchase_invoice_id' => (int)$id)
        ));
        if($hasPayments > 0)
        {
            $this->Session->setFlash(__('Cannot delete purchase invoice because it has recorded payments. Please delete or unlink the payments first.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'purchaseinvoices', $projectId));
        }
        $voucherTxId = (int)(isset($row['Ardpurchaseinvoice']['voucher_transaction_id']) ? $row['Ardpurchaseinvoice']['voucher_transaction_id'] : 0);
        $voucherLedgerIds = array();
        if($voucherTxId > 0)
        {
            $tx = $this->Ardtransaction->findById($voucherTxId);
            if(!empty($tx['Ardtransaction']))
            {
                $lockMessage = $this->_ardTransactionLockedMessage($tx['Ardtransaction'], (int)$tx['Ardtransaction']['project_id']);
                if($lockMessage !== '')
                {
                    $this->Session->setFlash($lockMessage, 'flash', array('alert' => 'danger'));
                    return $this->redirect(array('action' => 'purchaseinvoices', $projectId));
                }
                foreach(array('ledger_id','income_ledger_id','expense_ledger_id') as $ledgerField)
                {
                    if(!empty($tx['Ardtransaction'][$ledgerField]))
                    {
                        $voucherLedgerIds[(int)$tx['Ardtransaction'][$ledgerField]] = (int)$tx['Ardtransaction'][$ledgerField];
                    }
                }
            }
        }
        $this->_storeTrashRecord(
            'ardaccounts_construction_purchase_invoices',
            'Ardpurchaseinvoice',
            $row['Ardpurchaseinvoice'],
            isset($row['Ardpurchaseinvoice']['invoice_no']) ? (string)$row['Ardpurchaseinvoice']['invoice_no'] : ''
        );
        $this->Ardpurchaseinvoice->delete($id);
        if($voucherTxId > 0)
        {
            $this->_deleteJournalForTransaction($voucherTxId);
            $this->Ardtransaction->delete($voucherTxId);
            foreach($voucherLedgerIds as $ledgerId)
            {
                if($ledgerId > 0)
                {
                    $this->_recalculateLedgerBalance($ledgerId);
                }
            }
        }
        $this->Session->setFlash(__('Purchase invoice deleted. You can restore it from Trash.'), 'flash', array('alert' => 'success'));
        return $this->redirect(array('action' => 'purchaseinvoices', $projectId));
    }

    public function purchasepayments($id = null)
    {
        $this->loadModel('Admin.Ardpurchaseinvoicepayment');
        $this->loadModel('Admin.Ardpurchaseinvoice');
        $this->loadModel('Admin.Ardvendor');
        $this->loadModel('Admin.Ardledger');
        $this->loadModel('Admin.Ardtransaction');
        $id = $this->_activeProjectId($id);
        $this->set('projectName', $this->_projectList());
        $this->set('agencyId', $this->agencyId);
        $this->set('currentProjectId', $id);
        $viewIdFromUrl = isset($this->request->query['view']) ? (int)$this->request->query['view'] : 0;
        if($viewIdFromUrl <= 0 && isset($this->request->params['named']['view']))
        {
            $viewIdFromUrl = (int)$this->request->params['named']['view'];
        }
        if($viewIdFromUrl <= 0 && !empty($this->request->params['pass']) && is_array($this->request->params['pass']))
        {
            foreach((array)$this->request->params['pass'] as $passToken)
            {
                $token = urldecode((string)$passToken);
                if(stripos($token, 'view:') === 0)
                {
                    $candidate = (int)substr($token, 5);
                    if($candidate > 0)
                    {
                        $viewIdFromUrl = $candidate;
                        break;
                    }
                }
            }
        }
        $invoiceList = $this->Ardpurchaseinvoice->find('list', array(
            'fields' => array('Ardpurchaseinvoice.id', 'Ardpurchaseinvoice.invoice_no'),
            'conditions' => array($this->_scopeCondition('Ardpurchaseinvoice.project_id', $id)),
            'order' => array('Ardpurchaseinvoice.id' => 'desc')
        ));
        $vendorList = $this->Ardvendor->find('list', array(
            'fields' => array('Ardvendor.id', 'Ardvendor.vendor_name'),
            'conditions' => array($this->_scopeCondition('Ardvendor.project_id', $id)),
            'order' => array('Ardvendor.vendor_name' => 'asc')
        ));
        $ledgerList = $this->Ardledger->find('list', array(
            'fields' => array('Ardledger.id', 'Ardledger.name'),
            'conditions' => array($this->_scopeCondition('Ardledger.project_id', $id), 'Ardledger.is_trashed' => 0, 'Ardledger.type !=' => 'expense'),
            'order' => array('Ardledger.name' => 'asc')
        ));
        $this->set('invoiceList', $invoiceList);
        $this->set('vendorList', $vendorList);
        $this->set('ledgerList', $ledgerList);
        $this->set('viewIdFromUrl', $viewIdFromUrl);
        $this->set('paymentViewRow', array());

        if($this->request->is('post'))
        {
            $row = isset($this->request->data['Ardpurchaseinvoicepayment']) ? $this->request->data['Ardpurchaseinvoicepayment'] : array();
            $row['id'] = isset($row['id']) ? (int)$row['id'] : 0;
            $row['project_id'] = $this->_resolveProjectId(isset($row['project_id']) ? $row['project_id'] : null);
            if(!$this->_isAllowedProject($row['project_id']))
            {
                $this->Session->setFlash(__('Please select valid agency/project.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            $invoiceId = (int)$row['purchase_invoice_id'];
            $amount = round((float)$row['amount'], 2);
            $paymentDate = trim((string)$row['payment_date']);
            if($invoiceId <= 0 || $amount <= 0 || $paymentDate === '')
            {
                $this->Session->setFlash(__('Please enter valid payment details.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            $invoice = $this->Ardpurchaseinvoice->findById($invoiceId);
            if(empty($invoice) || !$this->_isAllowedProject((int)$invoice['Ardpurchaseinvoice']['project_id']))
            {
                $this->Session->setFlash(__('Invalid purchase invoice selected.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            if((int)$row['vendor_id'] <= 0)
            {
                $row['vendor_id'] = (int)$invoice['Ardpurchaseinvoice']['vendor_id'];
            }
            $vendorNameForTx = '';
            if((int)$row['vendor_id'] > 0 && isset($vendorList[(int)$row['vendor_id']]))
            {
                $vendorNameForTx = trim((string)$vendorList[(int)$row['vendor_id']]);
            }
            if($vendorNameForTx === '')
            {
                $vendorNameForTx = 'Vendor #' . (int)$row['vendor_id'];
            }
            $invoiceRefNo = trim((string)(isset($invoice['Ardpurchaseinvoice']['invoice_no']) ? $invoice['Ardpurchaseinvoice']['invoice_no'] : ''));
            if($invoiceRefNo === '')
            {
                $invoiceRefNo = 'Invoice #' . (int)$invoiceId;
            }

            $oldInvoiceId = 0;
            $oldVoucherTxId = 0;
            $ledgerIdsToRecalculate = array();
            if($row['id'] > 0)
            {
                $existingPayment = $this->Ardpurchaseinvoicepayment->findById($row['id']);
                if(empty($existingPayment) || !$this->_isAllowedProject((int)$existingPayment['Ardpurchaseinvoicepayment']['project_id']))
                {
                    $this->Session->setFlash(__('Invalid purchase payment.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect($this->referer());
                }
                $oldInvoiceId = (int)$existingPayment['Ardpurchaseinvoicepayment']['purchase_invoice_id'];
                $oldVoucherTxId = (int)$existingPayment['Ardpurchaseinvoicepayment']['voucher_transaction_id'];
                if($oldVoucherTxId > 0)
                {
                    $lockMessage = $this->_ardTransactionLockedMessage($oldVoucherTxId, (int)$existingPayment['Ardpurchaseinvoicepayment']['project_id']);
                    if($lockMessage !== '')
                    {
                        $this->Session->setFlash($lockMessage, 'flash', array('alert' => 'danger'));
                        return $this->redirect($this->referer());
                    }
                }
            }
            $row['voucher_transaction_id'] = $oldVoucherTxId;

            $savedPaymentId = 0;
            $savedVoucherTxId = $oldVoucherTxId;
            $syncJournalTxId = 0;
            $paymentSourceLabel = trim((string)$row['reference_no']) !== '' ? trim((string)$row['reference_no']) : $this->_nextReferenceNo((int)$row['project_id'], 'purchase_payment', 'PPAY-');
            if(trim((string)$row['reference_no']) === '')
            {
                $row['reference_no'] = $paymentSourceLabel;
            }
            $ds = $this->Ardpurchaseinvoicepayment->getDataSource();
            $ds->begin();
            $ok = true;

            $this->Ardpurchaseinvoicepayment->create();
            if($this->Ardpurchaseinvoicepayment->save(array('Ardpurchaseinvoicepayment' => $row)))
            {
                $savedPaymentId = (int)$this->Ardpurchaseinvoicepayment->id;
                $debitLedgerId = (int)$row['debit_ledger_id'];
                if($debitLedgerId > 0)
                {
                    $purchaseExpenseLedgerId = $this->_ardDefaultLedgerId((int)$row['project_id'], 'vendor_payable_ledger_id', 'Vendor Payable', 'liability');
                    $txPayload = array(
                        'project_id' => (int)$row['project_id'],
                        'ledger_id' => $debitLedgerId,
                        'expense_ledger_id' => $purchaseExpenseLedgerId,
                        'type' => 'expense',
                        'status' => 'Posted',
                        'amount' => $amount,
                        'description' => 'Vendor payment: '.$vendorNameForTx.' | '.$invoiceRefNo,
                        'ref_no' => $paymentSourceLabel,
                        'entry_date' => $paymentDate,
                        'construction_site_id' => 0,
                        'source_type' => 'purchase_payment',
                        'source_id' => (int)$savedPaymentId,
                        'auto_posted' => 1,
                        'posted_by' => (int)$this->luserId,
                        'posted_at' => date('Y-m-d H:i:s'),
                        'modified_by' => (int)$this->luserId
                    );
                    if($oldVoucherTxId > 0)
                    {
                        $oldTx = $this->Ardtransaction->findById($oldVoucherTxId);
                        if(!empty($oldTx) && $this->_isAllowedProject((int)$oldTx['Ardtransaction']['project_id']))
                        {
                            $txPayload['id'] = $oldVoucherTxId;
                            $ledgerIdsToRecalculate[] = (int)$oldTx['Ardtransaction']['ledger_id'];
                            $oldExpenseLedgerId = isset($oldTx['Ardtransaction']['expense_ledger_id']) ? (int)$oldTx['Ardtransaction']['expense_ledger_id'] : 0;
                            if($oldExpenseLedgerId > 0)
                            {
                                $ledgerIdsToRecalculate[] = $oldExpenseLedgerId;
                            }
                        }
                    }
                    $this->Ardtransaction->create();
                    if($this->Ardtransaction->save(array('Ardtransaction' => $txPayload)))
                    {
                        $savedVoucherTxId = (int)$this->Ardtransaction->id;
                        $syncJournalTxId = $savedVoucherTxId;
                        $ledgerIdsToRecalculate[] = $debitLedgerId;
                        if($purchaseExpenseLedgerId > 0)
                        {
                            $ledgerIdsToRecalculate[] = $purchaseExpenseLedgerId;
                        }
                    }
                    else
                    {
                        $ok = false;
                    }
                }
                elseif($oldVoucherTxId > 0)
                {
                    $oldTx = $this->Ardtransaction->findById($oldVoucherTxId);
                    if(!empty($oldTx) && $this->_isAllowedProject((int)$oldTx['Ardtransaction']['project_id']))
                    {
                        $ledgerIdsToRecalculate[] = (int)$oldTx['Ardtransaction']['ledger_id'];
                        $oldExpenseLedgerId = isset($oldTx['Ardtransaction']['expense_ledger_id']) ? (int)$oldTx['Ardtransaction']['expense_ledger_id'] : 0;
                        if($oldExpenseLedgerId > 0)
                        {
                            $ledgerIdsToRecalculate[] = $oldExpenseLedgerId;
                        }
                        $this->Ardtransaction->delete($oldVoucherTxId);
                        $this->_deleteJournalForTransaction($oldVoucherTxId);
                    }
                    $savedVoucherTxId = 0;
                }

                if($ok && $savedPaymentId > 0 && $savedVoucherTxId !== $oldVoucherTxId)
                {
                    $this->Ardpurchaseinvoicepayment->id = $savedPaymentId;
                    if(!$this->Ardpurchaseinvoicepayment->saveField('voucher_transaction_id', $savedVoucherTxId))
                    {
                        $ok = false;
                    }
                }
            }
            else
            {
                $ok = false;
            }

            if($ok)
            {
                $ds->commit();
                foreach(array_unique(array_filter($ledgerIdsToRecalculate)) as $ledgerId)
                {
                    $this->_recalculateLedgerBalance((int)$ledgerId);
                }
                if($syncJournalTxId > 0)
                {
                    $this->_syncJournalForTransaction($syncJournalTxId, 'purchase_payment', $savedPaymentId);
                }
                $this->_recalculatePurchaseInvoiceStatus($invoiceId);
                if($oldInvoiceId > 0 && $oldInvoiceId !== $invoiceId)
                {
                    $this->_recalculatePurchaseInvoiceStatus($oldInvoiceId);
                }
                $this->Session->setFlash(__('Purchase payment saved successfully.'), 'flash', array('alert' => 'success'));
            }
            else
            {
                $ds->rollback();
                $this->Session->setFlash(__('Unable to save purchase payment.'), 'flash', array('alert' => 'danger'));
            }
            return $this->redirect(array('action' => 'purchasepayments', $id));
        }

        $scope = $this->_scopeCondition('Ardpurchaseinvoicepayment.project_id', $id);
        $this->Paginator->settings = array(
            'page' => 1,
            'order' => array('Ardpurchaseinvoicepayment.id' => 'desc'),
            'limit' => $this->pageLimit,
            'maxLimit' => $this->maxLimit,
            'conditions' => array($scope)
        );
        $this->set('rows', $this->Paginator->paginate('Ardpurchaseinvoicepayment'));

        $editId = $this->_extractEditIdFromRequest();
        if($editId > 0)
        {
            $editRow = $this->Ardpurchaseinvoicepayment->findById($editId);
            if(!empty($editRow) && $this->_isAllowedProject((int)$editRow['Ardpurchaseinvoicepayment']['project_id']))
            {
                $this->request->data = $editRow;
            }
        }
        if($viewIdFromUrl > 0)
        {
            $viewRowRaw = $this->Ardpurchaseinvoicepayment->findById($viewIdFromUrl);
            if(!empty($viewRowRaw['Ardpurchaseinvoicepayment']) && $this->_isAllowedProject((int)$viewRowRaw['Ardpurchaseinvoicepayment']['project_id']))
            {
                $viewPayment = $viewRowRaw['Ardpurchaseinvoicepayment'];
                $this->set('paymentViewRow', array(
                    'id' => (int)$viewPayment['id'],
                    'invoice' => isset($invoiceList[(int)$viewPayment['purchase_invoice_id']]) ? (string)$invoiceList[(int)$viewPayment['purchase_invoice_id']] : '-',
                    'vendor' => isset($vendorList[(int)$viewPayment['vendor_id']]) ? (string)$vendorList[(int)$viewPayment['vendor_id']] : '-',
                    'amount' => (float)$viewPayment['amount'],
                    'date' => (!empty($viewPayment['payment_date']) && $viewPayment['payment_date'] !== '0000-00-00') ? date('d-M-Y', strtotime((string)$viewPayment['payment_date'])) : '-',
                    'method' => (string)$viewPayment['payment_method'],
                    'reference' => (string)$viewPayment['reference_no'],
                    'note' => (string)$viewPayment['note']
                ));
            }
        }
    }

    public function deletepurchasepayment($id = null, $projectId = null)
    {
        $this->loadModel('Admin.Ardpurchaseinvoicepayment');
        $this->loadModel('Admin.Ardtransaction');
        $row = $this->Ardpurchaseinvoicepayment->findById($id);
        if(empty($row) || !$this->_isAllowedProject((int)$row['Ardpurchaseinvoicepayment']['project_id']))
        {
            $this->Session->setFlash(__('Invalid purchase payment.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'purchasepayments', $projectId));
        }
        $invoiceId = (int)$row['Ardpurchaseinvoicepayment']['purchase_invoice_id'];
        $voucherTxId = (int)$row['Ardpurchaseinvoicepayment']['voucher_transaction_id'];
        $voucherLedgerId = 0;
        $voucherExpenseLedgerId = 0;
        $linkedTransaction = array();
        if($voucherTxId > 0)
        {
            $tx = $this->Ardtransaction->findById($voucherTxId);
            if(!empty($tx) && $this->_isAllowedProject((int)$tx['Ardtransaction']['project_id']))
            {
                $lockMessage = $this->_ardTransactionLockedMessage($tx['Ardtransaction'], (int)$tx['Ardtransaction']['project_id']);
                if($lockMessage !== '')
                {
                    $this->Session->setFlash($lockMessage, 'flash', array('alert' => 'danger'));
                    return $this->redirect(array('action' => 'purchasepayments', $projectId));
                }
                $voucherLedgerId = (int)$tx['Ardtransaction']['ledger_id'];
                $voucherExpenseLedgerId = isset($tx['Ardtransaction']['expense_ledger_id']) ? (int)$tx['Ardtransaction']['expense_ledger_id'] : 0;
                $linkedTransaction = $tx['Ardtransaction'];
            }
        }
        $trashExtra = array();
        if(!empty($linkedTransaction))
        {
            $trashExtra['linked_transaction'] = $linkedTransaction;
        }
        $this->_storeTrashRecord(
            'ardaccounts_construction_purchase_invoice_payments',
            'Ardpurchaseinvoicepayment',
            $row['Ardpurchaseinvoicepayment'],
            isset($row['Ardpurchaseinvoicepayment']['reference_no']) ? (string)$row['Ardpurchaseinvoicepayment']['reference_no'] : '',
            $trashExtra
        );

        $ds = $this->Ardpurchaseinvoicepayment->getDataSource();
        $ds->begin();
        $ok = (bool)$this->Ardpurchaseinvoicepayment->delete($id);
        if($ok && $voucherTxId > 0)
        {
            $txForDelete = $this->Ardtransaction->findById($voucherTxId);
            if(!empty($txForDelete))
            {
                $ok = (bool)$this->Ardtransaction->delete($voucherTxId);
            }
            if($ok)
            {
                $this->_deleteJournalForTransaction($voucherTxId);
            }
        }

        if($ok)
        {
            $ds->commit();
            $this->_recalculatePurchaseInvoiceStatus($invoiceId);
            if($voucherLedgerId > 0)
            {
                $this->_recalculateLedgerBalance($voucherLedgerId);
            }
            if($voucherExpenseLedgerId > 0)
            {
                $this->_recalculateLedgerBalance($voucherExpenseLedgerId);
            }
            $this->Session->setFlash(__('Purchase payment deleted. You can restore it from Trash.'), 'flash', array('alert' => 'success'));
        }
        else
        {
            $ds->rollback();
            $this->Session->setFlash(__('Unable to delete purchase payment.'), 'flash', array('alert' => 'danger'));
        }
        return $this->redirect(array('action' => 'purchasepayments', $projectId));
    }

    public function contracts($id = null)
    {
        $this->loadModel('Admin.Ardcontract');
        $this->loadModel('Admin.Ardcontractbill');
        $this->loadModel('Admin.Ardvendor');
        $this->loadModel('Admin.Ardconstructionproject');
        $id = $this->_activeProjectId($id);

        $this->set('projectName', $this->_projectList());
        $this->set('agencyId', $this->agencyId);
        $this->set('currentProjectId', $id);

        $contractorList = $this->Ardvendor->find('list', array(
            'fields' => array('Ardvendor.id', 'Ardvendor.vendor_name'),
            'conditions' => array($this->_scopeCondition('Ardvendor.project_id', $id)),
            'order' => array('Ardvendor.vendor_name' => 'asc')
        ));
        $this->set('contractorList', $contractorList);

        $projectRows = $this->Ardconstructionproject->find('all', array(
            'fields' => array('Ardconstructionproject.id', 'Ardconstructionproject.name', 'Ardconstructionproject.project_code'),
            'conditions' => array($this->_scopeCondition('Ardconstructionproject.project_id', $id)),
            'order' => array('Ardconstructionproject.id' => 'desc'),
            'recursive' => -1
        ));
        $constructionProjectList = array();
        foreach((array)$projectRows as $pr)
        {
            if(!empty($pr['Ardconstructionproject']))
            {
                $p = $pr['Ardconstructionproject'];
                $constructionProjectList[(int)$p['id']] = $p['name'] . (!empty($p['project_code']) ? ' ('.$p['project_code'].')' : '');
            }
        }
        $this->set('constructionProjectList', $constructionProjectList);

        if($this->request->is(array('post', 'put')))
        {
            $row = isset($this->request->data['Ardcontract']) ? $this->request->data['Ardcontract'] : array();
            $row['project_id'] = $this->_resolveProjectId(isset($row['project_id']) ? $row['project_id'] : null);
            if(!$this->_isAllowedProject($row['project_id']))
            {
                $this->Session->setFlash(__('Please select valid agency/project.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            $row['title'] = trim((string)(isset($row['title']) ? $row['title'] : ''));
            $row['contract_no'] = trim((string)(isset($row['contract_no']) ? $row['contract_no'] : ''));
            if($row['contract_no'] === '')
            {
                $row['contract_no'] = $this->_nextReferenceNo((int)$row['project_id'], 'contract', 'WO-');
            }
            $row['vendor_id'] = (int)(isset($row['vendor_id']) ? $row['vendor_id'] : 0);
            $row['construction_project_id'] = (int)(isset($row['construction_project_id']) ? $row['construction_project_id'] : 0);
            $row['contract_amount'] = round((float)(isset($row['contract_amount']) ? $row['contract_amount'] : 0), 2);
            $row['retention_percent'] = isset($row['retention_percent']) ? (float)$row['retention_percent'] : 5.0;
            if($row['title'] === '' || $row['vendor_id'] <= 0 || $row['contract_amount'] <= 0)
            {
                $this->Session->setFlash(__('Please provide contractor, contract title and contract amount.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            $this->Ardcontract->create();
            if($this->Ardcontract->save(array('Ardcontract' => $row)))
            {
                $this->Session->setFlash(__('Contract / Work Order saved successfully.'), 'flash', array('alert' => 'success'));
            }
            else
            {
                $this->Session->setFlash(__('Unable to save contract.'), 'flash', array('alert' => 'danger'));
            }
            return $this->redirect(array('action' => 'contracts', $id));
        }

        $scope = $this->_scopeCondition('Ardcontract.project_id', $id);
        $this->Paginator->settings = array(
            'page' => 1,
            'order' => array('Ardcontract.id' => 'desc'),
            'limit' => $this->pageLimit,
            'maxLimit' => $this->maxLimit,
            'joins' => array(
                array('table' => 'ardaccounts_construction_vendors', 'alias' => 'Ardvendor', 'type' => 'LEFT', 'conditions' => array('Ardvendor.id=Ardcontract.vendor_id')),
                array('table' => 'ardaccounts_construction_projects', 'alias' => 'Ardconstructionproject', 'type' => 'LEFT', 'conditions' => array('Ardconstructionproject.id=Ardcontract.construction_project_id'))
            ),
            'fields' => array('Ardcontract.*', 'Ardvendor.vendor_name', 'Ardconstructionproject.name'),
            'conditions' => array($scope)
        );
        $rows = $this->Paginator->paginate('Ardcontract');

        $billStats = array();
        $billSummaryRows = $this->Ardcontractbill->query(
            "SELECT contract_id, 
                    COALESCE(SUM(gross_amount), 0) AS total_certified,
                    COALESCE(SUM(retention_amount), 0) AS total_retention,
                    COALESCE(SUM(net_payable), 0) AS total_net_payable,
                    COALESCE(SUM(paid_amount), 0) AS total_paid
             FROM ardaccounts_construction_contract_bills
             WHERE " . $this->_projectSqlCondition('project_id', $id) . "
             GROUP BY contract_id"
        );
        foreach((array)$billSummaryRows as $bs)
        {
            if(isset($bs[0]))
            {
                $bRow = $bs[0];
                $billStats[(int)$bRow['contract_id']] = $bRow;
            }
        }
        $this->set('rows', $rows);
        $this->set('billStats', $billStats);

        $editId = isset($this->request->params['named']['edit']) ? (int)$this->request->params['named']['edit'] : 0;
        if($editId > 0)
        {
            $editRow = $this->Ardcontract->findById($editId);
            if(!empty($editRow) && $this->_isAllowedProject((int)$editRow['Ardcontract']['project_id']))
            {
                $this->request->data = $editRow;
            }
        }
    }

    public function deletecontract($id = null, $projectId = null)
    {
        $this->loadModel('Admin.Ardcontract');
        $this->loadModel('Admin.Ardcontractbill');
        $row = $this->Ardcontract->findById($id);
        if(empty($row) || !$this->_isAllowedProject((int)$row['Ardcontract']['project_id']))
        {
            $this->Session->setFlash(__('Invalid contract.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'contracts', $projectId));
        }
        $billCount = $this->Ardcontractbill->find('count', array(
            'conditions' => array('Ardcontractbill.contract_id' => (int)$id)
        ));
        if($billCount > 0)
        {
            $this->Session->setFlash(__('Cannot delete contract because it has recorded running bills (IPCs). Please delete the bills first.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'contracts', $projectId));
        }
        $this->_storeTrashRecord(
            'ardaccounts_construction_contracts',
            'Ardcontract',
            $row['Ardcontract'],
            isset($row['Ardcontract']['contract_no']) ? (string)$row['Ardcontract']['contract_no'] : ''
        );
        $this->Ardcontract->delete($id);
        $this->Session->setFlash(__('Contract deleted. You can restore it from Trash.'), 'flash', array('alert' => 'success'));
        return $this->redirect(array('action' => 'contracts', $projectId));
    }

    public function contractbills($id = null)
    {
        $this->loadModel('Admin.Ardcontractbill');
        $this->loadModel('Admin.Ardcontract');
        $this->loadModel('Admin.Ardvendor');
        $this->loadModel('Admin.Ardconstructionproject');
        $this->loadModel('Admin.Ardledger');
        $id = $this->_activeProjectId($id);

        $this->set('projectName', $this->_projectList());
        $this->set('agencyId', $this->agencyId);
        $this->set('currentProjectId', $id);

        $contracts = $this->Ardcontract->find('all', array(
            'fields' => array('Ardcontract.id', 'Ardcontract.contract_no', 'Ardcontract.title', 'Ardcontract.vendor_id', 'Ardcontract.construction_project_id', 'Ardcontract.retention_percent', 'Ardcontract.contract_amount'),
            'conditions' => array($this->_scopeCondition('Ardcontract.project_id', $id)),
            'order' => array('Ardcontract.id' => 'desc'),
            'recursive' => -1
        ));
        $contractList = array();
        $contractMap = array();
        foreach((array)$contracts as $c)
        {
            if(!empty($c['Ardcontract']))
            {
                $cid = (int)$c['Ardcontract']['id'];
                $contractList[$cid] = $c['Ardcontract']['contract_no'] . ' - ' . $c['Ardcontract']['title'];
                $contractMap[$cid] = $c['Ardcontract'];
            }
        }
        $this->set('contractList', $contractList);
        $this->set('contractMap', $contractMap);

        $contractorList = $this->Ardvendor->find('list', array(
            'fields' => array('Ardvendor.id', 'Ardvendor.vendor_name'),
            'conditions' => array($this->_scopeCondition('Ardvendor.project_id', $id)),
            'order' => array('Ardvendor.vendor_name' => 'asc')
        ));
        $this->set('contractorList', $contractorList);

        $projectList = $this->Ardconstructionproject->find('list', array(
            'fields' => array('Ardconstructionproject.id', 'Ardconstructionproject.name'),
            'conditions' => array($this->_scopeCondition('Ardconstructionproject.project_id', $id)),
            'order' => array('Ardconstructionproject.name' => 'asc')
        ));
        $this->set('constructionProjectList', $projectList);

        $paymentLedgerList = $this->Ardledger->find('list', array(
            'fields' => array('Ardledger.id', 'Ardledger.name'),
            'conditions' => array($this->_scopeCondition('Ardledger.project_id', $id), 'Ardledger.is_trashed' => 0, 'Ardledger.type !=' => 'expense'),
            'order' => array('Ardledger.name' => 'asc')
        ));
        $this->set('paymentLedgerList', $paymentLedgerList);

        if($this->request->is(array('post', 'put')))
        {
            $row = isset($this->request->data['Ardcontractbill']) ? $this->request->data['Ardcontractbill'] : array();
            $row['project_id'] = $this->_resolveProjectId(isset($row['project_id']) ? $row['project_id'] : null);
            if(!$this->_isAllowedProject($row['project_id']))
            {
                $this->Session->setFlash(__('Please select valid agency/project.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            $contractId = (int)(isset($row['contract_id']) ? $row['contract_id'] : 0);
            if($contractId > 0 && isset($contractMap[$contractId]))
            {
                if(empty($row['vendor_id'])) { $row['vendor_id'] = (int)$contractMap[$contractId]['vendor_id']; }
                if(empty($row['construction_project_id'])) { $row['construction_project_id'] = (int)$contractMap[$contractId]['construction_project_id']; }
            }
            $row['bill_no'] = trim((string)(isset($row['bill_no']) ? $row['bill_no'] : ''));
            if($row['bill_no'] === '')
            {
                $row['bill_no'] = $this->_nextReferenceNo((int)$row['project_id'], 'contract_bill', 'IPC-');
            }
            $gross = round((float)(isset($row['gross_amount']) ? $row['gross_amount'] : 0), 2);
            $retentionPct = isset($row['retention_percent']) ? (float)$row['retention_percent'] : 5.0;
            $retentionAmt = round($gross * ($retentionPct / 100), 2);
            $materialDed = round((float)(isset($row['material_deduction']) ? $row['material_deduction'] : 0), 2);
            $advanceDed = round((float)(isset($row['advance_deduction']) ? $row['advance_deduction'] : 0), 2);
            $taxDed = round((float)(isset($row['tax_deduction']) ? $row['tax_deduction'] : 0), 2);
            $netPayable = round($gross - $retentionAmt - $materialDed - $advanceDed - $taxDed, 2);

            $row['retention_percent'] = $retentionPct;
            $row['retention_amount'] = $retentionAmt;
            $row['net_payable'] = $netPayable;
            $row['bill_date'] = !empty($row['bill_date']) ? $this->_normalizeYmdDate($row['bill_date'], date('Y-m-d')) : date('Y-m-d');

            if($gross <= 0)
            {
                $this->Session->setFlash(__('Please enter valid gross certified amount.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }

            $this->Ardcontractbill->create();
            if($this->Ardcontractbill->save(array('Ardcontractbill' => $row)))
            {
                $billId = (int)$this->Ardcontractbill->id;
                $this->_syncContractBillVoucher($billId);
                $this->Session->setFlash(__('Contractor Running Bill (IPC) certified and posted successfully.'), 'flash', array('alert' => 'success'));
            }
            else
            {
                $this->Session->setFlash(__('Unable to save Running Bill.'), 'flash', array('alert' => 'danger'));
            }
            return $this->redirect(array('action' => 'contractbills', $id));
        }

        $scope = $this->_scopeCondition('Ardcontractbill.project_id', $id);
        $this->Paginator->settings = array(
            'page' => 1,
            'order' => array('Ardcontractbill.id' => 'desc'),
            'limit' => $this->pageLimit,
            'maxLimit' => $this->maxLimit,
            'joins' => array(
                array('table' => 'ardaccounts_construction_contracts', 'alias' => 'Ardcontract', 'type' => 'LEFT', 'conditions' => array('Ardcontract.id=Ardcontractbill.contract_id')),
                array('table' => 'ardaccounts_construction_vendors', 'alias' => 'Ardvendor', 'type' => 'LEFT', 'conditions' => array('Ardvendor.id=Ardcontractbill.vendor_id')),
                array('table' => 'ardaccounts_construction_projects', 'alias' => 'Ardconstructionproject', 'type' => 'LEFT', 'conditions' => array('Ardconstructionproject.id=Ardcontractbill.construction_project_id'))
            ),
            'fields' => array('Ardcontractbill.*', 'Ardcontract.title', 'Ardcontract.contract_no', 'Ardvendor.vendor_name', 'Ardconstructionproject.name'),
            'conditions' => array($scope)
        );
        $this->set('rows', $this->Paginator->paginate('Ardcontractbill'));

        $editId = isset($this->request->params['named']['edit']) ? (int)$this->request->params['named']['edit'] : 0;
        if($editId > 0)
        {
            $editRow = $this->Ardcontractbill->findById($editId);
            if(!empty($editRow) && $this->_isAllowedProject((int)$editRow['Ardcontractbill']['project_id']))
            {
                $this->request->data = $editRow;
            }
        }
    }

    public function deletecontractbill($id = null, $projectId = null)
    {
        $this->loadModel('Admin.Ardcontractbill');
        $this->loadModel('Admin.Ardtransaction');
        $row = $this->Ardcontractbill->findById($id);
        if(empty($row) || !$this->_isAllowedProject((int)$row['Ardcontractbill']['project_id']))
        {
            $this->Session->setFlash(__('Invalid running bill.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'contractbills', $projectId));
        }
        if((float)$row['Ardcontractbill']['paid_amount'] > 0.001)
        {
            $this->Session->setFlash(__('Cannot delete running bill with recorded payments.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'contractbills', $projectId));
        }
        $voucherTxId = (int)(isset($row['Ardcontractbill']['voucher_transaction_id']) ? $row['Ardcontractbill']['voucher_transaction_id'] : 0);
        $this->_storeTrashRecord(
            'ardaccounts_construction_contract_bills',
            'Ardcontractbill',
            $row['Ardcontractbill'],
            isset($row['Ardcontractbill']['bill_no']) ? (string)$row['Ardcontractbill']['bill_no'] : ''
        );
        $this->Ardcontractbill->delete($id);
        if($voucherTxId > 0)
        {
            $this->_deleteJournalForTransaction($voucherTxId);
            $tx = $this->Ardtransaction->findById($voucherTxId);
            if(!empty($tx['Ardtransaction']))
            {
                $this->Ardtransaction->delete($voucherTxId);
                $this->_recalculateLedgerBalance((int)$tx['Ardtransaction']['ledger_id']);
                if(!empty($tx['Ardtransaction']['income_ledger_id']))
                {
                    $this->_recalculateLedgerBalance((int)$tx['Ardtransaction']['income_ledger_id']);
                }
            }
        }
        $this->Session->setFlash(__('Running bill (IPC) deleted.'), 'flash', array('alert' => 'success'));
        return $this->redirect(array('action' => 'contractbills', $projectId));
    }

    protected function _syncContractBillVoucher($billId, $existingVoucherTxId = 0)
    {
        $this->loadModel('Admin.Ardcontractbill');
        $this->loadModel('Admin.Ardvendor');
        $billId = (int)$billId;
        if($billId <= 0)
        {
            return 0;
        }
        $bill = $this->Ardcontractbill->findById($billId);
        if(empty($bill['Ardcontractbill']) || !$this->_isAllowedProject((int)$bill['Ardcontractbill']['project_id']))
        {
            return 0;
        }
        $row = $bill['Ardcontractbill'];
        $projectId = (int)$row['project_id'];
        $netPayable = round((float)$row['net_payable'], 2);
        if($netPayable <= 0)
        {
            return 0;
        }
        $wipLedgerId = $this->_ardDefaultLedgerId($projectId, 'construction_wip_ledger_id', 'Construction WIP', 'asset');
        $subcontractorPayableLedgerId = $this->_ardDefaultLedgerId($projectId, 'subcontractor_payable_ledger_id', 'Subcontractor & Civil Labour Payable', 'liability');
        if($wipLedgerId <= 0 || $subcontractorPayableLedgerId <= 0)
        {
            return 0;
        }
        $vendorName = '';
        if(!empty($row['vendor_id']))
        {
            $vendorName = trim((string)$this->Ardvendor->field('vendor_name', array('Ardvendor.id' => (int)$row['vendor_id'])));
        }
        if($vendorName === '')
        {
            $vendorName = 'Contractor #' . (int)$row['vendor_id'];
        }
        $refNo = trim((string)$row['bill_no']);
        if($refNo === '')
        {
            $refNo = 'IPC-' . $billId;
        }
        $entryDate = !empty($row['bill_date']) ? $row['bill_date'] : date('Y-m-d');
        $txId = $this->_ardPostAutoVoucher(
            $projectId,
            $wipLedgerId,
            'income',
            $netPayable,
            $refNo,
            $entryDate,
            'Contractor IPC Certified: ' . $vendorName . ' | ' . $refNo . ' (Gross: Rs.' . number_format($row['gross_amount'],2) . ', Retention: Rs.' . number_format($row['retention_amount'],2) . ')',
            array(
                'existing_id' => $existingVoucherTxId > 0 ? $existingVoucherTxId : (int)$row['voucher_transaction_id'],
                'income_ledger_id' => $subcontractorPayableLedgerId,
                'source_type' => 'contract_bill',
                'source_id' => $billId,
                'status' => 'Posted'
            )
        );
        if($txId > 0)
        {
            try
            {
                $this->Ardcontractbill->query("UPDATE `ardaccounts_construction_contract_bills` SET `voucher_transaction_id`=" . (int)$txId . " WHERE `id`=" . (int)$billId);
            }
            catch(Exception $e) {}
        }
        return $txId;
    }

    public function reorderrules($id = null)
    {
        $this->loadModel('Admin.Ardreorderrule');
        $this->loadModel('Admin.Ardvendor');
        $this->loadModel('Admin.Ardsite');
        $id = $this->_activeProjectId($id);
        $this->set('projectName', $this->_projectList());
        $this->set('agencyId', $this->agencyId);
        $this->set('currentProjectId', $id);
        $this->set('vendorList', $this->Ardvendor->find('list', array(
            'fields' => array('Ardvendor.id', 'Ardvendor.vendor_name'),
            'conditions' => array($this->_scopeCondition('Ardvendor.project_id', $id)),
            'order' => array('Ardvendor.vendor_name' => 'asc')
        )));
        $this->set('siteList', $this->Ardsite->find('list', array(
            'fields' => array('Ardsite.id', 'Ardsite.site_name'),
            'conditions' => array($this->_scopeCondition('Ardsite.project_id', $id)),
            'order' => array('Ardsite.site_name' => 'asc')
        )));
        $constructionOptions = $this->_constructionMaterialUnitOptions((int)$id);
        $this->set('constructionMaterialOptions', $constructionOptions['materials']);
        $this->set('constructionUnitOptions', $constructionOptions['units']);
        $this->set('constructionMaterialUnitMap', isset($constructionOptions['material_units']) ? $constructionOptions['material_units'] : array());

        if($this->request->is('post'))
        {
            $row = isset($this->request->data['Ardreorderrule']) ? $this->request->data['Ardreorderrule'] : array();
            $row['project_id'] = $this->_resolveProjectId(isset($row['project_id']) ? $row['project_id'] : null);
            if(!$this->_isAllowedProject($row['project_id']))
            {
                $this->Session->setFlash(__('Please select valid agency/project.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            $row['enabled'] = !empty($row['enabled']) ? 1 : 0;
            $this->Ardreorderrule->create();
            if($this->Ardreorderrule->save(array('Ardreorderrule' => $row)))
            {
                $this->Session->setFlash(__('Reorder rule saved successfully.'), 'flash', array('alert' => 'success'));
            }
            else
            {
                $this->Session->setFlash(__('Unable to save reorder rule.'), 'flash', array('alert' => 'danger'));
            }
            return $this->redirect(array('action' => 'reorderrules', $id));
        }

        $scope = $this->_scopeCondition('Ardreorderrule.project_id', $id);
        $this->Paginator->settings = array(
            'page' => 1,
            'order' => array('Ardreorderrule.id' => 'desc'),
            'limit' => $this->pageLimit,
            'maxLimit' => $this->maxLimit,
            'conditions' => array($scope)
        );
        $this->set('rows', $this->Paginator->paginate('Ardreorderrule'));

        $editId = isset($this->request->params['named']['edit']) ? (int)$this->request->params['named']['edit'] : 0;
        if($editId > 0)
        {
            $editRow = $this->Ardreorderrule->findById($editId);
            if(!empty($editRow) && $this->_isAllowedProject((int)$editRow['Ardreorderrule']['project_id']))
            {
                $this->request->data = $editRow;
                $editProjectOptions = $this->_constructionMaterialUnitOptions((int)$editRow['Ardreorderrule']['project_id']);
                $this->set('constructionMaterialOptions', $editProjectOptions['materials']);
                $this->set('constructionUnitOptions', $editProjectOptions['units']);
                $this->set('constructionMaterialUnitMap', isset($editProjectOptions['material_units']) ? $editProjectOptions['material_units'] : array());
            }
        }
    }

    public function deletereorderrule($id = null, $projectId = null)
    {
        $this->loadModel('Admin.Ardreorderrule');
        $row = $this->Ardreorderrule->findById($id);
        if(empty($row) || !$this->_isAllowedProject((int)$row['Ardreorderrule']['project_id']))
        {
            $this->Session->setFlash(__('Invalid reorder rule.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'reorderrules', $projectId));
        }
        $this->_storeTrashRecord(
            'ardaccounts_construction_reorder_rules',
            'Ardreorderrule',
            $row['Ardreorderrule'],
            isset($row['Ardreorderrule']['material_type']) ? (string)$row['Ardreorderrule']['material_type'] : ''
        );
        $this->Ardreorderrule->delete($id);
        $this->Session->setFlash(__('Reorder rule deleted. You can restore it from Trash.'), 'flash', array('alert' => 'success'));
        return $this->redirect(array('action' => 'reorderrules', $projectId));
    }

    public function hrpayrollautofill($id = null)
    {
        $this->autoRender = false;
        $this->response->type('json');
        $this->loadModel('Admin.Ardhremployee');

        $projectId = 0;
        if(isset($this->request->query['project_id']))
        {
            $projectId = (int)$this->request->query['project_id'];
        }
        if($projectId <= 0 && isset($id) && (int)$id > 0)
        {
            $projectId = (int)$id;
        }
        $projectId = $this->_resolveProjectId($projectId);
        if(!$this->_isAllowedProject($projectId))
        {
            $this->response->body(json_encode(array('ok' => 0, 'message' => __('Invalid agency.'))));
            return $this->response;
        }

        $employeeId = isset($this->request->query['employee_id']) ? (int)$this->request->query['employee_id'] : 0;
        $payrollMonth = $this->_normalizePayrollMonthValue(isset($this->request->query['payroll_month']) ? $this->request->query['payroll_month'] : '', '');
        if($employeeId <= 0 || $payrollMonth === '')
        {
            $this->response->body(json_encode(array('ok' => 0, 'message' => __('Select employee and payroll month first.'))));
            return $this->response;
        }

        $employee = (array)$this->Ardhremployee->find('first', array(
            'conditions' => array(
                'Ardhremployee.id' => $employeeId,
                'Ardhremployee.project_id' => $projectId
            ),
            'recursive' => -1
        ));
        if(empty($employee['Ardhremployee']['id']))
        {
            $this->response->body(json_encode(array('ok' => 0, 'message' => __('Invalid employee for selected agency.'))));
            return $this->response;
        }

        $summary = $this->_hrAttendancePayrollSummary($projectId, $employee, $payrollMonth);
        $payload = array(
            'ok' => 1,
            'summary' => array(
                'project_id' => (int)$summary['project_id'],
                'employee_id' => (int)$summary['employee_id'],
                'payroll_month' => (string)$summary['payroll_month'],
                'salary_type' => (string)$summary['salary_type'],
                'base_salary' => (float)$summary['base_salary'],
                'working_days' => (float)$summary['working_days'],
                'present_days' => (float)$summary['present_days'],
                'absent_days' => (float)$summary['absent_days'],
                'leave_days' => (float)$summary['leave_days'],
                'half_days' => (float)$summary['half_days'],
                'overtime_hours' => (float)$summary['overtime_hours'],
                'overtime_rate' => (float)$summary['overtime_rate'],
                'overtime_amount' => (float)$summary['overtime_amount'],
                'gross_pay' => (float)$summary['gross_pay'],
                'commission_earned' => (float)$summary['commission_earned'],
                'commission_paid' => (float)$summary['commission_paid'],
                'commission_balance' => (float)$summary['commission_balance'],
                'commission_amount' => (float)$summary['commission_amount'],
                'net_pay_estimated' => (float)$summary['net_pay_estimated']
            )
        );
        $this->response->body(json_encode($payload));
        return $this->response;
    }

    public function hrpayrollentries($id = null)
    {
        $this->loadModel('Admin.Ardhpayroll');
        $this->loadModel('Admin.Ardhremployee');
        $this->loadModel('Admin.Ardhattendance');
        $id = $this->_activeProjectId($id);
        $employeeScope = $this->_hrEmployeeScopeFromRequest('all');
        $employeeScopeLabel = $this->_hrEmployeeScopeLabel($employeeScope);
        $employeeScopeQuery = $this->_hrEmployeeScopeQuery($employeeScope);
        $employeeTypeConditions = $this->_hrEmployeeScopeConditions('Ardhremployee', $employeeScope);
        $this->set('projectName', $this->_projectList());
        $this->set('agencyId', $this->agencyId);
        $this->set('currentProjectId', $id);
        $this->set('employeeScope', $employeeScope);
        $this->set('employeeScopeLabel', $employeeScopeLabel);
        $this->set('employeeScopeQuery', $employeeScopeQuery);
        $employeeListConditions = array($this->_scopeCondition('Ardhremployee.project_id', $id));
        if(!empty($employeeTypeConditions))
        {
            $employeeListConditions = array_merge($employeeListConditions, $employeeTypeConditions);
        }
        $employeeList = $this->Ardhremployee->find('list', array(
            'fields' => array('Ardhremployee.id', 'Ardhremployee.full_name'),
            'conditions' => $employeeListConditions,
            'order' => array('Ardhremployee.full_name' => 'asc')
        ));
        $this->set('employeeList', $employeeList);
        $scopedEmployeeIds = array_values(array_unique(array_map('intval', array_keys((array)$employeeList))));

        $sheetMonth = $this->_normalizePayrollMonthValue(isset($this->request->query['sheet_month']) ? $this->request->query['sheet_month'] : '', date('Y-m'));
        $sheetEmployeeId = isset($this->request->query['sheet_employee_id']) ? (int)$this->request->query['sheet_employee_id'] : 0;
        $sheetRows = array();
        $sheetEmployeeScope = $this->_scopeCondition('Ardhremployee.project_id', $id);
        $sheetEmployeeConditions = array();
        if(!empty($sheetEmployeeScope))
        {
            $sheetEmployeeConditions[] = $sheetEmployeeScope;
        }
        if(!empty($employeeTypeConditions))
        {
            $sheetEmployeeConditions = array_merge($sheetEmployeeConditions, $employeeTypeConditions);
        }
        if($sheetEmployeeId > 0)
        {
            $sheetEmployeeConditions['Ardhremployee.id'] = $sheetEmployeeId;
        }
        $sheetEmployees = (array)$this->Ardhremployee->find('all', array(
            'fields' => array(
                'Ardhremployee.id',
                'Ardhremployee.project_id',
                'Ardhremployee.linked_user_id',
                'Ardhremployee.employee_code',
                'Ardhremployee.full_name',
                'Ardhremployee.salary_type',
                'Ardhremployee.base_salary',
                'Ardhremployee.overtime_rate',
                'Ardhremployee.status'
            ),
            'conditions' => $sheetEmployeeConditions,
            'order' => array('Ardhremployee.full_name' => 'asc'),
            'recursive' => -1
        ));
        foreach($sheetEmployees as $sheetEmployee)
        {
            $employeeProjectId = isset($sheetEmployee['Ardhremployee']['project_id']) ? (int)$sheetEmployee['Ardhremployee']['project_id'] : 0;
            if($employeeProjectId <= 0)
            {
                $employeeProjectId = (int)$id;
            }
            $sheetRows[] = $this->_hrAttendancePayrollSummary($employeeProjectId, $sheetEmployee, $sheetMonth);
        }
        $this->set('attendanceSheetMonth', $sheetMonth);
        $this->set('attendanceSheetEmployeeId', $sheetEmployeeId);
        $this->set('attendanceSheetRows', $sheetRows);
        $attendanceSheetYear = (int)date('Y');
        if(preg_match('/^(\d{4})-\d{2}$/', (string)$sheetMonth, $yearParts))
        {
            $attendanceSheetYear = (int)$yearParts[1];
        }
        if($attendanceSheetYear <= 0)
        {
            $attendanceSheetYear = (int)date('Y');
        }
        $attendanceCalendarEmployee = array();
        $attendanceCalendarMap = array();
        if($sheetEmployeeId > 0)
        {
            foreach((array)$sheetEmployees as $sheetEmployeeRow)
            {
                $employeeIdCandidate = isset($sheetEmployeeRow['Ardhremployee']['id']) ? (int)$sheetEmployeeRow['Ardhremployee']['id'] : 0;
                if($employeeIdCandidate === (int)$sheetEmployeeId)
                {
                    $attendanceCalendarEmployee = (array)$sheetEmployeeRow;
                    break;
                }
            }
            if(empty($attendanceCalendarEmployee))
            {
                $singleEmployeeConditions = array('Ardhremployee.id' => (int)$sheetEmployeeId);
                $sheetEmployeeScopeForSingle = $this->_scopeCondition('Ardhremployee.project_id', $id);
                if(!empty($sheetEmployeeScopeForSingle))
                {
                    $singleEmployeeConditions[] = $sheetEmployeeScopeForSingle;
                }
                if(!empty($employeeTypeConditions))
                {
                    $singleEmployeeConditions = array_merge($singleEmployeeConditions, $employeeTypeConditions);
                }
                $attendanceCalendarEmployee = (array)$this->Ardhremployee->find('first', array(
                    'fields' => array(
                        'Ardhremployee.id',
                        'Ardhremployee.project_id',
                        'Ardhremployee.employee_code',
                        'Ardhremployee.full_name'
                    ),
                    'conditions' => $singleEmployeeConditions,
                    'recursive' => -1
                ));
            }
            if(!empty($attendanceCalendarEmployee['Ardhremployee']['id']))
            {
                $calendarProjectId = isset($attendanceCalendarEmployee['Ardhremployee']['project_id']) ? (int)$attendanceCalendarEmployee['Ardhremployee']['project_id'] : 0;
                if($calendarProjectId <= 0)
                {
                    $calendarProjectId = (int)$id;
                }
                $calendarStart = sprintf('%04d-01-01', (int)$attendanceSheetYear);
                $calendarEnd = sprintf('%04d-12-31', (int)$attendanceSheetYear);
                $attendanceCalendarRows = (array)$this->Ardhattendance->find('all', array(
                    'fields' => array(
                        'Ardhattendance.attendance_date',
                        'Ardhattendance.attendance_status',
                        'Ardhattendance.in_time',
                        'Ardhattendance.out_time',
                        'Ardhattendance.overtime_hours',
                        'Ardhattendance.note'
                    ),
                    'conditions' => array(
                        'Ardhattendance.project_id' => (int)$calendarProjectId,
                        'Ardhattendance.employee_id' => (int)$sheetEmployeeId,
                        'Ardhattendance.attendance_date >=' => $calendarStart,
                        'Ardhattendance.attendance_date <=' => $calendarEnd
                    ),
                    'order' => array('Ardhattendance.attendance_date' => 'asc', 'Ardhattendance.id' => 'asc'),
                    'recursive' => -1
                ));
                foreach((array)$attendanceCalendarRows as $attendanceCalendarRow)
                {
                    $attendanceDateKey = isset($attendanceCalendarRow['Ardhattendance']['attendance_date']) ? trim((string)$attendanceCalendarRow['Ardhattendance']['attendance_date']) : '';
                    if($attendanceDateKey === '')
                    {
                        continue;
                    }
                    $attendanceCalendarMap[$attendanceDateKey] = array(
                        'status' => isset($attendanceCalendarRow['Ardhattendance']['attendance_status']) ? strtolower(trim((string)$attendanceCalendarRow['Ardhattendance']['attendance_status'])) : '',
                        'in_time' => isset($attendanceCalendarRow['Ardhattendance']['in_time']) ? trim((string)$attendanceCalendarRow['Ardhattendance']['in_time']) : '',
                        'out_time' => isset($attendanceCalendarRow['Ardhattendance']['out_time']) ? trim((string)$attendanceCalendarRow['Ardhattendance']['out_time']) : '',
                        'overtime_hours' => isset($attendanceCalendarRow['Ardhattendance']['overtime_hours']) ? (float)$attendanceCalendarRow['Ardhattendance']['overtime_hours'] : 0,
                        'note' => isset($attendanceCalendarRow['Ardhattendance']['note']) ? trim((string)$attendanceCalendarRow['Ardhattendance']['note']) : ''
                    );
                }
            }
        }
        $this->set('attendanceSheetYear', (int)$attendanceSheetYear);
        $this->set('attendanceSheetCalendarEmployee', $attendanceCalendarEmployee);
        $this->set('attendanceSheetCalendarMap', $attendanceCalendarMap);

        if(!$this->request->is('post'))
        {
            $prefillEmployeeId = isset($this->request->query['prefill_employee_id']) ? (int)$this->request->query['prefill_employee_id'] : 0;
            $prefillMonth = $this->_normalizePayrollMonthValue(isset($this->request->query['prefill_month']) ? $this->request->query['prefill_month'] : '', $sheetMonth);
            if($prefillEmployeeId > 0 && $prefillMonth !== '')
            {
                $prefillConditions = array('Ardhremployee.id' => $prefillEmployeeId);
                $prefillScope = $this->_scopeCondition('Ardhremployee.project_id', $id);
                if(!empty($prefillScope))
                {
                    $prefillConditions[] = $prefillScope;
                }
                if(!empty($employeeTypeConditions))
                {
                    $prefillConditions = array_merge($prefillConditions, $employeeTypeConditions);
                }
                $prefillEmployee = (array)$this->Ardhremployee->find('first', array(
                    'conditions' => $prefillConditions,
                    'recursive' => -1
                ));
                if(!empty($prefillEmployee['Ardhremployee']['id']))
                {
                    $prefillProjectId = isset($prefillEmployee['Ardhremployee']['project_id']) ? (int)$prefillEmployee['Ardhremployee']['project_id'] : (int)$id;
                    $prefillSummary = $this->_hrAttendancePayrollSummary($prefillProjectId, $prefillEmployee, $prefillMonth);
                    $this->request->data['Ardhpayroll'] = array(
                        'project_id' => $prefillProjectId,
                        'employee_id' => (int)$prefillSummary['employee_id'],
                        'payroll_month' => (string)$prefillSummary['payroll_month'],
                        'working_days' => (float)$prefillSummary['working_days'],
                        'present_days' => (float)$prefillSummary['present_days'],
                        'overtime_hours' => (float)$prefillSummary['overtime_hours'],
                        'gross_pay' => (float)$prefillSummary['gross_pay'],
                        'commission_amount' => (float)$prefillSummary['commission_amount'],
                        'bonus' => 0,
                        'deductions' => 0,
                        'paid_amount' => 0,
                        'status' => 'unpaid',
                        'note' => __('Auto-filled from attendance sheet.')
                    );
                }
            }
        }

        if($this->request->is('post'))
        {
            $row = isset($this->request->data['Ardhpayroll']) ? $this->request->data['Ardhpayroll'] : array();
            $row['id'] = isset($row['id']) ? (int)$row['id'] : 0;
            $row['project_id'] = $this->_resolveProjectId(isset($row['project_id']) ? $row['project_id'] : null);
            if(!$this->_isAllowedProject($row['project_id']))
            {
                $this->Session->setFlash(__('Please select valid agency/project.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            $employeeId = (int)$row['employee_id'];
            $employee = $this->Ardhremployee->findById($employeeId);
            if(empty($employee) || !$this->_isAllowedProject((int)$employee['Ardhremployee']['project_id']))
            {
                $this->Session->setFlash(__('Please select valid employee.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            if(!$this->_hrEmployeeMatchesScope($employee, $employeeScope))
            {
                $this->Session->setFlash(__('Selected employee is outside current labour/staff scope.'), 'flash', array('alert' => 'danger'));
                return $this->redirect(array('action' => 'hrpayrollentries', $id, '?' => $employeeScopeQuery));
            }
            $row['payroll_month'] = $this->_normalizePayrollMonthValue(isset($row['payroll_month']) ? $row['payroll_month'] : '', '');
            if($row['payroll_month'] === '')
            {
                $this->Session->setFlash(__('Please enter valid payroll month (YYYY-MM).'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            $autoSummary = $this->_hrAttendancePayrollSummary((int)$row['project_id'], $employee, (string)$row['payroll_month']);
            $row['working_days'] = round((float)(isset($row['working_days']) ? $row['working_days'] : 0), 2);
            if($row['working_days'] <= 0)
            {
                $row['working_days'] = (float)$autoSummary['working_days'];
            }
            $row['present_days'] = round((float)(isset($row['present_days']) ? $row['present_days'] : 0), 2);
            if($row['present_days'] <= 0)
            {
                $row['present_days'] = (float)$autoSummary['present_days'];
            }
            $row['overtime_hours'] = round((float)(isset($row['overtime_hours']) ? $row['overtime_hours'] : 0), 2);
            if($row['overtime_hours'] <= 0 && (float)$autoSummary['overtime_hours'] > 0)
            {
                $row['overtime_hours'] = (float)$autoSummary['overtime_hours'];
            }

            $gross = round((float)$row['gross_pay'], 2);
            $bonus = round((float)$row['bonus'], 2);
            $deductions = round((float)$row['deductions'], 2);
            $commissionAmount = round((float)(isset($row['commission_amount']) ? $row['commission_amount'] : 0), 2);
            if($commissionAmount < 0)
            {
                $commissionAmount = 0;
            }
            if($gross <= 0)
            {
                $gross = round((float)$autoSummary['gross_pay'], 2);
                if($gross <= 0)
                {
                    $gross = round((float)$employee['Ardhremployee']['base_salary'], 2);
                }
            }
            if($commissionAmount <= 0 && (float)$autoSummary['commission_amount'] > 0)
            {
                $commissionAmount = round((float)$autoSummary['commission_amount'], 2);
            }
            $netPay = round($gross + $bonus + $commissionAmount - $deductions, 2);
            if($netPay < 0)
            {
                $netPay = 0;
            }
            $paid = round((float)$row['paid_amount'], 2);
            if($paid < 0)
            {
                $paid = 0;
            }
            $due = max(0, $netPay - $paid);
            $status = 'unpaid';
            if($netPay > 0 && $paid >= $netPay)
            {
                $status = 'paid';
            }
            elseif($paid > 0)
            {
                $status = 'partial';
            }
            $row['gross_pay'] = $gross;
            $row['commission_amount'] = $commissionAmount;
            $row['net_pay'] = $netPay;
            $row['paid_amount'] = $paid;
            $row['due_amount'] = $due;
            $row['status'] = $status;

            $this->Ardhpayroll->create();
            if($this->Ardhpayroll->save(array('Ardhpayroll' => $row)))
            {
                $this->Session->setFlash(__('HR payroll entry saved successfully.'), 'flash', array('alert' => 'success'));
            }
            else
            {
                $this->Session->setFlash(__('Unable to save HR payroll entry.'), 'flash', array('alert' => 'danger'));
            }
            return $this->redirect(array('action' => 'hrpayrollentries', $id, '?' => $employeeScopeQuery));
        }

        $scope = $this->_scopeCondition('Ardhpayroll.project_id', $id);
        $payrollListingConditions = array($scope);
        if($employeeScope !== 'all')
        {
            if(empty($scopedEmployeeIds))
            {
                $payrollListingConditions['Ardhpayroll.id'] = 0;
            }
            else
            {
                $payrollListingConditions['Ardhpayroll.employee_id'] = $scopedEmployeeIds;
            }
        }
        $this->Paginator->settings = array(
            'page' => 1,
            'order' => array('Ardhpayroll.id' => 'desc'),
            'limit' => $this->pageLimit,
            'maxLimit' => $this->maxLimit,
            'conditions' => $payrollListingConditions
        );
        $this->set('rows', $this->Paginator->paginate('Ardhpayroll'));

        $editId = isset($this->request->params['named']['edit']) ? (int)$this->request->params['named']['edit'] : 0;
        if($editId > 0)
        {
            $editRow = $this->Ardhpayroll->findById($editId);
            if(!empty($editRow) && $this->_isAllowedProject((int)$editRow['Ardhpayroll']['project_id']))
            {
                $editEmployee = $this->Ardhremployee->findById((int)$editRow['Ardhpayroll']['employee_id']);
                if($this->_hrEmployeeMatchesScope($editEmployee, $employeeScope))
                {
                    $this->request->data = $editRow;
                }
            }
        }
    }

    public function deletehrpayrollentry($id = null, $projectId = null)
    {
        $this->loadModel('Admin.Ardhpayroll');
        $this->loadModel('Admin.Ardhremployee');
        $employeeScope = $this->_hrEmployeeScopeFromRequest('all');
        $employeeScopeQuery = $this->_hrEmployeeScopeQuery($employeeScope);
        $row = $this->Ardhpayroll->findById($id);
        if(empty($row) || !$this->_isAllowedProject((int)$row['Ardhpayroll']['project_id']))
        {
            $this->Session->setFlash(__('Invalid payroll entry.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'hrpayrollentries', $projectId, '?' => $employeeScopeQuery));
        }
        $employeeRow = $this->Ardhremployee->findById((int)$row['Ardhpayroll']['employee_id']);
        if(!$this->_hrEmployeeMatchesScope($employeeRow, $employeeScope))
        {
            $this->Session->setFlash(__('Selected payroll entry is outside current labour/staff scope.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'hrpayrollentries', $projectId, '?' => $employeeScopeQuery));
        }
        $this->_storeTrashRecord(
            'ardaccounts_hr_payroll',
            'Ardhpayroll',
            $row['Ardhpayroll'],
            isset($row['Ardhpayroll']['payroll_month']) ? (string)$row['Ardhpayroll']['payroll_month'] : ''
        );
        $this->Ardhpayroll->delete($id);
        $this->Session->setFlash(__('Payroll entry deleted. You can restore it from Trash.'), 'flash', array('alert' => 'success'));
        return $this->redirect(array('action' => 'hrpayrollentries', $projectId, '?' => $employeeScopeQuery));
    }

    public function generatebulkpayroll($id = null)
    {
        if(!$this->request->is('post'))
        {
            return $this->redirect(array('action' => 'hrpayrollentries', $id));
        }
        $this->loadModel('Admin.Ardhpayroll');
        $this->loadModel('Admin.Ardhremployee');
        $id = $this->_activeProjectId($id);

        $postData = isset($this->request->data['BulkPayroll']) ? $this->request->data['BulkPayroll'] : array();
        $targetProjectId = isset($postData['project_id']) ? $this->_resolveProjectId($postData['project_id']) : $id;
        if(!$this->_isAllowedProject($targetProjectId))
        {
            $this->Session->setFlash(__('Please select valid agency/project.'), 'flash', array('alert' => 'danger'));
            return $this->redirect($this->referer());
        }

        $payrollMonth = isset($postData['payroll_month']) ? trim((string)$postData['payroll_month']) : '';
        $payrollMonth = $this->_normalizePayrollMonthValue($payrollMonth, date('Y-m'));
        if($payrollMonth === '')
        {
            $this->Session->setFlash(__('Please select valid payroll month.'), 'flash', array('alert' => 'danger'));
            return $this->redirect($this->referer());
        }

        $employeeScope = isset($postData['employee_scope']) ? $this->_normalizeHrEmployeeScope($postData['employee_scope']) : 'all';
        $overwrite = !empty($postData['overwrite']);

        $employeeConditions = array(
            $this->_scopeCondition('Ardhremployee.project_id', $targetProjectId),
            'Ardhremployee.status' => 'active'
        );
        $scopeConditions = $this->_hrEmployeeScopeConditions('Ardhremployee', $employeeScope);
        if(!empty($scopeConditions))
        {
            $employeeConditions = array_merge($employeeConditions, $scopeConditions);
        }

        $employees = (array)$this->Ardhremployee->find('all', array(
            'conditions' => $employeeConditions,
            'order' => array('Ardhremployee.full_name' => 'asc'),
            'recursive' => -1
        ));

        if(empty($employees))
        {
            $this->Session->setFlash(__('No active employees found in selected scope.'), 'flash', array('alert' => 'warning'));
            return $this->redirect(array('action' => 'hrpayrollentries', $targetProjectId, '?' => array('sheet_month' => $payrollMonth, 'employee_scope' => $employeeScope)));
        }

        $createdCount = 0;
        $updatedCount = 0;
        $skippedCount = 0;

        foreach($employees as $emp)
        {
            $empData = isset($emp['Ardhremployee']) ? $emp['Ardhremployee'] : array();
            $empId = (int)$empData['id'];
            $empProjectId = !empty($empData['project_id']) ? (int)$empData['project_id'] : (int)$targetProjectId;

            $existing = $this->Ardhpayroll->find('first', array(
                'conditions' => array(
                    'Ardhpayroll.project_id' => $empProjectId,
                    'Ardhpayroll.employee_id' => $empId,
                    'Ardhpayroll.payroll_month' => $payrollMonth
                ),
                'recursive' => -1
            ));

            $summary = $this->_hrAttendancePayrollSummary($empProjectId, $emp, $payrollMonth);
            $gross = round((float)$summary['gross_pay'], 2);
            $comm = round((float)$summary['commission_amount'], 2);

            if(!empty($existing['Ardhpayroll']['id']))
            {
                if($overwrite && strtolower(trim((string)$existing['Ardhpayroll']['status'])) === 'unpaid')
                {
                    $existingBonus = (float)$existing['Ardhpayroll']['bonus'];
                    $existingDeductions = (float)$existing['Ardhpayroll']['deductions'];
                    $net = round($gross + $comm + $existingBonus - $existingDeductions, 2);
                    if($net < 0)
                    {
                        $net = 0;
                    }
                    $paid = (float)$existing['Ardhpayroll']['paid_amount'];
                    $due = max(0, $net - $paid);

                    $this->Ardhpayroll->id = (int)$existing['Ardhpayroll']['id'];
                    $this->Ardhpayroll->save(array(
                        'working_days' => (float)$summary['working_days'],
                        'present_days' => (float)$summary['present_days'],
                        'overtime_hours' => (float)$summary['overtime_hours'],
                        'gross_pay' => $gross,
                        'commission_amount' => $comm,
                        'net_pay' => $net,
                        'due_amount' => $due,
                        'note' => __('Auto-recalculated from attendance.')
                    ));
                    $updatedCount++;
                }
                else
                {
                    $skippedCount++;
                }
                continue;
            }

            $netPay = round($gross + $comm, 2);
            if($netPay < 0)
            {
                $netPay = 0;
            }

            $payload = array(
                'project_id' => $empProjectId,
                'employee_id' => $empId,
                'payroll_month' => $payrollMonth,
                'working_days' => (float)$summary['working_days'],
                'present_days' => (float)$summary['present_days'],
                'overtime_hours' => (float)$summary['overtime_hours'],
                'gross_pay' => $gross,
                'commission_amount' => $comm,
                'bonus' => 0.00,
                'deductions' => 0.00,
                'net_pay' => $netPay,
                'paid_amount' => 0.00,
                'due_amount' => $netPay,
                'status' => 'unpaid',
                'note' => __('Bulk generated from attendance.')
            );

            $this->Ardhpayroll->create();
            if($this->Ardhpayroll->save(array('Ardhpayroll' => $payload)))
            {
                $createdCount++;
            }
        }

        $msg = sprintf(
            __('Bulk payroll for %s processed: %d created, %d updated, %d skipped.'),
            date('F Y', strtotime($payrollMonth . '-01')),
            $createdCount,
            $updatedCount,
            $skippedCount
        );
        $this->Session->setFlash($msg, 'flash', array('alert' => 'success'));
        return $this->redirect(array('action' => 'hrpayrollentries', $targetProjectId, '?' => array('sheet_month' => $payrollMonth, 'employee_scope' => $employeeScope)));
    }

    public function printpayslip($id = null)
    {
        $this->loadModel('Admin.Ardhpayroll');
        $this->loadModel('Admin.Ardhremployee');
        $this->loadModel('Admin.Ardhpayment');
        $payroll = $this->Ardhpayroll->findById((int)$id);
        if(empty($payroll) || !$this->_isAllowedProject((int)$payroll['Ardhpayroll']['project_id']))
        {
            throw new NotFoundException(__('Salary slip not found.'));
        }
        $employee = $this->Ardhremployee->findById((int)$payroll['Ardhpayroll']['employee_id']);
        if(empty($employee))
        {
            throw new NotFoundException(__('Employee not found.'));
        }
        $projectId = (int)$payroll['Ardhpayroll']['project_id'];
        $projectList = $this->_projectList();
        $agencyName = !empty($projectList[$projectId]) ? $projectList[$projectId] : 'White Villas';

        $payments = (array)$this->Ardhpayment->find('all', array(
            'conditions' => array(
                'Ardhpayment.payroll_id' => (int)$payroll['Ardhpayroll']['id']
            ),
            'order' => array('Ardhpayment.payment_date' => 'asc', 'Ardhpayment.id' => 'asc'),
            'recursive' => -1
        ));

        $netPayWords = $this->_voucherAmountInWords((float)$payroll['Ardhpayroll']['net_pay'], 'Rs');

        $this->layout = false;
        $this->set('payroll', $payroll['Ardhpayroll']);
        $this->set('employee', $employee['Ardhremployee']);
        $this->set('agencyName', $agencyName);
        $this->set('projectId', $projectId);
        $this->set('payments', $payments);
        $this->set('netPayWords', $netPayWords);
    }

    public function bankadvicesheet($id = null)
    {
        $this->loadModel('Admin.Ardhpayroll');
        $this->loadModel('Admin.Ardhremployee');
        $id = $this->_activeProjectId($id);
        $month = isset($this->request->query['month']) ? trim((string)$this->request->query['month']) : date('Y-m');
        $month = $this->_normalizePayrollMonthValue($month, date('Y-m'));
        $employeeScope = $this->_hrEmployeeScopeFromRequest('all');

        $conditions = array(
            $this->_scopeCondition('Ardhpayroll.project_id', $id),
            'Ardhpayroll.payroll_month' => $month
        );

        $this->Ardhpayroll->bindModel(array(
            'belongsTo' => array(
                'Ardhremployee' => array(
                    'className' => 'Admin.Ardhremployee',
                    'foreignKey' => 'employee_id'
                )
            )
        ), false);

        $rows = (array)$this->Ardhpayroll->find('all', array(
            'conditions' => $conditions,
            'order' => array('Ardhremployee.full_name' => 'asc'),
            'recursive' => 1
        ));

        $filtered = array();
        $totalNet = 0.0;
        $totalGross = 0.0;
        $totalDeductions = 0.0;
        foreach($rows as $r)
        {
            if(!$this->_hrEmployeeMatchesScope($r, $employeeScope))
            {
                continue;
            }
            $filtered[] = $r;
            $totalNet += (float)$r['Ardhpayroll']['net_pay'];
            $totalGross += (float)$r['Ardhpayroll']['gross_pay'];
            $totalDeductions += (float)$r['Ardhpayroll']['deductions'];
        }

        $projectList = $this->_projectList();
        $agencyName = !empty($projectList[$id]) ? $projectList[$id] : 'White Villas';
        $netPayWords = $this->_voucherAmountInWords($totalNet, 'Rs');

        $this->layout = false;
        $this->set('rows', $filtered);
        $this->set('month', $month);
        $this->set('agencyName', $agencyName);
        $this->set('projectId', $id);
        $this->set('totalNet', $totalNet);
        $this->set('totalGross', $totalGross);
        $this->set('totalDeductions', $totalDeductions);
        $this->set('netPayWords', $netPayWords);
    }

    public function hrpayments($id = null)
    {
        $this->loadModel('Admin.Ardhpayment');
        $this->loadModel('Admin.Ardhpayroll');
        $this->loadModel('Admin.Ardhremployee');
        $this->loadModel('Admin.Ardledger');
        $this->loadModel('Admin.Ardtransaction');
        $id = $this->_activeProjectId($id);
        $employeeScope = $this->_hrEmployeeScopeFromRequest('all');
        $employeeScopeLabel = $this->_hrEmployeeScopeLabel($employeeScope);
        $employeeScopeQuery = $this->_hrEmployeeScopeQuery($employeeScope);
        $employeeTypeConditions = $this->_hrEmployeeScopeConditions('Ardhremployee', $employeeScope);
        $this->set('projectName', $this->_projectList());
        $this->set('agencyId', $this->agencyId);
        $this->set('currentProjectId', $id);
        $this->set('employeeScope', $employeeScope);
        $this->set('employeeScopeLabel', $employeeScopeLabel);
        $this->set('employeeScopeQuery', $employeeScopeQuery);
        $employeeListConditions = array($this->_scopeCondition('Ardhremployee.project_id', $id));
        if(!empty($employeeTypeConditions))
        {
            $employeeListConditions = array_merge($employeeListConditions, $employeeTypeConditions);
        }
        $employeeList = $this->Ardhremployee->find('list', array(
            'fields' => array('Ardhremployee.id', 'Ardhremployee.full_name'),
            'conditions' => $employeeListConditions,
            'order' => array('Ardhremployee.full_name' => 'asc')
        ));
        $scopedEmployeeIds = array_values(array_unique(array_map('intval', array_keys((array)$employeeList))));
        $payrollListConditions = array($this->_scopeCondition('Ardhpayroll.project_id', $id));
        if($employeeScope !== 'all')
        {
            if(empty($scopedEmployeeIds))
            {
                $payrollListConditions['Ardhpayroll.id'] = 0;
            }
            else
            {
                $payrollListConditions['Ardhpayroll.employee_id'] = $scopedEmployeeIds;
            }
        }
        $this->set('payrollList', $this->Ardhpayroll->find('list', array(
            'fields' => array('Ardhpayroll.id', 'Ardhpayroll.payroll_month'),
            'conditions' => $payrollListConditions,
            'order' => array('Ardhpayroll.id' => 'desc')
        )));
        $this->set('employeeList', $employeeList);
        $this->set('ledgerList', $this->Ardledger->find('list', array(
            'fields' => array('Ardledger.id', 'Ardledger.name'),
            'conditions' => array($this->_scopeCondition('Ardledger.project_id', $id), 'Ardledger.is_trashed' => 0, 'Ardledger.type' => 'bank'),
            'order' => array('Ardledger.name' => 'asc')
        )));

        if($this->request->is('post'))
        {
            $row = isset($this->request->data['Ardhpayment']) ? $this->request->data['Ardhpayment'] : array();
            $row['id'] = isset($row['id']) ? (int)$row['id'] : 0;
            $row['project_id'] = $this->_resolveProjectId(isset($row['project_id']) ? $row['project_id'] : null);
            if(!$this->_isAllowedProject($row['project_id']))
            {
                $this->Session->setFlash(__('Please select valid agency/project.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            $payrollId = (int)$row['payroll_id'];
            $amount = round((float)$row['amount'], 2);
            $paymentDate = trim((string)$row['payment_date']);
            if($payrollId <= 0 || $amount <= 0 || $paymentDate === '')
            {
                $this->Session->setFlash(__('Please enter valid payroll payment details.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            $payroll = $this->Ardhpayroll->findById($payrollId);
            if(empty($payroll) || !$this->_isAllowedProject((int)$payroll['Ardhpayroll']['project_id']))
            {
                $this->Session->setFlash(__('Invalid payroll selected.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            $payrollEmployee = $this->Ardhremployee->findById((int)$payroll['Ardhpayroll']['employee_id']);
            if(!$this->_hrEmployeeMatchesScope($payrollEmployee, $employeeScope))
            {
                $this->Session->setFlash(__('Selected payroll is outside current labour/staff scope.'), 'flash', array('alert' => 'danger'));
                return $this->redirect(array('action' => 'hrpayments', $id, '?' => $employeeScopeQuery));
            }
            if((int)$row['employee_id'] <= 0)
            {
                $row['employee_id'] = (int)$payroll['Ardhpayroll']['employee_id'];
            }

            $oldPayrollId = 0;
            $oldVoucherTxId = 0;
            $ledgerIdsToRecalculate = array();
            if($row['id'] > 0)
            {
                $existingPayment = $this->Ardhpayment->findById($row['id']);
                if(empty($existingPayment) || !$this->_isAllowedProject((int)$existingPayment['Ardhpayment']['project_id']))
                {
                    $this->Session->setFlash(__('Invalid HR payment.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect($this->referer());
                }
                $existingPaymentEmployee = $this->Ardhremployee->findById((int)$existingPayment['Ardhpayment']['employee_id']);
                if(!$this->_hrEmployeeMatchesScope($existingPaymentEmployee, $employeeScope))
                {
                    $this->Session->setFlash(__('Selected HR payment is outside current labour/staff scope.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect(array('action' => 'hrpayments', $id, '?' => $employeeScopeQuery));
                }
                $oldPayrollId = (int)$existingPayment['Ardhpayment']['payroll_id'];
                $oldVoucherTxId = (int)$existingPayment['Ardhpayment']['voucher_transaction_id'];
                if($oldVoucherTxId > 0)
                {
                    $lockMessage = $this->_ardTransactionLockedMessage($oldVoucherTxId, (int)$existingPayment['Ardhpayment']['project_id']);
                    if($lockMessage !== '')
                    {
                        $this->Session->setFlash($lockMessage, 'flash', array('alert' => 'danger'));
                        return $this->redirect($this->referer());
                    }
                }
            }
            $row['voucher_transaction_id'] = $oldVoucherTxId;

            $savedPaymentId = 0;
            $savedVoucherTxId = $oldVoucherTxId;
            $syncJournalTxId = 0;
            $paymentSourceLabel = trim((string)$row['reference_no']) !== '' ? trim((string)$row['reference_no']) : $this->_nextReferenceNo((int)$row['project_id'], 'payroll_slip', 'SAL-');
            if(trim((string)$row['reference_no']) === '')
            {
                $row['reference_no'] = $paymentSourceLabel;
            }
            $employee = $this->Ardhremployee->findById((int)$row['employee_id']);
            if(empty($employee) || !$this->_isAllowedProject((int)$employee['Ardhremployee']['project_id']) || !$this->_hrEmployeeMatchesScope($employee, $employeeScope))
            {
                $this->Session->setFlash(__('Please select valid employee within current labour/staff scope.'), 'flash', array('alert' => 'danger'));
                return $this->redirect(array('action' => 'hrpayments', $id, '?' => $employeeScopeQuery));
            }
            $ds = $this->Ardhpayment->getDataSource();
            $ds->begin();
            $ok = true;

            $this->Ardhpayment->create();
            if($this->Ardhpayment->save(array('Ardhpayment' => $row)))
            {
                $savedPaymentId = (int)$this->Ardhpayment->id;
                $debitLedgerId = (int)$row['debit_ledger_id'];
                if($debitLedgerId > 0)
                {
                    $payrollExpenseLedgerId = $this->_defaultExpenseLedgerForAutoVoucher((int)$row['project_id'], 'payroll_payment_expense_ledger_id');
                    $txPayload = array(
                        'project_id' => (int)$row['project_id'],
                        'ledger_id' => $debitLedgerId,
                        'expense_ledger_id' => $payrollExpenseLedgerId,
                        'type' => 'expense',
                        'status' => 'Posted',
                        'amount' => $amount,
                        'description' => 'Payroll payment '.(!empty($employee['Ardhremployee']['full_name']) ? $employee['Ardhremployee']['full_name'] : ('#'.$row['employee_id'])).' ['.$payroll['Ardhpayroll']['payroll_month'].']',
                        'ref_no' => $paymentSourceLabel,
                        'entry_date' => $paymentDate,
                        'construction_site_id' => 0,
                        'source_type' => 'hr_payment',
                        'source_id' => (int)$savedPaymentId,
                        'auto_posted' => 1,
                        'posted_by' => (int)$this->luserId,
                        'posted_at' => date('Y-m-d H:i:s'),
                        'modified_by' => (int)$this->luserId
                    );
                    if($oldVoucherTxId > 0)
                    {
                        $oldTx = $this->Ardtransaction->findById($oldVoucherTxId);
                        if(!empty($oldTx) && $this->_isAllowedProject((int)$oldTx['Ardtransaction']['project_id']))
                        {
                            $txPayload['id'] = $oldVoucherTxId;
                            $ledgerIdsToRecalculate[] = (int)$oldTx['Ardtransaction']['ledger_id'];
                            $oldExpenseLedgerId = isset($oldTx['Ardtransaction']['expense_ledger_id']) ? (int)$oldTx['Ardtransaction']['expense_ledger_id'] : 0;
                            if($oldExpenseLedgerId > 0)
                            {
                                $ledgerIdsToRecalculate[] = $oldExpenseLedgerId;
                            }
                        }
                    }
                    $this->Ardtransaction->create();
                    if($this->Ardtransaction->save(array('Ardtransaction' => $txPayload)))
                    {
                        $savedVoucherTxId = (int)$this->Ardtransaction->id;
                        $syncJournalTxId = $savedVoucherTxId;
                        $ledgerIdsToRecalculate[] = $debitLedgerId;
                        if($payrollExpenseLedgerId > 0)
                        {
                            $ledgerIdsToRecalculate[] = $payrollExpenseLedgerId;
                        }
                    }
                    else
                    {
                        $ok = false;
                    }
                }
                elseif($oldVoucherTxId > 0)
                {
                    $oldTx = $this->Ardtransaction->findById($oldVoucherTxId);
                    if(!empty($oldTx) && $this->_isAllowedProject((int)$oldTx['Ardtransaction']['project_id']))
                    {
                        $ledgerIdsToRecalculate[] = (int)$oldTx['Ardtransaction']['ledger_id'];
                        $oldExpenseLedgerId = isset($oldTx['Ardtransaction']['expense_ledger_id']) ? (int)$oldTx['Ardtransaction']['expense_ledger_id'] : 0;
                        if($oldExpenseLedgerId > 0)
                        {
                            $ledgerIdsToRecalculate[] = $oldExpenseLedgerId;
                        }
                        $this->Ardtransaction->delete($oldVoucherTxId);
                        $this->_deleteJournalForTransaction($oldVoucherTxId);
                    }
                    $savedVoucherTxId = 0;
                }

                if($ok && $savedPaymentId > 0 && $savedVoucherTxId !== $oldVoucherTxId)
                {
                    $this->Ardhpayment->id = $savedPaymentId;
                    if(!$this->Ardhpayment->saveField('voucher_transaction_id', $savedVoucherTxId))
                    {
                        $ok = false;
                    }
                }
            }
            else
            {
                $ok = false;
            }

            if($ok)
            {
                $ds->commit();
                foreach(array_unique(array_filter($ledgerIdsToRecalculate)) as $ledgerId)
                {
                    $this->_recalculateLedgerBalance((int)$ledgerId);
                }
                if($syncJournalTxId > 0)
                {
                    $this->_syncJournalForTransaction($syncJournalTxId, 'hr_payment', $savedPaymentId);
                }
                $this->_recalculateHrPayrollStatus($payrollId);
                if($oldPayrollId > 0 && $oldPayrollId !== $payrollId)
                {
                    $this->_recalculateHrPayrollStatus($oldPayrollId);
                }
                $this->Session->setFlash(__('HR payroll payment saved successfully.'), 'flash', array('alert' => 'success'));
            }
            else
            {
                $ds->rollback();
                $this->Session->setFlash(__('Unable to save HR payroll payment.'), 'flash', array('alert' => 'danger'));
            }
            return $this->redirect(array('action' => 'hrpayments', $id, '?' => $employeeScopeQuery));
        }

        $scope = $this->_scopeCondition('Ardhpayment.project_id', $id);
        $paymentListingConditions = array($scope);
        if($employeeScope !== 'all')
        {
            if(empty($scopedEmployeeIds))
            {
                $paymentListingConditions['Ardhpayment.id'] = 0;
            }
            else
            {
                $paymentListingConditions['Ardhpayment.employee_id'] = $scopedEmployeeIds;
            }
        }
        $this->Paginator->settings = array(
            'page' => 1,
            'order' => array('Ardhpayment.id' => 'desc'),
            'limit' => $this->pageLimit,
            'maxLimit' => $this->maxLimit,
            'conditions' => $paymentListingConditions
        );
        $this->set('rows', $this->Paginator->paginate('Ardhpayment'));

        $editId = isset($this->request->params['named']['edit']) ? (int)$this->request->params['named']['edit'] : 0;
        if($editId > 0)
        {
            $editRow = $this->Ardhpayment->findById($editId);
            if(!empty($editRow) && $this->_isAllowedProject((int)$editRow['Ardhpayment']['project_id']))
            {
                $editEmployee = $this->Ardhremployee->findById((int)$editRow['Ardhpayment']['employee_id']);
                if($this->_hrEmployeeMatchesScope($editEmployee, $employeeScope))
                {
                    $this->request->data = $editRow;
                }
            }
        }
    }

    public function deletehrpayment($id = null, $projectId = null)
    {
        $this->loadModel('Admin.Ardhpayment');
        $this->loadModel('Admin.Ardhremployee');
        $this->loadModel('Admin.Ardtransaction');
        $employeeScope = $this->_hrEmployeeScopeFromRequest('all');
        $employeeScopeQuery = $this->_hrEmployeeScopeQuery($employeeScope);
        $row = $this->Ardhpayment->findById($id);
        if(empty($row) || !$this->_isAllowedProject((int)$row['Ardhpayment']['project_id']))
        {
            $this->Session->setFlash(__('Invalid HR payment.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'hrpayments', $projectId, '?' => $employeeScopeQuery));
        }
        $employeeRow = $this->Ardhremployee->findById((int)$row['Ardhpayment']['employee_id']);
        if(!$this->_hrEmployeeMatchesScope($employeeRow, $employeeScope))
        {
            $this->Session->setFlash(__('Selected HR payment is outside current labour/staff scope.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'hrpayments', $projectId, '?' => $employeeScopeQuery));
        }
        $payrollId = (int)$row['Ardhpayment']['payroll_id'];
        $voucherTxId = (int)$row['Ardhpayment']['voucher_transaction_id'];
        $voucherLedgerId = 0;
        $voucherExpenseLedgerId = 0;
        $linkedTransaction = array();
        if($voucherTxId > 0)
        {
            $tx = $this->Ardtransaction->findById($voucherTxId);
            if(!empty($tx) && $this->_isAllowedProject((int)$tx['Ardtransaction']['project_id']))
            {
                $lockMessage = $this->_ardTransactionLockedMessage($tx['Ardtransaction'], (int)$tx['Ardtransaction']['project_id']);
                if($lockMessage !== '')
                {
                    $this->Session->setFlash($lockMessage, 'flash', array('alert' => 'danger'));
                    return $this->redirect(array('action' => 'hrpayments', $projectId, '?' => $employeeScopeQuery));
                }
                $voucherLedgerId = (int)$tx['Ardtransaction']['ledger_id'];
                $voucherExpenseLedgerId = isset($tx['Ardtransaction']['expense_ledger_id']) ? (int)$tx['Ardtransaction']['expense_ledger_id'] : 0;
                $linkedTransaction = $tx['Ardtransaction'];
            }
        }
        $trashExtra = array();
        if(!empty($linkedTransaction))
        {
            $trashExtra['linked_transaction'] = $linkedTransaction;
        }
        $this->_storeTrashRecord(
            'ardaccounts_hr_payments',
            'Ardhpayment',
            $row['Ardhpayment'],
            isset($row['Ardhpayment']['reference_no']) ? (string)$row['Ardhpayment']['reference_no'] : '',
            $trashExtra
        );

        $ds = $this->Ardhpayment->getDataSource();
        $ds->begin();
        $ok = (bool)$this->Ardhpayment->delete($id);
        if($ok && $voucherTxId > 0)
        {
            $txForDelete = $this->Ardtransaction->findById($voucherTxId);
            if(!empty($txForDelete))
            {
                $ok = (bool)$this->Ardtransaction->delete($voucherTxId);
            }
            if($ok)
            {
                $this->_deleteJournalForTransaction($voucherTxId);
            }
        }

        if($ok)
        {
            $ds->commit();
            $this->_recalculateHrPayrollStatus($payrollId);
            if($voucherLedgerId > 0)
            {
                $this->_recalculateLedgerBalance($voucherLedgerId);
            }
            if($voucherExpenseLedgerId > 0)
            {
                $this->_recalculateLedgerBalance($voucherExpenseLedgerId);
            }
            $this->Session->setFlash(__('HR payment deleted. You can restore it from Trash.'), 'flash', array('alert' => 'success'));
        }
        else
        {
            $ds->rollback();
            $this->Session->setFlash(__('Unable to delete HR payment.'), 'flash', array('alert' => 'danger'));
        }
        return $this->redirect(array('action' => 'hrpayments', $projectId, '?' => $employeeScopeQuery));
    }

    protected function _projectSqlCondition($field, $projectId = null)
    {
        if($this->_isGlobalAdmin())
        {
            if((int)$projectId > 0)
            {
                return $field . '=' . (int)$projectId;
            }
            return '1=1';
        }
        return $field . '=' . (int)$this->agencyId;
    }

