    protected function _sanitizeLineText($text)
    {
        $rows = preg_split('/[\r\n,]+/', (string)$text);
        $out = array();
        if(is_array($rows))
        {
            foreach($rows as $row)
            {
                $row = trim($row);
                if($row !== '')
                {
                    $out[] = preg_replace('/\s+/', ' ', $row);
                }
            }
        }
        return implode("\n", array_unique($out));
    }

    protected function _lineTextToOptionList($text)
    {
        $rows = preg_split('/[\r\n,]+/', (string)$text);
        $options = array();
        if(is_array($rows))
        {
            foreach($rows as $row)
            {
                $row = trim((string)$row);
                if($row === '')
                {
                    continue;
                }
                $row = preg_replace('/\s+/', ' ', $row);
                if(!isset($options[$row]))
                {
                    $options[$row] = $row;
                }
            }
        }
        return $options;
    }

    protected function _parseManualListValues($rawText, $asInteger = false)
    {
        $tokens = preg_split('/[\r\n,]+/', (string)$rawText);
        $out = array();
        if(!is_array($tokens))
        {
            return $out;
        }
        foreach($tokens as $token)
        {
            $token = trim((string)$token);
            if($token === '')
            {
                continue;
            }
            if($asInteger)
            {
                $intVal = (int)$token;
                if($intVal > 0)
                {
                    $out[$intVal] = $intVal;
                }
                continue;
            }
            $out[$token] = $token;
        }
        return array_values($out);
    }

    protected function _manualMergeReceiptLedger($projectId, $sourceLedgerId, $targetLedgerId, $mergeMode = 'all', $selectedTxIds = array(), $selectedRefs = array())
    {
        $this->loadModel('Admin.Ardtransaction');
        $this->loadModel('Admin.Ardledger');
        $this->loadModel('DealsPayment');
        $this->loadModel('Admin.Ardjournalentry');

        $projectId = (int)$projectId;
        $sourceLedgerId = (int)$sourceLedgerId;
        $targetLedgerId = (int)$targetLedgerId;
        $mergeMode = strtolower(trim((string)$mergeMode));
        if(!in_array($mergeMode, array('all', 'selected_receipts', 'selected_transactions'), true))
        {
            $mergeMode = 'all';
        }

        $summary = array(
            'moved_transactions' => 0,
            'moved_payments' => 0,
            'moved_receipt_refs' => 0,
            'errors' => 0
        );
        if($projectId <= 0 || $sourceLedgerId <= 0 || $targetLedgerId <= 0 || $sourceLedgerId === $targetLedgerId)
        {
            $summary['errors']++;
            return $summary;
        }

        $sourceLedger = $this->Ardledger->find('first', array(
            'fields' => array('Ardledger.id', 'Ardledger.type'),
            'conditions' => array(
                'Ardledger.id' => $sourceLedgerId,
                'Ardledger.project_id' => $projectId,
                'Ardledger.is_trashed' => 0,
                'Ardledger.type !=' => 'expense'
            ),
            'recursive' => -1
        ));
        $targetLedger = $this->Ardledger->find('first', array(
            'fields' => array('Ardledger.id', 'Ardledger.type', 'Ardledger.name'),
            'conditions' => array(
                'Ardledger.id' => $targetLedgerId,
                'Ardledger.project_id' => $projectId,
                'Ardledger.is_trashed' => 0,
                'Ardledger.type !=' => 'expense'
            ),
            'recursive' => -1
        ));
        if(empty($sourceLedger['Ardledger']['id']) || empty($targetLedger['Ardledger']['id']))
        {
            $summary['errors']++;
            return $summary;
        }

        $selectedTxIds = array_values(array_unique(array_filter(array_map('intval', (array)$selectedTxIds))));
        $selectedRefs = array_values(array_unique(array_filter(array_map('trim', (array)$selectedRefs))));

        if($mergeMode === 'selected_transactions' && empty($selectedTxIds))
        {
            return $summary;
        }
        if($mergeMode === 'selected_receipts' && empty($selectedRefs))
        {
            return $summary;
        }

        $paymentLinkedTxIds = array();
        if($mergeMode === 'all')
        {
            $linkedPaymentRows = $this->DealsPayment->find('all', array(
                'joins' => array(
                    array('table' => 'deals', 'alias' => 'Deal', 'type' => 'INNER', 'conditions' => array('Deal.id = DealsPayment.deal_id')),
                    array('table' => 'properties', 'alias' => 'Property', 'type' => 'INNER', 'conditions' => array('Property.id = Deal.property_id'))
                ),
                'fields' => array('DealsPayment.ard_transaction_id'),
                'conditions' => array(
                    'Property.project_id' => $projectId,
                    'DealsPayment.ard_ledger_id' => $sourceLedgerId,
                    'DealsPayment.ard_transaction_id >' => 0
                ),
                'recursive' => -1
            ));
            foreach((array)$linkedPaymentRows as $linkedPaymentRow)
            {
                $linkedTxId = (int)(isset($linkedPaymentRow['DealsPayment']['ard_transaction_id']) ? $linkedPaymentRow['DealsPayment']['ard_transaction_id'] : 0);
                if($linkedTxId > 0)
                {
                    $paymentLinkedTxIds[$linkedTxId] = $linkedTxId;
                }
            }
            $paymentLinkedTxIds = array_values($paymentLinkedTxIds);
        }

        $txConditions = array(
            'Ardtransaction.project_id' => $projectId,
            'Ardtransaction.type' => 'income',
            'Ardtransaction.ledger_id' => $sourceLedgerId
        );
        if($mergeMode === 'selected_transactions')
        {
            $txConditions['Ardtransaction.id'] = $selectedTxIds;
        }
        elseif($mergeMode === 'selected_receipts')
        {
            $txConditions['Ardtransaction.ref_no'] = $selectedRefs;
        }
        elseif($mergeMode === 'all')
        {
            $txOr = array(
                array('Ardtransaction.ref_no !=' => '')
            );
            if(!empty($paymentLinkedTxIds))
            {
                $txOr[] = array('Ardtransaction.id' => $paymentLinkedTxIds);
            }
            $txConditions['OR'] = $txOr;
        }

        $txRows = $this->Ardtransaction->find('all', array(
            'fields' => array('Ardtransaction.id', 'Ardtransaction.ref_no', 'Ardtransaction.entry_date'),
            'conditions' => $txConditions,
            'order' => array('Ardtransaction.entry_date' => 'asc', 'Ardtransaction.id' => 'asc'),
            'recursive' => -1
        ));
        $txIdsToMove = array();
        $receiptRefs = array();
        foreach((array)$txRows as $txRow)
        {
            $txId = (int)(isset($txRow['Ardtransaction']['id']) ? $txRow['Ardtransaction']['id'] : 0);
            if($txId > 0)
            {
                $txIdsToMove[$txId] = $txId;
            }
            $refNo = trim((string)(isset($txRow['Ardtransaction']['ref_no']) ? $txRow['Ardtransaction']['ref_no'] : ''));
            if($refNo !== '')
            {
                $receiptRefs[$refNo] = $refNo;
            }
        }
        if($mergeMode === 'selected_receipts')
        {
            foreach((array)$selectedRefs as $selectedRef)
            {
                $selectedRef = trim((string)$selectedRef);
                if($selectedRef !== '')
                {
                    $receiptRefs[$selectedRef] = $selectedRef;
                }
            }
        }

        $txIdsToMove = array_values($txIdsToMove);
        $receiptRefs = array_values($receiptRefs);

        if(!empty($txIdsToMove))
        {
            $this->Ardtransaction->updateAll(
                array('Ardtransaction.ledger_id' => (int)$targetLedgerId),
                array(
                    'Ardtransaction.project_id' => $projectId,
                    'Ardtransaction.id' => $txIdsToMove,
                    'Ardtransaction.ledger_id' => $sourceLedgerId
                )
            );
            $summary['moved_transactions'] = count($txIdsToMove);

            $targetLedgerName = trim((string)(isset($targetLedger['Ardledger']['name']) ? $targetLedger['Ardledger']['name'] : ''));
            if($targetLedgerName !== '')
            {
                foreach(array_chunk($txIdsToMove, 500) as $txChunk)
                {
                    $this->Ardjournalentry->updateAll(
                        array('Ardjournalentry.credit_account' => "'" . addslashes($targetLedgerName) . "'"),
                        array('Ardjournalentry.transaction_id' => $txChunk)
                    );
                }
            }
        }

        $dpConditions = array(
            'Property.project_id' => $projectId,
            'DealsPayment.ard_ledger_id' => $sourceLedgerId
        );
        if($mergeMode === 'selected_transactions')
        {
            $dpOr = array();
            if(!empty($txIdsToMove))
            {
                $dpOr[] = array('DealsPayment.ard_transaction_id' => $txIdsToMove);
            }
            if(!empty($receiptRefs))
            {
                $dpOr[] = array('DealsPayment.receipt_no' => $receiptRefs);
            }
            if(empty($dpOr))
            {
                $dpOr[] = array('DealsPayment.id' => 0);
            }
            $dpConditions['OR'] = $dpOr;
        }
        elseif($mergeMode === 'selected_receipts')
        {
            $dpConditions['DealsPayment.receipt_no'] = $receiptRefs;
        }
        elseif($mergeMode === 'all' && !empty($receiptRefs))
        {
            // Keep all mode broad by ledger+project only; no extra condition required.
        }

        $paymentRows = $this->DealsPayment->find('all', array(
            'joins' => array(
                array('table' => 'deals', 'alias' => 'Deal', 'type' => 'INNER', 'conditions' => array('Deal.id = DealsPayment.deal_id')),
                array('table' => 'properties', 'alias' => 'Property', 'type' => 'INNER', 'conditions' => array('Property.id = Deal.property_id'))
            ),
            'fields' => array('DealsPayment.id', 'DealsPayment.receipt_no'),
            'conditions' => $dpConditions,
            'recursive' => -1
        ));
        $paymentIds = array();
        foreach((array)$paymentRows as $paymentRow)
        {
            $paymentId = (int)(isset($paymentRow['DealsPayment']['id']) ? $paymentRow['DealsPayment']['id'] : 0);
            if($paymentId > 0)
            {
                $paymentIds[$paymentId] = $paymentId;
            }
            $paymentReceiptRef = trim((string)(isset($paymentRow['DealsPayment']['receipt_no']) ? $paymentRow['DealsPayment']['receipt_no'] : ''));
            if($paymentReceiptRef !== '')
            {
                $receiptRefs[$paymentReceiptRef] = $paymentReceiptRef;
            }
        }
        $paymentIds = array_values($paymentIds);
        if(!empty($paymentIds))
        {
            $this->DealsPayment->updateAll(
                array('DealsPayment.ard_ledger_id' => (int)$targetLedgerId),
                array('DealsPayment.id' => $paymentIds)
            );
            $summary['moved_payments'] = count($paymentIds);
        }

        $summary['moved_receipt_refs'] = count($receiptRefs);
        $this->_recalculateLedgerBalance($sourceLedgerId);
        $this->_recalculateLedgerBalance($targetLedgerId);
        return $summary;
    }

    protected function _normalizeOptionText($value)
    {
        $value = trim((string)$value);
        if($value === '')
        {
            return '';
        }
        return preg_replace('/\s+/', ' ', $value);
    }

    protected function _appendMaterialUnitMap(&$materialUnitMap, $material, $unit)
    {
        $material = $this->_normalizeOptionText($material);
        $unit = $this->_normalizeOptionText($unit);
        if($material === '' || $unit === '')
        {
            return;
        }
        if(!isset($materialUnitMap[$material]))
        {
            $materialUnitMap[$material] = array();
        }
        if(!in_array($unit, $materialUnitMap[$material], true))
        {
            $materialUnitMap[$material][] = $unit;
        }
    }

    protected function _constructionMaterialUnitOptions($projectId = 0)
    {
        $projectId = (int)$projectId;
        $defaults = $this->_defaultSettings();
        $materialText = isset($defaults['construction_material_types']) ? (string)$defaults['construction_material_types'] : '';
        $unitText = isset($defaults['construction_unit_types']) ? (string)$defaults['construction_unit_types'] : '';

        if($projectId > 0)
        {
            $this->loadModel('Admin.Ardsetting');
            $settingRow = $this->Ardsetting->find('first', array(
                'conditions' => array('Ardsetting.project_id' => $projectId),
                'order' => array('Ardsetting.id' => 'desc'),
                'recursive' => -1
            ));
            if(!empty($settingRow['Ardsetting']))
            {
                if(trim((string)$settingRow['Ardsetting']['construction_material_types']) !== '')
                {
                    $materialText = (string)$settingRow['Ardsetting']['construction_material_types'];
                }
                if(trim((string)$settingRow['Ardsetting']['construction_unit_types']) !== '')
                {
                    $unitText = (string)$settingRow['Ardsetting']['construction_unit_types'];
                }
            }
        }

        $materialOptions = array();
        $unitOptions = $this->_lineTextToOptionList($unitText);
        $materialUnitMap = array();
        $materialRows = preg_split('/[\r\n,]+/', (string)$materialText);
        if(is_array($materialRows))
        {
            foreach($materialRows as $materialRow)
            {
                $materialRow = trim((string)$materialRow);
                if($materialRow === '')
                {
                    continue;
                }
                $materialName = $materialRow;
                $linkedUnit = '';
                if(preg_match('/^(.+?)\s*(?:\||=>|:)\s*(.+)$/', $materialRow, $parts))
                {
                    $materialName = $parts[1];
                    $linkedUnit = $parts[2];
                }
                $materialName = $this->_normalizeOptionText($materialName);
                if($materialName === '')
                {
                    continue;
                }
                if(!isset($materialOptions[$materialName]))
                {
                    $materialOptions[$materialName] = $materialName;
                }
                $linkedUnit = $this->_normalizeOptionText($linkedUnit);
                if($linkedUnit !== '')
                {
                    if(!isset($unitOptions[$linkedUnit]))
                    {
                        $unitOptions[$linkedUnit] = $linkedUnit;
                    }
                    $this->_appendMaterialUnitMap($materialUnitMap, $materialName, $linkedUnit);
                }
            }
        }

        if(empty($materialOptions))
        {
            $materialOptions = $this->_lineTextToOptionList($materialText);
        }

        return array(
            'materials' => $materialOptions,
            'units' => $unitOptions,
            'material_units' => $materialUnitMap
        );
    }

    protected function _reportNormalizeDate($value, $isMonth = false)
    {
        $value = trim((string)$value);
        if($value === '')
        {
            return '';
        }
        if($isMonth && preg_match('/^\d{4}-\d{2}$/', $value))
        {
            return $value . '-01';
        }
        if(preg_match('/^(\d{4}-\d{2}-\d{2})(?:[ T].*)?$/', $value, $matches))
        {
            return $matches[1];
        }
        if(preg_match('/^\d{2}\/\d{2}\/\d{4}$/', $value))
        {
            $parts = explode('/', $value);
            return $parts[2] . '-' . $parts[1] . '-' . $parts[0];
        }
        if(preg_match('/^\d{2}-\d{2}-\d{4}$/', $value))
        {
            $parts = explode('-', $value);
            return $parts[2] . '-' . $parts[1] . '-' . $parts[0];
        }

        // Report filters are displayed as 17-Jul-2026. Parse that format
        // explicitly so server locale and strtotime heuristics cannot alter it.
        foreach(array('d-M-Y', 'j-M-Y', 'd-F-Y', 'j-F-Y') as $format)
        {
            $parsed = DateTime::createFromFormat('!'.$format, $value);
            $errors = DateTime::getLastErrors();
            if($parsed instanceof DateTime && ($errors === false || ((int)$errors['warning_count'] === 0 && (int)$errors['error_count'] === 0)))
            {
                return $parsed->format('Y-m-d');
            }
        }
        $ts = strtotime($value);
        if($ts === false)
        {
            return '';
        }
        return date('Y-m-d', $ts);
    }

    protected function _reportInRange($dateValue, $startDate, $endDate, $isMonth = false)
    {
        $dateValue = $this->_reportNormalizeDate($dateValue, $isMonth);
        if($dateValue === '')
        {
            return false;
        }
        if($startDate !== '' && $dateValue < $startDate)
        {
            return false;
        }
        if($endDate !== '' && $dateValue > $endDate)
        {
            return false;
        }
        return true;
    }

    protected function _reportResolveDateRange($preset, $startRaw, $endRaw)
    {
        $allowed = array('daily','weekly','monthly','yearly','custom','lifetime');
        $preset = strtolower(trim((string)$preset));
        if(!in_array($preset, $allowed))
        {
            $preset = 'custom';
        }
        $today = date('Y-m-d');
        $start = '';
        $end = '';
        if($preset === 'daily')
        {
            $start = $today;
            $end = $today;
        }
        elseif($preset === 'weekly')
        {
            $dayNumber = (int)date('N');
            $start = date('Y-m-d', strtotime('-' . ($dayNumber - 1) . ' days'));
            $end = date('Y-m-d', strtotime($start . ' +6 days'));
        }
        elseif($preset === 'monthly')
        {
            $start = date('Y-m-01');
            $end = date('Y-m-t');
        }
        elseif($preset === 'yearly')
        {
            $start = date('Y-01-01');
            $end = date('Y-12-31');
        }
        elseif($preset === 'lifetime')
        {
            $start = '';
            $end = '';
        }
        else
        {
            $start = $this->_reportNormalizeDate($startRaw, false);
            $end = $this->_reportNormalizeDate($endRaw, false);
            if($start === '' && $end === '')
            {
                $start = $today;
                $end = $today;
            }
            elseif($start === '')
            {
                $start = $end;
            }
            elseif($end === '')
            {
                $end = $start;
            }
        }
        if($start !== '' && $end !== '' && $start > $end)
        {
            $tmp = $start;
            $start = $end;
            $end = $tmp;
        }
        return array(
            'preset' => $preset,
            'start' => $start,
            'end' => $end
        );
    }

    protected function _reportFormatMoney($amount)
    {
        $symbol = trim((string)$this->currency);
        if($symbol === '')
        {
            $symbol = 'Rs';
        }
        $amount = round((float)$amount, 2);
        if(abs($amount) < 0.005)
        {
            $amount = 0.0;
        }
        $decimals = (abs($amount - round($amount)) < 0.005) ? 0 : 2;
        return $symbol . ' ' . number_format($amount, $decimals, '.', ',');
    }

    protected function _reportFormatNumber($amount, $decimals = 2)
    {
        return number_format((float)$amount, (int)$decimals, '.', ',');
    }

    protected function _reportHasAmount($amount, $precision = 2)
    {
        return abs(round((float)$amount, (int)$precision)) > 0.0;
    }

    protected function _reportMonthKey($dateValue)
    {
        $dateValue = $this->_reportNormalizeDate($dateValue, false);
        if($dateValue === '')
        {
            return '';
        }
        return substr($dateValue, 0, 7);
    }

    protected function _reportMonthLabel($monthValue)
    {
        $monthValue = trim((string)$monthValue);
        if($monthValue === '')
        {
            return '-';
        }
        if(preg_match('/^\d{4}-\d{2}$/', $monthValue))
        {
            $dateValue = $monthValue . '-01';
        }
        else
        {
            $dateValue = $this->_reportNormalizeDate($monthValue, true);
        }
        if($dateValue === '')
        {
            return $monthValue;
        }
        return date('M Y', strtotime($dateValue));
    }

    protected function _reportParseSiteBudget($notes)
    {
        $notes = trim((string)$notes);
        if($notes === '')
        {
            return 0.0;
        }
        if(preg_match('/budget\s*[:=]\s*([0-9\.,]+)/i', $notes, $matches) && !empty($matches[1]))
        {
            return (float)str_replace(',', '', $matches[1]);
        }
        return 0.0;
    }

    protected function _reportCsvEscape($value)
    {
        $value = (string)$value;
        if(strpos($value, '"') !== false || strpos($value, ',') !== false || strpos($value, "\n") !== false || strpos($value, "\r") !== false)
        {
            return '"' . str_replace('"', '""', $value) . '"';
        }
        return $value;
    }

