        // project id carried in the route.
        if($this->_isGlobalAdmin() && array_key_exists('project_id', $this->request->query))
        {
            $id = max(0, (int)$this->request->query['project_id']);
        }
        $isReportSystemManager = $this->_isAgencySystemManagerRoleContext((array)$this->adminValue);
        $reportAssignedProjects = $isReportSystemManager ? (array)$this->_assignedAgencyProjectList((int)$this->luserId) : array();
        if($isReportSystemManager && array_key_exists('project_id', $this->request->query))
        {
            $requestedReportProjectId = max(0, (int)$this->request->query['project_id']);
            $id = ($requestedReportProjectId > 0 && isset($reportAssignedProjects[$requestedReportProjectId]))
                ? $requestedReportProjectId
                : 0;
        }
        $reportScope = function($field) use ($id, $isReportSystemManager, $reportAssignedProjects)
        {
            if($isReportSystemManager)
            {
                if((int)$id > 0)
                {
                    return array($field => (int)$id);
                }
                $assignedIds = array_map('intval', array_keys($reportAssignedProjects));
                return array($field => !empty($assignedIds) ? $assignedIds : array(-1));
            }
            return $this->_scopeCondition($field, $id);
        };
        $reportTabs = array(
            array('id' => 'daily', 'label' => 'Daily'),
            array('id' => 'audit', 'label' => 'Audit'),
            array('id' => 'trial', 'label' => 'Trial Balance'),
            array('id' => 'balance', 'label' => 'Balance Sheet'),
            array('id' => 'pnl', 'label' => 'P&L'),
            array('id' => 'cashflow', 'label' => 'Cash Flow'),
            array('id' => 'aging', 'label' => 'AR/AP Aging'),
            array('id' => 'budget_actual', 'label' => 'Budget vs Actual'),
            array('id' => 'reconcile', 'label' => 'Reconciliation'),
            array('id' => 'stock_value', 'label' => 'Stock Valuation'),
            array('id' => 'stock_reorder', 'label' => 'Low Stock'),
            array('id' => 'stock_move', 'label' => 'Stock Movement'),
            array('id' => 'site_cost', 'label' => 'Site Cost Sheet'),
            array('id' => 'site_budget', 'label' => 'Site Budget vs Actual'),
            array('id' => 'vendor_outstanding', 'label' => 'Vendor Outstanding'),
            array('id' => 'vendor_rate', 'label' => 'Vendor Rate Compare'),
            array('id' => 'vendor_ledger', 'label' => 'Vendor Ledger Summary'),
            array('id' => 'payroll_register', 'label' => 'Payroll Register'),
            array('id' => 'salary_liability', 'label' => 'Salary Liability'),
            array('id' => 'attendance_wage', 'label' => 'Attendance vs Wage'),
            array('id' => 'overtime', 'label' => 'Overtime Analysis'),
            array('id' => 'labour_productivity', 'label' => 'Labour Productivity'),
            array('id' => 'audit_trail', 'label' => 'Audit Trail'),
            array('id' => 'kpi', 'label' => 'KPI Dashboard')
