        $allowedTabs = array();
        $tabLabelMap = array();
        foreach($reportTabs as $tabRow){$allowedTabs[] = $tabRow['id']; $tabLabelMap[$tabRow['id']] = $tabRow['label'];}
        $activeTab = isset($this->request->query['tab']) ? strtolower(trim((string)$this->request->query['tab'])) : 'daily';
