            if(!$hasRange || $this->_reportInRange($r['entry_date'], $dateRange['start'], $dateRange['end'], false))
            {
                $transactionsFiltered[] = $r;
                if(!isset($txFilteredByLedger[$r['ledger_id']])){$txFilteredByLedger[$r['ledger_id']] = array();}
