        $stockRaw = $this->Ardstock->find('all', array(
            'joins' => array(array('table' => 'ardaccounts_construction_vendors', 'alias' => 'Ardvendor', 'type' => 'LEFT', 'conditions' => array('Ardvendor.id=Ardstock.vendor_id'))),
            'fields' => array('Ardstock.*', 'Ardvendor.vendor_name'),
            'conditions' => array($reportScope('Ardstock.project_id')),
            'order' => array('Ardstock.movement_date' => 'desc', 'Ardstock.id' => 'desc'),
            'recursive' => -1
        ));
        $stockRows = array(); $stockFiltered = array();
        foreach($stockRaw as $row)
        {
            $r = $row['Ardstock'];
            $r['id'] = (int)$r['id']; $r['vendor_id'] = (int)$r['vendor_id']; $r['quantity'] = (float)$r['quantity']; $r['unit_cost'] = (float)$r['unit_cost'];
            $r['vendor_name'] = isset($row['Ardvendor']['vendor_name']) ? $row['Ardvendor']['vendor_name'] : '';
            $stockRows[] = $r;
            if(!$hasRange || $this->_reportInRange($r['movement_date'], $dateRange['start'], $dateRange['end'], false)){$stockFiltered[] = $r;}
        }

        $vendorsRaw = $this->Ardvendor->find('all', array(
            'fields' => array('Ardvendor.*'),
