            $vendorById[$vendorId] = $row['Ardvendor'];
            $reportVendorList[$vendorId] = (string)$row['Ardvendor']['vendor_name'];
        }
        $selectedVendorId = isset($this->request->query['vendor_id']) ? (int)$this->request->query['vendor_id'] : 0;
        if($selectedVendorId > 0 && !isset($vendorById[$selectedVendorId]))
        {
