        }
        $selectedVendorName = ($selectedVendorId > 0 && !empty($vendorById[$selectedVendorId]['vendor_name']))
            ? (string)$vendorById[$selectedVendorId]['vendor_name']
            : '';

        $invoiceRaw = $this->Ardpurchaseinvoice->find('all', array(
            'fields' => array('Ardpurchaseinvoice.*'),
            'conditions' => array($reportScope('Ardpurchaseinvoice.project_id')),
            'recursive' => -1
        ));
        $paymentRaw = $this->Ardpurchaseinvoicepayment->find('all', array(
            'fields' => array('Ardpurchaseinvoicepayment.*'),
            'conditions' => array($reportScope('Ardpurchaseinvoicepayment.project_id')),
