        ));
        $purchaseOrderRaw = $this->Ardpurchaseorder->find('all', array(
            'fields' => array('Ardpurchaseorder.*'),
            'conditions' => array($reportScope('Ardpurchaseorder.project_id')),
            'recursive' => -1
        ));
        $invoiceIn = array(); $paymentIn = array(); $invoiceBefore = array(); $paymentBefore = array();
        foreach($invoiceRaw as $row)
        {
            $r = $row['Ardpurchaseinvoice']; $r['vendor_id'] = (int)$r['vendor_id']; $r['amount'] = (float)$r['amount'];
            if(!$hasRange || $this->_reportInRange($r['invoice_date'], $dateRange['start'], $dateRange['end'], false)){$invoiceIn[] = $r;}
            $normalizedInvoiceDate = $this->_reportNormalizeDate($r['invoice_date'], false);
            if($hasRange && $dateRange['start'] !== '' && $normalizedInvoiceDate !== '' && $normalizedInvoiceDate < $dateRange['start']){$invoiceBefore[] = $r;}
        }
        foreach($paymentRaw as $row)
        {
            $r = $row['Ardpurchaseinvoicepayment']; $r['vendor_id'] = (int)$r['vendor_id']; $r['amount'] = (float)$r['amount'];
            if(!$hasRange || $this->_reportInRange($r['payment_date'], $dateRange['start'], $dateRange['end'], false)){$paymentIn[] = $r;}
            $normalizedPaymentDate = $this->_reportNormalizeDate($r['payment_date'], false);
            if($hasRange && $dateRange['start'] !== '' && $normalizedPaymentDate !== '' && $normalizedPaymentDate < $dateRange['start']){$paymentBefore[] = $r;}
        }

        $payrollRaw = $this->Ardhpayroll->find('all', array(
