        ));
        $payrollIn = array();
        foreach($payrollRaw as $row)
        {
            $r = $row['Ardhpayroll']; $r['due_amount'] = (float)$r['due_amount']; $r['gross_pay']=(float)$r['gross_pay']; $r['net_pay']=(float)$r['net_pay']; $r['paid_amount']=(float)$r['paid_amount'];
            $r['full_name'] = isset($row['Ardhremployee']['full_name']) ? $row['Ardhremployee']['full_name'] : '';
            $r['department'] = isset($row['Ardhremployee']['department']) ? $row['Ardhremployee']['department'] : '';
