            $paymentReceiptNo = trim((string)(isset($payment['receipt_no']) ? $payment['receipt_no'] : ''));
            if($paymentReceiptNo !== ''){$dealPaymentReceiptNos[$paymentReceiptNo] = true;}
            if(!empty($payment['ard_transaction_id'])){$dealPaymentTransactionIds[(int)$payment['ard_transaction_id']] = true;}
        }

        $reportData = array('title' => 'Audit', 'columns' => array('Date','Account','Type','Ref','Amount'), 'rightCols' => array(4), 'rows' => array());
        $balanceSheetSummary = array();
        $vendorLedgerSummary = array('credit_material' => 0.0, 'debit_paid' => 0.0, 'balance' => 0.0);

        // Convert the compact voucher record into its two accounting sides for
        // financial statements. Invalid legacy links are kept visible in an
        // unmapped account instead of silently making the reports unbalanced.
        $buildPostingTotals = function($transactionRows) use ($ledgerById)
        {
            $totals = array();
            $addPosting = function($key, $name, $accountType, $side, $amount) use (&$totals)
            {
                $amount = round((float)$amount, 2);
                if($amount <= 0)
                {
                    return;
                }
                if(!isset($totals[$key]))
                {
                    $totals[$key] = array(
                        'key' => $key,
                        'name' => $name,
                        'type' => strtolower(trim((string)$accountType)),
                        'debit' => 0.0,
                        'credit' => 0.0
                    );
                }
                $totals[$key][$side] += $amount;
            };
            $ledgerMeta = function($ledgerId) use ($ledgerById)
            {
                $ledgerId = (int)$ledgerId;
                if($ledgerId <= 0 || empty($ledgerById[$ledgerId]))
                {
                    return array();
                }
                return $ledgerById[$ledgerId];
            };

            foreach((array)$transactionRows as $tx)
            {
                $amount = round((float)(isset($tx['amount']) ? $tx['amount'] : 0), 2);
                if($amount <= 0)
                {
                    continue;
                }
                $type = strtolower(trim((string)(isset($tx['type']) ? $tx['type'] : '')));
                $voucherSourceType = strtolower(trim((string)(isset($tx['source_type']) ? $tx['source_type'] : '')));
                $voucherDescription = strtolower(trim((string)(isset($tx['description']) ? $tx['description'] : '')));
                $sourceId = (int)(isset($tx['ledger_id']) ? $tx['ledger_id'] : 0);
                $incomeId = (int)(isset($tx['income_ledger_id']) ? $tx['income_ledger_id'] : 0);
                $expenseId = (int)(isset($tx['expense_ledger_id']) ? $tx['expense_ledger_id'] : 0);
                $source = $ledgerMeta($sourceId);
                $income = $ledgerMeta($incomeId);
                $expense = $ledgerMeta($expenseId);
                $sourceType = !empty($source['type']) ? strtolower(trim((string)$source['type'])) : '';
                $incomeType = !empty($income['type']) ? strtolower(trim((string)$income['type'])) : '';
                $expenseType = !empty($expense['type']) ? strtolower(trim((string)$expense['type'])) : '';
                $validSource = (!empty($source) && !in_array($sourceType, array('income','expense'), true));

                if($type === 'income' && $voucherSourceType === 'deal_receipt_tax')
                {
                    if($validSource)
                    {
                        $addPosting('ledger:'.$sourceId, (string)$source['name'], $sourceType, 'debit', $amount);
                    }
                    else
                    {
                        $addPosting('virtual:suspense', 'Unmapped / Suspense', 'suspense', 'debit', $amount);
                    }
                    if(!empty($income) && $incomeType === 'liability' && $incomeId !== $sourceId)
                    {
                        $addPosting('ledger:'.$incomeId, (string)$income['name'], 'liability', 'credit', $amount);
                    }
                    else
                    {
                        $addPosting('virtual:tax_payable', 'Tax Accounts Payable', 'liability', 'credit', $amount);
                    }
                }
                elseif($type === 'income' && $voucherSourceType === 'deal_refund_payable')
                {
                    if(!empty($source) && $sourceType === 'expense')
                    {
                        $addPosting('ledger:'.$sourceId, (string)$source['name'], 'expense', 'debit', $amount);
                    }
                    else
                    {
                        $addPosting('virtual:refund_expense', 'Refund Expense / Payable', 'expense', 'debit', $amount);
                    }
                    if(!empty($income) && $incomeType === 'liability' && $incomeId !== $sourceId)
                    {
                        $addPosting('ledger:'.$incomeId, (string)$income['name'], 'liability', 'credit', $amount);
                    }
                    else
                    {
                        $addPosting('virtual:refund_payable', 'Refund Accounts Payable', 'liability', 'credit', $amount);
                    }
                }
                elseif($type === 'income')
                {
                    if($validSource)
                    {
                        $addPosting('ledger:'.$sourceId, (string)$source['name'], $sourceType, 'debit', $amount);
                    }
                    else
                    {
                        $addPosting('virtual:suspense', 'Unmapped / Suspense', 'suspense', 'debit', $amount);
                    }
                    if(!empty($income) && $incomeType === 'income' && $incomeId !== $sourceId)
