            $rows = array(array('Total',$this->_reportFormatMoney($incomeTotal),$this->_reportFormatMoney($expenseTotal),$this->_reportFormatMoney($incomeTotal-$expenseTotal)));
            $months = array_keys($monthMap); rsort($months); foreach($months as $m){$rows[] = array('Month '.$m,$this->_reportFormatMoney($monthMap[$m]['income']),$this->_reportFormatMoney($monthMap[$m]['expense']),$this->_reportFormatMoney($monthMap[$m]['income']-$monthMap[$m]['expense']));}
