            ksort($map); $rows = array(); $total = 0.0; foreach($map as $v){$avg=($v['qin']>0)?($v['inval']/$v['qin']):0.0;$on=$v['qin']-$v['qout'];$val=$on*$avg;$total += $val;$rows[] = array($v['m'],$v['u'],$this->_reportFormatNumber($v['qin'],3),$this->_reportFormatNumber($v['qout'],3),$this->_reportFormatNumber($on,3),$this->_reportFormatMoney($avg),$this->_reportFormatMoney($val));}
            $rows[] = array('Total','','','','','',$this->_reportFormatMoney($total));
