            foreach($invoiceIn as $inv){$vid=(int)$inv['vendor_id'];if(!isset($purchase[$vid])){$purchase[$vid]=0.0;$payment[$vid]=0.0;}$purchase[$vid] += (float)$inv['amount'];}
            foreach($paymentIn as $pay){$vid=(int)$pay['vendor_id'];if(!isset($purchase[$vid])){$purchase[$vid]=0.0;$payment[$vid]=0.0;}$payment[$vid] += (float)$pay['amount'];}
            $rows = array(); $tP=0.0;$tPa=0.0;$tO=0.0; foreach($purchase as $vid => $p){$pa=isset($payment[$vid])?$payment[$vid]:0.0;$o=$p-$pa;if(!$this->_reportHasAmount($p) && !$this->_reportHasAmount($pa) && !$this->_reportHasAmount($o)){continue;}$name=isset($vendorById[$vid]['vendor_name'])?$vendorById[$vid]['vendor_name']:('Vendor #'.$vid);$rows[] = array($name,$this->_reportFormatMoney($p),$this->_reportFormatMoney($pa),$this->_reportFormatMoney($o));$tP += $p;$tPa += $pa;$tO += $o;}
            $rows[] = array('Total',$this->_reportFormatMoney($tP),$this->_reportFormatMoney($tPa),$this->_reportFormatMoney($tO));
            $reportData = array('title' => 'Vendor Outstanding', 'columns' => array('Vendor','Purchase','Payment','Outstanding'), 'rightCols' => array(1,2,3), 'rows' => $rows);
        }
        elseif($activeTab === 'vendor_ledger')
        {
            $entryDateLabel = function($value){
                $ts = strtotime((string)$value);
                return ($ts !== false) ? date('d-M-Y', $ts) : '-';
            };
            $esc = function($value){
                return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8');
            };
            $confirmText = addslashes((string)__('Are you sure?'));
            if($selectedVendorId > 0)
            {
                $openingCredit = 0.0; // Material from PO (Credit side)
                $openingDebit = 0.0;  // Paid via vouchers (Debit side)
                $entryRows = array();

                foreach((array)$purchaseOrderRaw as $poRow)
                {
                    $r = isset($poRow['Ardpurchaseorder']) ? $poRow['Ardpurchaseorder'] : array();
                    $vendorId = isset($r['vendor_id']) ? (int)$r['vendor_id'] : 0;
                    if($vendorId !== $selectedVendorId)
                    {
                        continue;
                    }
                    $status = strtolower(trim((string)(isset($r['status']) ? $r['status'] : '')));
                    if($status === 'cancelled')
                    {
                        continue;
                    }
                    $amount = round((float)(isset($r['total_cost']) ? $r['total_cost'] : 0), 2);
                    if($amount <= 0)
                    {
                        continue;
                    }
                    $poDate = isset($r['po_date']) ? (string)$r['po_date'] : '';
                    $normalizedDate = $this->_reportNormalizeDate($poDate, false);
                    if($hasRange && $dateRange['start'] !== '' && $normalizedDate !== '' && $normalizedDate < $dateRange['start'])
                    {
                        $openingCredit += $amount;
                        continue;
                    }
                    if($hasRange && !$this->_reportInRange($poDate, $dateRange['start'], $dateRange['end'], false))
                    {
                        continue;
                    }
                    $poId = (int)(isset($r['id']) ? $r['id'] : 0);
                    $poViewUrl = Router::url(array('controller' => 'Ardaccounts', 'action' => 'purchaseorders', $id, '?' => array('view' => $poId)), false);
                    $poEditUrl = Router::url(array('controller' => 'Ardaccounts', 'action' => 'purchaseorders', $id, '?' => array('edit' => $poId)), false);
                    $poDeleteUrl = Router::url(array('controller' => 'Ardaccounts', 'action' => 'deletepurchaseorder', $poId, $id), false);
                    $poActionHtml =
                        '<a href="'.$esc($poViewUrl).'" class="btn btn-xs btn-info">'.__('View').'</a> '.
                        '<a href="'.$esc($poEditUrl).'" class="btn btn-xs btn-warning">'.__('Edit').'</a> '.
                        '<a href="'.$esc($poDeleteUrl).'" class="btn btn-xs btn-danger" onclick="return confirm(\''.$confirmText.'\');">'.__('Delete').'</a>';
                    $entryRows[] = array(
                        'sort_date' => ($normalizedDate !== '' ? $normalizedDate : '9999-12-31'),
                        'sort_rank' => 1,
                        'sort_id' => $poId,
                        'date' => $entryDateLabel($poDate),
                        'type' => 'Material Credit',
                        'reference' => trim((string)(isset($r['po_no']) ? $r['po_no'] : '')),
                        'details' => trim((string)(isset($r['note']) ? $r['note'] : '')),
                        'debit' => 0.0,
                        'credit' => $amount,
                        'action' => $poActionHtml
                    );
                }

                foreach((array)$paymentRaw as $payRow)
                {
                    $r = isset($payRow['Ardpurchaseinvoicepayment']) ? $payRow['Ardpurchaseinvoicepayment'] : array();
                    $vendorId = isset($r['vendor_id']) ? (int)$r['vendor_id'] : 0;
                    if($vendorId !== $selectedVendorId)
                    {
                        continue;
                    }
                    $amount = round((float)(isset($r['amount']) ? $r['amount'] : 0), 2);
                    if($amount <= 0)
                    {
                        continue;
                    }
                    $paymentDate = isset($r['payment_date']) ? (string)$r['payment_date'] : '';
                    $normalizedDate = $this->_reportNormalizeDate($paymentDate, false);
                    if($hasRange && $dateRange['start'] !== '' && $normalizedDate !== '' && $normalizedDate < $dateRange['start'])
                    {
                        $openingDebit += $amount;
                        continue;
                    }
                    if($hasRange && !$this->_reportInRange($paymentDate, $dateRange['start'], $dateRange['end'], false))
                    {
                        continue;
                    }
                    $paymentId = (int)(isset($r['id']) ? $r['id'] : 0);
                    $payViewUrl = Router::url(array('controller' => 'Ardaccounts', 'action' => 'purchasepayments', $id, '?' => array('view' => $paymentId)), false);
                    $payEditUrl = Router::url(array('controller' => 'Ardaccounts', 'action' => 'purchasepayments', $id, '?' => array('edit' => $paymentId)), false);
                    $payDeleteUrl = Router::url(array('controller' => 'Ardaccounts', 'action' => 'deletepurchasepayment', $paymentId, $id), false);
                    $payActionHtml =
                        '<a href="'.$esc($payViewUrl).'" class="btn btn-xs btn-info">'.__('View').'</a> '.
                        '<a href="'.$esc($payEditUrl).'" class="btn btn-xs btn-warning">'.__('Edit').'</a> '.
                        '<a href="'.$esc($payDeleteUrl).'" class="btn btn-xs btn-danger" onclick="return confirm(\''.$confirmText.'\');">'.__('Delete').'</a>';
                    $voucherTxId = (int)(isset($r['voucher_transaction_id']) ? $r['voucher_transaction_id'] : 0);
                    if($voucherTxId > 0)
                    {
                        $voucherUrl = Router::url(array('controller' => 'Ardaccounts', 'action' => 'printvoucher', $voucherTxId, $id), false);
                        $payActionHtml .= ' <a href="'.$esc($voucherUrl).'" class="btn btn-xs btn-primary" target="_blank">'.__('Voucher').'</a>';
                    }
                    $paymentDetails = trim((string)(isset($r['payment_method']) ? $r['payment_method'] : ''));
                    $paymentNote = trim((string)(isset($r['note']) ? $r['note'] : ''));
                    if($paymentNote !== '')
                    {
                        $paymentDetails = ($paymentDetails !== '') ? ($paymentDetails.' | '.$paymentNote) : $paymentNote;
                    }
                    $entryRows[] = array(
                        'sort_date' => ($normalizedDate !== '' ? $normalizedDate : '9999-12-31'),
                        'sort_rank' => 2,
                        'sort_id' => $paymentId,
                        'date' => $entryDateLabel($paymentDate),
                        'type' => 'Payment Debit',
                        'reference' => trim((string)(isset($r['reference_no']) ? $r['reference_no'] : '')),
                        'details' => $paymentDetails,
                        'debit' => $amount,
                        'credit' => 0.0,
                        'action' => $payActionHtml
                    );
                }

                usort($entryRows, function($a, $b){
                    $da = isset($a['sort_date']) ? (string)$a['sort_date'] : '';
                    $db = isset($b['sort_date']) ? (string)$b['sort_date'] : '';
                    if($da !== $db)
                    {
                        return strcmp($da, $db);
                    }
                    $ra = isset($a['sort_rank']) ? (int)$a['sort_rank'] : 0;
                    $rb = isset($b['sort_rank']) ? (int)$b['sort_rank'] : 0;
                    if($ra !== $rb)
                    {
                        return ($ra < $rb) ? -1 : 1;
                    }
                    $ia = isset($a['sort_id']) ? (int)$a['sort_id'] : 0;
                    $ib = isset($b['sort_id']) ? (int)$b['sort_id'] : 0;
                    if($ia === $ib)
                    {
                        return 0;
                    }
                    return ($ia < $ib) ? -1 : 1;
                });

                $rows = array();
                $runningBalance = $openingCredit - $openingDebit;
                $rows[] = array(
                    '-',
                    'Opening Balance',
                    '-',
                    $hasRange ? ('Before '.date('d-M-Y', strtotime((string)$dateRange['start']))) : 'Carry Forward',
                    $this->_reportFormatMoney($openingDebit),
                    $this->_reportFormatMoney($openingCredit),
                    $this->_reportFormatMoney($runningBalance),
                    '-'
                );
                $periodDebit = 0.0;
                $periodCredit = 0.0;
                foreach($entryRows as $entry)
                {
                    $debit = (float)$entry['debit'];
                    $credit = (float)$entry['credit'];
                    $periodDebit += $debit;
                    $periodCredit += $credit;
                    $runningBalance += $credit - $debit;
                    $rows[] = array(
                        $entry['date'],
                        $entry['type'],
                        ($entry['reference'] !== '' ? $entry['reference'] : '-'),
                        ($entry['details'] !== '' ? $entry['details'] : '-'),
                        $this->_reportFormatMoney($debit),
                        $this->_reportFormatMoney($credit),
                        $this->_reportFormatMoney($runningBalance),
                        isset($entry['action']) ? $entry['action'] : '-'
                    );
                }
                $rows[] = array(
                    '',
                    'Period Total',
                    '',
                    '',
                    $this->_reportFormatMoney($periodDebit),
                    $this->_reportFormatMoney($periodCredit),
                    $this->_reportFormatMoney($runningBalance),
                    '-'
                );
                $vendorLedgerSummary = array(
                    'credit_material' => (float)$periodCredit,
                    'debit_paid' => (float)$periodDebit,
                    'balance' => (float)$runningBalance
                );
                $reportData = array(
                    'title' => 'Vendor Ledger - '.$selectedVendorName,
                    'columns' => array('Date','Entry','Reference','Details','Debit Paid','Credit Material','Balance','Action'),
                    'rightCols' => array(4,5,6),
                    'rawCols' => array(7),
                    'rows' => $rows
                );
            }
            else
            {
                $purchase = array();
                $payment = array();
                foreach($vendorById as $vid => $v)
                {
                    $purchase[(int)$vid] = 0.0;
                    $payment[(int)$vid] = 0.0;
                }
                foreach((array)$purchaseOrderRaw as $poRow)
                {
                    $r = isset($poRow['Ardpurchaseorder']) ? $poRow['Ardpurchaseorder'] : array();
                    $status = strtolower(trim((string)(isset($r['status']) ? $r['status'] : '')));
                    if($status === 'cancelled')
                    {
                        continue;
                    }
                    $vendorId = (int)(isset($r['vendor_id']) ? $r['vendor_id'] : 0);
                    $amount = (float)(isset($r['total_cost']) ? $r['total_cost'] : 0);
                    if($vendorId <= 0 || $amount <= 0)
                    {
                        continue;
                    }
                    $poDate = isset($r['po_date']) ? (string)$r['po_date'] : '';
                    if($hasRange && !$this->_reportInRange($poDate, $dateRange['start'], $dateRange['end'], false))
                    {
                        continue;
                    }
                    if(!isset($purchase[$vendorId]))
                    {
                        $purchase[$vendorId] = 0.0;
                        $payment[$vendorId] = 0.0;
                    }
                    $purchase[$vendorId] += $amount;
                }
                foreach($paymentIn as $pay)
                {
                    $vendorId = (int)$pay['vendor_id'];
                    if(!isset($purchase[$vendorId]))
                    {
                        $purchase[$vendorId] = 0.0;
                        $payment[$vendorId] = 0.0;
                    }
                    $payment[$vendorId] += (float)$pay['amount'];
                }
                $rows = array();
                $totalPurchase = 0.0;
                $totalPayment = 0.0;
                $totalBalance = 0.0;
                foreach($purchase as $vendorId => $purchaseAmount)
                {
                    $paymentAmount = isset($payment[$vendorId]) ? (float)$payment[$vendorId] : 0.0;
                    $balanceAmount = $purchaseAmount - $paymentAmount;
                    if(!$this->_reportHasAmount($purchaseAmount) && !$this->_reportHasAmount($paymentAmount) && !$this->_reportHasAmount($balanceAmount))
                    {
                        continue;
                    }
                    $vendorName = isset($vendorById[$vendorId]['vendor_name']) ? (string)$vendorById[$vendorId]['vendor_name'] : ('Vendor #'.$vendorId);
                    $openUrl = Router::url(array(
                        'controller' => 'Ardaccounts',
                        'action' => 'reports',
                        $id,
                        '?' => array(
                            'tab' => 'vendor_ledger',
                            'preset' => $dateRange['preset'],
                            'start' => $dateRange['start'],
                            'end' => $dateRange['end'],
                            'project_id' => $id,
                            'vendor_id' => $vendorId
                        )
                    ), false);
                    $rows[] = array(
                        $vendorName,
                        $this->_reportFormatMoney($purchaseAmount),
                        $this->_reportFormatMoney($paymentAmount),
                        $this->_reportFormatMoney($balanceAmount),
                        '<a href="'.$esc($openUrl).'" class="btn btn-xs btn-primary">'.__('Open Ledger').'</a>'
                    );
                    $totalPurchase += $purchaseAmount;
                    $totalPayment += $paymentAmount;
                    $totalBalance += $balanceAmount;
                }
                $rows[] = array(
                    'Total',
                    $this->_reportFormatMoney($totalPurchase),
                    $this->_reportFormatMoney($totalPayment),
                    $this->_reportFormatMoney($totalBalance),
                    '-'
                );
                $vendorLedgerSummary = array(
                    'credit_material' => (float)$totalPurchase,
                    'debit_paid' => (float)$totalPayment,
                    'balance' => (float)$totalBalance
                );
                $reportData = array(
                    'title' => 'Vendor Ledger Summary',
                    'columns' => array('Vendor','Credit Material','Debit Paid','Balance','Action'),
                    'rightCols' => array(1,2,3),
                    'rawCols' => array(4),
                    'rows' => $rows
                );
            }
        }
        elseif($activeTab === 'payroll_register')
        {
            $rows = array(); foreach($payrollIn as $p){$rows[] = array($this->_reportMonthLabel($p['payroll_month']),$p['full_name']!==''?$p['full_name']:('Employee #'.(int)$p['employee_id']),$p['department']!==''?$p['department']:'-',$this->_reportFormatMoney($p['gross_pay']),$this->_reportFormatMoney($p['net_pay']),$this->_reportFormatMoney($p['paid_amount']),$this->_reportFormatMoney($p['due_amount']),$p['status']);}
            $reportData = array('title' => 'Payroll Register', 'columns' => array('Month','Employee','Department','Gross','Net','Paid','Due','Status'), 'rightCols' => array(3,4,5,6), 'rows' => $rows);
        }
        elseif($activeTab === 'kpi')
        {
            $inHand = 0.0; $totalAsset = 0.0;
            foreach($liquidityLedgers as $ledger)
            {
                $ledgerAmount = (float)$ledger['balance'];
                if($hasRange)
                {
                    $ledgerAmount = 0.0;
                    $lid = (int)$ledger['id'];
                    foreach(isset($txFilteredByLedger[$lid]) ? $txFilteredByLedger[$lid] : array() as $tx)
                    {
                        $type = strtolower(trim((string)$tx['type']));
                        if($type === 'income' || $type === 'transfer_in'){$ledgerAmount += (float)$tx['amount'];}
                        elseif($type === 'expense' || $type === 'transfer_out'){$ledgerAmount -= (float)$tx['amount'];}
                    }
                }
                $totalAsset += $ledgerAmount;
                $n=strtolower((string)$ledger['name']);if(strpos($n,'cash')!==false || strpos($n,'hand')!==false){$inHand += $ledgerAmount;}
            }
            $stockValue = 0.0; $sm = array(); foreach($stockFiltered as $s){$k=trim((string)$s['material_type']).'||'.trim((string)$s['unit_type']);if(!isset($sm[$k])){$sm[$k]=array('qin'=>0.0,'qout'=>0.0,'inval'=>0.0);} if(strtolower((string)$s['movement_type'])==='out'){$sm[$k]['qout'] += (float)$s['quantity'];}else{$sm[$k]['qin'] += (float)$s['quantity'];$sm[$k]['inval'] += ((float)$s['quantity'])*((float)$s['unit_cost']);}}
            foreach($sm as $sv){$avg=($sv['qin']>0)?($sv['inval']/$sv['qin']):0.0;$stockValue += (($sv['qin']-$sv['qout'])*$avg);}
            $vendorPurchase = 0.0; $vendorPayment = 0.0; foreach($invoiceIn as $inv){$vendorPurchase += (float)$inv['amount'];} foreach($paymentIn as $pay){$vendorPayment += (float)$pay['amount'];}
            $payrollDue = 0.0; foreach($payrollIn as $p){$payrollDue += (float)$p['due_amount'];}
            $constructionSpend = $vendorPayment;
            $rows = array(
                array('Cash In Hand',$this->_reportFormatMoney($inHand),'Liquidity available as cash'),
                array('Cash In Account',$this->_reportFormatMoney($totalAsset - $inHand),'Bank/account balances'),
                array('Stock Value',$this->_reportFormatMoney($stockValue),'Material on-hand value'),
                array('Vendor Due',$this->_reportFormatMoney($vendorPurchase - $vendorPayment),'Outstanding payable to vendors'),
                array('Payroll Due',$this->_reportFormatMoney($payrollDue),'Outstanding salaries'),
                array('Construction Spend',$this->_reportFormatMoney($constructionSpend),'Vendor payments in selected filter'),
                array('Net Financial Position',$this->_reportFormatMoney($totalAsset - ($vendorPurchase - $vendorPayment) - $payrollDue),'Asset minus major liabilities')
            );
            $reportData = array('title' => 'KPI Dashboard', 'columns' => array('Metric','Value','Notes'), 'rightCols' => array(1), 'rows' => $rows);
        }
        else
        {
            if($activeTab === 'audit')
            {
                $rows = array();
                foreach($transactionsFiltered as $tx)
                {
                    $auditDate = '-';
                    $auditTs = strtotime((string)$tx['entry_date']);
                    if($auditTs !== false)
                    {
                        $auditDate = date('d-M-Y', $auditTs);
                    }
                    $rows[] = array(
                        $auditDate,
                        $tx['ledger_name'] !== '' ? $tx['ledger_name'] : ('Ledger #' . (int)$tx['ledger_id']),
                        ucfirst((string)$tx['type']),
                        (string)$tx['ref_no'],
                        $this->_reportFormatMoney($tx['amount'])
                    );
                }
                $reportData = array('title' => 'Audit', 'columns' => array('Date','Account','Type','Ref','Amount'), 'rightCols' => array(4), 'rows' => $rows);
            }
            else
            {
                $incomeTotal = 0.0;
                $expenseTotal = 0.0;
                $txCount = count($transactionsFiltered);
                foreach($transactionsFiltered as $tx)
                {
                    $type = strtolower((string)$tx['type']);
                    if($type === 'income' || $type === 'transfer_in')
                    {
                        $incomeTotal += (float)$tx['amount'];
                    }
                    elseif($type === 'expense' || $type === 'transfer_out')
                    {
                        $expenseTotal += (float)$tx['amount'];
                    }
                }
                $rows = array(
                    array('Transactions In Range', (string)$txCount),
                    array('Total Income', $this->_reportFormatMoney($incomeTotal)),
                    array('Total Expense', $this->_reportFormatMoney($expenseTotal)),
                    array('Net', $this->_reportFormatMoney($incomeTotal - $expenseTotal)),
                    array('Stock Entries In Range', (string)count($stockFiltered)),
                    array('Vendors', (string)count($vendorById))
                );
                $title = isset($tabLabelMap[$activeTab]) ? $tabLabelMap[$activeTab] : 'Report';
                $reportData = array('title' => $title, 'columns' => array('Metric','Value'), 'rightCols' => array(1), 'rows' => $rows);
            }
        }

        if(isset($this->request->query['export']) && strtolower(trim((string)$this->request->query['export'])) === 'csv')
        {
            $lines = array();
            $head = array();
            foreach($reportData['columns'] as $c){$head[] = $this->_reportCsvEscape($c);}
            $lines[] = implode(',', $head);
            foreach($reportData['rows'] as $r){$line = array(); foreach($r as $c){$line[] = $this->_reportCsvEscape($c);} $lines[] = implode(',', $line);}
            $csv = implode("\r\n", $lines);
            $filename = preg_replace('/[^a-z0-9]+/i', '_', strtolower((string)$reportData['title']));
            if($filename === ''){$filename = 'report';}
            $filename .= '_' . date('Ymd') . '.csv';
            $this->autoRender = false;
            $this->response->type('csv');
            $this->response->download($filename);
            $this->response->body($csv);
            return $this->response;
        }

        $this->set('projectName', $isReportSystemManager ? $reportAssignedProjects : $this->_projectList());
        $this->set('currentProjectId', $id);
        $reportAgency = array();
        if((int)$id > 0)
        {
            $agencySchema = (array)$this->Agency->schema();
            $agencyFields = array('Agency.id');
            $optionalAgencyFields = array('name','address','phone','mobile','email','photo');
            foreach($optionalAgencyFields as $optionalField)
            {
                if(isset($agencySchema[$optionalField]))
                {
                    $agencyFields[] = 'Agency.' . $optionalField;
                }
            }
            $agencyRow = $this->Agency->find('first', array(
                'fields' => $agencyFields,
                'conditions' => array('Agency.id' => (int)$id),
                'recursive' => -1
            ));
            if(!empty($agencyRow['Agency']) && is_array($agencyRow['Agency']))
            {
                $reportAgency = $agencyRow['Agency'];
            }
        }
        $this->set('reportAgency', $reportAgency);
        $this->set('reportTabs', $reportTabs);
        $this->set('activeReportTab', $activeTab);
        $this->set('reportPreset', $dateRange['preset']);
        $this->set('reportStart', $dateRange['start']);
        $this->set('reportEnd', $dateRange['end']);
        $this->set('reportVendorList', $reportVendorList);
        $this->set('selectedVendorId', $selectedVendorId);
        $this->set('selectedVendorName', $selectedVendorName);
        $this->set('vendorLedgerSummary', $vendorLedgerSummary);
        $this->set('reportData', $reportData);
        $this->set('balanceSheetSummary', $balanceSheetSummary);
    }

    public function accounting($id = null)
    {
        $this->loadModel('Admin.Ardledger');
        $this->loadModel('Admin.Ardtransaction');
        $this->loadModel('Admin.Ardrecurring');
        $this->loadModel('Admin.Ardbudget');
        $this->loadModel('Admin.Ardarap');
        $id = $this->_activeProjectId($id);

        $ledgerScope = $this->_scopeCondition('Ardledger.project_id', $id);
        $txScope = $this->_scopeCondition('Ardtransaction.project_id', $id);
        $recurringScope = $this->_scopeCondition('Ardrecurring.project_id', $id);
        $budgetScope = $this->_scopeCondition('Ardbudget.project_id', $id);
        $arapScope = $this->_scopeCondition('Ardarap.project_id', $id);

        $this->set('projectName', $this->_projectList());
        $this->set('currentProjectId', $id);
        $this->set('summary', array(
            'ledgers' => $this->Ardledger->find('count', array('conditions' => array($ledgerScope, 'Ardledger.is_trashed' => 0))),
            'transactions' => $this->Ardtransaction->find('count', array('conditions' => array($txScope))),
            'recurring' => $this->Ardrecurring->find('count', array('conditions' => array($recurringScope))),
            'budgets' => $this->Ardbudget->find('count', array('conditions' => array($budgetScope))),
            'arap' => $this->Ardarap->find('count', array('conditions' => array($arapScope)))
        ));

        $this->set('recentRecurring', $this->Ardrecurring->find('all', array(
            'conditions' => array($recurringScope),
            'order' => array('Ardrecurring.id' => 'desc'),
            'limit' => 8,
            'recursive' => -1
        )));
        $this->set('recentArap', $this->Ardarap->find('all', array(
            'conditions' => array($arapScope),
            'order' => array('Ardarap.due_date' => 'asc', 'Ardarap.id' => 'desc'),
            'limit' => 8,
            'recursive' => -1
        )));
    }

    public function construction($id = null)
    {
        $this->loadModel('Admin.Ardsite');
        $this->loadModel('Admin.Ardstock');
        $this->loadModel('Admin.Ardvendor');
        $id = $this->_activeProjectId($id);

        $siteScope = $this->_scopeCondition('Ardsite.project_id', $id);
        $stockScope = $this->_scopeCondition('Ardstock.project_id', $id);
        $vendorScope = $this->_scopeCondition('Ardvendor.project_id', $id);
        $projectFilter = $this->_projectSqlCondition('project_id', $id);

        $poCount = $this->Ardsite->query("SELECT COUNT(*) AS total_count FROM ardaccounts_construction_purchase_orders WHERE {$projectFilter}");
        $grnCount = $this->Ardsite->query("SELECT COUNT(*) AS total_count FROM ardaccounts_construction_grn WHERE {$projectFilter}");
        $piCount = $this->Ardsite->query("SELECT COUNT(*) AS total_count FROM ardaccounts_construction_purchase_invoices WHERE {$projectFilter}");
        $ppCount = $this->Ardsite->query("SELECT COUNT(*) AS total_count FROM ardaccounts_construction_purchase_invoice_payments WHERE {$projectFilter}");
        $labourCount = $this->Ardsite->query("SELECT COUNT(*) AS total_count FROM ardaccounts_construction_labours WHERE {$projectFilter}");
        $attCount = $this->Ardsite->query("SELECT COUNT(*) AS total_count FROM ardaccounts_construction_labour_attendance WHERE {$projectFilter}");
        $reorderCount = $this->Ardsite->query("SELECT COUNT(*) AS total_count FROM ardaccounts_construction_reorder_rules WHERE {$projectFilter}");
        $projectCount = $this->Ardsite->query("SELECT COUNT(*) AS total_count FROM ardaccounts_construction_projects WHERE {$projectFilter}");
        $contractCount = $this->Ardsite->query("SELECT COUNT(*) AS total_count FROM ardaccounts_construction_contracts WHERE {$projectFilter}");
        $billCount = $this->Ardsite->query("SELECT COUNT(*) AS total_count FROM ardaccounts_construction_contract_bills WHERE {$projectFilter}");

        $this->set('projectName', $this->_projectList());
        $this->set('currentProjectId', $id);
        $this->set('summary', array(
            'sites' => $this->Ardsite->find('count', array('conditions' => array($siteScope))),
            'stock' => $this->Ardstock->find('count', array('conditions' => array($stockScope))),
            'vendors' => $this->Ardvendor->find('count', array('conditions' => array($vendorScope))),
            'purchase_orders' => (int)$poCount[0][0]['total_count'],
            'grn' => (int)$grnCount[0][0]['total_count'],
            'purchase_invoices' => (int)$piCount[0][0]['total_count'],
            'purchase_payments' => (int)$ppCount[0][0]['total_count'],
            'labours' => (int)$labourCount[0][0]['total_count'],
            'attendance' => (int)$attCount[0][0]['total_count'],
            'reorder_rules' => (int)$reorderCount[0][0]['total_count'],
            'construction_projects' => (int)$projectCount[0][0]['total_count'],
            'contracts' => (int)$contractCount[0][0]['total_count'],
            'contract_bills' => (int)$billCount[0][0]['total_count']
        ));
        $this->set('recentVendors', $this->Ardvendor->find('all', array(
            'conditions' => array($vendorScope),
            'order' => array('Ardvendor.id' => 'desc'),
            'limit' => 8,
            'recursive' => -1
        )));
    }

    public function constructionprojects($id = null)
    {
        $this->loadModel('Admin.Ardconstructionproject');
        $this->loadModel('Admin.Ardconstructionmilestone');
        $this->loadModel('Admin.Ardconstructionconsumption');
        $this->loadModel('Admin.Ardsite');
        $this->loadModel('Admin.Ardhremployee');
        $id = $this->_activeProjectId($id);
        $editId = $this->_extractEditIdFromRequest();
        $milestoneEditId = isset($this->request->query['milestone_edit']) ? (int)$this->request->query['milestone_edit'] : 0;

        $this->set('projectName', $this->_projectList());
        $this->set('agencyId', $this->agencyId);
        $this->set('currentProjectId', $id);
        $this->set('date', CakeTime::format($this->dtFormat, CakeTime::convert(time(), $this->siteTimezone)));
        $consStart = $this->_normalizeYmdDate(isset($this->request->query['cons_start']) ? $this->request->query['cons_start'] : '', '');
        $consEnd = $this->_normalizeYmdDate(isset($this->request->query['cons_end']) ? $this->request->query['cons_end'] : '', '');
        if($consStart !== '' && $consEnd !== '' && strtotime($consStart) > strtotime($consEnd))
        {
            $tmpCons = $consStart;
            $consStart = $consEnd;
            $consEnd = $tmpCons;
        }
        $this->set('consStart', $consStart);
        $this->set('consEnd', $consEnd);

        $siteScope = $this->_scopeCondition('Ardsite.project_id', $id);
        $siteList = $this->Ardsite->find('list', array(
            'fields' => array('Ardsite.id', 'Ardsite.site_name'),
            'conditions' => array($siteScope),
            'order' => array('Ardsite.site_name' => 'asc')
        ));
        $this->set('siteList', $siteList);

        $employeeScope = $this->_scopeCondition('Ardhremployee.project_id', $id);
        $employeeList = $this->Ardhremployee->find('list', array(
            'fields' => array('Ardhremployee.id', 'Ardhremployee.full_name'),
            'conditions' => array($employeeScope),
            'order' => array('Ardhremployee.full_name' => 'asc')
        ));
        $this->set('employeeList', $employeeList);
        $labourList = array();
        $labourSqlScope = $this->_projectSqlCondition('project_id', $id);
        $labourRows = $this->Ardsite->query(
            "SELECT id, full_name
             FROM ardaccounts_construction_labours
             WHERE {$labourSqlScope}
             ORDER BY full_name ASC"
        );
        foreach((array)$labourRows as $labourRow)
        {
            $l = isset($labourRow[0]) ? $labourRow[0] : array();
            $labourId = isset($l['id']) ? (int)$l['id'] : 0;
            if($labourId <= 0)
            {
                continue;
            }
            $labourName = trim((string)(isset($l['full_name']) ? $l['full_name'] : ''));
            if($labourName === '')
            {
                $labourName = 'Labour #' . $labourId;
            }
            $labourList[$labourId] = $labourName;
        }
        if(empty($labourList))
        {
            foreach((array)$employeeList as $empId => $empName)
            {
                $labourList[(int)$empId] = (string)$empName;
            }
        }
        $this->set('labourList', $labourList);

        if($this->request->is(array('post', 'put')))
        {
            $formType = '';
            if(isset($this->request->data['_form_type']))
            {
                $formType = strtolower(trim((string)$this->request->data['_form_type']));
            }
            elseif(isset($this->request->data['Ardconstructionproject']['_form_type']))
            {
                $formType = strtolower(trim((string)$this->request->data['Ardconstructionproject']['_form_type']));
            }
            elseif(isset($this->request->data['Ardconstructionmilestone']['_form_type']))
            {
                $formType = strtolower(trim((string)$this->request->data['Ardconstructionmilestone']['_form_type']));
            }
            elseif(isset($this->request->data['Ardconstructionconsumption']['_form_type']))
            {
                $formType = strtolower(trim((string)$this->request->data['Ardconstructionconsumption']['_form_type']));
            }
            if($formType === '')
            {
                if(!empty($this->request->data['Ardconstructionmilestone']))
                {
                    $formType = 'milestone';
                }
                elseif(!empty($this->request->data['Ardconstructionconsumption']))
                {
                    $formType = 'labour_consumption';
                }
                else
                {
                    $formType = 'project';
                }
            }

            if($formType === 'labour_consumption')
            {
                $row = isset($this->request->data['Ardconstructionconsumption']) ? $this->request->data['Ardconstructionconsumption'] : array();
                $row['id'] = isset($row['id']) ? (int)$row['id'] : 0;
                $row['project_id'] = $this->_resolveProjectId(isset($row['project_id']) ? $row['project_id'] : null);
                $row['construction_project_id'] = isset($row['construction_project_id']) ? (int)$row['construction_project_id'] : 0;
                $row['milestone_id'] = isset($row['milestone_id']) ? (int)$row['milestone_id'] : 0;
                $row['labour_id'] = isset($row['labour_id']) ? (int)$row['labour_id'] : 0;
                $row['quantity'] = round((float)(isset($row['quantity']) ? $row['quantity'] : 0), 3);
                $row['unit_cost'] = round((float)(isset($row['unit_cost']) ? $row['unit_cost'] : 0), 2);
                $row['total_cost'] = round($row['quantity'] * $row['unit_cost'], 2);
                $row['entry_date'] = $this->_normalizeYmdDate(isset($row['entry_date']) ? $row['entry_date'] : '', date('Y-m-d'));
                $row['unit_type'] = trim((string)(isset($row['unit_type']) ? $row['unit_type'] : 'day'));
                $row['notes'] = trim((string)(isset($row['notes']) ? $row['notes'] : ''));
                $row['consumption_type'] = 'labour';
                $row['stock_entry_id'] = 0;

                if(!$this->_isAllowedProject($row['project_id']) || $row['construction_project_id'] <= 0 || $row['quantity'] <= 0)
                {
                    $this->Session->setFlash(__('Please fill required labour consumption fields.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect(array('action' => 'constructionprojects', $id));
                }

                $projectRow = $this->Ardconstructionproject->find('first', array(
                    'conditions' => array(
                        'Ardconstructionproject.id' => (int)$row['construction_project_id'],
                        'Ardconstructionproject.project_id' => (int)$row['project_id']
                    ),
                    'recursive' => -1
                ));
                if(empty($projectRow['Ardconstructionproject']))
                {
                    $this->Session->setFlash(__('Invalid construction project selected.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect(array('action' => 'constructionprojects', $id));
                }
                $row['site_id'] = isset($projectRow['Ardconstructionproject']['site_id']) ? (int)$projectRow['Ardconstructionproject']['site_id'] : 0;

                if($row['milestone_id'] > 0)
                {
                    $validMilestone = $this->Ardconstructionmilestone->find('first', array(
                        'conditions' => array(
                            'Ardconstructionmilestone.id' => (int)$row['milestone_id'],
                            'Ardconstructionmilestone.project_id' => (int)$row['project_id'],
                            'Ardconstructionmilestone.construction_project_id' => (int)$row['construction_project_id']
                        ),
                        'recursive' => -1
                    ));
                    if(empty($validMilestone['Ardconstructionmilestone']))
                    {
                        $this->Session->setFlash(__('Please select valid milestone for selected construction project.'), 'flash', array('alert' => 'danger'));
                        return $this->redirect(array('action' => 'constructionprojects', $id));
                    }
                }

                $labourLabel = '';
                if($row['labour_id'] > 0)
                {
                    $labourNameRows = $this->Ardsite->query(
                        "SELECT full_name FROM ardaccounts_construction_labours WHERE id=" . (int)$row['labour_id'] . " AND " . $this->_projectSqlCondition('project_id', $row['project_id']) . " LIMIT 1"
                    );
                    if(!empty($labourNameRows[0][0]['full_name']))
                    {
                        $labourLabel = trim((string)$labourNameRows[0][0]['full_name']);
                    }
                    elseif(!empty($employeeList[(int)$row['labour_id']]))
                    {
                        $labourLabel = trim((string)$employeeList[(int)$row['labour_id']]);
                    }
                }
                $row['material_type'] = ($labourLabel !== '') ? $labourLabel : 'Labour';

                if($row['id'] > 0)
                {
                    $existingCons = $this->Ardconstructionconsumption->findById($row['id']);
                    if(empty($existingCons) || !$this->_isAllowedProject((int)$existingCons['Ardconstructionconsumption']['project_id']))
                    {
                        $this->Session->setFlash(__('Invalid labour consumption record.'), 'flash', array('alert' => 'danger'));
                        return $this->redirect(array('action' => 'constructionprojects', $id));
                    }
                    $this->Ardconstructionconsumption->id = $row['id'];
                }
                else
                {
                    unset($row['id']);
                    $this->Ardconstructionconsumption->create();
                }

                if($this->Ardconstructionconsumption->save(array('Ardconstructionconsumption' => $row), false))
                {
                    $this->Session->setFlash(__('Labour consumption saved successfully.'), 'flash', array('alert' => 'success'));
                }
                else
                {
                    $this->Session->setFlash(__('Unable to save labour consumption.'), 'flash', array('alert' => 'danger'));
                }
                return $this->redirect(array('action' => 'constructionprojects', $id));
            }

            if($formType === 'milestone')
            {
                $row = isset($this->request->data['Ardconstructionmilestone']) ? $this->request->data['Ardconstructionmilestone'] : array();
                $row['id'] = isset($row['id']) ? (int)$row['id'] : 0;
                $row['project_id'] = $this->_resolveProjectId(isset($row['project_id']) ? $row['project_id'] : null);
                $row['construction_project_id'] = isset($row['construction_project_id']) ? (int)$row['construction_project_id'] : 0;
                $row['title'] = trim((string)(isset($row['title']) ? $row['title'] : ''));
                $row['target_date'] = $this->_normalizeYmdDate(isset($row['target_date']) ? $row['target_date'] : '', '');
                $row['completed_date'] = $this->_normalizeYmdDate(isset($row['completed_date']) ? $row['completed_date'] : '', '');
                $row['status'] = strtolower(trim((string)(isset($row['status']) ? $row['status'] : 'pending')));
                if(!in_array($row['status'], array('pending', 'in_progress', 'completed', 'hold')))
                {
                    $row['status'] = 'pending';
                }
                $row['budget_amount'] = round((float)(isset($row['budget_amount']) ? $row['budget_amount'] : 0), 2);
                $row['material_cost'] = round((float)(isset($row['material_cost']) ? $row['material_cost'] : 0), 2);
                $row['labour_cost'] = round((float)(isset($row['labour_cost']) ? $row['labour_cost'] : 0), 2);
                $row['notes'] = trim((string)(isset($row['notes']) ? $row['notes'] : ''));

                if(!$this->_isAllowedProject($row['project_id']) || $row['construction_project_id'] <= 0 || $row['title'] === '')
                {
                    $this->Session->setFlash(__('Please fill required milestone fields.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect(array('action' => 'constructionprojects', $id));
                }
                $projectRow = $this->Ardconstructionproject->find('first', array(
                    'conditions' => array(
                        'Ardconstructionproject.id' => (int)$row['construction_project_id'],
                        'Ardconstructionproject.project_id' => (int)$row['project_id']
                    ),
                    'recursive' => -1
                ));
                if(empty($projectRow['Ardconstructionproject']))
                {
                    $this->Session->setFlash(__('Invalid construction project selected.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect(array('action' => 'constructionprojects', $id));
                }

                if($row['id'] > 0)
                {
                    $this->Ardconstructionmilestone->id = $row['id'];
                }
                else
                {
                    unset($row['id']);
                    $this->Ardconstructionmilestone->create();
                }
                if($this->Ardconstructionmilestone->save(array('Ardconstructionmilestone' => $row), false))
                {
                    $this->Session->setFlash(__('Milestone saved successfully.'), 'flash', array('alert' => 'success'));
                }
                else
                {
                    $this->Session->setFlash(__('Unable to save milestone.'), 'flash', array('alert' => 'danger'));
                }
                return $this->redirect(array('action' => 'constructionprojects', $id));
            }

            $row = isset($this->request->data['Ardconstructionproject']) ? $this->request->data['Ardconstructionproject'] : array();
            $row['id'] = isset($row['id']) ? (int)$row['id'] : 0;
            if($row['id'] <= 0 && $editId > 0)
            {
                $row['id'] = $editId;
            }
            $row['project_id'] = $this->_resolveProjectId(isset($row['project_id']) ? $row['project_id'] : null);
            $row['site_id'] = isset($row['site_id']) ? (int)$row['site_id'] : 0;
            $row['name'] = trim((string)(isset($row['name']) ? $row['name'] : ''));
            $row['project_code'] = trim((string)(isset($row['project_code']) ? $row['project_code'] : ''));
            $row['workflow_stage'] = strtolower(trim((string)(isset($row['workflow_stage']) ? $row['workflow_stage'] : 'planning')));
            if(!in_array($row['workflow_stage'], array('planning', 'foundation', 'structure', 'finishing', 'handover')))
            {
                $row['workflow_stage'] = 'planning';
            }
            $row['start_date'] = $this->_normalizeYmdDate(isset($row['start_date']) ? $row['start_date'] : '', '');
            $row['expected_end_date'] = $this->_normalizeYmdDate(isset($row['expected_end_date']) ? $row['expected_end_date'] : '', '');
            $row['completed_date'] = $this->_normalizeYmdDate(isset($row['completed_date']) ? $row['completed_date'] : '', '');
            $row['manager_name'] = trim((string)(isset($row['manager_name']) ? $row['manager_name'] : ''));
            $row['manager_phone'] = trim((string)(isset($row['manager_phone']) ? $row['manager_phone'] : ''));
            $row['budget_total'] = round((float)(isset($row['budget_total']) ? $row['budget_total'] : 0), 2);
            $row['budget_material'] = round((float)(isset($row['budget_material']) ? $row['budget_material'] : 0), 2);
            $row['budget_labour'] = round((float)(isset($row['budget_labour']) ? $row['budget_labour'] : 0), 2);
            $row['status'] = strtolower(trim((string)(isset($row['status']) ? $row['status'] : 'active')));
            if(!in_array($row['status'], array('active', 'hold', 'completed', 'cancelled')))
            {
                $row['status'] = 'active';
            }
            $row['notes'] = trim((string)(isset($row['notes']) ? $row['notes'] : ''));

            if(!$this->_isAllowedProject($row['project_id']) || $row['name'] === '' || $row['site_id'] <= 0)
            {
                $this->Session->setFlash(__('Please fill required construction project fields.'), 'flash', array('alert' => 'danger'));
                return $this->redirect(array('action' => 'constructionprojects', $id));
            }

            if($row['id'] > 0)
            {
                $this->Ardconstructionproject->id = $row['id'];
            }
            else
            {
                if($row['project_code'] === '')
                {
                    $row['project_code'] = 'CP-' . strtoupper(substr(md5(uniqid('', true)), 0, 6));
                }
                $this->Ardconstructionproject->create();
            }
            if($this->Ardconstructionproject->save(array('Ardconstructionproject' => $row), false))
            {
                $this->Session->setFlash(__('Construction project saved successfully.'), 'flash', array('alert' => 'success'));
            }
            else
            {
                $this->Session->setFlash(__('Unable to save construction project.'), 'flash', array('alert' => 'danger'));
            }
            return $this->redirect(array('action' => 'constructionprojects', $id));
        }

        $projectScope = $this->_scopeCondition('Ardconstructionproject.project_id', $id);
        $this->Paginator->settings = array(
            'page' => 1,
            'order' => array('Ardconstructionproject.id' => 'desc'),
            'limit' => $this->pageLimit,
            'maxLimit' => $this->maxLimit,
            'conditions' => array($projectScope)
        );
        $projects = $this->Paginator->paginate('Ardconstructionproject');
        $this->set('rows', $projects);

        $projectIds = array();
        foreach((array)$projects as $projectRow)
        {
            if(!empty($projectRow['Ardconstructionproject']['id']))
            {
                $projectIds[] = (int)$projectRow['Ardconstructionproject']['id'];
            }
        }

        $milestoneRows = array();
        if(!empty($projectIds))
        {
            $milestoneRows = $this->Ardconstructionmilestone->find('all', array(
                'conditions' => array(
                    'Ardconstructionmilestone.project_id' => (int)$id,
                    'Ardconstructionmilestone.construction_project_id' => $projectIds
                ),
                'order' => array('Ardconstructionmilestone.id' => 'desc'),
                'recursive' => -1
            ));
        }
        $milestonesByProject = array();
        $milestoneOptions = array();
        $milestoneProjectMap = array();
        foreach((array)$milestoneRows as $milestoneRow)
        {
            if(empty($milestoneRow['Ardconstructionmilestone']))
            {
                continue;
            }
            $m = $milestoneRow['Ardconstructionmilestone'];
            $pid = (int)$m['construction_project_id'];
            if(!isset($milestonesByProject[$pid]))
            {
                $milestonesByProject[$pid] = array();
            }
            $milestonesByProject[$pid][] = $m;
            $mid = isset($m['id']) ? (int)$m['id'] : 0;
            if($mid > 0)
            {
                $milestoneOptions[$mid] = trim((string)$m['title']) !== '' ? (string)$m['title'] : ('Milestone #' . $mid);
                $milestoneProjectMap[$mid] = $pid;
            }
        }
        $this->set('milestonesByProject', $milestonesByProject);
        $this->set('milestoneOptions', $milestoneOptions);
        $this->set('milestoneProjectMap', $milestoneProjectMap);

        $consumptionSummary = array();
        $projectConsumptionBreakdown = array();
        foreach((array)$projectIds as $cpId)
        {
            $projectConsumptionBreakdown[(int)$cpId] = array(
                'material_qty' => 0,
                'material_cost' => 0,
                'labour_qty' => 0,
                'labour_cost' => 0,
                'total_qty' => 0,
                'total_cost' => 0
            );
        }

        $consumptionConditions = array(
            'Ardconstructionconsumption.project_id' => (int)$id
        );
        if(!empty($projectIds))
        {
            $consumptionConditions['Ardconstructionconsumption.construction_project_id'] = $projectIds;
        }
        if($consStart !== '')
        {
            $consumptionConditions['Ardconstructionconsumption.entry_date >='] = $consStart;
        }
        if($consEnd !== '')
        {
            $consumptionConditions['Ardconstructionconsumption.entry_date <='] = $consEnd;
        }

        if(!empty($projectIds))
        {
            $consRows = $this->Ardconstructionconsumption->find('all', array(
                'fields' => array(
                    'Ardconstructionconsumption.construction_project_id',
                    'Ardconstructionconsumption.consumption_type',
                    'SUM(Ardconstructionconsumption.quantity) AS total_qty',
                    'SUM(Ardconstructionconsumption.total_cost) AS total_cost'
                ),
                'conditions' => $consumptionConditions,
                'group' => array('Ardconstructionconsumption.construction_project_id', 'Ardconstructionconsumption.consumption_type'),
                'recursive' => -1
            ));
            foreach((array)$consRows as $consRow)
            {
                $cpId = isset($consRow['Ardconstructionconsumption']['construction_project_id']) ? (int)$consRow['Ardconstructionconsumption']['construction_project_id'] : 0;
                if($cpId <= 0 || !isset($projectConsumptionBreakdown[$cpId]))
                {
                    continue;
                }
                $consType = strtolower(trim((string)(isset($consRow['Ardconstructionconsumption']['consumption_type']) ? $consRow['Ardconstructionconsumption']['consumption_type'] : 'material')));
                $qty = isset($consRow[0]['total_qty']) ? (float)$consRow[0]['total_qty'] : 0;
                $cost = isset($consRow[0]['total_cost']) ? (float)$consRow[0]['total_cost'] : 0;
                if($consType === 'labour')
                {
                    $projectConsumptionBreakdown[$cpId]['labour_qty'] += $qty;
                    $projectConsumptionBreakdown[$cpId]['labour_cost'] += $cost;
                }
                else
                {
                    $projectConsumptionBreakdown[$cpId]['material_qty'] += $qty;
                    $projectConsumptionBreakdown[$cpId]['material_cost'] += $cost;
                }
                $projectConsumptionBreakdown[$cpId]['total_qty'] += $qty;
                $projectConsumptionBreakdown[$cpId]['total_cost'] += $cost;
            }
        }

        foreach((array)$projectConsumptionBreakdown as $cpId => $summary)
        {
            $consumptionSummary[(int)$cpId] = array(
                'total_qty' => (float)$summary['total_qty'],
                'total_cost' => (float)$summary['total_cost'],
                'material_qty' => (float)$summary['material_qty'],
                'material_cost' => (float)$summary['material_cost'],
                'labour_qty' => (float)$summary['labour_qty'],
                'labour_cost' => (float)$summary['labour_cost']
            );
        }
        $this->set('consumptionSummary', $consumptionSummary);
        $this->set('projectConsumptionBreakdown', $projectConsumptionBreakdown);

        $milestoneActualById = array();
        $milestoneProgressById = array();
        $projectProgressById = array();
        if(!empty($projectIds))
        {
            $milestoneConsumptionConditions = $consumptionConditions;
            $milestoneConsumptionConditions['Ardconstructionconsumption.milestone_id >'] = 0;
            $milestoneConsRows = $this->Ardconstructionconsumption->find('all', array(
                'fields' => array(
                    'Ardconstructionconsumption.milestone_id',
                    'Ardconstructionconsumption.consumption_type',
                    'SUM(Ardconstructionconsumption.quantity) AS total_qty',
                    'SUM(Ardconstructionconsumption.total_cost) AS total_cost'
                ),
                'conditions' => $milestoneConsumptionConditions,
                'group' => array('Ardconstructionconsumption.milestone_id', 'Ardconstructionconsumption.consumption_type'),
                'recursive' => -1
            ));
            foreach((array)$milestoneConsRows as $milestoneConsRow)
            {
                $mid = isset($milestoneConsRow['Ardconstructionconsumption']['milestone_id']) ? (int)$milestoneConsRow['Ardconstructionconsumption']['milestone_id'] : 0;
                if($mid <= 0)
                {
                    continue;
                }
                if(!isset($milestoneActualById[$mid]))
                {
                    $milestoneActualById[$mid] = array(
                        'material_qty' => 0,
                        'material_cost' => 0,
                        'labour_qty' => 0,
                        'labour_cost' => 0,
                        'total_qty' => 0,
                        'total_cost' => 0
                    );
                }
                $consType = strtolower(trim((string)(isset($milestoneConsRow['Ardconstructionconsumption']['consumption_type']) ? $milestoneConsRow['Ardconstructionconsumption']['consumption_type'] : 'material')));
                $qty = isset($milestoneConsRow[0]['total_qty']) ? (float)$milestoneConsRow[0]['total_qty'] : 0;
                $cost = isset($milestoneConsRow[0]['total_cost']) ? (float)$milestoneConsRow[0]['total_cost'] : 0;
                if($consType === 'labour')
                {
                    $milestoneActualById[$mid]['labour_qty'] += $qty;
                    $milestoneActualById[$mid]['labour_cost'] += $cost;
                }
                else
                {
                    $milestoneActualById[$mid]['material_qty'] += $qty;
                    $milestoneActualById[$mid]['material_cost'] += $cost;
                }
                $milestoneActualById[$mid]['total_qty'] += $qty;
                $milestoneActualById[$mid]['total_cost'] += $cost;
            }
        }

        foreach((array)$projects as $projectRow)
        {
            if(empty($projectRow['Ardconstructionproject']))
            {
                continue;
            }
            $projectData = $projectRow['Ardconstructionproject'];
            $cpId = isset($projectData['id']) ? (int)$projectData['id'] : 0;
            if($cpId <= 0)
            {
                continue;
            }
            $projectMilestones = isset($milestonesByProject[$cpId]) ? $milestonesByProject[$cpId] : array();
            $projectBudgetWeight = 0.0;
            $projectWeightedProgress = 0.0;
            $projectSimpleProgress = 0.0;
            $projectMilestoneCount = 0;
            foreach((array)$projectMilestones as $ms)
            {
                $mid = isset($ms['id']) ? (int)$ms['id'] : 0;
                if($mid <= 0)
                {
                    continue;
                }
                $msStatus = strtolower(trim((string)(isset($ms['status']) ? $ms['status'] : 'pending')));
                $msBudget = round((float)(isset($ms['budget_amount']) ? $ms['budget_amount'] : 0), 2);
                $msActual = isset($milestoneActualById[$mid]['total_cost']) ? (float)$milestoneActualById[$mid]['total_cost'] : 0;
                if($msBudget > 0)
                {
                    $msProgress = min(100, round(($msActual / $msBudget) * 100, 2));
                }
                else
                {
                    if($msStatus === 'completed')
                    {
                        $msProgress = 100;
                    }
                    elseif($msStatus === 'in_progress')
                    {
                        $msProgress = 50;
                    }
                    else
                    {
                        $msProgress = 0;
                    }
                }
                if($msStatus === 'completed' && $msProgress < 100)
                {
                    $msProgress = 100;
                }
                $milestoneProgressById[$mid] = round((float)$msProgress, 2);
                if(!isset($milestoneActualById[$mid]))
                {
                    $milestoneActualById[$mid] = array(
                        'material_qty' => 0,
                        'material_cost' => 0,
                        'labour_qty' => 0,
                        'labour_cost' => 0,
                        'total_qty' => 0,
                        'total_cost' => 0
                    );
                }
                $milestoneActualById[$mid]['progress_pct'] = $milestoneProgressById[$mid];
                $projectSimpleProgress += (float)$milestoneProgressById[$mid];
                $projectMilestoneCount++;
                if($msBudget > 0)
                {
                    $projectBudgetWeight += $msBudget;
                    $projectWeightedProgress += ($msBudget * (float)$milestoneProgressById[$mid]);
                }
            }
            if($projectBudgetWeight > 0)
            {
                $projectProgressById[$cpId] = round($projectWeightedProgress / $projectBudgetWeight, 2);
            }
            elseif($projectMilestoneCount > 0)
            {
                $projectProgressById[$cpId] = round($projectSimpleProgress / $projectMilestoneCount, 2);
            }
            else
            {
                $projectTotalBudget = round((float)(isset($projectData['budget_total']) ? $projectData['budget_total'] : 0), 2);
                $projectActualCost = isset($projectConsumptionBreakdown[$cpId]['total_cost']) ? (float)$projectConsumptionBreakdown[$cpId]['total_cost'] : 0;
                if($projectTotalBudget > 0)
                {
                    $projectProgressById[$cpId] = min(100, round(($projectActualCost / $projectTotalBudget) * 100, 2));
                }
                else
                {
                    $projectProgressById[$cpId] = 0;
                }
            }
        }
        $this->set('milestoneActualById', $milestoneActualById);
        $this->set('milestoneProgressById', $milestoneProgressById);
        $this->set('projectProgressById', $projectProgressById);

        $projectConsumptionChart = array(
            'labels' => array(),
            'material_cost' => array(),
            'labour_cost' => array(),
            'progress' => array()
        );
        foreach((array)$projects as $projectRow)
        {
            if(empty($projectRow['Ardconstructionproject']))
            {
                continue;
            }
            $projectData = $projectRow['Ardconstructionproject'];
            $cpId = isset($projectData['id']) ? (int)$projectData['id'] : 0;
            if($cpId <= 0)
            {
                continue;
            }
            $projectConsumptionChart['labels'][] = (string)$projectData['name'];
            $projectConsumptionChart['material_cost'][] = isset($projectConsumptionBreakdown[$cpId]['material_cost']) ? round((float)$projectConsumptionBreakdown[$cpId]['material_cost'], 2) : 0;
            $projectConsumptionChart['labour_cost'][] = isset($projectConsumptionBreakdown[$cpId]['labour_cost']) ? round((float)$projectConsumptionBreakdown[$cpId]['labour_cost'], 2) : 0;
            $projectConsumptionChart['progress'][] = isset($projectProgressById[$cpId]) ? round((float)$projectProgressById[$cpId], 2) : 0;
        }
        $this->set('projectConsumptionChart', $projectConsumptionChart);

        $this->set('constructionProjectList', $this->Ardconstructionproject->find('list', array(
            'fields' => array('Ardconstructionproject.id', 'Ardconstructionproject.name'),
            'conditions' => array($projectScope),
            'order' => array('Ardconstructionproject.name' => 'asc')
        )));

        if($editId > 0)
        {
            $editRow = $this->Ardconstructionproject->findById($editId);
            if(!empty($editRow) && $this->_isAllowedProject((int)$editRow['Ardconstructionproject']['project_id']))
            {
                $this->request->data['Ardconstructionproject'] = $editRow['Ardconstructionproject'];
            }
        }
        if($milestoneEditId > 0)
        {
            $milestoneEdit = $this->Ardconstructionmilestone->findById($milestoneEditId);
            if(!empty($milestoneEdit) && $this->_isAllowedProject((int)$milestoneEdit['Ardconstructionmilestone']['project_id']))
            {
                $this->request->data['Ardconstructionmilestone'] = $milestoneEdit['Ardconstructionmilestone'];
            }
        }
    }

    public function deleteconstructionproject($id = null, $projectId = null)
    {
        $this->loadModel('Admin.Ardconstructionproject');
        $this->loadModel('Admin.Ardconstructionmilestone');
        $this->loadModel('Admin.Ardconstructionconsumption');
        $row = $this->Ardconstructionproject->findById($id);
        if(empty($row) || !$this->_isAllowedProject((int)$row['Ardconstructionproject']['project_id']))
        {
            $this->Session->setFlash(__('Invalid construction project.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'constructionprojects', $projectId));
        }
        $childCount = $this->Ardconstructionmilestone->find('count', array(
            'conditions' => array(
                'Ardconstructionmilestone.project_id' => (int)$row['Ardconstructionproject']['project_id'],
                'Ardconstructionmilestone.construction_project_id' => (int)$row['Ardconstructionproject']['id']
            )
        ));
        $consCount = $this->Ardconstructionconsumption->find('count', array(
            'conditions' => array(
                'Ardconstructionconsumption.project_id' => (int)$row['Ardconstructionproject']['project_id'],
                'Ardconstructionconsumption.construction_project_id' => (int)$row['Ardconstructionproject']['id']
            )
        ));
        if($childCount > 0 || $consCount > 0)
        {
            $this->Session->setFlash(__('Cannot delete project with milestones or consumption records.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'constructionprojects', (int)$row['Ardconstructionproject']['project_id']));
        }
        $this->_storeTrashRecord(
            'ardaccounts_construction_projects',
            'Ardconstructionproject',
            $row['Ardconstructionproject'],
            isset($row['Ardconstructionproject']['name']) ? (string)$row['Ardconstructionproject']['name'] : ''
        );
        $this->Ardconstructionproject->delete($id);
        $this->Session->setFlash(__('Construction project deleted. You can restore it from Trash.'), 'flash', array('alert' => 'success'));
        return $this->redirect(array('action' => 'constructionprojects', (int)$row['Ardconstructionproject']['project_id']));
    }

    public function deletemilestone($id = null, $projectId = null)
    {
        $this->loadModel('Admin.Ardconstructionmilestone');
