    }

    public function hrpayroll($id = null)
    {
        $this->loadModel('Admin.Ardhremployee');
        $this->loadModel('Admin.Ardhpayroll');
        $this->loadModel('Admin.Ardhpayment');
        $id = $this->_activeProjectId($id);
        $employeeScope = $this->_hrEmployeeScopeFromRequest('all');
        $employeeScopeLabel = $this->_hrEmployeeScopeLabel($employeeScope);
        $projectEmployeeScope = $this->_scopeCondition('Ardhremployee.project_id', $id);
        $employeeScopeConditions = array($projectEmployeeScope);
        $employeeTypeConditions = $this->_hrEmployeeScopeConditions('Ardhremployee', $employeeScope);
        if(!empty($employeeTypeConditions))
        {
            $employeeScopeConditions = array_merge($employeeScopeConditions, $employeeTypeConditions);
        }

        $projectFilter = $this->_projectSqlCondition('project_id', $id);
        $employeeProjectFilter = $this->_projectSqlCondition('project_id', $id);
        $employeeScopeSql = $this->_hrEmployeeScopeSql('salary_type', $employeeScope);

        $payrollSqlFilter = $projectFilter;
        $paymentSqlFilter = $projectFilter;
        if($employeeScope !== 'all')
        {
            $scopedEmployeeSubQuery = "SELECT id FROM ardaccounts_hr_employees WHERE {$employeeProjectFilter} AND {$employeeScopeSql}";
            $payrollSqlFilter .= " AND employee_id IN ({$scopedEmployeeSubQuery})";
            $paymentSqlFilter .= " AND employee_id IN ({$scopedEmployeeSubQuery})";
        }

        $payrollCount = $this->Ardhremployee->query("SELECT COUNT(*) AS total_count FROM ardaccounts_hr_payroll WHERE {$payrollSqlFilter}");
        $paymentCount = $this->Ardhremployee->query("SELECT COUNT(*) AS total_count FROM ardaccounts_hr_payments WHERE {$paymentSqlFilter}");
        $payrollDue = $this->Ardhremployee->query("SELECT SUM(due_amount) AS due_total FROM ardaccounts_hr_payroll WHERE {$payrollSqlFilter}");

        $this->set('projectName', $this->_projectList());
        $this->set('currentProjectId', $id);
        $this->set('employeeScope', $employeeScope);
        $this->set('employeeScopeLabel', $employeeScopeLabel);
        $this->set('employeeScopeQuery', $this->_hrEmployeeScopeQuery($employeeScope));
        $this->set('summary', array(
            'employees' => $this->Ardhremployee->find('count', array('conditions' => $employeeScopeConditions)),
            'payroll_entries' => (int)$payrollCount[0][0]['total_count'],
            'payments' => (int)$paymentCount[0][0]['total_count'],
            'due' => (float)$payrollDue[0][0]['due_total']
        ));
        $this->set('recentEmployees', $this->Ardhremployee->find('all', array(
            'conditions' => $employeeScopeConditions,
            'order' => array('Ardhremployee.id' => 'desc'),
            'limit' => 10,
            'recursive' => -1
        )));
    }

    public function labourcontrol($id = null)
    {
        $this->loadModel('Admin.Ardlabour');
        $this->loadModel('Admin.Ardlabourattendance');
        $this->loadModel('Admin.Ardlabourpayment');
        $this->loadModel('Admin.Ardledger');
        $this->loadModel('Admin.Ardtransaction');
        $id = $this->_activeProjectId($id);

        $this->set('projectName', $this->_projectList());
        $this->set('agencyId', $this->agencyId);
        $this->set('currentProjectId', $id);
        $this->set('date', CakeTime::format($this->dtFormat, CakeTime::convert(time(), $this->siteTimezone)));

        $paymentLedgers = $this->Ardledger->find('list', array(
            'fields' => array('Ardledger.id', 'Ardledger.name'),
            'conditions' => array($this->_scopeCondition('Ardledger.project_id', $id), 'Ardledger.is_trashed' => 0, 'Ardledger.type !=' => 'expense'),
            'order' => array('Ardledger.name' => 'asc')
        ));
        $this->set('paymentLedgers', $paymentLedgers);

        if($this->request->is(array('post', 'put')))
        {
            $formType = isset($this->request->data['_form_type']) ? trim((string)$this->request->data['_form_type']) : 'labour';
            if($formType === 'attendance')
            {
                $row = isset($this->request->data['Ardlabourattendance']) ? $this->request->data['Ardlabourattendance'] : array();
                $row['project_id'] = $this->_resolveProjectId(isset($row['project_id']) ? $row['project_id'] : null);
                if(!$this->_isAllowedProject($row['project_id']))
                {
                    $this->Session->setFlash(__('Please select valid agency/project.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect($this->referer());
                }
                $row['attendance_date'] = !empty($row['attendance_date']) ? $this->_normalizeYmdDate($row['attendance_date'], date('Y-m-d')) : date('Y-m-d');
                $row['units'] = isset($row['units']) ? round((float)$row['units'], 2) : 1.0;
                $this->Ardlabourattendance->create();
                if($this->Ardlabourattendance->save(array('Ardlabourattendance' => $row)))
                {
                    $this->Session->setFlash(__('Attendance recorded successfully.'), 'flash', array('alert' => 'success'));
                }
                else
                {
                    $this->Session->setFlash(__('Unable to record attendance.'), 'flash', array('alert' => 'danger'));
                }
            }
            elseif($formType === 'payment')
            {
                $row = isset($this->request->data['Ardlabourpayment']) ? $this->request->data['Ardlabourpayment'] : array();
                $row['project_id'] = $this->_resolveProjectId(isset($row['project_id']) ? $row['project_id'] : null);
                if(!$this->_isAllowedProject($row['project_id']))
                {
                    $this->Session->setFlash(__('Please select valid agency/project.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect($this->referer());
                }
                $amount = round((float)(isset($row['amount']) ? $row['amount'] : 0), 2);
                $labourId = (int)(isset($row['labour_id']) ? $row['labour_id'] : 0);
                $debitLedgerId = (int)(isset($row['debit_ledger_id']) ? $row['debit_ledger_id'] : 0);
                $paymentDate = !empty($row['payment_date']) ? $this->_normalizeYmdDate($row['payment_date'], date('Y-m-d')) : date('Y-m-d');
                if($amount <= 0 || $labourId <= 0 || $debitLedgerId <= 0)
                {
                    $this->Session->setFlash(__('Please fill all payment fields correctly.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect($this->referer());
                }
                $labourName = (string)$this->Ardlabour->field('full_name', array('Ardlabour.id' => $labourId));
                $refNo = trim((string)(isset($row['reference_no']) ? $row['reference_no'] : ''));
                if($refNo === '')
                {
                    $refNo = $this->_nextReferenceNo((int)$row['project_id'], 'labour_pay', 'LPAY-');
                }
                $row['reference_no'] = $refNo;
                $row['payment_date'] = $paymentDate;
                $this->Ardlabourpayment->create();
                if($this->Ardlabourpayment->save(array('Ardlabourpayment' => $row)))
                {
                    $wipLedgerId = $this->_ardDefaultLedgerId((int)$row['project_id'], 'construction_wip_ledger_id', 'Construction WIP', 'asset');
                    $txPayload = array(
                        'project_id' => (int)$row['project_id'],
                        'ledger_id' => $debitLedgerId,
                        'expense_ledger_id' => $wipLedgerId,
                        'type' => 'expense',
                        'status' => 'Posted',
                        'amount' => $amount,
                        'description' => 'Labour wage payment: ' . $labourName . ' | ' . $refNo,
                        'ref_no' => $refNo,
                        'entry_date' => $paymentDate,
                        'construction_site_id' => 0,
                        'source_type' => 'labour_payment',
                        'source_id' => (int)$this->Ardlabourpayment->id,
                        'auto_posted' => 1
                    );
                    $this->Ardtransaction->create();
                    if($this->Ardtransaction->save(array('Ardtransaction' => $txPayload)))
                    {
                        $txId = (int)$this->Ardtransaction->id;
                        $this->_syncJournalForTransaction($txId, 'labour_payment', (int)$this->Ardlabourpayment->id);
                        $this->_recalculateLedgerBalance($debitLedgerId);
                        if($wipLedgerId > 0)
                        {
                            $this->_recalculateLedgerBalance($wipLedgerId);
                        }
                    }
                    $this->Session->setFlash(__('Labour wage payment posted successfully.'), 'flash', array('alert' => 'success'));
                }
                else
                {
                    $this->Session->setFlash(__('Unable to post wage payment.'), 'flash', array('alert' => 'danger'));
                }
            }
            else
            {
                $row = isset($this->request->data['Ardlabour']) ? $this->request->data['Ardlabour'] : array();
                $row['project_id'] = $this->_resolveProjectId(isset($row['project_id']) ? $row['project_id'] : null);
                if(!$this->_isAllowedProject($row['project_id']))
                {
                    $this->Session->setFlash(__('Please select valid agency/project.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect($this->referer());
                }
                $row['full_name'] = trim((string)(isset($row['full_name']) ? $row['full_name'] : ''));
                $row['daily_rate'] = round((float)(isset($row['daily_rate']) ? $row['daily_rate'] : 0), 2);
                if($row['full_name'] === '')
                {
                    $this->Session->setFlash(__('Please enter labour name.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect($this->referer());
                }
                $this->Ardlabour->create();
                if($this->Ardlabour->save(array('Ardlabour' => $row)))
                {
                    $this->Session->setFlash(__('Labourer saved successfully.'), 'flash', array('alert' => 'success'));
                }
                else
                {
                    $this->Session->setFlash(__('Unable to save labourer.'), 'flash', array('alert' => 'danger'));
                }
            }
            return $this->redirect(array('action' => 'labourcontrol', $id));
        }

        $labourScope = $this->_scopeCondition('Ardlabour.project_id', $id);
        $labours = $this->Ardlabour->find('all', array(
            'conditions' => array($labourScope),
            'order' => array('Ardlabour.full_name' => 'asc'),
            'recursive' => -1
        ));
        $labourList = array();
        foreach((array)$labours as $l)
        {
            if(!empty($l['Ardlabour']))
            {
                $labourList[(int)$l['Ardlabour']['id']] = $l['Ardlabour']['full_name'] . (!empty($l['Ardlabour']['labour_type']) ? ' ('.$l['Ardlabour']['labour_type'].')' : '') . ' - Rs.' . number_format($l['Ardlabour']['daily_rate'], 0) . '/day';
            }
        }
        $this->set('labours', $labours);
        $this->set('labourList', $labourList);

        $attScope = $this->_scopeCondition('Ardlabourattendance.project_id', $id);
        $recentAttendance = $this->Ardlabourattendance->find('all', array(
            'joins' => array(
                array('table' => 'ardaccounts_construction_labours', 'alias' => 'Ardlabour', 'type' => 'LEFT', 'conditions' => array('Ardlabour.id=Ardlabourattendance.labour_id'))
            ),
            'fields' => array('Ardlabourattendance.*', 'Ardlabour.full_name', 'Ardlabour.labour_type', 'Ardlabour.daily_rate'),
            'conditions' => array($attScope),
            'order' => array('Ardlabourattendance.attendance_date' => 'desc', 'Ardlabourattendance.id' => 'desc'),
            'limit' => 30,
            'recursive' => -1
        ));
        $this->set('recentAttendance', $recentAttendance);

        $payScope = $this->_scopeCondition('Ardlabourpayment.project_id', $id);
        $recentPayments = $this->Ardlabourpayment->find('all', array(
            'joins' => array(
                array('table' => 'ardaccounts_construction_labours', 'alias' => 'Ardlabour', 'type' => 'LEFT', 'conditions' => array('Ardlabour.id=Ardlabourpayment.labour_id')),
                array('table' => 'ardaccounts_ledgers', 'alias' => 'Ardledger', 'type' => 'LEFT', 'conditions' => array('Ardledger.id=Ardlabourpayment.debit_ledger_id'))
            ),
            'fields' => array('Ardlabourpayment.*', 'Ardlabour.full_name', 'Ardledger.name'),
            'conditions' => array($payScope),
            'order' => array('Ardlabourpayment.payment_date' => 'desc', 'Ardlabourpayment.id' => 'desc'),
            'limit' => 30,
            'recursive' => -1
        ));
        $this->set('recentPayments', $recentPayments);

        $today = date('Y-m-d');
        $todayAttCount = $this->Ardlabourattendance->find('count', array(
            'conditions' => array($attScope, 'Ardlabourattendance.attendance_date' => $today, 'Ardlabourattendance.attendance_status' => 'present')
        ));
        $totalPaidSum = $this->Ardlabourpayment->find('first', array(
            'fields' => array('SUM(Ardlabourpayment.amount) AS total_paid'),
            'conditions' => array($payScope),
            'recursive' => -1
        ));
        $this->set('labourStats', array(
            'total_labours' => count($labours),
            'present_today' => $todayAttCount,
            'total_paid' => isset($totalPaidSum[0]['total_paid']) ? (float)$totalPaidSum[0]['total_paid'] : 0.0
        ));
    }

    public function deletelabour($id = null, $projectId = null)
    {
        $this->loadModel('Admin.Ardlabour');
        $this->loadModel('Admin.Ardlabourattendance');
        $this->loadModel('Admin.Ardlabourpayment');
        $row = $this->Ardlabour->findById($id);
        if(empty($row) || !$this->_isAllowedProject((int)$row['Ardlabour']['project_id']))
        {
            $this->Session->setFlash(__('Invalid labourer.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'labourcontrol', $projectId));
        }
        $attCount = $this->Ardlabourattendance->find('count', array('conditions' => array('Ardlabourattendance.labour_id' => (int)$id)));
        $payCount = $this->Ardlabourpayment->find('count', array('conditions' => array('Ardlabourpayment.labour_id' => (int)$id)));
        if($attCount > 0 || $payCount > 0)
        {
            $this->Session->setFlash(__('Cannot delete worker with attendance or payment records.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'labourcontrol', $projectId));
        }
        $this->Ardlabour->delete($id);
        $this->Session->setFlash(__('Worker deleted successfully.'), 'flash', array('alert' => 'success'));
        return $this->redirect(array('action' => 'labourcontrol', $projectId));
    }

    public function deletelabourattendance($id = null, $projectId = null)
    {
        $this->loadModel('Admin.Ardlabourattendance');
        $row = $this->Ardlabourattendance->findById($id);
        if(empty($row) || !$this->_isAllowedProject((int)$row['Ardlabourattendance']['project_id']))
        {
            $this->Session->setFlash(__('Invalid attendance entry.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'labourcontrol', $projectId));
        }
        $this->Ardlabourattendance->delete($id);
        $this->Session->setFlash(__('Attendance entry deleted.'), 'flash', array('alert' => 'success'));
        return $this->redirect(array('action' => 'labourcontrol', $projectId));
    }

    public function cashclosing($id = null)
    {
        $this->_ensureBusinessAccountingSchema();
        $this->loadModel('Admin.Ardcashclosing');
        $this->loadModel('Admin.Ardledger');
        $this->loadModel('User');
        $id = $this->_activeProjectId($id);
        $projectList = $this->_projectList();
        $this->set('projectName', $projectList);
        $this->set('agencyId', $this->agencyId);
        $this->set('currentProjectId', $id);

        $closingDate = isset($this->request->query['date']) ? trim((string)$this->request->query['date']) : date('Y-m-d');
        if($this->request->is(array('post','put')) && !empty($this->request->data['Ardcashclosing']['closing_date']))
        {
            $closingDate = trim((string)$this->request->data['Ardcashclosing']['closing_date']);
        }
        $closingDate = $this->_reportNormalizeDate($closingDate, false);
        if($closingDate === '')
        {
            $closingDate = date('Y-m-d');
        }

        $cashLedgerOptions = array(0 => __('Please Select'));
        $selectedProjectId = (int)$id > 0 ? (int)$id : (int)$this->agencyId;
        if($selectedProjectId > 0)
        {
            $cashLedgerOptions += (array)$this->Ardledger->find('list', array(
                'fields' => array('Ardledger.id', 'Ardledger.name'),
                'conditions' => array(
                    'Ardledger.project_id' => $selectedProjectId,
                    'Ardledger.is_trashed' => 0,
                    'Ardledger.type !=' => 'expense'
                ),
                'order' => array('Ardledger.name' => 'asc'),
                'recursive' => -1
            ));
        }
        $defaultCashLedgerId = $this->_ardDefaultLedgerId($selectedProjectId, 'cash_closing_cash_ledger_id', 'Cash In Hand', 'asset');
        $cashLedgerId = isset($this->request->query['ledger_id']) ? (int)$this->request->query['ledger_id'] : $defaultCashLedgerId;
        if($this->request->is(array('post','put')))
        {
            $cashLedgerId = isset($this->request->data['Ardcashclosing']['cash_ledger_id']) ? (int)$this->request->data['Ardcashclosing']['cash_ledger_id'] : $cashLedgerId;
        }
        if($cashLedgerId <= 0)
        {
            $cashLedgerId = $defaultCashLedgerId;
        }

        $metrics = $this->_cashClosingMetrics($selectedProjectId, $cashLedgerId, $closingDate);
        $existing = $this->Ardcashclosing->find('first', array(
            'conditions' => array(
                'Ardcashclosing.project_id' => $selectedProjectId,
                'Ardcashclosing.closing_date' => $closingDate,
                'Ardcashclosing.cash_ledger_id' => $cashLedgerId
            ),
            'recursive' => -1
        ));

        if($this->request->is(array('post','put')))
        {
            if(!$this->_isAllowedProject($selectedProjectId))
            {
                $this->Session->setFlash(__('Please select valid agency/project.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            if(!empty($existing['Ardcashclosing']) && in_array($existing['Ardcashclosing']['status'], array('Approved','Posted'), true) && !$this->_isGlobalAdmin())
            {
                $this->Session->setFlash(__('This cash closing is locked. Only admin can change approved/posted closing sheets.'), 'flash', array('alert' => 'danger'));
                return $this->redirect(array('action' => 'cashclosing', $selectedProjectId, '?' => array('date' => $closingDate, 'ledger_id' => $cashLedgerId)));
            }
            $posted = isset($this->request->data['Ardcashclosing']) ? (array)$this->request->data['Ardcashclosing'] : array();
            $bankDeposit = round((float)str_replace(',', '', isset($posted['bank_deposit']) ? $posted['bank_deposit'] : 0), 2);
            $adjustment = round((float)str_replace(',', '', isset($posted['adjustment_amount']) ? $posted['adjustment_amount'] : 0), 2);
            $countedCash = round((float)str_replace(',', '', isset($posted['counted_cash']) ? $posted['counted_cash'] : 0), 2);
            $closingCash = round($metrics['opening_cash'] + $metrics['received_cash'] - $metrics['expense_cash'] - $bankDeposit + $adjustment, 2);
            $status = $this->_ardNormalizeVoucherStatus(isset($posted['status']) ? $posted['status'] : 'Draft', 'Draft');
            if(!in_array($status, array('Draft','Approved','Posted'), true))
            {
                $status = 'Draft';
            }
            $saveRow = array(
                'project_id' => $selectedProjectId,
                'closing_date' => $closingDate,
                'cash_ledger_id' => $cashLedgerId,
                'opening_cash' => $metrics['opening_cash'],
                'received_cash' => $metrics['received_cash'],
                'expense_cash' => $metrics['expense_cash'],
                'bank_deposit' => $bankDeposit,
                'adjustment_amount' => $adjustment,
                'closing_cash' => $closingCash,
                'counted_cash' => $countedCash,
                'difference_amount' => round($countedCash - $closingCash, 2),
                'cashier_user_id' => (int)$this->luserId,
                'status' => $status,
                'note' => trim((string)(isset($posted['note']) ? $posted['note'] : '')),
                'modified_by' => (int)$this->luserId
            );
            if(!empty($existing['Ardcashclosing']['id']))
            {
                $saveRow['id'] = (int)$existing['Ardcashclosing']['id'];
            }
            else
            {
                $saveRow['created_by'] = (int)$this->luserId;
            }
            $this->Ardcashclosing->create();
            if($this->Ardcashclosing->save(array('Ardcashclosing' => $saveRow), false))
            {
                $this->Session->setFlash(__('Cash closing saved successfully.'), 'flash', array('alert' => 'success'));
            }
            else
            {
                $this->Session->setFlash(__('Unable to save cash closing.'), 'flash', array('alert' => 'danger'));
            }
            return $this->redirect(array('action' => 'cashclosing', $selectedProjectId, '?' => array('date' => $closingDate, 'ledger_id' => $cashLedgerId)));
        }

        $rowData = !empty($existing['Ardcashclosing']) ? $existing['Ardcashclosing'] : array(
            'project_id' => $selectedProjectId,
            'closing_date' => $closingDate,
            'cash_ledger_id' => $cashLedgerId,
            'opening_cash' => $metrics['opening_cash'],
            'received_cash' => $metrics['received_cash'],
            'expense_cash' => $metrics['expense_cash'],
            'bank_deposit' => 0,
            'adjustment_amount' => 0,
            'closing_cash' => round($metrics['opening_cash'] + $metrics['received_cash'] - $metrics['expense_cash'], 2),
            'counted_cash' => round($metrics['opening_cash'] + $metrics['received_cash'] - $metrics['expense_cash'], 2),
            'difference_amount' => 0,
            'status' => 'Draft',
            'note' => ''
        );
        $this->request->data['Ardcashclosing'] = $rowData;
        $recentClosings = $this->Ardcashclosing->find('all', array(
            'conditions' => array($this->_scopeCondition('Ardcashclosing.project_id', $id)),
            'order' => array('Ardcashclosing.closing_date' => 'desc', 'Ardcashclosing.id' => 'desc'),
            'limit' => 30,
            'recursive' => -1
        ));
        $this->set(compact('cashLedgerOptions', 'closingDate', 'cashLedgerId', 'metrics', 'recentClosings'));
    }

    public function printcashclosing($closingId = null)
    {
        $this->_ensureBusinessAccountingSchema();
        $this->loadModel('Admin.Ardcashclosing');
        $this->loadModel('Admin.Ardledger');
        $row = $this->Ardcashclosing->find('first', array('conditions' => array('Ardcashclosing.id' => (int)$closingId), 'recursive' => -1));
        if(empty($row['Ardcashclosing']) || !$this->_isAllowedProject((int)$row['Ardcashclosing']['project_id']))
        {
            throw new NotFoundException(__('Cash closing not found.'));
        }
        $ledgerName = $this->Ardledger->field('name', array('Ardledger.id' => (int)$row['Ardcashclosing']['cash_ledger_id']));
        $projectList = $this->_projectList();
        $agencyName = !empty($projectList[(int)$row['Ardcashclosing']['project_id']]) ? $projectList[(int)$row['Ardcashclosing']['project_id']] : ('Agency #'.(int)$row['Ardcashclosing']['project_id']);
        $this->layout = false;
        $this->set('closing', $row['Ardcashclosing']);
        $this->set('ledgerName', $ledgerName);
        $this->set('agencyName', $agencyName);
    }

    protected function _cashClosingMetrics($projectId, $cashLedgerId, $date)
    {
        $projectId = (int)$projectId;
        $cashLedgerId = (int)$cashLedgerId;
        $date = trim((string)$date);
        $metrics = array('opening_cash' => 0.0, 'received_cash' => 0.0, 'expense_cash' => 0.0);
        if($projectId <= 0 || $cashLedgerId <= 0 || $date === '')
        {
            return $metrics;
        }
        $this->loadModel('Admin.Ardtransaction');
        $this->loadModel('Admin.Ardcashclosing');
        $previous = $this->Ardcashclosing->find('first', array(
            'fields' => array('Ardcashclosing.closing_cash'),
            'conditions' => array(
                'Ardcashclosing.project_id' => $projectId,
                'Ardcashclosing.cash_ledger_id' => $cashLedgerId,
                'Ardcashclosing.closing_date <' => $date
            ),
            'order' => array('Ardcashclosing.closing_date' => 'desc', 'Ardcashclosing.id' => 'desc'),
            'recursive' => -1
        ));
        if(!empty($previous['Ardcashclosing']))
        {
            $metrics['opening_cash'] = round((float)$previous['Ardcashclosing']['closing_cash'], 2);
        }
        else
        {
            $beforeRows = $this->Ardtransaction->find('all', array(
                'fields' => array('Ardtransaction.type', 'Ardtransaction.amount', 'Ardtransaction.ledger_id', 'Ardtransaction.expense_ledger_id'),
                'conditions' => array(
                    'Ardtransaction.project_id' => $projectId,
                    'OR' => array(
                        'Ardtransaction.ledger_id' => $cashLedgerId,
                        array('Ardtransaction.type' => 'transfer', 'Ardtransaction.expense_ledger_id' => $cashLedgerId)
                    ),
                    'Ardtransaction.entry_date <' => $date,
                    'NOT' => array('Ardtransaction.status' => array('Void','Reversed'))
                ),
                'recursive' => -1
            ));
            foreach($beforeRows as $beforeRow)
            {
                $amount = (float)$beforeRow['Ardtransaction']['amount'];
                $type = strtolower(trim((string)$beforeRow['Ardtransaction']['type']));
                $isIncomingTransfer = ($type === 'transfer' && (int)(isset($beforeRow['Ardtransaction']['expense_ledger_id']) ? $beforeRow['Ardtransaction']['expense_ledger_id'] : 0) === $cashLedgerId);
                $metrics['opening_cash'] += ($type === 'income' || $type === 'transfer_in' || $isIncomingTransfer) ? $amount : (-1 * $amount);
            }
            $metrics['opening_cash'] = round($metrics['opening_cash'], 2);
        }
        $todayRows = $this->Ardtransaction->find('all', array(
            'fields' => array('Ardtransaction.type', 'Ardtransaction.amount', 'Ardtransaction.ledger_id', 'Ardtransaction.expense_ledger_id'),
            'conditions' => array(
                'Ardtransaction.project_id' => $projectId,
                'OR' => array(
                    'Ardtransaction.ledger_id' => $cashLedgerId,
                    array('Ardtransaction.type' => 'transfer', 'Ardtransaction.expense_ledger_id' => $cashLedgerId)
                ),
                'Ardtransaction.entry_date' => $date,
                'NOT' => array('Ardtransaction.status' => array('Void','Reversed'))
            ),
            'recursive' => -1
        ));
        foreach($todayRows as $todayRow)
        {
            $amount = (float)$todayRow['Ardtransaction']['amount'];
            $type = strtolower(trim((string)$todayRow['Ardtransaction']['type']));
            $isIncomingTransfer = ($type === 'transfer' && (int)(isset($todayRow['Ardtransaction']['expense_ledger_id']) ? $todayRow['Ardtransaction']['expense_ledger_id'] : 0) === $cashLedgerId);
            if($type === 'income' || $type === 'transfer_in' || $isIncomingTransfer)
            {
                $metrics['received_cash'] += $amount;
            }
            else
            {
                $metrics['expense_cash'] += $amount;
            }
        }
        $metrics['received_cash'] = round($metrics['received_cash'], 2);
        $metrics['expense_cash'] = round($metrics['expense_cash'], 2);
        return $metrics;
    }

    public function settings($id = null)
    {
        $this->loadModel('Admin.Ardsetting');
        $this->loadModel('Admin.Ardtemplate');
        $this->loadModel('Admin.Ardpaymentbankaccount');
        $this->Ardpaymentbankaccount->ensureSchema();
        $id = $this->_activeProjectId($id);
        $projectList = $this->_activeAgencyProjectList();
        $this->set('projectName', $projectList);
        $this->set('agencyId', $this->agencyId);
        $this->set('currentProjectId', $id);
        $allowedTabs = array('general','vouchers','construction','backup','templates','commission','bulk');
        $activeTab = isset($this->request->query['tab']) ? strtolower(trim((string)$this->request->query['tab'])) : 'general';
        if(!in_array($activeTab, $allowedTabs))
        {
            $activeTab = 'general';
        }
        if($this->_isGlobalAdmin() && ((int)$id <= 0 || !isset($projectList[(int)$id])) && !$this->request->is(array('post','put')))
        {
            $defaultProjectId = 0;
            foreach((array)$projectList as $projectListId => $projectTitle)
            {
                if((int)$projectListId > 0)
                {
                    $defaultProjectId = (int)$projectListId;
                    break;
                }
            }
            if($defaultProjectId > 0)
            {
                return $this->redirect(array('action' => 'settings', $defaultProjectId, '?' => array('tab' => $activeTab)));
            }
        }

        if($this->request->is(array('post','put')) && isset($this->request->data['Ardtemplate']))
        {
            $row = isset($this->request->data['Ardtemplate']) ? $this->request->data['Ardtemplate'] : array();
            $row['project_id'] = $this->_resolveProjectId(isset($row['project_id']) ? $row['project_id'] : null);
            if(!$this->_isAllowedProject($row['project_id']) || !isset($projectList[(int)$row['project_id']]))
            {
                $this->Session->setFlash(__('Please select valid agency/project.'), 'flash', array('alert' => 'danger'));
                return $this->redirect(array('action' => 'settings', $id, '?' => array('tab' => 'templates')));
            }
            $row['template_name'] = trim((string)$row['template_name']);
            $row['template_type'] = trim((string)$row['template_type']);
            $row['template_content'] = isset($row['template_content']) ? (string)$row['template_content'] : '';
            if($row['template_name'] === '' || $row['template_type'] === '')
            {
                $this->Session->setFlash(__('Template name and type are required.'), 'flash', array('alert' => 'danger'));
                return $this->redirect(array('action' => 'settings', $id, '?' => array('tab' => 'templates')));
            }
            $row['is_active'] = !empty($row['is_active']) ? 1 : 0;
            $this->Ardtemplate->create();
            if($this->Ardtemplate->save(array('Ardtemplate' => $row)))
            {
                $savedTemplateId = (int)$this->Ardtemplate->id;
                if((int)$row['is_active'] === 1)
                {
                    $this->_syncSingleActiveTemplate((int)$row['project_id'], $row['template_type'], $savedTemplateId);
                }
                else
                {
                    $this->_syncSingleActiveTemplate((int)$row['project_id'], $row['template_type'], 0);
                }
                $this->Session->setFlash(__('Template saved successfully.'), 'flash', array('alert' => 'success'));
            }
            else
            {
                $this->Session->setFlash(__('Unable to save template.'), 'flash', array('alert' => 'danger'));
            }
            return $this->redirect(array('action' => 'settings', $id, '?' => array('tab' => 'templates')));
        }

        if($this->request->is(array('post','put')))
        {
            $postedRow = isset($this->request->data['Ardsetting']) ? $this->request->data['Ardsetting'] : array();
            $row = $postedRow;
            $targetProjectId = isset($row['project_id']) ? $row['project_id'] : $id;
            $row['project_id'] = $this->_resolveProjectId($targetProjectId);
            if($this->_isGlobalAdmin() && (int)$row['project_id'] <= 0)
            {
                $row['project_id'] = (int)$id;
                if((int)$row['project_id'] <= 0)
                {
                    foreach((array)$projectList as $projectListId => $projectTitle)
                    {
                        if((int)$projectListId > 0)
                        {
                            $row['project_id'] = (int)$projectListId;
                            break;
                        }
                    }
                }
            }
            if(!$this->_isAllowedProject($row['project_id']) || !isset($projectList[(int)$row['project_id']]))
            {
                $this->Session->setFlash(__('Please select valid agency/project.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }

            $defaults = $this->_defaultSettings();
            $existing = $this->_fetchArdSettingsRowRaw((int)$row['project_id']);
            $base = $defaults;
            if(!empty($existing))
            {
                $base = $this->_normalizeArdSettingsWithDefaults($existing, $defaults);
            }
            $row = array_merge($base, $row);

            if($activeTab === 'general')
            {
                if($this->_isGlobalAdmin())
                {
                    $row['expense_approval_enabled'] = !empty($postedRow['expense_approval_enabled']) ? 1 : 0;
                    $row['expense_approval_ceo_user_id'] = max(0, (int)(isset($postedRow['expense_approval_ceo_user_id']) ? $postedRow['expense_approval_ceo_user_id'] : 0));
                    if($row['expense_approval_ceo_user_id'] > 0)
                    {
                        $this->loadModel('User');
                        if(!$this->User->userHasProjectAccess($row['expense_approval_ceo_user_id'], (int)$row['project_id']))
                        {
                            $this->Session->setFlash(__('Selected CEO does not have access to this agency.'), 'flash', array('alert' => 'danger'));
                            return $this->redirect(array('action' => 'settings', (int)$row['project_id'], '?' => array('tab' => 'general')));
                        }
                    }
                    if(!empty($row['expense_approval_enabled']))
                    {
                        $roleReadiness = $this->_expenseApprovalRoleReadiness((int)$row['project_id']);
                        $hasCeo = $row['expense_approval_ceo_user_id'] > 0 || !empty($roleReadiness['ceos']);
                        if(empty($roleReadiness['accountants']) || empty($roleReadiness['managers']) || !$hasCeo)
                        {
                            $this->Session->setFlash(__('Assign at least one Accountant, one Manager, and one CEO/Agency Owner to this agency before enabling the workflow.'), 'flash', array('alert' => 'danger'));
                            return $this->redirect(array('action' => 'settings', (int)$row['project_id'], '?' => array('tab' => 'general')));
                        }
                    }
                }
                else
                {
                    $row['expense_approval_enabled'] = !empty($base['expense_approval_enabled']) ? 1 : 0;
                    $row['expense_approval_ceo_user_id'] = max(0, (int)(isset($base['expense_approval_ceo_user_id']) ? $base['expense_approval_ceo_user_id'] : 0));
                }
            }

            if($activeTab === 'commission')
            {
                $row['commission_milestone_release_enabled'] = !empty($postedRow['commission_milestone_release_enabled']) ? 1 : 0;
                $row['commission_min_collection_lock_enabled'] = !empty($postedRow['commission_min_collection_lock_enabled']) ? 1 : 0;
                $row['commission_min_collection_percent'] = max(0, min(100, (float)(isset($postedRow['commission_min_collection_percent']) ? $postedRow['commission_min_collection_percent'] : 15.00)));
                $row['commission_cancellation_clawback_enabled'] = !empty($postedRow['commission_cancellation_clawback_enabled']) ? 1 : 0;
                $row['commission_wht_deduction_enabled'] = !empty($postedRow['commission_wht_deduction_enabled']) ? 1 : 0;
                $row['commission_wht_filer_percent'] = max(0, min(100, (float)(isset($postedRow['commission_wht_filer_percent']) ? $postedRow['commission_wht_filer_percent'] : 12.00)));
                $row['commission_wht_non_filer_percent'] = max(0, min(100, (float)(isset($postedRow['commission_wht_non_filer_percent']) ? $postedRow['commission_wht_non_filer_percent'] : 24.00)));
                $row['commission_split_deals_enabled'] = !empty($postedRow['commission_split_deals_enabled']) ? 1 : 0;
                $row['commission_tranche1_percent'] = max(0, min(100, (float)(isset($postedRow['commission_tranche1_percent']) ? $postedRow['commission_tranche1_percent'] : 40.00)));
                $row['commission_tranche2_percent'] = max(0, min(100, (float)(isset($postedRow['commission_tranche2_percent']) ? $postedRow['commission_tranche2_percent'] : 30.00)));
                $row['commission_tranche3_percent'] = max(0, min(100, (float)(isset($postedRow['commission_tranche3_percent']) ? $postedRow['commission_tranche3_percent'] : 30.00)));
                $row['default_agent_commission_rate'] = max(0, (float)(isset($postedRow['default_agent_commission_rate']) ? $postedRow['default_agent_commission_rate'] : 2.00));
                $rawCommType = strtolower(trim((string)(isset($postedRow['default_agent_commission_type']) ? $postedRow['default_agent_commission_type'] : 'percentage')));
                $row['default_agent_commission_type'] = in_array($rawCommType, array('percentage', 'value'), true) ? $rawCommType : 'percentage';
                $row['agent_commission_expense_ledger_id'] = max(0, (int)(isset($postedRow['agent_commission_expense_ledger_id']) ? $postedRow['agent_commission_expense_ledger_id'] : 0));
                $row['agent_commission_payable_ledger_id'] = max(0, (int)(isset($postedRow['agent_commission_payable_ledger_id']) ? $postedRow['agent_commission_payable_ledger_id'] : 0));
                $row['commission_wht_payable_ledger_id'] = max(0, (int)(isset($postedRow['commission_wht_payable_ledger_id']) ? $postedRow['commission_wht_payable_ledger_id'] : 0));
            }

            if($activeTab === 'bulk')
            {
                if(isset($postedRow['bulk_expense_ledger_ids']))
                {
                    $expIds = is_array($postedRow['bulk_expense_ledger_ids']) ? $postedRow['bulk_expense_ledger_ids'] : explode(',', (string)$postedRow['bulk_expense_ledger_ids']);
                    $cleanExpIds = array();
                    foreach($expIds as $eid)
                    {
                        $eid = (int)$eid;
                        if($eid > 0)
                        {
                            $cleanExpIds[] = $eid;
                        }
                    }
                    $row['bulk_expense_ledger_ids'] = implode(',', array_unique($cleanExpIds));
                }
                if(isset($postedRow['bulk_income_ledger_ids']))
                {
                    $incIds = is_array($postedRow['bulk_income_ledger_ids']) ? $postedRow['bulk_income_ledger_ids'] : explode(',', (string)$postedRow['bulk_income_ledger_ids']);
                    $cleanIncIds = array();
                    foreach($incIds as $iid)
                    {
                        $iid = (int)$iid;
                        if($iid > 0)
                        {
                            $cleanIncIds[] = $iid;
                        }
                    }
                    $row['bulk_income_ledger_ids'] = implode(',', array_unique($cleanIncIds));
                }
                $row['bulk_default_source_ledger_id'] = max(0, (int)(isset($postedRow['bulk_default_source_ledger_id']) ? $postedRow['bulk_default_source_ledger_id'] : 0));
                $row['bulk_voucher_custom_date_enabled'] = !empty($postedRow['bulk_voucher_custom_date_enabled']) ? 1 : 0;
            }

            $row['company_name'] = trim((string)$row['company_name']);
            if($row['company_name'] === '')
            {
                $row['company_name'] = $defaults['company_name'];
            }
            $row['currency_symbol'] = trim((string)$row['currency_symbol']);
            if($row['currency_symbol'] === '')
            {
                $row['currency_symbol'] = $defaults['currency_symbol'];
            }
            $row['rows_per_page'] = max(20, min(500, (int)$row['rows_per_page']));
            $row['currency_position'] = (isset($row['currency_position']) && $row['currency_position'] === 'right') ? 'right' : 'left';
            $row['currency_decimals'] = max(0, min(4, (int)$row['currency_decimals']));
            $fiscalLockDate = trim((string)(isset($row['fiscal_lock_date']) ? $row['fiscal_lock_date'] : ''));
            if($fiscalLockDate === '' || $fiscalLockDate === '0000-00-00')
            {
                $row['fiscal_lock_date'] = null;
            }
            else
            {
                $normalizedLockDate = $this->_reportNormalizeDate($fiscalLockDate, false);
                $row['fiscal_lock_date'] = ($normalizedLockDate !== '') ? $normalizedLockDate : null;
            }
            $row['deal_receipt_online_ledger_id'] = max(0, (int)(isset($row['deal_receipt_online_ledger_id']) ? $row['deal_receipt_online_ledger_id'] : 0));
            $row['deal_receipt_cash_ledger_id'] = max(0, (int)(isset($row['deal_receipt_cash_ledger_id']) ? $row['deal_receipt_cash_ledger_id'] : 0));
            $row['purchase_payment_expense_ledger_id'] = max(0, (int)(isset($row['purchase_payment_expense_ledger_id']) ? $row['purchase_payment_expense_ledger_id'] : 0));
