        {
            $editRow = $this->Ardtemplate->findById($templateEditId);
            if(!empty($editRow) && $this->_isAllowedProject((int)$editRow['Ardtemplate']['project_id']))
            {
                $this->request->data['Ardtemplate'] = $editRow['Ardtemplate'];
                $activeTab = 'templates';
            }
        }
        if(empty($this->request->data['Ardtemplate']))
        {
            $this->request->data['Ardtemplate'] = array(
                'project_id' => ($this->_isGlobalAdmin()) ? (int)$id : (int)$this->agencyId,
                'template_type' => 'voucher',
                'template_name' => '',
                'template_content' => '',
                'is_active' => 0
            );
        }
        $this->set('templatePlaceholderCatalog', $this->_templatePlaceholderCatalog());
        $this->set('activeSettingsTab', $activeTab);
    }

    protected function _savePaymentBankAccounts($projectId, $postedRows)
    {
        $projectId = (int)$projectId;
        if($projectId <= 0 || !$this->_isAllowedProject($projectId))
        {
            return false;
        }
        $this->loadModel('Admin.Ardpaymentbankaccount');
        $this->Ardpaymentbankaccount->ensureSchema();
        $postedRows = is_array($postedRows) ? $postedRows : array();
        $primaryId = 0;
        $firstSavedId = 0;
        $order = 1;
        try
        {
            foreach($postedRows as $postedRow)
            {
                $postedRow = is_array($postedRow) ? $postedRow : array();
                $rowId = !empty($postedRow['id']) ? (int)$postedRow['id'] : 0;
                if($rowId > 0)
                {
                    $existingProjectId = (int)$this->Ardpaymentbankaccount->field('project_id', array('Ardpaymentbankaccount.id' => $rowId));
                    if($existingProjectId !== $projectId)
                    {
                        continue;
                    }
                }
                if(!empty($postedRow['delete']))
                {
                    if($rowId > 0)
                    {
                        $this->Ardpaymentbankaccount->delete($rowId, false);
                    }
                    continue;
                }
                $clean = $this->_normalizePaymentBankAccountRow($postedRow);
                if(empty($clean))
                {
                    continue;
                }
                $clean['project_id'] = $projectId;
                $clean['ordering'] = $order++;
                if($rowId > 0)
                {
                    $clean['id'] = $rowId;
                }
                $this->Ardpaymentbankaccount->create();
                if(!$this->Ardpaymentbankaccount->save(array('Ardpaymentbankaccount' => $clean), array('validate' => false)))
                {
                    return false;
                }
                $savedId = !empty($clean['id']) ? (int)$clean['id'] : (int)$this->Ardpaymentbankaccount->id;
                if($firstSavedId <= 0)
                {
                    $firstSavedId = $savedId;
                }
                if(!empty($clean['is_primary']) && $primaryId <= 0)
                {
                    $primaryId = $savedId;
                }
            }
            if($primaryId <= 0)
            {
                $activeRows = $this->Ardpaymentbankaccount->activeRowsForProject($projectId);
                if(!empty($activeRows[0]['Ardpaymentbankaccount']['id']))
                {
                    $primaryId = (int)$activeRows[0]['Ardpaymentbankaccount']['id'];
                }
                elseif($firstSavedId > 0)
                {
                    $primaryId = $firstSavedId;
                }
            }
            $ds = $this->Ardpaymentbankaccount->getDataSource();
            if($primaryId > 0)
            {
                $this->Ardpaymentbankaccount->query("UPDATE `ardaccounts_payment_bank_accounts` SET `is_primary`=0 WHERE `project_id`=".(int)$projectId);
                $this->Ardpaymentbankaccount->query("UPDATE `ardaccounts_payment_bank_accounts` SET `is_primary`=1 WHERE `id`=".(int)$primaryId." AND `project_id`=".(int)$projectId." LIMIT 1");
            }
            else
            {
                $this->Ardpaymentbankaccount->query("UPDATE `ardaccounts_payment_bank_accounts` SET `is_primary`=0 WHERE `project_id`=".(int)$projectId);
            }
        }
        catch(Exception $e)
        {
            return false;
        }
        return true;
    }

    protected function _normalizePaymentBankAccountRow($row)
    {
        $row = is_array($row) ? $row : array();
        $fields = array('bank_name', 'account_title', 'account_no', 'iban', 'branch', 'swift_code', 'instructions');
        $clean = array();
        $hasValue = false;
        foreach($fields as $field)
        {
            $value = isset($row[$field]) ? trim((string)$row[$field]) : '';
            $clean[$field] = $value;
            if($value !== '')
            {
                $hasValue = true;
            }
        }
        if(!$hasValue)
        {
            return array();
        }
        $status = isset($row['status']) ? strtolower(trim((string)$row['status'])) : 'active';
        $clean['status'] = ($status === 'inactive') ? 'inactive' : 'active';
        $clean['is_primary'] = !empty($row['is_primary']) ? 1 : 0;
        return $clean;
    }

    protected function _repairArdSettingsPersist($projectId, $safeRow, $saveFieldList)
    {
        $projectId = (int)$projectId;
        if($projectId <= 0)
        {
            return false;
        }
        $safeRow = is_array($safeRow) ? $safeRow : array();
        $saveFieldList = is_array($saveFieldList) ? $saveFieldList : array();

        $ds = $this->Ardsetting->getDataSource();
        $insertFields = array('project_id');
        $insertValues = array((string)$projectId);
        $updateParts = array();
        foreach($saveFieldList as $field)
        {
            if($field === 'id' || $field === 'project_id')
            {
                continue;
            }
            if(!array_key_exists($field, $safeRow))
            {
                continue;
            }
            $safeField = preg_replace('/[^a-z0-9_]/i', '', (string)$field);
            if($safeField === '')
            {
                continue;
            }
            $insertFields[] = $safeField;
            if($safeRow[$field] === null)
            {
                $insertValues[] = 'NULL';
            }
            else
            {
                $insertValues[] = $ds->value($safeRow[$field]);
            }
            $updateParts[] = "`{$safeField}`=VALUES(`{$safeField}`)";
        }
        $insertFields[] = 'created';
        $insertValues[] = 'NOW()';
        $insertFields[] = 'modified';
        $insertValues[] = 'NOW()';
        $updateParts[] = "`modified`=NOW()";

        if(empty($updateParts))
        {
            return false;
        }
        $insertFieldSql = '`' . implode('`,`', $insertFields) . '`';
        $sql = "INSERT INTO `ardaccounts_settings` ({$insertFieldSql}) VALUES (" . implode(',', $insertValues) . ") ON DUPLICATE KEY UPDATE " . implode(',', $updateParts);
        try
        {
            $this->Ardsetting->query($sql);
            return true;
        }
        catch(Exception $e)
        {
            return false;
        }
    }

    protected function _fetchArdSettingsRowRaw($projectId)
    {
        $projectId = (int)$projectId;
        if($projectId <= 0)
        {
            return array();
        }
        if(!isset($this->Ardsetting) || !is_object($this->Ardsetting))
        {
            try
            {
                $this->loadModel('Admin.Ardsetting');
            }
            catch(Exception $e)
            {
                return array();
            }
        }
        if(!isset($this->Ardsetting) || !is_object($this->Ardsetting))
        {
            return array();
        }
        try
        {
            $rows = $this->Ardsetting->query(
                "SELECT * FROM `ardaccounts_settings` AS `Ardsetting` WHERE `project_id`=" . $projectId . " ORDER BY `id` DESC LIMIT 1"
            );
        }
        catch(Exception $e)
        {
            return array();
        }
        if(empty($rows) || empty($rows[0]) || !is_array($rows[0]))
        {
            return array();
        }
        if(!empty($rows[0][0]) && is_array($rows[0][0]))
        {
            return $rows[0][0];
        }
        if(!empty($rows[0]['Ardsetting']) && is_array($rows[0]['Ardsetting']))
        {
            return $rows[0]['Ardsetting'];
        }
        foreach($rows[0] as $rowBlock)
        {
            if(is_array($rowBlock) && !empty($rowBlock))
            {
                return $rowBlock;
            }
        }
        return array();
    }

