    protected function _normalizeArdSettingsWithDefaults($rowData, $defaults)
    {
        $rowData = is_array($rowData) ? $rowData : array();
        $defaults = is_array($defaults) ? $defaults : array();
        $merged = array_merge($defaults, $rowData);

        foreach($defaults as $field => $defaultValue)
        {
            if(!array_key_exists($field, $merged) || $merged[$field] === null)
            {
                $merged[$field] = $defaultValue;
            }
        }

        $lineTextFields = array(
            'construction_material_types',
            'construction_unit_types',
            'construction_labour_types',
            'hr_department_types',
            'hr_designation_types',
            'construction_department_types',
            'construction_designation_types',
            'balloting_block_types',
            'balloting_street_address_types',
            'ledger_asset_categories',
            'ledger_expense_categories',
            'deal_charge_types'
        );
        foreach($lineTextFields as $lineTextField)
        {
            $currentValue = trim((string)(isset($merged[$lineTextField]) ? $merged[$lineTextField] : ''));
            if($currentValue === '')
            {
                $merged[$lineTextField] = isset($defaults[$lineTextField]) ? $defaults[$lineTextField] : '';
            }
        }

        if(trim((string)(isset($merged['company_name']) ? $merged['company_name'] : '')) === '')
        {
            $merged['company_name'] = isset($defaults['company_name']) ? $defaults['company_name'] : 'ARD Accounts';
        }
        if(trim((string)(isset($merged['currency_symbol']) ? $merged['currency_symbol'] : '')) === '')
        {
            $merged['currency_symbol'] = isset($defaults['currency_symbol']) ? $defaults['currency_symbol'] : 'Rs';
        }
        $merged['rows_per_page'] = max(20, min(500, (int)(isset($merged['rows_per_page']) ? $merged['rows_per_page'] : 100)));
        $merged['currency_position'] = (isset($merged['currency_position']) && trim((string)$merged['currency_position']) === 'right') ? 'right' : 'left';
        $merged['currency_decimals'] = max(0, min(4, (int)(isset($merged['currency_decimals']) ? $merged['currency_decimals'] : 0)));
        $merged['currency_space'] = !empty($merged['currency_space']) ? 1 : 0;
        $merged['deal_receipt_online_ledger_id'] = max(0, (int)(isset($merged['deal_receipt_online_ledger_id']) ? $merged['deal_receipt_online_ledger_id'] : 0));
        $merged['deal_receipt_cash_ledger_id'] = max(0, (int)(isset($merged['deal_receipt_cash_ledger_id']) ? $merged['deal_receipt_cash_ledger_id'] : 0));
        $merged['purchase_payment_expense_ledger_id'] = max(0, (int)(isset($merged['purchase_payment_expense_ledger_id']) ? $merged['purchase_payment_expense_ledger_id'] : 0));
        $merged['payroll_payment_expense_ledger_id'] = max(0, (int)(isset($merged['payroll_payment_expense_ledger_id']) ? $merged['payroll_payment_expense_ledger_id'] : 0));
        foreach(array_keys($this->_ardBusinessMappingFields()) as $businessLedgerField)
        {
            $merged[$businessLedgerField] = max(0, (int)(isset($merged[$businessLedgerField]) ? $merged[$businessLedgerField] : 0));
        }
        $merged['paid_receipt_share_link_enabled'] = !empty($merged['paid_receipt_share_link_enabled']) ? 1 : 0;
        $merged['paid_notification_popup_enabled'] = !empty($merged['paid_notification_popup_enabled']) ? 1 : 0;
        $merged['expense_approval_enabled'] = !empty($merged['expense_approval_enabled']) ? 1 : 0;
        $merged['expense_approval_ceo_user_id'] = max(0, (int)(isset($merged['expense_approval_ceo_user_id']) ? $merged['expense_approval_ceo_user_id'] : 0));
        $merged['daily_backup_enabled'] = !empty($merged['daily_backup_enabled']) ? 1 : 0;
        $merged['low_stock_auto_draft_po'] = !empty($merged['low_stock_auto_draft_po']) ? 1 : 0;
        $merged['backup_keep_count'] = max(5, min(200, (int)(isset($merged['backup_keep_count']) ? $merged['backup_keep_count'] : 30)));
        $allowedBackupFrequencies = array('daily', 'weekly', 'monthly');
        $backupFrequency = strtolower(trim((string)(isset($merged['auto_backup_frequency']) ? $merged['auto_backup_frequency'] : 'daily')));
        if(!in_array($backupFrequency, $allowedBackupFrequencies, true))
        {
            $backupFrequency = 'daily';
        }
        $merged['auto_backup_frequency'] = $backupFrequency;
        $backupTime = trim((string)(isset($merged['auto_backup_time']) ? $merged['auto_backup_time'] : '02:00'));
        if(!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/', $backupTime))
        {
            $backupTime = '02:00';
        }
        $merged['auto_backup_time'] = $backupTime;
        if(empty($merged['auto_backup_last_run']) || $merged['auto_backup_last_run'] === '0000-00-00 00:00:00')
        {
            $merged['auto_backup_last_run'] = '';
        }
        $merged['backup_zip_password'] = trim((string)(isset($merged['backup_zip_password']) ? $merged['backup_zip_password'] : ''));

        $nextNoFields = array(
            'income_voucher_next_no',
            'expense_voucher_next_no',
            'payroll_slip_next_no',
            'bill_receipt_next_no',
            'po_next_no',
            'grn_next_no',
            'purchase_invoice_next_no',
            'purchase_payment_next_no',
            'journal_voucher_next_no',
            'deal_invoice_next_no',
            'deal_payment_receipt_next_no',
            'rental_receipt_next_no',
            'rental_agreement_next_no',
            'letters_next_no',
            'welcome_letter_next_no',
            'booking_letter_next_no',
            'charge_letter_next_no',
            'deal_agreement_letter_next_no',
            'demarcation_letter_next_no',
            'design_map_approval_next_no',
            'noc_letter_next_no',
            'allot_letter_next_no',
            'demand_letter_next_no',
            'receipt_letter_next_no',
            'possession_letter_next_no',
            'transfer_letter_next_no',
            'cancel_letter_next_no',
            'final_cancel_letter_next_no',
            'refund_letter_next_no',
            'employee_code_next_no'
        );
        foreach($nextNoFields as $nextNoField)
        {
            $merged[$nextNoField] = max(1, (int)(isset($merged[$nextNoField]) ? $merged[$nextNoField] : 1));
        }

        return $merged;
    }

    public function backups($id = null)
    {
        $this->loadModel('Admin.Ardbackup');
        $this->loadModel('Admin.Ardsetting');

        $id = $this->_activeProjectId($id);
        $projectList = (array)$this->_projectList();
        if($this->_isGlobalAdmin())
        {
            $projectList = array('0' => __('All Agencies (Full System / Consolidated)')) + $projectList;
        }
        if(!$this->_isGlobalAdmin())
        {
            $id = (int)$this->agencyId;
        }

        $defaults = $this->_defaultSettings();
        $settingsRow = ((int)$id > 0) ? $this->_fetchArdSettingsRowRaw((int)$id) : array();
        $settings = !empty($settingsRow) ? $this->_normalizeArdSettingsWithDefaults($settingsRow, $defaults) : array_merge($defaults, array('project_id' => (int)$id));

        if($this->request->is(array('post','put')))
        {
            $posted = isset($this->request->data['Ardbackup']) ? (array)$this->request->data['Ardbackup'] : array();
            $task = strtolower(trim((string)(isset($posted['task']) ? $posted['task'] : '')));
            $targetProjectId = isset($posted['project_id']) ? (int)$posted['project_id'] : (int)$id;
            if(!$this->_isGlobalAdmin())
            {
                $targetProjectId = (int)$this->agencyId;
            }

            if($task === 'save_auto_settings')
            {
                if(!$this->_isGlobalAdmin() && !$this->_isAllowedProject($targetProjectId))
                {
                    $this->Session->setFlash(__('Please select valid agency/project.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect(array('action' => 'backups', $id));
                }
                $autoSafe = array(
                    'project_id' => (int)$targetProjectId,
                    'daily_backup_enabled' => !empty($posted['daily_backup_enabled']) ? 1 : 0,
                    'backup_keep_count' => max(5, min(200, (int)(isset($posted['backup_keep_count']) ? $posted['backup_keep_count'] : 30))),
                    'auto_backup_frequency' => strtolower(trim((string)(isset($posted['auto_backup_frequency']) ? $posted['auto_backup_frequency'] : 'daily'))),
                    'auto_backup_time' => trim((string)(isset($posted['auto_backup_time']) ? $posted['auto_backup_time'] : '02:00'))
                );
                if(!in_array($autoSafe['auto_backup_frequency'], array('daily','weekly','monthly'), true))
                {
                    $autoSafe['auto_backup_frequency'] = 'daily';
                }
                if(!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/', $autoSafe['auto_backup_time']))
                {
                    $autoSafe['auto_backup_time'] = '02:00';
                }
                $saveFields = array('project_id','daily_backup_enabled','backup_keep_count','auto_backup_frequency','auto_backup_time');
                $saved = $this->_repairArdSettingsPersist((int)$targetProjectId, $autoSafe, $saveFields);
                if($saved)
                {
                    $this->Session->setFlash(__('Auto backup settings updated.'), 'flash', array('alert' => 'success'));
                }
                else
                {
                    $this->Session->setFlash(__('Unable to save auto backup settings.'), 'flash', array('alert' => 'danger'));
                }
                return $this->redirect(array('action' => 'backups', (int)$targetProjectId));
            }

            if($task === 'create_backup')
            {
                $backupScope = 'agency';
                if($this->_isGlobalAdmin())
                {
                    if((int)$targetProjectId === 0 || (isset($posted['backup_scope']) && strtolower(trim((string)$posted['backup_scope'])) === 'global'))
                    {
                        $backupScope = 'global';
                        $targetProjectId = 0;
                    }
                }
                if($backupScope === 'agency' && !$this->_isAllowedProject($targetProjectId))
                {
                    $this->Session->setFlash(__('Please select valid agency/project.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect(array('action' => 'backups', $id));
                }
                $includeFiles = ($this->_isGlobalAdmin() && $backupScope === 'global' && !empty($posted['include_files'])) ? 1 : 0;
                $note = isset($posted['notes']) ? trim((string)$posted['notes']) : '';
                $backupPassword = trim((string)(isset($posted['backup_password']) ? $posted['backup_password'] : ''));
                if($backupPassword === '')
                {
                    $passwordProjectId = ($backupScope === 'global') ? (int)$targetProjectId : (int)$targetProjectId;
                    $backupPassword = $this->_backupZipPasswordForProject($passwordProjectId, $settings);
                }
                $create = $this->_makeBackupArchive(($backupScope === 'global') ? 0 : (int)$targetProjectId, $backupScope, $includeFiles, 0, $note, $backupPassword);
                if(!empty($create['ok']))
                {
                    $this->Session->setFlash(__('Backup created successfully.'), 'flash', array('alert' => 'success'));
                }
                else
                {
                    $this->Session->setFlash(__('Backup failed: %s', isset($create['message']) ? $create['message'] : __('Unknown error')), 'flash', array('alert' => 'danger'));
                }
                return $this->redirect(array('action' => 'backups', $id));
            }

            if($task === 'run_auto_now')
            {
                $scope = ((int)$targetProjectId === 0 && $this->_isGlobalAdmin()) ? 'global' : 'agency';
                if($scope === 'agency' && !$this->_isAllowedProject($targetProjectId))
                {
                    $this->Session->setFlash(__('Please select valid agency/project.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect(array('action' => 'backups', $id));
                }
                $autoBackupPassword = $this->_backupZipPasswordForProject((int)$targetProjectId, $settings);
                $run = $this->_makeBackupArchive((int)$targetProjectId, $scope, 0, 1, 'Auto backup (manual run)', $autoBackupPassword);
                if(!empty($run['ok']))
                {
                    $this->_repairArdSettingsPersist((int)$targetProjectId, array(
                        'project_id' => (int)$targetProjectId,
                        'auto_backup_last_run' => date('Y-m-d H:i:s')
                    ), array('project_id','auto_backup_last_run'));
                    $this->Session->setFlash(__('Auto backup completed.'), 'flash', array('alert' => 'success'));
                }
                else
                {
                    $this->Session->setFlash(__('Auto backup failed: %s', isset($run['message']) ? $run['message'] : __('Unknown error')), 'flash', array('alert' => 'danger'));
                }
                return $this->redirect(array('action' => 'backups', (int)$targetProjectId));
            }

            if($task === 'restore_existing')
            {
                $backupId = isset($posted['backup_id']) ? (int)$posted['backup_id'] : 0;
                $restorePassword = trim((string)(isset($posted['restore_password']) ? $posted['restore_password'] : ''));
                $restore = $this->_restoreBackupRecord($backupId, (int)$targetProjectId, $restorePassword);
                if(!empty($restore['ok']))
                {
                    $this->Session->setFlash(__('Backup restored successfully.'), 'flash', array('alert' => 'success'));
                }
                else
                {
                    $this->Session->setFlash(__('Restore failed: %s', isset($restore['message']) ? $restore['message'] : __('Unknown error')), 'flash', array('alert' => 'danger'));
                }
                return $this->redirect(array('action' => 'backups', $id));
            }

            if($task === 'upload_restore')
            {
                $upload = isset($this->request->data['Ardbackup']['upload_file']) ? $this->request->data['Ardbackup']['upload_file'] : array();
                if(empty($upload['tmp_name']) && !empty($_FILES['data']['tmp_name']['Ardbackup']['upload_file']))
                {
                    $upload = array(
                        'name' => $_FILES['data']['name']['Ardbackup']['upload_file'],
                        'type' => $_FILES['data']['type']['Ardbackup']['upload_file'],
                        'tmp_name' => $_FILES['data']['tmp_name']['Ardbackup']['upload_file'],
                        'error' => $_FILES['data']['error']['Ardbackup']['upload_file'],
                        'size' => $_FILES['data']['size']['Ardbackup']['upload_file']
                    );
                }
                elseif(empty($upload['tmp_name']) && !empty($_FILES['upload_file']['tmp_name']))
                {
                    $upload = $_FILES['upload_file'];
                }
                $restorePassword = trim((string)(isset($posted['restore_password']) ? $posted['restore_password'] : ''));
                $uploadResult = $this->_restoreUploadedBackup($upload, (int)$targetProjectId, $restorePassword);
                if(!empty($uploadResult['ok']))
                {
                    $this->Session->setFlash(__('Uploaded backup restored successfully.'), 'flash', array('alert' => 'success'));
                }
                else
                {
                    $this->Session->setFlash(__('Upload restore failed: %s', isset($uploadResult['message']) ? $uploadResult['message'] : __('Unknown error')), 'flash', array('alert' => 'danger'));
                }
                return $this->redirect(array('action' => 'backups', $id));
            }

            if($task === 'delete_backup')
            {
                $backupId = isset($posted['backup_id']) ? (int)$posted['backup_id'] : 0;
                $deleted = $this->_deleteBackupRecord($backupId, (int)$targetProjectId);
                if(!empty($deleted['ok']))
                {
                    $this->Session->setFlash(__('Backup deleted.'), 'flash', array('alert' => 'success'));
                }
                else
                {
                    $this->Session->setFlash(__('Unable to delete backup: %s', isset($deleted['message']) ? $deleted['message'] : __('Unknown error')), 'flash', array('alert' => 'danger'));
                }
                return $this->redirect(array('action' => 'backups', $id));
            }
        }

        if((int)$id > 0)
        {
            $dueAuto = $this->_runDueAutoBackupIfNeeded((int)$id, $settings);
            if(!empty($dueAuto['ran']) && empty($dueAuto['ok']))
            {
                $this->Session->setFlash(__('Auto backup failed: %s', isset($dueAuto['message']) ? $dueAuto['message'] : __('Unknown error')), 'flash', array('alert' => 'danger'));
            }
        }

        $conditions = array();
        if(!$this->_isGlobalAdmin())
        {
            $conditions['Ardbackup.project_id'] = (int)$this->agencyId;
        }
        else
        {
            if((int)$id > 0)
            {
                $conditions['Ardbackup.project_id'] = array(0, (int)$id);
            }
        }

        $backupRows = $this->Ardbackup->find('all', array(
            'joins' => array(
                array(
                    'table' => 'projects',
                    'alias' => 'Agency',
                    'type' => 'LEFT',
                    'conditions' => array('Agency.id = Ardbackup.project_id')
                )
            ),
            'fields' => array('Ardbackup.*','Agency.name'),
            'conditions' => $conditions,
            'order' => array('Ardbackup.id' => 'desc'),
            'recursive' => -1
        ));
        foreach($backupRows as $backupIndex => $backupRow)
        {
            $size = (float)(isset($backupRow['Ardbackup']['file_size']) ? $backupRow['Ardbackup']['file_size'] : 0);
            $backupRows[$backupIndex]['Ardbackup']['file_size_human'] = $this->_formatBytes($size);
        }

        $dbStats = $this->_collectDatabaseStats();

        $this->set('currentProjectId', (int)$id);
        $this->set('projectName', $projectList);
        $this->set('agencyId', (int)$this->agencyId);
        $this->set('settings', $settings);
        $this->set('backupRows', $backupRows);
        $this->set('dbStats', $dbStats);
        $this->set('isGlobalAdmin', $this->_isGlobalAdmin());
    }

    public function directsqlexport($scope = 'full', $id = null)
    {
        $this->autoRender = false;
        @set_time_limit(0);
        ini_set('memory_limit', '1024M');

        $id = $this->_activeProjectId($id);
        if(!$this->_isGlobalAdmin())
        {
            $id = (int)$this->agencyId;
        }

        $scope = strtolower(trim((string)$scope));
        if(!in_array($scope, array('full','realestate','accounts','crm','schema_only'), true))
        {
            $scope = 'full';
        }

        $stamp = date('Y-m-d_His');
        $fileName = 'whitevillas_backup_' . $scope . '_' . $stamp . '.sql';

        $tmpSql = tempnam(sys_get_temp_dir(), 'wv_sqldump_');
        $dumpResult = $this->_exportCustomSqlDump($tmpSql, (int)$id, $scope);
        if(empty($dumpResult['ok']))
        {
            @unlink($tmpSql);
            $this->Session->setFlash(__('Export failed: %s', isset($dumpResult['message']) ? $dumpResult['message'] : __('Unknown error')), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'backups', $id));
        }

        $this->response->type('application/sql');
        $this->response->download($fileName);
        $this->response->file($tmpSql, array('download' => true, 'name' => $fileName));
        return $this->response;
    }

    public function downloadbackup($backupId = null, $id = null)
    {
        $this->autoRender = false;
        $this->loadModel('Admin.Ardbackup');
        $id = $this->_activeProjectId($id);
        if(!$this->_isGlobalAdmin())
        {
            $id = (int)$this->agencyId;
        }
        $row = $this->_findBackupRow((int)$backupId);
        if(empty($row['Ardbackup']))
        {
            $this->Session->setFlash(__('Backup not found.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'backups', $id));
        }
        if(!$this->_canAccessBackupRow($row, (int)$id))
        {
            $this->Session->setFlash(__('Permission denied for this backup.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'backups', $id));
        }
        $filePath = $this->_absoluteBackupPath((string)$row['Ardbackup']['file_path']);
        if(!is_file($filePath))
        {
            $this->Session->setFlash(__('Backup file not found on disk.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'backups', $id));
        }
        return $this->response->file($filePath, array(
            'download' => true,
            'name' => (string)$row['Ardbackup']['file_name']
        ));
    }

    protected function _collectDatabaseStats()
    {
        $stats = array(
            'total_tables' => 0,
            'total_rows' => 0,
            'db_size_mb' => 0,
            'disk_free_human' => 'Available',
            'backup_dir_size_human' => '0 B',
            'backup_count' => 0,
            'server_version' => 'MySQL',
            'top_tables' => array()
        );

        try
        {
            $this->loadModel('Admin.Ardledger');
            $ds = $this->Ardledger->getDataSource();
            $dbName = $ds->getSchemaName();
            if(!empty($dbName))
            {
                $rows = $this->Ardledger->query("SELECT 
                    COUNT(TABLE_NAME) as total_tables,
                    SUM(TABLE_ROWS) as total_rows,
                    ROUND(SUM(DATA_LENGTH + INDEX_LENGTH) / 1024 / 1024, 2) as db_size_mb
                FROM information_schema.TABLES 
                WHERE TABLE_SCHEMA = '" . addslashes($dbName) . "'");

                if(!empty($rows[0][0]))
                {
                    $stats['total_tables'] = (int)$rows[0][0]['total_tables'];
                    $stats['total_rows'] = (int)$rows[0][0]['total_rows'];
                    $stats['db_size_mb'] = (float)$rows[0][0]['db_size_mb'];
                }

                $topTableRows = $this->Ardledger->query("SELECT 
                    TABLE_NAME as name,
                    TABLE_ROWS as row_count,
                    ROUND((DATA_LENGTH + INDEX_LENGTH) / 1024, 1) as size_kb
                FROM information_schema.TABLES 
                WHERE TABLE_SCHEMA = '" . addslashes($dbName) . "'
                ORDER BY (DATA_LENGTH + INDEX_LENGTH) DESC 
                LIMIT 8");

                if(!empty($topTableRows))
                {
                    foreach($topTableRows as $tRow)
                    {
                        if(!empty($tRow['TABLES']))
                        {
                            $stats['top_tables'][] = $tRow['TABLES'];
                        }
                        elseif(!empty($tRow[0]))
                        {
                            $stats['top_tables'][] = $tRow[0];
                        }
                    }
                }
            }

            $versionRows = $this->Ardledger->query("SELECT VERSION() as v");
            if(!empty($versionRows[0][0]['v']))
            {
                $stats['server_version'] = $versionRows[0][0]['v'];
            }
        }
        catch(Exception $e)
        {
            // fallback
        }

        if(function_exists('disk_free_space'))
        {
            $free = @disk_free_space(APP . 'tmp');
            if($free !== false)
            {
                $stats['disk_free_human'] = $this->_formatBytes($free);
            }
        }

        $baseDir = APP . 'tmp' . DS . 'ard_backups';
        if(is_dir($baseDir))
        {
            $dirSize = 0;
            $fileCount = 0;
            try
            {
                $files = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($baseDir, RecursiveDirectoryIterator::SKIP_DOTS));
                foreach ($files as $file) {
                    if($file->isFile())
                    {
                        $dirSize += $file->getSize();
                        $fileCount++;
                    }
                }
            }
            catch(Exception $e) {}
            $stats['backup_dir_size_human'] = $this->_formatBytes($dirSize);
            $stats['backup_count'] = $fileCount;
        }

        return $stats;
    }

    protected function _exportCustomSqlDump($sqlPath, $projectId, $scope = 'full')
    {
        $this->loadModel('Admin.Ardledger');
        $ds = $this->Ardledger->getDataSource();
        try
        {
            $tablesRaw = $this->Ardledger->query("SHOW TABLES");
        }
        catch(Exception $e)
        {
            return array('ok' => false, 'message' => __('Unable to read database tables.'));
        }
        $tableNames = array();
        foreach((array)$tablesRaw as $tableRow)
        {
            if(!is_array($tableRow)) continue;
            foreach($tableRow as $tableCell)
            {
                if(is_array($tableCell))
                {
                    foreach($tableCell as $tableName)
                    {
                        if($tableName !== '') $tableNames[] = (string)$tableName;
                    }
                }
                elseif($tableCell !== '')
                {
                    $tableNames[] = (string)$tableCell;
                }
            }
        }
        $tableNames = array_values(array_unique(array_filter($tableNames)));
        if(empty($tableNames))
        {
            return array('ok' => false, 'message' => __('No database tables found.'));
        }

        $scopeFilter = null;
        if($scope === 'realestate')
        {
            $scopeFilter = array('deals','deals_payments','plans','plans_payments','deal_charges','plan_schedule_rows','properties','properties_documents','properties_features','properties_photos','clients','balloting_allotments','balloting_runs','balloting_settings','balloting_units','real_estate_letters','deal_rentals','deal_rental_receipts','deal_rental_receipt_allocations','deal_rental_schedules','deal_rental_settings','deal_refunds','deal_refund_requests','deal_refund_schedules','deal_transfers','deal_transfer_settings');
        }
        elseif($scope === 'accounts')
        {
            $scopeFilter = array('ardaccounts_settings','ardaccounts_templates','ardaccounts_ledgers','ardaccounts_journal_entries','ardaccounts_transactions','ardaccounts_payment_bank_accounts','ardaccounts_construction_projects','ardaccounts_construction_project_milestones','ardaccounts_construction_sites','ardaccounts_construction_vendors','ardaccounts_construction_stock','ardaccounts_construction_purchase_orders','ardaccounts_construction_purchase_order_items','ardaccounts_construction_consumption','ardaccounts_expense_approval_requests','ardaccounts_expense_approval_history','ardaccounts_hr_employees','ardaccounts_hr_attendance','ardaccounts_hr_payroll','expenses','expenses_payments','expense_categories','purchases','purchases_payments','paymenttypes','taxes','currencies');
        }
        elseif($scope === 'crm')
        {
            $scopeFilter = array('leads','lead_histories','lead_sms_schedules','contacts','website_contacts','communication_rules','communication_templates','crm_automation_settings','crm_user_email_settings','crm_user_google_calendar_settings','crm_user_sms_settings','payment_reminders','payment_reminder_settings');
        }

        $fh = @fopen($sqlPath, 'w');
        if(!$fh)
        {
            return array('ok' => false, 'message' => __('Unable to create SQL dump file.'));
        }
        fwrite($fh, "-- White Villas Enterprise SQL Backup (" . strtoupper($scope) . ")\n");
        fwrite($fh, "-- Generated: " . date('Y-m-d H:i:s') . "\n");
        fwrite($fh, "-- Server: " . (string)env('SERVER_SOFTWARE') . "\n\n");
        fwrite($fh, "SET SQL_MODE = \"NO_AUTO_VALUE_ON_ZERO\";\n");
        fwrite($fh, "SET AUTOCOMMIT = 0;\n");
        fwrite($fh, "START TRANSACTION;\n");
        fwrite($fh, "SET FOREIGN_KEY_CHECKS=0;\n\n");

        $columnsCache = array();
        foreach($tableNames as $tableName)
        {
            if($scopeFilter !== null && !in_array($tableName, $scopeFilter, true))
            {
                continue;
            }

            $skipInserts = ($scope === 'schema_only');
            try
            {
                $createRows = $this->Ardledger->query("SHOW CREATE TABLE `" . $tableName . "`");
            }
            catch(Exception $e)
            {
                continue;
            }
            $createSql = '';
            if(!empty($createRows[0][0]['Create Table']))
            {
                $createSql = (string)$createRows[0][0]['Create Table'];
            }
            elseif(!empty($createRows[0]['Table']['Create Table']))
            {
                $createSql = (string)$createRows[0]['Table']['Create Table'];
            }
            if($createSql === '')
            {
                continue;
            }

            fwrite($fh, "\n-- Table: `" . $tableName . "`\n");
            fwrite($fh, "DROP TABLE IF EXISTS `" . $tableName . "`;\n");
            fwrite($fh, $createSql . ";\n");

            if(!$skipInserts)
            {
                $whereClause = '';
                if($projectId > 0 && $scope !== 'full' && $scope !== 'schema_only')
                {
                    $whereClause = (string)$this->_backupWhereClauseForTable($tableName, $projectId, 'agency', $columnsCache);
                }

                $sql = "SELECT * FROM `" . $tableName . "`";
                if($whereClause !== '')
                {
                    $sql .= " WHERE " . $whereClause;
                }
                $rows = $this->Ardledger->query($sql);
                if(!empty($rows))
                {
                    foreach($rows as $row)
                    {
                        $flatRow = $this->_flattenSqlRow($row);
                        if(empty($flatRow)) continue;
                        $columns = array_keys($flatRow);
                        $escapedCols = array();
                        $values = array();
                        foreach($columns as $col)
                        {
                            $escapedCols[] = '`' . str_replace('`', '``', (string)$col) . '`';
                            $val = isset($flatRow[$col]) ? $flatRow[$col] : null;
                            $values[] = ($val === null) ? 'NULL' : $ds->value($val);
                        }
                        fwrite($fh, "INSERT INTO `" . $tableName . "` (" . implode(',', $escapedCols) . ") VALUES (" . implode(',', $values) . ");\n");
                    }
                }
            }
        }

        fwrite($fh, "\nSET FOREIGN_KEY_CHECKS=1;\nCOMMIT;\n");
        fclose($fh);
        return array('ok' => true);
    }

    protected function _runDueAutoBackupIfNeeded($projectId, $settings)
    {
        $projectId = (int)$projectId;
        if($projectId <= 0)
        {
            return array('ran' => false, 'ok' => true, 'message' => '');
        }
        if(empty($settings['daily_backup_enabled']))
        {
            return array('ran' => false, 'ok' => true, 'message' => '');
        }
        $frequency = strtolower(trim((string)(isset($settings['auto_backup_frequency']) ? $settings['auto_backup_frequency'] : 'daily')));
        if(!in_array($frequency, array('daily','weekly','monthly'), true))
        {
            $frequency = 'daily';
        }
        $backupTime = trim((string)(isset($settings['auto_backup_time']) ? $settings['auto_backup_time'] : '02:00'));
        if(!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/', $backupTime))
        {
            $backupTime = '02:00';
        }

        $now = new DateTime('now');
        $due = false;
        $lastRunRaw = trim((string)(isset($settings['auto_backup_last_run']) ? $settings['auto_backup_last_run'] : ''));
        if($lastRunRaw === '' || $lastRunRaw === '0000-00-00 00:00:00')
        {
            $firstDueAt = DateTime::createFromFormat('Y-m-d H:i:s', $now->format('Y-m-d') . ' ' . $backupTime . ':00');
            if($firstDueAt instanceof DateTime && $now >= $firstDueAt)
            {
                $due = true;
            }
        }
        else
        {
            $lastRun = DateTime::createFromFormat('Y-m-d H:i:s', $lastRunRaw);
            if($lastRun instanceof DateTime)
            {
                if($frequency === 'weekly')
                {
                    $lastRun->modify('+1 week');
                }
                elseif($frequency === 'monthly')
                {
                    $lastRun->modify('+1 month');
                }
                else
                {
                    $lastRun->modify('+1 day');
                }
                $parts = explode(':', $backupTime);
                $lastRun->setTime((int)$parts[0], (int)$parts[1], 0);
                if($now >= $lastRun)
                {
                    $due = true;
                }
            }
        }

        if(!$due)
        {
            return array('ran' => false, 'ok' => true, 'message' => '');
        }

        $autoBackupPassword = $this->_backupZipPasswordForProject($projectId, $settings);
        $autoRun = $this->_makeBackupArchive($projectId, 'agency', 0, 1, 'Auto scheduled backup', $autoBackupPassword);
        if(empty($autoRun['ok']))
        {
            return array('ran' => true, 'ok' => false, 'message' => isset($autoRun['message']) ? $autoRun['message'] : __('Unknown error'));
        }

        $this->_repairArdSettingsPersist($projectId, array(
            'project_id' => $projectId,
            'auto_backup_last_run' => date('Y-m-d H:i:s')
        ), array('project_id','auto_backup_last_run'));

        return array('ran' => true, 'ok' => true, 'message' => '');
    }

    protected function _backupZipPasswordForProject($projectId, $settings = array())
    {
        $projectId = (int)$projectId;
        if($projectId <= 0)
        {
            return '';
        }
        $settings = is_array($settings) ? $settings : array();
        if(!empty($settings) && isset($settings['project_id']) && (int)$settings['project_id'] === $projectId)
        {
            return trim((string)(isset($settings['backup_zip_password']) ? $settings['backup_zip_password'] : ''));
        }
        $settingsRow = $this->_fetchArdSettingsRowRaw($projectId);
        if(empty($settingsRow))
        {
            return '';
        }
        $defaults = $this->_defaultSettings();
        $normalized = $this->_normalizeArdSettingsWithDefaults($settingsRow, $defaults);
        return trim((string)(isset($normalized['backup_zip_password']) ? $normalized['backup_zip_password'] : ''));
    }

    protected function _zipEncryptionMethod()
    {
        if(defined('ZipArchive::EM_AES_256'))
        {
            return ZipArchive::EM_AES_256;
        }
        if(defined('ZipArchive::EM_TRAD_PKWARE'))
        {
            return ZipArchive::EM_TRAD_PKWARE;
        }
        return null;
    }

    protected function _encryptZipEntry($zip, $entryName, $password, &$error)
    {
        $error = '';
        $entryName = trim((string)$entryName);
        $password = (string)$password;
        if($entryName === '' || $password === '')
        {
            return true;
        }
        if(!is_object($zip) || !method_exists($zip, 'setPassword') || !method_exists($zip, 'setEncryptionName'))
        {
            $error = __('Server zip encryption support is not available.');
            return false;
        }
        $method = $this->_zipEncryptionMethod();
        if($method === null)
        {
            $error = __('Server zip encryption method is not available.');
            return false;
        }
        if(!$zip->setPassword($password))
        {
            $error = __('Unable to set backup zip password.');
            return false;
        }
        if(!$zip->setEncryptionName($entryName, $method))
        {
            $error = __('Unable to encrypt backup zip entry.');
            return false;
        }
        return true;
    }

    protected function _makeBackupArchive($projectId, $backupScope, $includeFiles, $autoGenerated, $notes = '', $zipPassword = '')
    {
        $this->loadModel('Admin.Ardbackup');
        $projectId = (int)$projectId;
        $backupScope = strtolower(trim((string)$backupScope));
        $zipPassword = trim((string)$zipPassword);
        if($backupScope !== 'global')
        {
            $backupScope = 'agency';
        }
        if($backupScope === 'global')
        {
            $projectId = 0;
        }
        if($backupScope === 'agency' && $projectId <= 0)
        {
            return array('ok' => false, 'message' => __('Invalid agency/project for backup.'));
        }
        if(!class_exists('ZipArchive'))
        {
            return array('ok' => false, 'message' => __('ZipArchive extension is not enabled on server.'));
        }

        @set_time_limit(0);

        $baseDir = APP . 'tmp' . DS . 'ard_backups';
        $scopeDirName = ($backupScope === 'global') ? 'global' : ('project_' . $projectId);
        $scopeDir = $baseDir . DS . $scopeDirName;
        $folder = new Folder();
        if(!$folder->create($scopeDir, 0755))
        {
            return array('ok' => false, 'message' => __('Unable to create backup directory.'));
        }

        $stamp = date('Ymd_His');
        $safeTag = ($backupScope === 'global') ? 'FULL_SYSTEM' : ('AGENCY_' . $projectId);
        $zipFileName = 'backup_' . $safeTag . '_' . $stamp . '.zip';
        $zipFilePath = $scopeDir . DS . $zipFileName;
        $tmpDir = $baseDir . DS . '_build_' . uniqid();
        $folder->create($tmpDir, 0755);

        $sqlPath = $tmpDir . DS . 'database.sql';
        $dump = $this->_exportSqlDump($sqlPath, $projectId, $backupScope);
        if(empty($dump['ok']))
        {
            $this->_deleteDirRecursive($tmpDir);
            return array('ok' => false, 'message' => isset($dump['message']) ? $dump['message'] : __('Unable to export database.'));
        }

        $metadata = array(
            'backup_scope' => $backupScope,
            'project_id' => $projectId,
            'include_files' => (!empty($includeFiles) && $backupScope === 'global') ? 1 : 0,
            'is_password_protected' => ($zipPassword !== '') ? 1 : 0,
            'created_at' => date('Y-m-d H:i:s'),
            'created_by' => (int)$this->luserId
        );
        file_put_contents($tmpDir . DS . 'metadata.json', json_encode($metadata));

        $zip = new ZipArchive();
        if($zip->open($zipFilePath, ZipArchive::CREATE | ZipArchive::OVERWRITE) !== true)
        {
            $this->_deleteDirRecursive($tmpDir);
            return array('ok' => false, 'message' => __('Unable to create backup zip file.'));
        }
        $zip->addFile($sqlPath, 'database.sql');
        $zip->addFile($tmpDir . DS . 'metadata.json', 'metadata.json');
        if($zipPassword !== '')
        {
            $encryptionError = '';
            if(!$this->_encryptZipEntry($zip, 'database.sql', $zipPassword, $encryptionError) || !$this->_encryptZipEntry($zip, 'metadata.json', $zipPassword, $encryptionError))
            {
                $zip->close();
                $this->_deleteDirRecursive($tmpDir);
                @unlink($zipFilePath);
                return array('ok' => false, 'message' => ($encryptionError !== '' ? $encryptionError : __('Unable to encrypt backup zip.')));
            }
        }
        if(!empty($includeFiles) && $backupScope === 'global')
        {
            $filesResult = $this->_addProjectFilesToZip($zip, $zipPassword);
            if(empty($filesResult['ok']))
            {
                $zip->close();
                $this->_deleteDirRecursive($tmpDir);
                @unlink($zipFilePath);
                return array('ok' => false, 'message' => isset($filesResult['message']) ? $filesResult['message'] : __('Unable to add files snapshot to backup zip.'));
            }
        }
        $zip->close();

        $this->_deleteDirRecursive($tmpDir);

        clearstatcache();
        $fileSize = is_file($zipFilePath) ? (float)filesize($zipFilePath) : 0;
        if($fileSize <= 0)
        {
            return array('ok' => false, 'message' => __('Backup zip file was not generated.'));
        }

        $relativePath = str_replace('\\', '/', $scopeDirName . '/' . $zipFileName);
        $backupName = ($backupScope === 'global') ? ('Full System Backup ' . date('d-M-Y H:i')) : ('Agency Backup ' . date('d-M-Y H:i'));
        $this->Ardbackup->create();
        $saved = $this->Ardbackup->save(array('Ardbackup' => array(
            'project_id' => (int)$projectId,
            'backup_scope' => $backupScope,
            'backup_name' => $backupName,
            'file_name' => $zipFileName,
            'file_path' => $relativePath,
            'file_size' => $fileSize,
            'backup_format' => 'zip',
            'is_password_protected' => ($zipPassword !== '') ? 1 : 0,
            'auto_generated' => !empty($autoGenerated) ? 1 : 0,
            'created_by' => (int)$this->luserId,
            'status' => 'ready',
            'notes' => (string)$notes
        )));
        if(!$saved)
        {
            return array('ok' => false, 'message' => __('Backup was created but metadata save failed.'));
        }

        $keepCount = 30;
        if($backupScope === 'agency' && $projectId > 0)
        {
            $settingsRow = $this->_fetchArdSettingsRowRaw($projectId);
            $defaults = $this->_defaultSettings();
            $settings = !empty($settingsRow) ? $this->_normalizeArdSettingsWithDefaults($settingsRow, $defaults) : $defaults;
            $keepCount = max(5, min(200, (int)$settings['backup_keep_count']));
        }
        $this->_cleanupOldBackups($projectId, $backupScope, $keepCount);

        return array('ok' => true, 'backup_id' => (int)$this->Ardbackup->id);
    }

    protected function _exportSqlDump($sqlPath, $projectId, $backupScope)
    {
        $this->loadModel('Admin.Ardledger');
        $ds = $this->Ardledger->getDataSource();
        try
        {
            $tablesRaw = $this->Ardledger->query("SHOW TABLES");
        }
        catch(Exception $e)
        {
            return array('ok' => false, 'message' => __('Unable to read database tables.'));
        }
        $tableNames = array();
        foreach((array)$tablesRaw as $tableRow)
        {
            if(!is_array($tableRow))
            {
                continue;
            }
            foreach($tableRow as $tableCell)
            {
                if(is_array($tableCell))
                {
                    foreach($tableCell as $tableName)
                    {
                        if($tableName !== '')
                        {
                            $tableNames[] = (string)$tableName;
                        }
                    }
                }
                elseif($tableCell !== '')
                {
                    $tableNames[] = (string)$tableCell;
                }
            }
        }
        $tableNames = array_values(array_unique(array_filter($tableNames)));
        if(empty($tableNames))
        {
            return array('ok' => false, 'message' => __('No database tables found.'));
        }

        $fh = @fopen($sqlPath, 'w');
        if(!$fh)
        {
            return array('ok' => false, 'message' => __('Unable to create SQL dump file.'));
        }
        fwrite($fh, "-- ARDAccounts backup\n");
        fwrite($fh, "-- Generated: " . date('Y-m-d H:i:s') . "\n\n");
        fwrite($fh, "SET SQL_MODE = \"NO_AUTO_VALUE_ON_ZERO\";\n");
        fwrite($fh, "SET AUTOCOMMIT = 0;\n");
        fwrite($fh, "START TRANSACTION;\n");
        fwrite($fh, "SET FOREIGN_KEY_CHECKS=0;\n\n");

        $columnsCache = array();
        foreach($tableNames as $tableName)
        {
            $dumpTable = $this->_dumpSingleTableSql($fh, $tableName, (int)$projectId, (string)$backupScope, $columnsCache, $ds);
            if(empty($dumpTable['ok']))
            {
                fclose($fh);
                return array('ok' => false, 'message' => isset($dumpTable['message']) ? $dumpTable['message'] : __('Failed while dumping table %s', $tableName));
            }
        }

        fwrite($fh, "\nSET FOREIGN_KEY_CHECKS=1;\nCOMMIT;\n");
        fclose($fh);
        return array('ok' => true);
    }

    protected function _dumpSingleTableSql($fh, $tableName, $projectId, $backupScope, &$columnsCache, $ds)
    {
        $tableName = trim((string)$tableName);
        if($tableName === '')
        {
            return array('ok' => true);
        }
        try
        {
            $createRows = $this->Ardledger->query("SHOW CREATE TABLE `" . $tableName . "`");
        }
        catch(Exception $e)
        {
            return array('ok' => false, 'message' => __('Unable to read schema for table %s', $tableName));
        }
        $createSql = '';
        if(!empty($createRows[0][0]['Create Table']))
        {
            $createSql = (string)$createRows[0][0]['Create Table'];
        }
        elseif(!empty($createRows[0]['Table']['Create Table']))
        {
            $createSql = (string)$createRows[0]['Table']['Create Table'];
        }
        else
        {
            foreach((array)$createRows[0] as $createBlock)
            {
                if(is_array($createBlock))
                {
                    foreach($createBlock as $createValue)
                    {
                        if(is_string($createValue) && stripos($createValue, 'CREATE TABLE') !== false)
                        {
                            $createSql = $createValue;
                            break 2;
                        }
                    }
                }
            }
        }
        if($createSql === '')
        {
            return array('ok' => false, 'message' => __('Unable to parse schema for table %s', $tableName));
        }

        if($backupScope === 'global')
        {
            fwrite($fh, "\nDROP TABLE IF EXISTS `" . $tableName . "`;\n");
            fwrite($fh, $createSql . ";\n");
        }
        else
        {
            $createSqlScoped = preg_replace('/^CREATE TABLE /i', 'CREATE TABLE IF NOT EXISTS ', $createSql, 1);
            fwrite($fh, "\n" . $createSqlScoped . ";\n");
        }

        $whereClause = $this->_backupWhereClauseForTable($tableName, $projectId, $backupScope, $columnsCache);
        if($whereClause === null)
        {
            return array('ok' => true);
        }

        if($backupScope !== 'global')
        {
            fwrite($fh, "DELETE FROM `" . $tableName . "` WHERE " . $whereClause . ";\n");
        }

        $sql = "SELECT * FROM `" . $tableName . "`";
        if($whereClause !== '')
        {
            $sql .= " WHERE " . $whereClause;
        }
        try
        {
            $rows = $this->Ardledger->query($sql);
        }
        catch(Exception $e)
        {
            return array('ok' => false, 'message' => __('Unable to export rows from %s', $tableName));
        }
        if(empty($rows))
        {
            return array('ok' => true);
        }

        foreach($rows as $row)
        {
            $flatRow = $this->_flattenSqlRow($row);
            if(empty($flatRow))
            {
                continue;
            }
            $columns = array_keys($flatRow);
            $escapedColumns = array();
            $values = array();
            foreach($columns as $columnName)
            {
                $escapedColumns[] = '`' . str_replace('`', '``', (string)$columnName) . '`';
                $columnValue = isset($flatRow[$columnName]) ? $flatRow[$columnName] : null;
                if($columnValue === null)
                {
                    $values[] = 'NULL';
                }
                else
                {
                    $values[] = $ds->value($columnValue);
                }
            }
            $insertSql = "INSERT INTO `" . $tableName . "` (" . implode(',', $escapedColumns) . ") VALUES (" . implode(',', $values) . ");\n";
            fwrite($fh, $insertSql);
        }

        return array('ok' => true);
    }

    protected function _flattenSqlRow($row)
    {
        if(!is_array($row))
        {
            return array();
        }
        if(!empty($row[0]) && is_array($row[0]))
        {
            return $row[0];
        }
        foreach($row as $rowPart)
        {
            if(is_array($rowPart) && !empty($rowPart))
            {
                return $rowPart;
            }
        }
        return array();
    }

    protected function _backupWhereClauseForTable($tableName, $projectId, $backupScope, &$columnsCache)
    {
        if($backupScope === 'global')
        {
            return '';
        }
        $projectId = (int)$projectId;
        if($projectId <= 0)
        {
            return null;
        }
        $columns = $this->_tableColumnsForBackup($tableName, $columnsCache);
        if(in_array('project_id', $columns, true))
        {
            return "`project_id`=" . $projectId;
        }
        if(in_array('agency_id', $columns, true))
        {
            return "`agency_id`=" . $projectId;
        }
        if(strtolower((string)$tableName) === 'projects')
        {
            return "`id`=" . $projectId;
        }
        return null;
    }

    protected function _tableColumnsForBackup($tableName, &$columnsCache)
    {
        $cacheKey = strtolower((string)$tableName);
        if(isset($columnsCache[$cacheKey]) && is_array($columnsCache[$cacheKey]))
        {
            return $columnsCache[$cacheKey];
        }
        $columns = array();
        try
        {
            $columnRows = $this->Ardledger->query("SHOW COLUMNS FROM `" . $tableName . "`");
            foreach((array)$columnRows as $columnRow)
            {
                if(!empty($columnRow[0]['Field']))
                {
                    $columns[] = (string)$columnRow[0]['Field'];
                    continue;
                }
                if(!empty($columnRow['COLUMNS']['Field']))
                {
                    $columns[] = (string)$columnRow['COLUMNS']['Field'];
                    continue;
                }
                foreach((array)$columnRow as $columnBlock)
                {
                    if(is_array($columnBlock) && !empty($columnBlock['Field']))
                    {
                        $columns[] = (string)$columnBlock['Field'];
                        break;
                    }
                }
            }
        }
        catch(Exception $e)
        {
            $columns = array();
        }
        $columns = array_values(array_unique(array_filter($columns)));
        $columnsCache[$cacheKey] = $columns;
        return $columns;
    }

    protected function _addProjectFilesToZip($zip, $zipPassword = '')
    {
        $zipPassword = trim((string)$zipPassword);
        $rootPath = realpath(ROOT);
        if($rootPath === false)
        {
            return array('ok' => true);
        }
        $rootPath = rtrim((string)$rootPath, DIRECTORY_SEPARATOR);
        $skipPrefixes = array(
            '.git/',
            'app/tmp/cache/',
            'app/tmp/logs/',
            'app/tmp/sessions/',
            'app/tmp/tests/',
            'app/tmp/ard_backups/',
            'node_modules/'
        );

        $iterator = new RecursiveIteratorIterator(
            new RecursiveDirectoryIterator($rootPath, FilesystemIterator::SKIP_DOTS),
            RecursiveIteratorIterator::SELF_FIRST
        );
        foreach($iterator as $item)
        {
            $pathName = (string)$item->getPathname();
            $relative = ltrim(str_replace('\\', '/', substr($pathName, strlen($rootPath))), '/');
            if($relative === '')
            {
                continue;
            }
            $skip = false;
            foreach($skipPrefixes as $skipPrefix)
            {
                if(strpos($relative, $skipPrefix) === 0)
                {
                    $skip = true;
                    break;
                }
            }
            if($skip)
            {
                continue;
            }
            $zipName = 'app_snapshot/' . $relative;
            if($item->isDir())
            {
                $zip->addEmptyDir($zipName);
            }
            else
            {
                $zip->addFile($pathName, $zipName);
                if($zipPassword !== '')
                {
                    $encryptionError = '';
                    if(!$this->_encryptZipEntry($zip, $zipName, $zipPassword, $encryptionError))
                    {
                        return array('ok' => false, 'message' => ($encryptionError !== '' ? $encryptionError : __('Unable to encrypt file snapshot entry.')));
                    }
                }
            }
        }
        return array('ok' => true);
    }

    protected function _cleanupOldBackups($projectId, $backupScope, $keepCount)
    {
        $projectId = (int)$projectId;
        $backupScope = strtolower(trim((string)$backupScope));
        $keepCount = max(1, (int)$keepCount);
        $conditions = array('Ardbackup.backup_scope' => $backupScope);
        if($backupScope === 'global')
        {
            $conditions['Ardbackup.project_id'] = 0;
        }
        else
        {
            $conditions['Ardbackup.project_id'] = $projectId;
        }
        $rows = $this->Ardbackup->find('all', array(
            'fields' => array('Ardbackup.id','Ardbackup.file_path'),
            'conditions' => $conditions,
            'order' => array('Ardbackup.id' => 'desc'),
            'recursive' => -1
        ));
        if(count($rows) <= $keepCount)
        {
            return;
        }
        $index = 0;
        foreach($rows as $row)
        {
            $index++;
            if($index <= $keepCount)
            {
                continue;
            }
            $deleteId = (int)$row['Ardbackup']['id'];
            $deletePath = $this->_absoluteBackupPath((string)$row['Ardbackup']['file_path']);
            if(is_file($deletePath))
            {
                @unlink($deletePath);
            }
            $this->Ardbackup->delete($deleteId);
        }
    }

    protected function _restoreBackupRecord($backupId, $projectId, $restorePassword = '')
    {
        $row = $this->_findBackupRow((int)$backupId);
        if(empty($row['Ardbackup']))
        {
            return array('ok' => false, 'message' => __('Backup not found.'));
        }
        if(!$this->_canAccessBackupRow($row, (int)$projectId))
        {
            return array('ok' => false, 'message' => __('Permission denied for selected backup.'));
        }
        $filePath = $this->_absoluteBackupPath((string)$row['Ardbackup']['file_path']);
        if(!is_file($filePath))
        {
            return array('ok' => false, 'message' => __('Backup file not found on disk.'));
        }
        $restorePassword = trim((string)$restorePassword);
        $isProtected = !empty($row['Ardbackup']['is_password_protected']) ? 1 : 0;
        if($isProtected && $restorePassword === '')
        {
            return array('ok' => false, 'message' => __('This backup is password protected. Please enter backup password.'));
        }
        try {
            $this->_makeBackupArchive(0, 'global', 0, 1, 'Auto pre-restore safety snapshot (' . date('d-M-Y H:i') . ')', '');
        } catch(Exception $e) {}
        return $this->_restoreBackupFromFile($filePath, (int)$projectId, (string)$row['Ardbackup']['backup_scope'], $restorePassword);
    }

    protected function _restoreUploadedBackup($upload, $projectId, $restorePassword = '')
    {
        @set_time_limit(0);
        ini_set('memory_limit', '1024M');

        if(isset($upload['error']) && (int)$upload['error'] !== UPLOAD_ERR_OK)
        {
            switch((int)$upload['error'])
            {
                case UPLOAD_ERR_INI_SIZE:
                case UPLOAD_ERR_FORM_SIZE:
                    return array('ok' => false, 'message' => __('Uploaded file exceeds maximum allowed file size on server (upload_max_filesize / post_max_size).'));
                case UPLOAD_ERR_PARTIAL:
                    return array('ok' => false, 'message' => __('The backup file was only partially uploaded. Please try again.'));
                case UPLOAD_ERR_NO_FILE:
                    return array('ok' => false, 'message' => __('Please choose a backup file to upload.'));
                default:
                    return array('ok' => false, 'message' => __('Upload failed with system error code: %d', (int)$upload['error']));
            }
        }

        if(empty($upload['tmp_name']) || !is_uploaded_file($upload['tmp_name']))
        {
            return array('ok' => false, 'message' => __('Please choose a backup file to upload.'));
        }
        $originalName = isset($upload['name']) ? (string)$upload['name'] : 'uploaded_backup.zip';
        $ext = strtolower(pathinfo($originalName, PATHINFO_EXTENSION));
        if(!in_array($ext, array('zip','sql'), true))
        {
            return array('ok' => false, 'message' => __('Only ZIP or SQL backup files are allowed.'));
        }
        if(!$this->_isGlobalAdmin() && $ext !== 'zip')
        {
            return array('ok' => false, 'message' => __('Agency users can restore ZIP backups only.'));
        }
        try {
            $this->_makeBackupArchive(0, 'global', 0, 1, 'Auto pre-restore safety snapshot (' . date('d-M-Y H:i') . ')', '');
        } catch(Exception $e) {}
        $tmpDir = APP . 'tmp' . DS . 'ard_backups' . DS . '_upload_' . uniqid();
        $folder = new Folder();
        $folder->create($tmpDir, 0755);
        $targetPath = $tmpDir . DS . preg_replace('/[^a-zA-Z0-9_\-\.]/', '_', $originalName);
        if(!@move_uploaded_file($upload['tmp_name'], $targetPath))
        {
            return array('ok' => false, 'message' => __('Unable to move uploaded backup file.'));
        }
        $defaultScope = ((int)$projectId === 0 && $this->_isGlobalAdmin()) ? 'global' : 'agency';
        $result = $this->_restoreBackupFromFile($targetPath, (int)$projectId, $defaultScope, trim((string)$restorePassword));
        $this->_deleteDirRecursive($tmpDir);
        return $result;
    }

    protected function _restoreBackupFromFile($filePath, $projectId, $defaultScope, $zipPassword = '')
    {
        @set_time_limit(0);
        ini_set('memory_limit', '1024M');
        $projectId = (int)$projectId;
        $defaultScope = strtolower(trim((string)$defaultScope));
        $zipPassword = trim((string)$zipPassword);
        if($defaultScope !== 'global')
        {
            $defaultScope = 'agency';
        }

        $extension = strtolower(pathinfo((string)$filePath, PATHINFO_EXTENSION));
        if($extension === 'sql')
        {
            if(!$this->_isGlobalAdmin() && $defaultScope === 'global')
            {
                return array('ok' => false, 'message' => __('Agency users cannot restore global SQL dumps.'));
            }
            $run = $this->_executeSqlFile((string)$filePath);
            if(!empty($run['ok']))
            {
                $this->_flushSchemaAndModelCache();
            }
            return $run;
        }

        if($extension !== 'zip')
        {
            return array('ok' => false, 'message' => __('Unsupported backup format.'));
        }
        if(!class_exists('ZipArchive'))
        {
            return array('ok' => false, 'message' => __('ZipArchive extension is not enabled on server.'));
        }

        $extract = $this->_extractZipSafely((string)$filePath, $zipPassword);
        if(empty($extract['ok']))
        {
            return $extract;
        }
        $extractPath = (string)$extract['path'];
        $metadataPath = $extractPath . DS . 'metadata.json';
        $metadata = array();
        if(is_file($metadataPath))
        {
            $metadataRaw = file_get_contents($metadataPath);
            $metadataDecoded = json_decode((string)$metadataRaw, true);
            if(is_array($metadataDecoded))
            {
                $metadata = $metadataDecoded;
            }
        }
        $backupScope = strtolower(trim((string)(isset($metadata['backup_scope']) ? $metadata['backup_scope'] : $defaultScope)));
        if($backupScope !== 'global')
        {
            $backupScope = 'agency';
        }
        $backupProjectId = isset($metadata['project_id']) ? (int)$metadata['project_id'] : $projectId;

        if(!$this->_isGlobalAdmin())
        {
            if($backupScope === 'global')
            {
                $this->_deleteDirRecursive($extractPath);
                return array('ok' => false, 'message' => __('Agency users cannot restore global backups.'));
            }
            if($backupProjectId > 0 && $backupProjectId !== (int)$this->agencyId)
            {
                $this->_deleteDirRecursive($extractPath);
                return array('ok' => false, 'message' => __('This backup belongs to another agency.'));
            }
        }

        $sqlPath = $extractPath . DS . 'database.sql';
        if(!is_file($sqlPath))
        {
            $sqlCandidates = (array)glob($extractPath . DS . '*.sql');
            if(!empty($sqlCandidates[0]) && is_file($sqlCandidates[0]))
            {
                $sqlPath = $sqlCandidates[0];
            }
            else
            {
                $subSqlCandidates = (array)glob($extractPath . DS . '*' . DS . '*.sql');
                if(!empty($subSqlCandidates[0]) && is_file($subSqlCandidates[0]))
                {
                    $sqlPath = $subSqlCandidates[0];
                }
            }
        }
        if(!is_file($sqlPath))
        {
            $this->_deleteDirRecursive($extractPath);
            return array('ok' => false, 'message' => __('SQL database file not found in uploaded backup archive.'));
        }

        $runSql = $this->_executeSqlFile($sqlPath);
        if(empty($runSql['ok']))
        {
            $this->_deleteDirRecursive($extractPath);
            return $runSql;
        }

        if($this->_isGlobalAdmin() && $backupScope === 'global' && !empty($metadata['include_files']))
        {
            $snapshotPath = $extractPath . DS . 'app_snapshot';
            if(is_dir($snapshotPath))
            {
                $this->_restoreSnapshotFiles($snapshotPath, ROOT);
            }
        }

        $this->_flushSchemaAndModelCache();
        $this->_deleteDirRecursive($extractPath);
        return array('ok' => true);
    }

    protected function _executeSqlFile($sqlPath)
    {
        $sqlPath = (string)$sqlPath;
        if(!is_file($sqlPath))
        {
            return array('ok' => false, 'message' => __('SQL file not found.'));
        }
        @set_time_limit(0);
        ini_set('memory_limit', '1024M');

        $this->loadModel('Admin.Ardledger');
        $ds = $this->Ardledger->getDataSource();
        $handle = @fopen($sqlPath, 'r');
        if(!$handle)
        {
            return array('ok' => false, 'message' => __('Unable to open SQL file.'));
        }

        try
        {
            $ds->query('SET NAMES utf8mb4');
            $ds->query('SET FOREIGN_KEY_CHECKS=0');
            $ds->query("SET SQL_MODE=''");
        }
        catch(Exception $e) {}

        $query = '';
        $inString = false;
        $stringChar = '';
        $escaped = false;
        $inComment = false;
        $lineIndex = 0;

        while(($line = fgets($handle)) !== false)
        {
            $lineLen = strlen($line);
            if($lineIndex === 0 && strpos($line, "\xEF\xBB\xBF") === 0)
            {
                $line = substr($line, 3);
                $lineLen = strlen($line);
            }
            $lineIndex++;

            for($i = 0; $i < $lineLen; $i++)
            {
                $char = $line[$i];
                $nextChar = ($i + 1 < $lineLen) ? $line[$i + 1] : '';

                if($inString)
                {
                    $query .= $char;
                    if($escaped)
                    {
                        $escaped = false;
                    }
                    elseif($char === '\\')
                    {
                        $escaped = true;
                    }
                    elseif($char === $stringChar)
                    {
                        $inString = false;
                        $stringChar = '';
                    }
                    continue;
                }

                if($inComment)
                {
                    if($char === '*' && $nextChar === '/')
                    {
                        $inComment = false;
                        $i++;
                    }
                    continue;
                }

                if(($char === '-' && $nextChar === '-') || $char === '#')
                {
                    break;
                }

                if($char === '/' && $nextChar === '*')
                {
                    $thirdChar = ($i + 2 < $lineLen) ? $line[$i + 2] : '';
                    if($thirdChar !== '!')
                    {
                        $inComment = true;
                        $i++;
                        continue;
                    }
                }

                if($char === "'" || $char === '"' || $char === '`')
                {
                    $inString = true;
                    $stringChar = $char;
                    $query .= $char;
                    continue;
                }

                if($char === ';')
                {
                    $trimmed = trim($query);
                    if($trimmed !== '')
                    {
                        try
                        {
                            $ds->query($trimmed);
                        }
                        catch(Exception $e)
                        {
                            fclose($handle);
                            try { $ds->query('SET FOREIGN_KEY_CHECKS=1'); } catch(Exception $e2) {}
                            return array('ok' => false, 'message' => $e->getMessage());
                        }
                    }
                    $query = '';
                    continue;
                }

                $query .= $char;
            }
        }
        fclose($handle);

        $trimmed = trim($query);
        if($trimmed !== '')
        {
            try
            {
                $ds->query($trimmed);
            }
            catch(Exception $e)
            {
                try { $ds->query('SET FOREIGN_KEY_CHECKS=1'); } catch(Exception $e2) {}
                return array('ok' => false, 'message' => $e->getMessage());
            }
        }

        try
        {
            $ds->query('SET FOREIGN_KEY_CHECKS=1');
        }
        catch(Exception $e) {}

        return array('ok' => true);
    }

    protected function _flushSchemaAndModelCache()
    {
