            if($dbName !== '')
            {
                Cache::delete('default_'.$dbName.'_list', 'models');
            }
            Cache::clear(false, '_cake_model_');
            Cache::clear(false, '_cake_core_');
        }
        catch(Exception $e) {}
    }

    protected function _extractZipSafely($zipPath, $zipPassword = '')
    {
        $zipPath = (string)$zipPath;
        $zipPassword = trim((string)$zipPassword);
        if(!is_file($zipPath))
        {
            return array('ok' => false, 'message' => __('Zip file not found.'));
        }
        $zip = new ZipArchive();
        if($zip->open($zipPath) !== true)
        {
            return array('ok' => false, 'message' => __('Unable to open backup zip file.'));
        }
        $targetDir = APP . 'tmp' . DS . 'ard_backups' . DS . '_restore_' . uniqid();
        $folder = new Folder();
        $folder->create($targetDir, 0755);
        for($i = 0; $i < $zip->numFiles; $i++)
        {
            $entryName = (string)$zip->getNameIndex($i);
            $entryNormalized = str_replace('\\', '/', $entryName);
            if($entryNormalized === '')
            {
                continue;
            }
            if(strpos($entryNormalized, '../') !== false || strpos($entryNormalized, '..\\') !== false || strpos($entryNormalized, '/..') !== false)
            {
                $zip->close();
                $this->_deleteDirRecursive($targetDir);
                return array('ok' => false, 'message' => __('Unsafe file path found inside backup zip.'));
            }
            if(preg_match('/^[a-zA-Z]:/', $entryNormalized) || strpos($entryNormalized, '/') === 0)
            {
                $zip->close();
                $this->_deleteDirRecursive($targetDir);
                return array('ok' => false, 'message' => __('Absolute path found inside backup zip.'));
            }
        }
        if($zipPassword !== '' && method_exists($zip, 'setPassword'))
        {
            $zip->setPassword($zipPassword);
        }
        $didExtract = @$zip->extractTo($targetDir);
        $zip->close();
        if(!$didExtract)
        {
            $this->_deleteDirRecursive($targetDir);
            return array('ok' => false, 'message' => __('Unable to extract backup zip. If it is password protected, please enter correct password.'));
        }
        return array('ok' => true, 'path' => $targetDir);
    }

    protected function _restoreSnapshotFiles($sourceDir, $targetDir)
    {
        $sourceDir = rtrim((string)$sourceDir, DIRECTORY_SEPARATOR);
        $targetDir = rtrim((string)$targetDir, DIRECTORY_SEPARATOR);
        if(!is_dir($sourceDir) || !is_dir($targetDir))
        {
            return;
        }
        $iterator = new RecursiveIteratorIterator(
            new RecursiveDirectoryIterator($sourceDir, FilesystemIterator::SKIP_DOTS),
            RecursiveIteratorIterator::SELF_FIRST
        );
        foreach($iterator as $item)
        {
            $sourcePath = (string)$item->getPathname();
            $relative = ltrim(str_replace('\\', '/', substr($sourcePath, strlen($sourceDir))), '/');
            if($relative === '')
            {
                continue;
            }
            $targetPath = $targetDir . DIRECTORY_SEPARATOR . str_replace('/', DIRECTORY_SEPARATOR, $relative);
            if($item->isDir())
            {
                if(!is_dir($targetPath))
                {
                    @mkdir($targetPath, 0755, true);
                }
            }
            else
            {
                $targetFolder = dirname($targetPath);
                if(!is_dir($targetFolder))
                {
                    @mkdir($targetFolder, 0755, true);
                }
                @copy($sourcePath, $targetPath);
            }
        }
    }

    protected function _deleteDirRecursive($path)
    {
        $path = (string)$path;
        if($path === '' || !file_exists($path))
        {
            return;
        }
        if(is_file($path))
        {
            @unlink($path);
            return;
        }
        $iterator = new RecursiveIteratorIterator(
            new RecursiveDirectoryIterator($path, FilesystemIterator::SKIP_DOTS),
            RecursiveIteratorIterator::CHILD_FIRST
        );
        foreach($iterator as $item)
        {
            if($item->isDir())
            {
                @rmdir($item->getPathname());
            }
            else
            {
                @unlink($item->getPathname());
            }
        }
        @rmdir($path);
    }

    protected function _findBackupRow($backupId)
    {
        $backupId = (int)$backupId;
        if($backupId <= 0)
        {
            return array();
        }
        return $this->Ardbackup->find('first', array(
            'conditions' => array('Ardbackup.id' => $backupId),
            'recursive' => -1
        ));
    }

    protected function _canAccessBackupRow($row, $projectId)
    {
        $backupProjectId = (int)(isset($row['Ardbackup']['project_id']) ? $row['Ardbackup']['project_id'] : 0);
        if($this->_isGlobalAdmin())
        {
            return true;
        }
        return ($backupProjectId > 0 && $backupProjectId === (int)$this->agencyId);
    }

    protected function _deleteBackupRecord($backupId, $projectId)
    {
        $this->loadModel('Admin.Ardbackup');
        $row = $this->_findBackupRow((int)$backupId);
        if(empty($row['Ardbackup']))
        {
            return array('ok' => false, 'message' => __('Backup not found.'));
        }
        if(!$this->_canAccessBackupRow($row, (int)$projectId))
        {
            return array('ok' => false, 'message' => __('Permission denied for backup delete.'));
        }
        $filePath = $this->_absoluteBackupPath((string)$row['Ardbackup']['file_path']);
        if(is_file($filePath))
        {
            @unlink($filePath);
        }
        if(!$this->Ardbackup->delete((int)$row['Ardbackup']['id']))
        {
            return array('ok' => false, 'message' => __('Unable to delete backup record.'));
        }
        return array('ok' => true);
    }

    protected function _absoluteBackupPath($relativePath)
    {
        $relativePath = str_replace(array('\\','..'), array('/',''), (string)$relativePath);
        return APP . 'tmp' . DS . 'ard_backups' . DS . str_replace('/', DS, ltrim($relativePath, '/'));
    }

    protected function _formatBytes($bytes)
    {
        $bytes = (float)$bytes;
        if($bytes <= 0)
        {
            return '0 B';
        }
        $units = array('B','KB','MB','GB','TB');
        $pow = floor(log($bytes, 1024));
        $pow = min((int)$pow, count($units) - 1);
        $value = $bytes / pow(1024, $pow);
        return number_format($value, 2) . ' ' . $units[$pow];
    }

    public function templates($id = null)
    {
        $this->loadModel('Admin.Ardtemplate');
        $id = $this->_activeProjectId($id);
        $this->_ensureDefaultTemplatesForProject($id, array('salary', 'stock_purchase'));
        $templateTypeOptions = $this->_templateTypeOptions();
        foreach(array_keys($templateTypeOptions) as $templateTypeKey)
        {
            $this->_syncSingleActiveTemplate($id, $templateTypeKey, 0);
        }
        $this->set('projectName', $this->_projectList());
        $this->set('agencyId', $this->agencyId);
        $this->set('currentProjectId', $id);

        $rows = $this->Ardtemplate->find('all', array(
            'joins' => array(
                array(
                    'table' => 'projects',
                    'alias' => 'Agency',
                    'type' => 'LEFT',
                    'conditions' => array('Agency.id=Ardtemplate.project_id')
                )
            ),
            'fields' => array('Ardtemplate.*', 'Agency.name'),
            'conditions' => array($this->_scopeCondition('Ardtemplate.project_id', $id)),
            'order' => array('Ardtemplate.id' => 'desc'),
            'recursive' => -1
        ));
        $this->set('rows', $rows);
    }

    public function templateadd($id = null)
    {
        $this->loadModel('Admin.Ardtemplate');
        $id = $this->_activeProjectId($id);
        $templateTypeOptions = $this->_templateTypeOptions();

        if($this->request->is('post'))
        {
            $row = isset($this->request->data['Ardtemplate']) ? $this->request->data['Ardtemplate'] : array();
            $targetProjectId = isset($row['project_id']) ? $row['project_id'] : $id;
            $row['project_id'] = $this->_resolveProjectId($targetProjectId);
            if(!$this->_isAllowedProject($row['project_id']))
            {
                $this->Session->setFlash(__('Please select valid agency/project.'), 'flash', array('alert' => 'danger'));
                return $this->redirect(array('action' => 'templateadd', $id));
            }
            $row['template_name'] = trim((string)$row['template_name']);
            $row['template_type'] = trim((string)$row['template_type']);
            $row['template_content'] = (string)$row['template_content'];
            if($row['template_name'] === '' || $row['template_type'] === '')
            {
                $this->Session->setFlash(__('Template name and type are required.'), 'flash', array('alert' => 'danger'));
            }
            elseif(!isset($templateTypeOptions[$row['template_type']]))
            {
                $this->Session->setFlash(__('Invalid template type.'), 'flash', array('alert' => 'danger'));
            }
            else
            {
                $row['is_active'] = !empty($row['is_active']) ? 1 : 0;
                $this->Ardtemplate->create();
                if($this->Ardtemplate->save(array('Ardtemplate' => $row)))
                {
                    $savedTemplateId = (int)$this->Ardtemplate->id;
                    if((int)$row['is_active'] === 1)
                    {
                        $this->_syncSingleActiveTemplate((int)$row['project_id'], $row['template_type'], $savedTemplateId);
                    }
                    else
                    {
                        $this->_syncSingleActiveTemplate((int)$row['project_id'], $row['template_type'], 0);
                    }
                    $this->Session->setFlash(__('Template saved successfully.'), 'flash', array('alert' => 'success'));
                    return $this->redirect(array('action' => 'templates', (int)$row['project_id']));
                }
                $this->Session->setFlash(__('Unable to save template.'), 'flash', array('alert' => 'danger'));
            }
            $this->request->data['Ardtemplate'] = $row;
        }

        if(empty($this->request->data['Ardtemplate']))
        {
            $this->request->data['Ardtemplate'] = array(
                'project_id' => ($this->_isGlobalAdmin()) ? (int)$id : (int)$this->agencyId,
                'template_type' => 'voucher',
                'template_name' => '',
                'template_content' => '',
                'is_active' => 0
            );
        }

        $this->set('projectName', $this->_projectList());
        $this->set('agencyId', $this->agencyId);
        $this->set('currentProjectId', $id);
        $this->set('templateTypeOptions', $templateTypeOptions);
        $this->set('templatePlaceholderCatalog', $this->_templatePlaceholderCatalog());
        $this->set('isTemplateEdit', false);
        $this->set('templateFormTitle', __('Add Template'));
        $this->render('template_form');
    }

    public function templateedit($templateId = null, $projectId = null)
    {
        $this->loadModel('Admin.Ardtemplate');
        $templateId = (int)$templateId;
        if($templateId <= 0)
        {
            $this->Session->setFlash(__('Invalid template.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'templates', $this->_activeProjectId($projectId)));
        }

        $existing = $this->Ardtemplate->findById($templateId);
        if(empty($existing) || !$this->_isAllowedProject((int)$existing['Ardtemplate']['project_id']))
        {
            $this->Session->setFlash(__('Invalid template.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'templates', $this->_activeProjectId($projectId)));
        }

        $currentProjectId = $this->_activeProjectId((int)$existing['Ardtemplate']['project_id']);
        $templateTypeOptions = $this->_templateTypeOptions();

        if($this->request->is(array('post', 'put')))
        {
            $row = isset($this->request->data['Ardtemplate']) ? $this->request->data['Ardtemplate'] : array();
            $oldProjectId = (int)$existing['Ardtemplate']['project_id'];
            $oldTemplateType = trim((string)$existing['Ardtemplate']['template_type']);
            $targetProjectId = isset($row['project_id']) ? $row['project_id'] : $existing['Ardtemplate']['project_id'];
            $row['project_id'] = $this->_resolveProjectId($targetProjectId);
            $row['id'] = $templateId;
            if(!$this->_isAllowedProject($row['project_id']))
            {
                $this->Session->setFlash(__('Please select valid agency/project.'), 'flash', array('alert' => 'danger'));
            }
            else
            {
                $row['template_name'] = trim((string)$row['template_name']);
                $row['template_type'] = trim((string)$row['template_type']);
                $row['template_content'] = (string)$row['template_content'];
                if($row['template_name'] === '' || $row['template_type'] === '')
                {
                    $this->Session->setFlash(__('Template name and type are required.'), 'flash', array('alert' => 'danger'));
                }
                elseif(!isset($templateTypeOptions[$row['template_type']]))
                {
                    $this->Session->setFlash(__('Invalid template type.'), 'flash', array('alert' => 'danger'));
                }
                else
                {
                    $row['is_active'] = !empty($row['is_active']) ? 1 : 0;
                    $this->Ardtemplate->id = $templateId;
                    if($this->Ardtemplate->save(array('Ardtemplate' => $row)))
                    {
                        if((int)$row['is_active'] === 1)
                        {
                            $this->_syncSingleActiveTemplate((int)$row['project_id'], $row['template_type'], $templateId);
                        }
                        else
                        {
                            $this->_syncSingleActiveTemplate((int)$row['project_id'], $row['template_type'], 0);
                        }
                        if($oldProjectId !== (int)$row['project_id'] || $oldTemplateType !== (string)$row['template_type'])
                        {
                            $this->_syncSingleActiveTemplate($oldProjectId, $oldTemplateType, 0);
                        }
                        $this->Session->setFlash(__('Template updated successfully.'), 'flash', array('alert' => 'success'));
                        return $this->redirect(array('action' => 'templates', (int)$row['project_id']));
                    }
                    $this->Session->setFlash(__('Unable to update template.'), 'flash', array('alert' => 'danger'));
                }
            }
            $this->request->data['Ardtemplate'] = $row;
        }
        else
        {
            $this->request->data['Ardtemplate'] = $existing['Ardtemplate'];
        }

        $this->set('projectName', $this->_projectList());
        $this->set('agencyId', $this->agencyId);
        $this->set('currentProjectId', $currentProjectId);
        $this->set('templateTypeOptions', $templateTypeOptions);
        $this->set('templatePlaceholderCatalog', $this->_templatePlaceholderCatalog());
        $this->set('isTemplateEdit', true);
        $this->set('templateFormTitle', __('Edit Template'));
        $this->render('template_form');
    }

    protected function _resolveAgencyLogoUrlForTemplate($projectId, $agencyRow = array())
    {
        $projectId = (int)$projectId;
        $agencyRow = is_array($agencyRow) ? $agencyRow : array();
        $resolveImagePath = function($candidates = array())
        {
            foreach((array)$candidates as $candidate)
            {
                $candidate = trim((string)$candidate);
                if($candidate === '')
                {
                    continue;
                }
                $cleanPath = str_replace('\\', '/', $candidate);
                $cleanPath = ltrim($cleanPath, '/');
                if($cleanPath === '')
                {
                    continue;
                }
                $fullPath = WWW_ROOT . 'img' . DS . str_replace('/', DS, $cleanPath);
                if(file_exists($fullPath))
                {
                    return $cleanPath;
                }
            }
            return '';
        };

        $agencyLogoFile = '';
        if($projectId > 0)
        {
            try
            {
                $this->loadModel('User');
                $userFields = array('User.id');
                if($this->User->hasField('photo'))
                {
                    $userFields[] = 'User.photo';
                }
                $baseConditions = array(
                    'User.project_id' => $projectId,
                    'User.photo <>' => ''
                );
                $agencyUserRow = array();
                if($this->User->hasField('ugroup_id'))
                {
                    $agencyUserRow = $this->User->find('first', array(
                        'fields' => $userFields,
                        'conditions' => array_merge($baseConditions, array('User.ugroup_id' => 4)),
                        'order' => array('User.id' => 'asc'),
                        'recursive' => -1
                    ));
                }
                if(empty($agencyUserRow))
                {
                    $agencyUserRow = $this->User->find('first', array(
                        'fields' => $userFields,
                        'conditions' => $baseConditions,
                        'order' => array('User.id' => 'asc'),
                        'recursive' => -1
                    ));
                }
                if(!empty($agencyUserRow['User']['photo']))
                {
                    $agencyLogoFile = trim((string)$agencyUserRow['User']['photo']);
                }
            }
            catch(Exception $e)
            {
                $agencyLogoFile = '';
            }
        }

        $agencyLogoPath = $resolveImagePath(array(
            ($agencyLogoFile !== '' ? 'user_thumb/' . $agencyLogoFile : ''),
            ($agencyLogoFile !== '' ? 'user/' . $agencyLogoFile : ''),
            ($agencyLogoFile !== '' ? $agencyLogoFile : ''),
            !empty($agencyRow['photo']) ? 'agency_thumb/' . $agencyRow['photo'] : '',
            !empty($agencyRow['photo']) ? 'agency/' . $agencyRow['photo'] : '',
            !empty($agencyRow['photo']) ? $agencyRow['photo'] : ''
        ));

        return ($agencyLogoPath !== '') ? Router::url('/img/' . $agencyLogoPath, true) : '';
    }

