    public function templateview($templateId = null, $projectId = null)
    {
        $this->loadModel('Admin.Ardtemplate');

        $templateId = (int)$templateId;
        if($templateId <= 0)
        {
            $this->Session->setFlash(__('Invalid template.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'templates', $this->_activeProjectId($projectId)));
        }

        $row = (array)$this->Ardtemplate->findById($templateId);
        if(empty($row['Ardtemplate']) || !$this->_isAllowedProject((int)$row['Ardtemplate']['project_id']))
        {
            $this->Session->setFlash(__('Invalid template.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'templates', $this->_activeProjectId($projectId)));
        }

        $templateRow = (array)$row['Ardtemplate'];
        $templateProjectId = (int)$templateRow['project_id'];
        $templateType = strtolower(trim((string)(isset($templateRow['template_type']) ? $templateRow['template_type'] : 'voucher')));
        $templateContent = isset($templateRow['template_content']) ? (string)$templateRow['template_content'] : '';
        if(trim((string)$templateContent) === '')
        {
            $templateContent = (string)$this->_defaultTemplateContentByType($templateType);
        }

        $tokenMap = $this->_templatePreviewTokenMap($templateProjectId, $templateType);
        if($templateType === 'voucher')
        {
            $legacyBarcodePattern = '/<svg[^>]*viewBox="0 0 400 32"[^>]*>.*?<\/svg>/s';
            if(preg_match($legacyBarcodePattern, $templateContent))
            {
                $templateContent = preg_replace($legacyBarcodePattern, '{{barcode_svg}}', $templateContent);
                $templateContent = str_replace('tracking-[0.8em]', 'tracking-[0.25em]', $templateContent);
                $templateContent = str_replace('text-gray-500 uppercase">{{barcode_text}}', 'text-gray-700 uppercase font-extrabold">{{barcode_text}}', $templateContent);
            }
            $legacyAccBoxPattern = '/<div class="w-64 border-2 border-black p-3 h-20 flex flex-col justify-between bg-white">\s*<span class="text-\[9px\] font-black uppercase text-gray-400 tracking-widest">Acc\/From<\/span>\s*<span class="font-bold tracking-\[0\.2em\] text-lg">\{\{account_no\}\}<\/span>\s*<\/div>/s';
            if(preg_match($legacyAccBoxPattern, $templateContent))
            {
                $newAccBoxMarkup = '<div class="w-64 border-2 border-black p-2.5 h-20 flex flex-col justify-between bg-white">' .
                    '<div class="flex justify-between items-center border-b border-gray-200 pb-0.5">' .
                    '<span class="text-[9px] font-black uppercase text-gray-500 tracking-widest">{{account_box_label}}</span>' .
                    '<span class="text-[10px] font-mono font-bold text-gray-700 tracking-wider">A/C: <strong class="text-black font-extrabold">{{account_code}}</strong></span>' .
                    '</div>' .
                    '<div class="flex flex-col justify-end">' .
                    '<span class="font-mono font-bold tracking-[0.2em] text-lg text-black leading-tight">{{account_display_no}}</span>' .
                    '<span class="text-[9px] font-bold text-gray-500 uppercase tracking-wider truncate mt-0.5">{{account_head_name}}</span>' .
                    '</div>' .
                    '</div>';
                $templateContent = preg_replace($legacyAccBoxPattern, $newAccBoxMarkup, $templateContent);
            }
        }
        $html = $this->_renderVoucherTemplateTokens($templateContent, $tokenMap);
        if(trim((string)$html) === '')
        {
            $html = '<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Template Preview</title></head><body><div style="font-family:Arial,sans-serif;padding:20px;">No preview content available.</div></body></html>';
        }
        else
        {
            $lowerHtml = strtolower((string)$html);
            if(strpos($lowerHtml, '<html') === false && strpos($lowerHtml, '<!doctype') === false)
            {
                $html = '<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Template Preview</title><style>body{font-family:Arial,Helvetica,sans-serif;background:#f5f7fb;margin:0;padding:15px;color:#1b2f4a;} .preview-wrap{max-width:1200px;margin:0 auto;}</style></head><body><div class="preview-wrap">' . $html . '</div></body></html>';
            }
        }

        $this->layout = null;
        $this->autoRender = false;
        $this->response->type('html');
        if($templateType === 'voucher')
        {
            $html = $this->_applyVoucherDateMonthStyle($html);
        }
        $this->response->body((string)$html);
        return $this->response;
    }

    public function deletetemplate($id = null, $projectId = null)
    {
        $this->loadModel('Admin.Ardtemplate');
        $row = $this->Ardtemplate->findById($id);
        if(empty($row) || !$this->_isAllowedProject((int)$row['Ardtemplate']['project_id']))
        {
            $this->Session->setFlash(__('Invalid template.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'templates', $this->_activeProjectId($projectId)));
        }
        $this->_storeTrashRecord(
            'ardaccounts_templates',
            'Ardtemplate',
            $row['Ardtemplate'],
            isset($row['Ardtemplate']['template_name']) ? (string)$row['Ardtemplate']['template_name'] : ''
        );
        $deletedProjectId = (int)$row['Ardtemplate']['project_id'];
        $deletedType = trim((string)$row['Ardtemplate']['template_type']);
        $this->Ardtemplate->delete($id);
        if($deletedProjectId > 0 && $deletedType !== '')
        {
            $this->_syncSingleActiveTemplate($deletedProjectId, $deletedType, 0);
        }
        $this->Session->setFlash(__('Template deleted. You can restore it from Trash.'), 'flash', array('alert' => 'success'));
        return $this->redirect(array('action' => 'templates', (int)$row['Ardtemplate']['project_id']));
    }

    public function vendors($id = null)
    {
        $this->loadModel('Admin.Ardvendor');
        $id = $this->_activeProjectId($id);
        $editIdFromUrl = 0;
        if(isset($this->request->query['edit']))
        {
            $editIdFromUrl = (int)$this->request->query['edit'];
        }
        if($editIdFromUrl <= 0 && isset($this->request->params['named']['edit']))
        {
            $editIdFromUrl = (int)$this->request->params['named']['edit'];
        }
        $this->set('projectName', $this->_projectList());
        $this->set('agencyId', $this->agencyId);
        $this->set('currentProjectId', $id);
        $this->set('editIdFromUrl', $editIdFromUrl);

        if($this->request->is('post'))
        {
            $row = isset($this->request->data['Ardvendor']) ? $this->request->data['Ardvendor'] : array();
            $row['id'] = (int)(isset($row['id']) ? $row['id'] : 0);
            $row['project_id'] = $this->_resolveProjectId(isset($row['project_id']) ? $row['project_id'] : null);
            if(!$this->_isAllowedProject($row['project_id']))
            {
                $this->Session->setFlash(__('Please select valid agency/project.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            if($row['id'] > 0)
            {
                $existing = (array)$this->Ardvendor->findById($row['id']);
                if(empty($existing['Ardvendor']['id']) || !$this->_isAllowedProject((int)$existing['Ardvendor']['project_id']))
                {
                    $this->Session->setFlash(__('Invalid vendor edit request.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect(array('action' => 'vendors', $id));
                }
            }
            $row['vendor_name'] = trim((string)$row['vendor_name']);
            if($row['vendor_name'] === '')
            {
                $this->Session->setFlash(__('Vendor name is required.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            $row['status'] = (isset($row['status']) && strtolower((string)$row['status']) === 'inactive') ? 'inactive' : 'active';
            $saveOk = false;
            if($row['id'] > 0)
            {
                $this->Ardvendor->id = (int)$row['id'];
                $saveOk = (bool)$this->Ardvendor->save(array('Ardvendor' => $row));
            }
            else
            {
                $this->Ardvendor->create();
                $saveOk = (bool)$this->Ardvendor->save(array('Ardvendor' => $row));
            }
            if($saveOk)
            {
                $this->Session->setFlash(($row['id'] > 0) ? __('Vendor updated successfully.') : __('Vendor saved successfully.'), 'flash', array('alert' => 'success'));
            }
            else
            {
                $this->Session->setFlash(__('Unable to save vendor.'), 'flash', array('alert' => 'danger'));
            }
            return $this->redirect(array('action' => 'vendors', (int)$row['project_id']));
        }

        $scope = $this->_scopeCondition('Ardvendor.project_id', $id);
        $this->Paginator->settings = array(
            'page' => 1,
            'order' => array('Ardvendor.id' => 'desc'),
            'limit' => $this->pageLimit,
            'maxLimit' => $this->maxLimit,
            'conditions' => array($scope)
        );
        $this->set('rows', $this->Paginator->paginate('Ardvendor'));

        $editId = $editIdFromUrl;
        if($editId > 0)
        {
            $editRow = $this->Ardvendor->findById($editId);
            if(!empty($editRow) && $this->_isAllowedProject((int)$editRow['Ardvendor']['project_id']))
            {
                $this->request->data = $editRow;
            }
            else
            {
                $this->Session->setFlash(__('Invalid vendor edit request.'), 'flash', array('alert' => 'danger'));
                return $this->redirect(array('action' => 'vendors', $id));
            }
        }
        else
        {
            $this->request->data = array();
        }
    }

