    protected function _hrEmployeeLinkedUsersByProject($projectId)
    {
        $projectId = (int)$projectId;
        if($projectId <= 0)
        {
            return array('options' => array(), 'meta' => array());
        }
        $this->loadModel('User');
        $userRows = (array)$this->User->find('all', array(
            'joins' => array(
                array(
                    'table' => 'ugroups',
                    'alias' => 'Ugroup',
                    'type' => 'LEFT',
                    'conditions' => array('Ugroup.id=User.ugroup_id')
                )
            ),
            'fields' => array('User.id', 'User.name', 'User.mobile', 'User.phone', 'User.email', 'Ugroup.name', 'Ugroup.type'),
            'conditions' => array('User.project_id' => $projectId),
            'order' => array('User.name' => 'asc', 'User.id' => 'asc'),
            'recursive' => -1
        ));
        $userIds = array();
        foreach($userRows as $userRow)
        {
            $userId = isset($userRow['User']['id']) ? (int)$userRow['User']['id'] : 0;
            if($userId > 0)
            {
                $userIds[] = $userId;
            }
        }
        $walletByUser = array();
        $walletRowFoundByUser = array();
        $walletHistoryFoundByUser = array();
        $extractSqlValue = function($row, $column){
            if(isset($row[0]) && is_array($row[0]) && array_key_exists($column, $row[0]))
            {
                return $row[0][$column];
            }
            if(array_key_exists($column, (array)$row))
            {
                return $row[$column];
            }
            foreach((array)$row as $part)
            {
                if(!is_array($part))
                {
                    continue;
                }
                if(array_key_exists($column, $part))
                {
                    return $part[$column];
                }
                foreach($part as $partKey => $partValue)
                {
                    if(strtolower((string)$partKey) === strtolower((string)$column))
                    {
                        return $partValue;
                    }
                }
            }
            return null;
        };
        if(!empty($userIds))
        {
            // Read latest wallet row per user (do not hard-filter by project_id),
            // so moved users still show their true current wallet.
            $walletSql = "SELECT aw.user_id, aw.balance, aw.project_id, aw.id
                FROM awallets aw
                INNER JOIN (
                    SELECT user_id, MAX(id) AS max_id
                    FROM awallets
                    WHERE user_id IN(".implode(',', array_map('intval', $userIds)).")
                    GROUP BY user_id
                ) latest ON latest.max_id = aw.id";
            $walletRows = (array)$this->Ardhremployee->query($walletSql);
            foreach($walletRows as $walletRow)
            {
                $walletUserId = (int)$extractSqlValue((array)$walletRow, 'user_id');
                if($walletUserId <= 0)
                {
                    continue;
                }
                $walletByUser[$walletUserId] = (float)$extractSqlValue((array)$walletRow, 'balance');
                $walletRowFoundByUser[$walletUserId] = true;
            }

            $historySql = "SELECT user_id,
                SUM(CASE WHEN UPPER(TRIM(COALESCE(type,'')))='CR' THEN amount ELSE (-1 * amount) END) AS hist_balance,
                COUNT(*) AS hist_rows
                FROM awallet_histories
                WHERE user_id IN(".implode(',', array_map('intval', $userIds)).")
                GROUP BY user_id";
            $historyRows = (array)$this->Ardhremployee->query($historySql);
            foreach($historyRows as $historyRow)
            {
                $historyUserId = (int)$extractSqlValue((array)$historyRow, 'user_id');
                if($historyUserId <= 0)
                {
                    continue;
                }
                $historyBalance = (float)$extractSqlValue((array)$historyRow, 'hist_balance');
                $historyCount = (int)$extractSqlValue((array)$historyRow, 'hist_rows');
                if($historyCount > 0)
                {
                    $walletHistoryFoundByUser[$historyUserId] = true;
                }
                if(empty($walletRowFoundByUser[$historyUserId]))
                {
                    $walletByUser[$historyUserId] = $historyBalance;
                }
            }
        }

        $options = array();
        $meta = array();
        foreach($userRows as $userRow)
        {
            $userId = isset($userRow['User']['id']) ? (int)$userRow['User']['id'] : 0;
            if($userId <= 0)
            {
                continue;
            }
            $userName = trim((string)(isset($userRow['User']['name']) ? $userRow['User']['name'] : ''));
            $roleName = trim((string)(isset($userRow['Ugroup']['name']) ? $userRow['Ugroup']['name'] : ''));
            $roleType = strtoupper(trim((string)(isset($userRow['Ugroup']['type']) ? $userRow['Ugroup']['type'] : '')));
            if($userName === '')
            {
                $userName = 'User #'.$userId;
            }
            $displayLabel = $userName;
            if($roleName !== '')
            {
                $displayLabel .= ' ['.$roleName.']';
            }
            $hasWallet = (!empty($walletRowFoundByUser[$userId]) || !empty($walletHistoryFoundByUser[$userId]));
            $walletBalance = isset($walletByUser[$userId]) ? (float)$walletByUser[$userId] : 0.0;
            if(!$hasWallet && ($roleType === 'AGT' || stripos($roleName, 'agent') !== false))
            {
                // Safety fallback: use existing wallet helper so HR employee popup matches wallet module behavior.
                $legacyWalletBalance = (float)str_replace(',', '', trim((string)$this->CustomFunction->awalletBalance($userId)));
                if(abs($legacyWalletBalance) > 0)
                {
                    $walletBalance = $legacyWalletBalance;
                    $hasWallet = true;
                }
            }
            if($hasWallet)
            {
                $displayLabel .= ' | Wallet: Rs '.number_format($walletBalance, 0, '.', ',');
            }
            $mobileNo = trim((string)(isset($userRow['User']['mobile']) ? $userRow['User']['mobile'] : ''));
            if($mobileNo === '')
            {
                $mobileNo = trim((string)(isset($userRow['User']['phone']) ? $userRow['User']['phone'] : ''));
            }
            $options[$userId] = $displayLabel;
            $meta[$userId] = array(
                'name' => $userName,
                'mobile' => $mobileNo,
                'email' => trim((string)(isset($userRow['User']['email']) ? $userRow['User']['email'] : '')),
                'role_name' => $roleName,
                'role_type' => $roleType,
                'wallet_balance' => $walletBalance,
                'has_wallet' => $hasWallet ? 1 : 0
            );
        }
        return array('options' => $options, 'meta' => $meta);
    }

    protected function _hrEmployeeLinkedUserRow($projectId, $userId)
