            'recursive' => -1
        ));
    }

    public function hremployeecodepreview($id = null)
    {
        $this->autoRender = false;
        $this->response->type('json');
        $projectId = 0;
        // Always prefer explicit dropdown-selected project_id from query.
        if(isset($this->request->query['project_id']))
        {
            $projectId = (int)$this->request->query['project_id'];
        }
        if($projectId <= 0 && isset($id) && (int)$id > 0)
        {
            $projectId = (int)$id;
        }
        $projectId = $this->_resolveProjectId($projectId);
        if($projectId <= 0 || !$this->_isAllowedProject($projectId))
        {
            $payload = array('ok' => 0, 'message' => __('Invalid or unauthorized agency.'));
            $this->response->body(json_encode($payload));
            return $this->response;
        }
        $code = trim((string)$this->_peekReferenceNo($projectId, 'employee_id', 'EMP-'));
        if($code === '')
        {
            $code = 'EMP-' . date('YmdHis');
        }
        $payload = array(
            'ok' => 1,
            'project_id' => (int)$projectId,
            'code' => $code
        );
        $this->response->body(json_encode($payload));
        return $this->response;
    }

    public function hremployees($id = null)
    {
        $this->loadModel('Admin.Ardhremployee');
        $this->loadModel('Admin.Ardhattendance');
        $this->loadModel('Admin.Ardsetting');
        $this->loadModel('Admin.Ardledger');
        $id = $this->_activeProjectId($id);
        $employeeScope = $this->_hrEmployeeScopeFromRequest('all');
        $employeeScopeLabel = $this->_hrEmployeeScopeLabel($employeeScope);
        $employeeScopeQuery = $this->_hrEmployeeScopeQuery($employeeScope);
        $employeeTypeConditions = $this->_hrEmployeeScopeConditions('Ardhremployee', $employeeScope);
        $projectName = $this->_projectList();
        $this->set('projectName', $projectName);
        $this->set('agencyId', $this->agencyId);
        $this->set('currentProjectId', $id);
        $this->set('employeeScope', $employeeScope);
        $this->set('employeeScopeLabel', $employeeScopeLabel);
        $this->set('employeeScopeQuery', $employeeScopeQuery);
        $projectIdsForLinkedUsers = array();
        if($this->_isGlobalAdmin())
        {
            foreach((array)$projectName as $projectId => $projectLabel)
            {
                $projectId = (int)$projectId;
                if($projectId > 0)
                {
                    $projectIdsForLinkedUsers[] = $projectId;
                }
            }
        }
        else
        {
            $projectIdsForLinkedUsers[] = ((int)$id > 0 ? (int)$id : (int)$this->agencyId);
        }
        if((int)$id > 0)
        {
            $projectIdsForLinkedUsers[] = (int)$id;
        }
        $projectIdsForLinkedUsers = array_values(array_unique(array_filter(array_map('intval', $projectIdsForLinkedUsers))));
        $linkedUsersByProject = array();
        $linkedUsersMetaByProject = array();
        $linkedUsersMetaByUserId = array();
        foreach($projectIdsForLinkedUsers as $projectIdForUsers)
        {
            $linkedBundle = $this->_hrEmployeeLinkedUsersByProject((int)$projectIdForUsers);
            $linkedUsersByProject[(int)$projectIdForUsers] = isset($linkedBundle['options']) ? (array)$linkedBundle['options'] : array();
            $linkedUsersMetaByProject[(int)$projectIdForUsers] = isset($linkedBundle['meta']) ? (array)$linkedBundle['meta'] : array();
            foreach((array)$linkedUsersMetaByProject[(int)$projectIdForUsers] as $metaUserId => $metaRow)
            {
                $metaUserId = (int)$metaUserId;
                if($metaUserId <= 0 || isset($linkedUsersMetaByUserId[$metaUserId]))
                {
                    continue;
                }
                $linkedUsersMetaByUserId[$metaUserId] = (array)$metaRow;
            }
        }
        $this->set('linkedUsersByProject', $linkedUsersByProject);
        $this->set('linkedUsersMetaByProject', $linkedUsersMetaByProject);
        $this->set('linkedUsersMetaByUserId', $linkedUsersMetaByUserId);

        $projectIdsForSettings = $projectIdsForLinkedUsers;
        if((int)$id > 0 && !in_array((int)$id, $projectIdsForSettings, true))
        {
            $projectIdsForSettings[] = (int)$id;
        }
        if(!$this->_isGlobalAdmin() && (int)$this->agencyId > 0 && !in_array((int)$this->agencyId, $projectIdsForSettings, true))
        {
            $projectIdsForSettings[] = (int)$this->agencyId;
        }
        $projectIdsForSettings = array_values(array_unique(array_filter(array_map('intval', $projectIdsForSettings))));
        $settingsDefaults = $this->_defaultSettings();
        $toOptionMap = function($lineText){
            $options = array();
            foreach((array)$this->_lineTextToOptionList($lineText) as $optionKey => $optionLabel)
            {
                $optionKey = trim((string)$optionKey);
                if($optionKey === '' || isset($options[$optionKey]))
                {
                    continue;
                }
                $options[$optionKey] = trim((string)$optionLabel);
            }
            return $options;
        };
        $departmentOptionsByProject = array();
        $designationOptionsByProject = array();
        $employeeCodePreviewByProject = array();
        foreach($projectIdsForSettings as $settingsProjectId)
        {
            $settingsProjectId = (int)$settingsProjectId;
            if($settingsProjectId <= 0)
            {
                continue;
            }
            $settingsData = $settingsDefaults;
            $settingsRow = $this->Ardsetting->find('first', array(
                'conditions' => array('Ardsetting.project_id' => $settingsProjectId),
                'order' => array('Ardsetting.id' => 'desc'),
                'recursive' => -1
            ));
            if(!empty($settingsRow['Ardsetting']))
            {
                $settingsData = array_merge($settingsData, (array)$settingsRow['Ardsetting']);
            }
            $hrDepartmentTypes = isset($settingsData['hr_department_types']) ? $settingsData['hr_department_types'] : '';
            $hrDesignationTypes = isset($settingsData['hr_designation_types']) ? $settingsData['hr_designation_types'] : '';
            $constructionDepartmentTypes = isset($settingsData['construction_department_types']) ? $settingsData['construction_department_types'] : '';
            $constructionDesignationTypes = isset($settingsData['construction_designation_types']) ? $settingsData['construction_designation_types'] : '';

            if($employeeScope === 'labour')
            {
                // Labour create/edit must use agency construction settings.
                $departmentLineText = $constructionDepartmentTypes;
                $designationLineText = $constructionDesignationTypes;
                if(trim((string)$departmentLineText) === '')
                {
                    $departmentLineText = $hrDepartmentTypes;
                }
                if(trim((string)$designationLineText) === '')
                {
                    $designationLineText = $hrDesignationTypes;
                }
            }
            else
            {
                $departmentLineText = $hrDepartmentTypes;
                $designationLineText = $hrDesignationTypes;
                if(trim((string)$departmentLineText) === '')
                {
                    $departmentLineText = $constructionDepartmentTypes;
                }
                if(trim((string)$designationLineText) === '')
                {
                    $designationLineText = $constructionDesignationTypes;
                }
            }

            $departmentOptionsByProject[$settingsProjectId] = $toOptionMap($departmentLineText);
            $designationOptionsByProject[$settingsProjectId] = $toOptionMap($designationLineText);
            $employeeCodePreviewByProject[$settingsProjectId] = (string)$this->_peekReferenceNo($settingsProjectId, 'employee_id', 'EMP-');
        }
        $initialSettingsProjectId = (int)$id;
        if($initialSettingsProjectId <= 0)
        {
            if(!$this->_isGlobalAdmin() && (int)$this->agencyId > 0)
            {
                $initialSettingsProjectId = (int)$this->agencyId;
            }
            elseif(!empty($projectIdsForSettings))
            {
                $initialSettingsProjectId = (int)reset($projectIdsForSettings);
            }
        }
        $departmentOptions = isset($departmentOptionsByProject[$initialSettingsProjectId]) ? (array)$departmentOptionsByProject[$initialSettingsProjectId] : array();
        $designationOptions = isset($designationOptionsByProject[$initialSettingsProjectId]) ? (array)$designationOptionsByProject[$initialSettingsProjectId] : array();
        if(empty($departmentOptions))
        {
            foreach((array)$departmentOptionsByProject as $projectWiseOptions)
            {
                if(!empty($projectWiseOptions))
                {
                    $departmentOptions = (array)$projectWiseOptions;
                    break;
                }
            }
        }
        if(empty($designationOptions))
        {
            foreach((array)$designationOptionsByProject as $projectWiseOptions)
            {
                if(!empty($projectWiseOptions))
                {
                    $designationOptions = (array)$projectWiseOptions;
                    break;
                }
            }
        }
        $this->set('departmentOptions', $departmentOptions);
        $this->set('designationOptions', $designationOptions);
        $this->set('departmentOptionsByProject', $departmentOptionsByProject);
        $this->set('designationOptionsByProject', $designationOptionsByProject);
        if($initialSettingsProjectId > 0 && !isset($employeeCodePreviewByProject[$initialSettingsProjectId]))
        {
            $employeeCodePreviewByProject[$initialSettingsProjectId] = (string)$this->_peekReferenceNo($initialSettingsProjectId, 'employee_id', 'EMP-');
        }
        $this->set('employeeCodePreviewByProject', $employeeCodePreviewByProject);

        if($this->request->is('post'))
        {
            $attendanceSubmit = !empty($this->request->data['attendance_popup_submit']) || !empty($this->request->data['Ardhattendance']);
            if($attendanceSubmit)
            {
                $attendance = isset($this->request->data['Ardhattendance']) ? (array)$this->request->data['Ardhattendance'] : array();
                $attendanceProjectId = $this->_resolveProjectId(isset($attendance['project_id']) ? $attendance['project_id'] : $id);
                if(!$this->_isAllowedProject($attendanceProjectId))
                {
                    $this->Session->setFlash(__('Please select valid agency/project.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect(array('action' => 'hremployees', $id, '?' => $employeeScopeQuery));
                }
                $employeeId = isset($attendance['employee_id']) ? (int)$attendance['employee_id'] : 0;
                $employeeRow = array();
                if($employeeId > 0)
                {
                    $employeeRow = $this->Ardhremployee->find('first', array(
                        'conditions' => array(
                            'Ardhremployee.id' => $employeeId,
                            'Ardhremployee.project_id' => $attendanceProjectId
                        ),
                        'recursive' => -1
                    ));
                    if(empty($employeeRow['Ardhremployee']))
                    {
                        $employeeRow = $this->Ardhremployee->find('first', array(
                            'conditions' => array(
                                'Ardhremployee.id' => $employeeId
                            ),
                            'recursive' => -1
                        ));
                        if(!empty($employeeRow['Ardhremployee']['project_id']) && $this->_isAllowedProject((int)$employeeRow['Ardhremployee']['project_id']))
                        {
                            $attendanceProjectId = (int)$employeeRow['Ardhremployee']['project_id'];
                        }
                    }
                }
                if(empty($employeeRow['Ardhremployee']))
                {
                    $this->Session->setFlash(__('Please select valid employee.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect(array('action' => 'hremployees', $id, '?' => $employeeScopeQuery));
                }
                $employeeProjectId = isset($employeeRow['Ardhremployee']['project_id']) ? (int)$employeeRow['Ardhremployee']['project_id'] : 0;
                if($employeeProjectId > 0 && $employeeProjectId !== (int)$attendanceProjectId)
                {
                    // Keep attendance isolated by the employee's own agency/project.
                    $attendanceProjectId = $employeeProjectId;
                }
                if(!$this->_hrEmployeeMatchesScope($employeeRow, $employeeScope))
                {
                    $this->Session->setFlash(__('Selected employee is outside current labour/staff scope.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect(array('action' => 'hremployees', $id, '?' => $employeeScopeQuery));
                }
                $attendanceDate = $this->_normalizeYmdDate(isset($attendance['attendance_date']) ? $attendance['attendance_date'] : '', '');
                if($attendanceDate === '')
                {
                    $this->Session->setFlash(__('Attendance date is required.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect(array('action' => 'hremployees', $id, '?' => $employeeScopeQuery));
                }
                $status = strtolower(trim((string)(isset($attendance['attendance_status']) ? $attendance['attendance_status'] : 'present')));
                $allowedStatuses = array('present','absent','leave','half_day');
                if(!in_array($status, $allowedStatuses, true))
                {
                    $status = 'present';
                }
                $normalizeTimeValue = function($value){
                    $value = trim((string)$value);
                    if($value === '')
                    {
                        return '';
                    }
                    if(preg_match('/^([01]\d|2[0-3]):([0-5]\d)$/', $value))
                    {
                        return $value.':00';
                    }
                    if(preg_match('/^([01]\d|2[0-3]):([0-5]\d):([0-5]\d)$/', $value))
                    {
                        return $value;
                    }
                    return '';
                };
                $inTime = $normalizeTimeValue(isset($attendance['in_time']) ? $attendance['in_time'] : '');
                $outTime = $normalizeTimeValue(isset($attendance['out_time']) ? $attendance['out_time'] : '');
                $overtime = round((float)(isset($attendance['overtime_hours']) ? $attendance['overtime_hours'] : 0), 2);
                if($overtime < 0)
                {
                    $overtime = 0;
                }
                $note = trim((string)(isset($attendance['note']) ? $attendance['note'] : ''));
                $existingAttendance = $this->Ardhattendance->find('first', array(
                    'conditions' => array(
                        'Ardhattendance.project_id' => $attendanceProjectId,
                        'Ardhattendance.employee_id' => $employeeId,
                        'Ardhattendance.attendance_date' => $attendanceDate
                    ),
                    'recursive' => -1
                ));
                if(!empty($existingAttendance['Ardhattendance']['id']))
                {
                    $this->Ardhattendance->id = (int)$existingAttendance['Ardhattendance']['id'];
                }
                else
                {
                    $this->Ardhattendance->create();
                }
                $saveAttendanceData = array(
                    'Ardhattendance' => array(
                        'project_id' => $attendanceProjectId,
                        'employee_id' => $employeeId,
                        'attendance_date' => $attendanceDate,
                        'attendance_status' => $status,
                        'in_time' => $inTime,
                        'out_time' => $outTime,
                        'overtime_hours' => $overtime,
                        'note' => $note
                    )
                );
                if($this->Ardhattendance->save($saveAttendanceData))
                {
                    $this->Session->setFlash(__('Attendance saved successfully.'), 'flash', array('alert' => 'success'));
                }
                else
                {
                    $saveErrors = (array)$this->Ardhattendance->validationErrors;
                    $saveErrorText = '';
                    if(!empty($saveErrors))
                    {
                        $flatErrors = array();
                        foreach($saveErrors as $fieldErrors)
                        {
                            foreach((array)$fieldErrors as $fieldErrorText)
                            {
                                $fieldErrorText = trim((string)$fieldErrorText);
                                if($fieldErrorText !== '')
                                {
                                    $flatErrors[] = $fieldErrorText;
                                }
                            }
                        }
                        if(!empty($flatErrors))
                        {
                            $saveErrorText = implode('; ', array_unique($flatErrors));
                        }
                    }
                    if($saveErrorText !== '')
                    {
                        $this->Session->setFlash(__('Unable to save attendance: %s', $saveErrorText), 'flash', array('alert' => 'danger'));
                    }
                    else
                    {
                        $this->Session->setFlash(__('Unable to save attendance.'), 'flash', array('alert' => 'danger'));
                    }
                }
                return $this->redirect(array('action' => 'hremployees', $id, '?' => $employeeScopeQuery));
            }

            $row = isset($this->request->data['Ardhremployee']) ? $this->request->data['Ardhremployee'] : array();
            $employeeFormMode = strtolower(trim((string)(isset($row['form_mode']) ? $row['form_mode'] : 'create')));
            unset($row['form_mode']);
            $row['project_id'] = $this->_resolveProjectId(isset($row['project_id']) ? $row['project_id'] : null);
            if(!$this->_isAllowedProject($row['project_id']))
            {
                $this->Session->setFlash(__('Please select valid agency/project.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            $employeeId = isset($row['id']) ? (int)$row['id'] : 0;
            // Safety: Create popup should always insert a new row, even if stale hidden id is posted.
            if($employeeFormMode !== 'edit')
            {
                $employeeId = 0;
                unset($row['id']);
            }
            $existingEmployee = array();
            if($employeeId > 0)
            {
                $existingEmployee = (array)$this->Ardhremployee->findById($employeeId);
                if(empty($existingEmployee) || !$this->_isAllowedProject((int)$existingEmployee['Ardhremployee']['project_id']))
                {
                    $this->Session->setFlash(__('Invalid employee.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect($this->referer());
                }
            }
            $row['linked_user_id'] = isset($row['linked_user_id']) ? (int)$row['linked_user_id'] : 0;
            // Keep existing link on edit if user is already connected and posted value is empty.
            if($employeeId > 0 && (int)$row['linked_user_id'] <= 0 && !empty($existingEmployee['Ardhremployee']['linked_user_id']))
            {
                $row['linked_user_id'] = (int)$existingEmployee['Ardhremployee']['linked_user_id'];
            }
            $linkedUserRoleName = '';
            if((int)$row['linked_user_id'] > 0)
            {
                $duplicateLinkedConditions = array(
                    'Ardhremployee.project_id' => (int)$row['project_id'],
                    'Ardhremployee.linked_user_id' => (int)$row['linked_user_id']
                );
                if($employeeId > 0)
                {
                    $duplicateLinkedConditions['Ardhremployee.id !='] = (int)$employeeId;
                }
                $duplicateLinked = (array)$this->Ardhremployee->find('first', array(
                    'fields' => array('Ardhremployee.id', 'Ardhremployee.full_name'),
                    'conditions' => $duplicateLinkedConditions,
                    'recursive' => -1
                ));
                if(!empty($duplicateLinked['Ardhremployee']['id']))
                {
                    $existingName = trim((string)(isset($duplicateLinked['Ardhremployee']['full_name']) ? $duplicateLinked['Ardhremployee']['full_name'] : ''));
                    if($existingName === '')
                    {
                        $existingName = '#'.(int)$duplicateLinked['Ardhremployee']['id'];
                    }
                    $this->Session->setFlash(__('This user is already linked with employee: %s', $existingName), 'flash', array('alert' => 'danger'));
                    return $this->redirect($this->referer());
                }
                $linkedUserRow = $this->_hrEmployeeLinkedUserRow((int)$row['project_id'], (int)$row['linked_user_id']);
                if(empty($linkedUserRow['User']['id']))
                {
                    $this->Session->setFlash(__('Selected linked user is invalid for this agency.'), 'flash', array('alert' => 'danger'));
                    return $this->redirect($this->referer());
                }
                $linkedUserName = trim((string)(isset($linkedUserRow['User']['name']) ? $linkedUserRow['User']['name'] : ''));
                $linkedUserMobile = trim((string)(isset($linkedUserRow['User']['mobile']) ? $linkedUserRow['User']['mobile'] : ''));
                if($linkedUserMobile === '')
                {
                    $linkedUserMobile = trim((string)(isset($linkedUserRow['User']['phone']) ? $linkedUserRow['User']['phone'] : ''));
                }
                $linkedUserRoleName = trim((string)(isset($linkedUserRow['Ugroup']['name']) ? $linkedUserRow['Ugroup']['name'] : ''));
                if(trim((string)(isset($row['full_name']) ? $row['full_name'] : '')) === '' && $linkedUserName !== '')
                {
                    $row['full_name'] = $linkedUserName;
                }
                if(trim((string)(isset($row['mobile_no']) ? $row['mobile_no'] : '')) === '' && $linkedUserMobile !== '')
                {
                    $row['mobile_no'] = $linkedUserMobile;
                }
                if(trim((string)(isset($row['designation']) ? $row['designation'] : '')) === '' && $linkedUserRoleName !== '')
                {
                    $row['designation'] = $linkedUserRoleName;
                }
                if(trim((string)(isset($row['email']) ? $row['email'] : '')) === '')
                {
                    $row['email'] = trim((string)(isset($linkedUserRow['User']['email']) ? $linkedUserRow['User']['email'] : ''));
                }
            }
            $row['father_name'] = trim((string)(isset($row['father_name']) ? $row['father_name'] : ''));
            $row['employee_code'] = trim((string)(isset($row['employee_code']) ? $row['employee_code'] : ''));
            $row['cnic'] = trim((string)(isset($row['cnic']) ? $row['cnic'] : ''));
            $row['dob'] = $this->_normalizeYmdDate(isset($row['dob']) ? $row['dob'] : '', null);
            $row['email'] = trim((string)(isset($row['email']) ? $row['email'] : ''));
            $row['address'] = trim((string)(isset($row['address']) ? $row['address'] : ''));
            $row['reference'] = trim((string)(isset($row['reference']) ? $row['reference'] : ''));
            if($employeeId > 0 && $row['employee_code'] === '' && !empty($existingEmployee['Ardhremployee']['employee_code']))
            {
                $row['employee_code'] = trim((string)$existingEmployee['Ardhremployee']['employee_code']);
            }
            if($employeeId <= 0)
            {
                // Always generate new employee code from agency settings (prefix + next no).
                $row['employee_code'] = $this->_nextReferenceNo((int)$row['project_id'], 'employee_id', 'EMP-');
                // Guard against existing duplicate code from old/manual entries.
                $attempt = 0;
                while($attempt < 50)
                {
                    $duplicateAutoCode = (array)$this->Ardhremployee->find('first', array(
                        'fields' => array('Ardhremployee.id'),
                        'conditions' => array(
                            'Ardhremployee.project_id' => (int)$row['project_id'],
                            'Ardhremployee.employee_code' => (string)$row['employee_code']
                        ),
                        'recursive' => -1
                    ));
                    if(empty($duplicateAutoCode['Ardhremployee']['id']))
                    {
                        break;
                    }
                    $row['employee_code'] = $this->_nextReferenceNo((int)$row['project_id'], 'employee_id', 'EMP-');
                    $attempt++;
                }
            }
            if($row['employee_code'] === '')
            {
                $this->Session->setFlash(__('Employee code could not be generated. Please check Employee ID prefix/start number in account settings.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            $duplicateCodeConditions = array(
                'Ardhremployee.project_id' => (int)$row['project_id'],
                'Ardhremployee.employee_code' => (string)$row['employee_code']
            );
            if($employeeId > 0)
            {
                $duplicateCodeConditions['Ardhremployee.id !='] = (int)$employeeId;
            }
            $duplicateCode = (array)$this->Ardhremployee->find('first', array(
                'fields' => array('Ardhremployee.id', 'Ardhremployee.full_name'),
                'conditions' => $duplicateCodeConditions,
                'recursive' => -1
            ));
            if(!empty($duplicateCode['Ardhremployee']['id']))
            {
                $existingName = trim((string)(isset($duplicateCode['Ardhremployee']['full_name']) ? $duplicateCode['Ardhremployee']['full_name'] : ''));
                if($existingName === '')
                {
                    $existingName = '#'.(int)$duplicateCode['Ardhremployee']['id'];
                }
                $this->Session->setFlash(__('Employee code already exists for this agency: %s', $existingName), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            $row['full_name'] = trim((string)$row['full_name']);
            if($row['full_name'] === '')
            {
                $this->Session->setFlash(__('Employee name is required.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            $row['status'] = (isset($row['status']) && strtolower((string)$row['status']) === 'inactive') ? 'inactive' : 'active';
            $row['salary_type'] = (isset($row['salary_type']) && strtolower((string)$row['salary_type']) === 'daily') ? 'daily' : 'monthly';
            if($employeeScope === 'labour')
            {
                // In Labour Control, keep employee strictly in labour stream.
                $row['salary_type'] = 'daily';
            }
            $row['labour_ledger_id'] = isset($row['labour_ledger_id']) ? (int)$row['labour_ledger_id'] : 0;
            if($employeeId > 0 && $row['labour_ledger_id'] <= 0 && !empty($existingEmployee['Ardhremployee']['labour_ledger_id']))
            {
                $row['labour_ledger_id'] = (int)$existingEmployee['Ardhremployee']['labour_ledger_id'];
            }
            $labourLedgerId = $this->_ensureHrLabourLedger(
                (int)$row['project_id'],
                (string)$row['employee_code'],
                (string)$row['full_name'],
                (int)$row['labour_ledger_id']
            );
            if($labourLedgerId <= 0)
            {
                $this->Session->setFlash(__('Unable to link HR ledger. Please check Accounts Ledgers permissions/settings.'), 'flash', array('alert' => 'danger'));
                return $this->redirect(array('action' => 'hremployees', $id, '?' => $employeeScopeQuery));
            }
            $row['labour_ledger_id'] = $labourLedgerId;
            if($employeeId > 0)
            {
                $this->Ardhremployee->id = $employeeId;
            }
            else
            {
                $this->Ardhremployee->create();
            }
            if($this->Ardhremployee->save(array('Ardhremployee' => $row)))
            {
                $this->Session->setFlash(__('Employee saved successfully.'), 'flash', array('alert' => 'success'));
            }
            else
            {
                $this->Session->setFlash(__('Unable to save employee.'), 'flash', array('alert' => 'danger'));
            }
            return $this->redirect(array('action' => 'hremployees', $id, '?' => $employeeScopeQuery));
        }

        $scope = $this->_scopeCondition('Ardhremployee.project_id', $id);
        $listingConditions = array($scope);
        if(!empty($employeeTypeConditions))
        {
            $listingConditions = array_merge($listingConditions, $employeeTypeConditions);
        }
        $this->Paginator->settings = array(
            'page' => 1,
            'order' => array('Ardhremployee.id' => 'desc'),
            'limit' => $this->pageLimit,
            'maxLimit' => $this->maxLimit,
            'joins' => array(
                array(
                    'table' => 'users',
                    'alias' => 'LinkedUser',
                    'type' => 'LEFT',
                    'conditions' => array('LinkedUser.id=Ardhremployee.linked_user_id')
                ),
                array(
                    'table' => 'ugroups',
                    'alias' => 'LinkedUserGroup',
                    'type' => 'LEFT',
                    'conditions' => array('LinkedUserGroup.id=LinkedUser.ugroup_id')
                )
            ),
            'fields' => array(
                'Ardhremployee.*',
                'LinkedUser.id', 'LinkedUser.name', 'LinkedUser.mobile', 'LinkedUser.phone', 'LinkedUser.email', 'LinkedUser.project_id',
                'LinkedUserGroup.id', 'LinkedUserGroup.name', 'LinkedUserGroup.type'
            ),
            'conditions' => $listingConditions
        );
        $rows = $this->Paginator->paginate('Ardhremployee');
        $this->set('rows', $rows);
        $labourLedgerNamesById = array();
        $labourLedgerIds = array();
        foreach((array)$rows as $rowIndex => $employeeRow)
        {
            $ledgerId = isset($employeeRow['Ardhremployee']['labour_ledger_id']) ? (int)$employeeRow['Ardhremployee']['labour_ledger_id'] : 0;
            if($ledgerId <= 0)
            {
                $autoLedgerId = $this->_ensureHrLabourLedger(
                    (int)(isset($employeeRow['Ardhremployee']['project_id']) ? $employeeRow['Ardhremployee']['project_id'] : 0),
                    (string)(isset($employeeRow['Ardhremployee']['employee_code']) ? $employeeRow['Ardhremployee']['employee_code'] : ''),
                    (string)(isset($employeeRow['Ardhremployee']['full_name']) ? $employeeRow['Ardhremployee']['full_name'] : ''),
                    0
                );
                if($autoLedgerId > 0)
                {
                    $ledgerId = $autoLedgerId;
                    $rows[$rowIndex]['Ardhremployee']['labour_ledger_id'] = $autoLedgerId;
                    $this->Ardhremployee->id = (int)$employeeRow['Ardhremployee']['id'];
                    $this->Ardhremployee->saveField('labour_ledger_id', $autoLedgerId, false);
                }
            }
            elseif($ledgerId > 0)
            {
                $normalizedLedgerId = $this->_normalizeHrEmployeeLedger(
                    (int)(isset($employeeRow['Ardhremployee']['project_id']) ? $employeeRow['Ardhremployee']['project_id'] : 0),
                    (int)$ledgerId
                );
                if($normalizedLedgerId > 0)
                {
                    $ledgerId = $normalizedLedgerId;
                    $rows[$rowIndex]['Ardhremployee']['labour_ledger_id'] = $normalizedLedgerId;
                }
            }
            if($ledgerId > 0)
            {
                $labourLedgerIds[$ledgerId] = $ledgerId;
            }
        }
        $this->set('rows', $rows);
        if(!empty($labourLedgerIds))
        {
            $labourLedgerNamesById = (array)$this->Ardledger->find('list', array(
                'fields' => array('Ardledger.id', 'Ardledger.name'),
                'conditions' => array(
                    'Ardledger.id' => array_values($labourLedgerIds),
                    $this->_scopeCondition('Ardledger.project_id', $id)
                ),
                'recursive' => -1
            ));
        }
        $this->set('labourLedgerNamesById', $labourLedgerNamesById);
        $attendanceStatusByEmployee = array();
        $employeeIds = array();
        foreach((array)$rows as $employeeRow)
        {
            $employeeId = isset($employeeRow['Ardhremployee']['id']) ? (int)$employeeRow['Ardhremployee']['id'] : 0;
            if($employeeId > 0)
            {
                $employeeIds[] = $employeeId;
            }
        }
        if(!empty($employeeIds))
        {
            $attendanceConditions = array(
                'Ardhattendance.employee_id' => $employeeIds
            );
            if((int)$id > 0)
            {
                $attendanceConditions['Ardhattendance.project_id'] = (int)$id;
            }
            elseif(!$this->_isGlobalAdmin() && (int)$this->agencyId > 0)
            {
                $attendanceConditions['Ardhattendance.project_id'] = (int)$this->agencyId;
            }
            $attendanceRows = $this->Ardhattendance->find('all', array(
                'fields' => array('Ardhattendance.employee_id', 'Ardhattendance.attendance_date', 'Ardhattendance.attendance_status'),
                'conditions' => $attendanceConditions,
                'order' => array('Ardhattendance.attendance_date' => 'desc', 'Ardhattendance.id' => 'desc'),
                'recursive' => -1
            ));
            foreach((array)$attendanceRows as $attendanceRow)
            {
                $employeeId = isset($attendanceRow['Ardhattendance']['employee_id']) ? (int)$attendanceRow['Ardhattendance']['employee_id'] : 0;
                if($employeeId <= 0 || isset($attendanceStatusByEmployee[$employeeId]))
                {
                    continue;
                }
                $attendanceStatusByEmployee[$employeeId] = array(
                    'date' => isset($attendanceRow['Ardhattendance']['attendance_date']) ? (string)$attendanceRow['Ardhattendance']['attendance_date'] : '',
                    'status' => isset($attendanceRow['Ardhattendance']['attendance_status']) ? (string)$attendanceRow['Ardhattendance']['attendance_status'] : ''
                );
            }
        }
        $this->set('attendanceStatusByEmployee', $attendanceStatusByEmployee);

        $editId = isset($this->request->params['named']['edit']) ? (int)$this->request->params['named']['edit'] : 0;
        if($editId > 0)
        {
            $editRow = $this->Ardhremployee->findById($editId);
