    public function deletehremployee($id = null, $projectId = null)
    {
        $this->loadModel('Admin.Ardhremployee');
        $employeeScope = $this->_hrEmployeeScopeFromRequest('all');
        $employeeScopeQuery = $this->_hrEmployeeScopeQuery($employeeScope);
        $row = $this->Ardhremployee->findById($id);
        if(empty($row) || !$this->_isAllowedProject((int)$row['Ardhremployee']['project_id']))
        {
            $this->Session->setFlash(__('Invalid employee.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'hremployees', $projectId, '?' => $employeeScopeQuery));
        }
        if(!$this->_hrEmployeeMatchesScope($row, $employeeScope))
        {
            $this->Session->setFlash(__('Selected employee is outside current labour/staff scope.'), 'flash', array('alert' => 'danger'));
            return $this->redirect(array('action' => 'hremployees', $projectId, '?' => $employeeScopeQuery));
        }
        $this->_storeTrashRecord(
            'ardaccounts_hr_employees',
            'Ardhremployee',
            $row['Ardhremployee'],
            isset($row['Ardhremployee']['full_name']) ? (string)$row['Ardhremployee']['full_name'] : ''
        );
        $this->Ardhremployee->delete($id);
        $this->Session->setFlash(__('Employee deleted. You can restore it from Trash.'), 'flash', array('alert' => 'success'));
        return $this->redirect(array('action' => 'hremployees', $projectId, '?' => $employeeScopeQuery));
    }

