    public function transfer($id = null)
    {
        $this->loadModel('Admin.Ardledger');
        $this->loadModel('Admin.Ardtransaction');
        $id = $this->_activeProjectId($id);

        $this->set('projectName', $this->_projectList());
        $this->set('agencyId', $this->agencyId);
        $this->set('currentProjectId', $id);
        $this->set('date', CakeTime::format($this->dtFormat, CakeTime::convert(time(), $this->siteTimezone)));
        $scopeLedger = $this->_scopeCondition('Ardledger.project_id', $id);
        $ledgerRows = $this->Ardledger->find('all', array(
            'fields' => array('Ardledger.id', 'Ardledger.name', 'Ardledger.type'),
            'conditions' => array($scopeLedger, 'Ardledger.is_trashed' => 0),
            'order' => array('Ardledger.name' => 'asc'),
            'recursive' => -1
        ));
        $assetLedgers = array();
        foreach((array)$ledgerRows as $ledgerRow)
        {
            $ledgerType = strtolower(trim((string)(isset($ledgerRow['Ardledger']['type']) ? $ledgerRow['Ardledger']['type'] : '')));
            if($ledgerType === 'expense')
            {
                continue;
            }
            $ledgerId = (int)(isset($ledgerRow['Ardledger']['id']) ? $ledgerRow['Ardledger']['id'] : 0);
            if($ledgerId <= 0)
            {
                continue;
            }
            $ledgerName = trim((string)(isset($ledgerRow['Ardledger']['name']) ? $ledgerRow['Ardledger']['name'] : ''));
            if($ledgerName === '')
            {
                $ledgerName = 'Ledger #' . $ledgerId;
            }
            $assetLedgers[$ledgerId] = $ledgerName;
        }
        $this->set('bankLedgers', $assetLedgers);

        if($this->request->is('post'))
        {
            $projectId = $this->_resolveProjectId(isset($this->request->data['Ardtransaction']['project_id']) ? $this->request->data['Ardtransaction']['project_id'] : null);
            if(!$this->_isAllowedProject($projectId))
            {
                $this->Session->setFlash(__('Please select valid agency/project.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }

            $fromLedgerId = (int)$this->request->data['Ardtransaction']['from_ledger_id'];
            $toLedgerId = (int)$this->request->data['Ardtransaction']['to_ledger_id'];
            $amount = round((float)$this->request->data['Ardtransaction']['amount'], 2);
            $entryDate = trim((string)$this->request->data['Ardtransaction']['entry_date']);
            $description = trim((string)$this->request->data['Ardtransaction']['description']);
            $refNo = trim((string)$this->request->data['Ardtransaction']['ref_no']);
            if($refNo === '')
            {
                $refNo = $this->_nextReferenceNo((int)$projectId, 'journal_voucher', 'JV-');
            }

            $entryDate = $this->_reportNormalizeDate($entryDate, false);
            if($fromLedgerId <= 0 || $toLedgerId <= 0 || $fromLedgerId === $toLedgerId || $amount <= 0 || $entryDate === '')
            {
                $this->Session->setFlash(__('Please enter valid transfer details.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }

            $fromLedger = $this->Ardledger->findById($fromLedgerId);
            $toLedger = $this->Ardledger->findById($toLedgerId);
            if(empty($fromLedger) || empty($toLedger))
            {
                $this->Session->setFlash(__('Invalid transfer ledger selected.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }
            $fromType = strtolower(trim((string)$fromLedger['Ardledger']['type']));
            $toType = strtolower(trim((string)$toLedger['Ardledger']['type']));
            if(
                !$this->_isAllowedProject((int)$fromLedger['Ardledger']['project_id']) ||
                !$this->_isAllowedProject((int)$toLedger['Ardledger']['project_id']) ||
                (int)$fromLedger['Ardledger']['project_id'] !== (int)$projectId ||
                (int)$toLedger['Ardledger']['project_id'] !== (int)$projectId ||
                $fromType === 'expense' ||
                $toType === 'expense'
            )
            {
                $this->Session->setFlash(__('Journal Voucher transfer is only allowed between active Asset/Bank ledgers of selected agency.'), 'flash', array('alert' => 'danger'));
                return $this->redirect($this->referer());
            }

            $fromLedgerName = trim((string)$fromLedger['Ardledger']['name']);
            if($fromLedgerName === '')
            {
                $fromLedgerName = 'Ledger #' . $fromLedgerId;
            }
            $toLedgerName = trim((string)$toLedger['Ardledger']['name']);
            if($toLedgerName === '')
            {
                $toLedgerName = 'Ledger #' . $toLedgerId;
            }
            $extraNarration = ($description !== '') ? (' | ' . $description) : '';
            $debitNarration = 'Journal Voucher DR: ' . $fromLedgerName . ' | CR: ' . $toLedgerName . $extraNarration;
            $creditNarration = 'Journal Voucher CR: ' . $toLedgerName . ' | DR: ' . $fromLedgerName . $extraNarration;

            $ds = $this->Ardtransaction->getDataSource();
            $ds->begin();
            $ok = true;
            $outTxId = 0;
            $inTxId = 0;

            $outRow = array(
                'project_id' => (int)$projectId,
                'ledger_id' => $fromLedgerId,
                'expense_ledger_id' => $toLedgerId,
                'type' => 'expense',
                'amount' => $amount,
                'description' => $debitNarration,
                'ref_no' => $refNo,
                'entry_date' => $entryDate,
                'construction_site_id' => 0
            );
            $this->Ardtransaction->create();
            if(!$this->Ardtransaction->save(array('Ardtransaction' => $outRow)))
            {
                $ok = false;
            }
            else
            {
                $outTxId = (int)$this->Ardtransaction->id;
            }

            if($ok)
            {
                $inRow = array(
                    'project_id' => (int)$projectId,
                    'ledger_id' => $toLedgerId,
                    'income_ledger_id' => $fromLedgerId,
                    'type' => 'income',
                    'amount' => $amount,
                    'description' => $creditNarration,
                    'ref_no' => $refNo,
                    'entry_date' => $entryDate,
                    'construction_site_id' => 0
                );
                $this->Ardtransaction->create();
                if(!$this->Ardtransaction->save(array('Ardtransaction' => $inRow)))
                {
                    $ok = false;
                }
                else
                {
                    $inTxId = (int)$this->Ardtransaction->id;
                }
            }

            if($ok)
            {
                $ds->commit();
                $this->_recalculateLedgerBalance($fromLedgerId);
                $this->_recalculateLedgerBalance($toLedgerId);
                if($outTxId > 0)
                {
                    $this->_syncJournalForTransaction($outTxId, 'transfer', $outTxId);
                }
                $this->Session->setFlash(__('Journal Voucher posted successfully.'), 'flash', array('alert' => 'success'));
            }
            else
            {
                $ds->rollback();
                $this->Session->setFlash(__('Unable to post Journal Voucher.'), 'flash', array('alert' => 'danger'));
            }
            return $this->redirect(array('action' => 'transfer', $id));
        }

        $this->set('recentTransfers', $this->Ardtransaction->find('all', array(
            'joins' => array(
                array('table' => 'ardaccounts_ledgers', 'alias' => 'Ardledger', 'type' => 'LEFT', 'conditions' => array('Ardledger.id=Ardtransaction.ledger_id'))
            ),
            'fields' => array('Ardtransaction.*', 'Ardledger.name'),
            'conditions' => array(
                $this->_scopeCondition('Ardtransaction.project_id', $id),
                'Ardtransaction.type' => 'expense',
                'OR' => array(
                    array('Ardtransaction.ref_no LIKE' => 'TRF-%'),
                    array('Ardtransaction.ref_no LIKE' => 'JV-%')
                )
            ),
            'order' => array('Ardtransaction.entry_date' => 'desc', 'Ardtransaction.id' => 'desc'),
            'limit' => 20,
            'recursive' => -1
        )));
    }
}
